#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include "third_party_logger.h"

#define MAX_THREADS 10
#define DEFAULT_MAX_SIZE 1000

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} IntegerArray;

void init_integer_array(IntegerArray *array, size_t initial_capacity) {
    array->data = malloc(initial_capacity * sizeof(int));
    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->mutex, NULL);
}

void free_integer_array(IntegerArray *array) {
    pthread_mutex_destroy(&array->mutex);
    free(array->data);
}

int add_to_array(IntegerArray *array, int value) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        int *new_data = realloc(array->data, new_capacity * sizeof(int));
        if (!new_data) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = value;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void *process_network_stream(void *arg) {
    IntegerArray *array = (IntegerArray *)arg;
    // Simulate reading from a network stream
    for (int i = -100; i < 100; ++i) {
        if (add_to_array(array, i) != 0) {
            log_error("Memory allocation failed during data processing");
            break;
        }
    }
    return NULL;
}

void find_and_print_largest(IntegerArray *array) {
    pthread_mutex_lock(&array->mutex);
    int largest = array->size > 0 ? array->data[0] : INT_MIN;
    for (size_t i = 1; i < array->size; ++i) {
        if (array->data[i] > largest) {
            largest = array->data[i];
        }
    }
    pthread_mutex_unlock(&array->mutex);
    printf("Largest integer: %d\n", largest);
}

int main() {
    IntegerArray array;
    init_integer_array(&array, DEFAULT_MAX_SIZE);

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, process_network_stream, &array) != 0) {
            log_error("Failed to create thread");
            return 1;
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    find_and_print_largest(&array);

    free_integer_array(&array);
    return 0;
}
```

