#define MAX_LOG_LENGTH 1024
#define MAX_LOGS_PER_MINUTE 5

typedef struct {
    time_t last_log_time;
    int log_count;
} RateLimiter;

RateLimiter rate_limiter = {0};

pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

int sendLogToService(const char* message) {
    // Simulate sending a log to an external service
    printf("Logging: %s\n", message);
    return 0; // Return 0 for success, -1 for failure
}

int conditionalLogService(int condition, const char* format, ...) {
    if (!condition) {
        return 0; // Do not log if the condition is false
    }

    va_list args;
    va_start(args, format);
    char buffer[MAX_LOG_LENGTH];
    int result = vsnprintf(buffer, MAX_LOG_LENGTH, format, args);
    va_end(args);

    if (result < 0 || result >= MAX_LOG_LENGTH) {
        fprintf(stderr, "Buffer overflow detected.\n");
        return -1; // Handle buffer overflow
    }

    pthread_mutex_lock(&log_mutex);
    time_t now = time(NULL);
    if ((now > rate_limiter.last_log_time && rate_limiter.log_count < MAX_LOGS_PER_MINUTE) ||
        (rate_limiter.last_log_time == 0)) {
        sendLogToService(buffer);
        rate_limiter.last_log_time = now;
        rate_limiter.log_count++;
        pthread_mutex_unlock(&log_mutex);
    } else if (now <= rate_limiter.last_log_time) {
        // Rate limit exceeded, handle accordingly
        pthread_mutex_unlock(&log_mutex);
        return -1; // Handle rate limiting
    } else {
        pthread_mutex_unlock(&log_mutex);
        return -1; // Handle rate limiting
    }

    return 0; // Return 0 for success, -1 for failure
}
