// Controller for generating detailed reports for a batch of Pokemon objects
@RestController
@RequestMapping("/reports")
public class ReportController {

    @Autowired
    private PokemonService pokemonService;

    @Autowired
    private DatabaseService databaseService;

    @PostMapping("/batch")
    public ResponseEntity<List<PokemonReport>> generateBatchReport(@RequestBody List<String> pokemonIds) {
        List<PokemonReport> reports = new ArrayList<>();
        for (String id : pokemonIds) {
            PokemonDetails apiDetails = pokemonService.getPokemonDetails(id);
            PokemonDatabaseDetails dbDetails = databaseService.getPokemonFromDatabase(id);

            // Combine details and add to report list
            reports.add(new PokemonReport(apiDetails, dbDetails));
        }

        return ResponseEntity.ok(reports);
    }
}
