#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define MAX_THREADS 10

typedef struct {
    char *file_path;
    int encrypt_mode;
} FileTask;

void* process_file(void* arg) {
    FileTask *task = (FileTask *)arg;
    FILE *file = fopen(task->file_path, task->encrypt_mode ? "rb" : "wb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        fclose(file);
        return NULL;
    }

    // Initialize encryption/decryption
    if (EVP_Init_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Failed to initialize cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        fclose(file);
        return NULL;
    }

    // Process file in chunks
    unsigned char buffer[4096];
    int bytes_read, bytes_written;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        if (EVP_EncryptUpdate(ctx, buffer, &bytes_written, buffer, bytes_read) != 1) {
            fprintf(stderr, "Failed to update cipher\n");
            EVP_CIPHER_CTX_free(ctx);
            fclose(file);
            return NULL;
        }
        fwrite(buffer, 1, bytes_written, file);
    }

    // Finalize encryption/decryption
    if (EVP_EncryptFinal_ex(ctx, buffer, &bytes_written) != 1) {
        fprintf(stderr, "Failed to finalize cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        fclose(file);
        return NULL;
    }
    fwrite(buffer, 1, bytes_written, file);

    EVP_CIPHER_CTX_free(ctx);
    fclose(file);
    return NULL;
}

void handle_files(char **file_paths, int encrypt_mode) {
    pthread_t threads[MAX_THREADS];
    FileTask tasks[MAX_THREADS];

    for (int i = 0; file_paths[i] != NULL && i < MAX_THREADS; i++) {
        tasks[i].file_path = file_paths[i];
        tasks[i].encrypt_mode = encrypt_mode;

        if (pthread_create(&threads[i], NULL, process_file, &tasks[i]) != 0) {
            fprintf(stderr, "Failed to create thread for %s\n", file_paths[i]);
            continue;
        }
    }

    for (int i = 0; i < MAX_THREADS && tasks[i].file_path != NULL; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <encrypt/decrypt> <file1> [file2] [...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int encrypt_mode = !strcmp(argv[1], "encrypt");
    char *file_paths[] = {argv[2], argv[3], NULL}; // Example usage with two files

    handle_files(file_paths, encrypt_mode);

    return EXIT_SUCCESS;
}
```

