#include <forward_list>
#include <string>
#include <cstdio>
#include <cstdarg>

void insertOrLog(std::forward_list<std::string>& list, const std::string& target, const std::string& value, bool shouldLog, const char* logFile) {
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == target) {
            it = list.insert_after(it, value);
            if (shouldLog) {
                logOperation(target, value, "inserted", logFile);
            }
            return;
        }
        ++it;
    }

    list.push_back(value);
    if (shouldLog) {
        logOperation(target, value, "appended", logFile);
    }
}

void logOperation(const std::string& target, const std::string& value, const char* action, const char* logFile) {
    constexpr size_t bufferSize = 256;
    char buffer[bufferSize];
    snprintf(buffer, bufferSize, "%s: %s after %s", action, value.c_str(), target.c_str());

    FILE* file = fopen(logFile, "a");
    if (file != nullptr) {
        fwrite(buffer, 1, strlen(buffer), file);
        fclose(file);
    }
}

// Example unit tests
#include <iostream>
#include <thread>

void testInsertOrLog() {
    std::forward_list<std::string> list = {"apple", "banana", "cherry"};
    insertOrLog(list, "banana", "durian", true, "log.txt");
    for (const auto& item : list) {
        std::cout << item << " ";
    }
    std::cout << std::endl;

    std::forward_list<std::string> emptyList;
    insertOrLog(emptyList, "apple", "orange", true, "log.txt");
    for (const auto& item : emptyList) {
        std::cout << item << " ";
    }
    std::cout << std::endl;

    std::forward_list<std::string> listWithTarget = {"apple", "banana", "cherry"};
    insertOrLog(listWithTarget, "cherry", "date", true, "log.txt");
    for (const auto& item : listWithTarget) {
        std::cout << item << " ";
    }
    std::cout << std::endl;
}

void testConcurrency() {
    std::forward_list<std::string> list = {"apple"};
    std::thread t1(insertOrLog, std::ref(list), "apple", "banana", true, "log.txt");
    std::thread t2(insertOrLog, std::ref(list), "apple", "cherry", true, "log.txt");

    t1.join();
    t2.join();

    for (const auto& item : list) {
        std::cout << item << " ";
    }
    std::cout << std::endl;
}

int main() {
    testInsertOrLog();
    testConcurrency();
    return 0;
}
