class HealthCheckService {
public:
    void addService(const std::string& url, int interval) {
        services.push_back({url, interval});
    }

    void start() {
        for (auto& service : services) {
            workerThreads.emplace_back([this, &service]() {
                while (true) {
                    std::unique_lock<std::mutex> lock(mutex);
                    condition.wait(lock, [this] { return !stop || !tasks.empty(); });
                    if (!stop && !tasks.empty()) {
                        auto task = tasks.front();
                        tasks.pop();
                        lock.unlock();

                        performHealthCheck(task.url, service.interval);
                    } else {
                        break;
                    }
                }
            });
        }
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (auto& thread : workerThreads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

