#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <random>
#include <future>
#include <chrono>

class RNGService {
public:
    RNGService(std::function<void()> init_config) : reseed_interval(10s), global_seed(42) {
        init_config();
        std::thread([this]() {
            while (true) {
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait_for(lock, reseed_interval, [this] { return !reseeding; });
                if (!running) break;
                reseeding = true;
                lock.unlock();
                reseed();
                lock.lock();
                reseeding = false;
            }
        }).detach();
    }

    void requestRNG(int client_id, std::function<void(uint32_t)> callback) {
        std::lock_guard<std::mutex> lock(mutex);
        client_requests.emplace(client_id, callback);
        cv.notify_one();
    }

private:
    std::mt19937_64 rng;
    std::uniform_int_distribution<uint32_t> dist{0, UINT32_MAX};
    std::mutex mutex;
    std::condition_variable cv;
    std::map<int, std::function<void(uint32_t)>> client_requests;
    std::chrono::seconds reseed_interval;
    uint64_t global_seed;
    bool running = true;
    bool reseeding = false;

    void reseed() {
        // Fetch new seed from external service
        std::promise<uint64_t> p;
        std::future<uint64_t> f = p.get_future();
        auto future_thread = std::thread([this, &p]() {
            try {
                uint64_t new_seed = fetchSeedFromExternalService();
                p.set_value(new_seed);
            } catch (...) {
                p.set_exception(std::current_exception());
            }
        });

        uint64_t seed;
        try {
            seed = f.get();
        } catch (...) {
            handleException("Failed to fetch seed from external service");
            return;
        }

        future_thread.join();

        // Update global seed and reseed all clients
        std::lock_guard<std::mutex> lock(mutex);
        global_seed = (global_seed + 1) % UINT64_MAX;
        rng.seed((client_id * global_seed) + seed);

        for (auto& request : client_requests) {
            request.second(dist(rng));
        }
    }

    uint64_t fetchSeedFromExternalService() {
        // Simulate fetching a new seed from an external service
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        return rand() % UINT64_MAX;
    }

    void handleException(const std::string& message) {
        // Log or handle exceptions here
        std::cerr << "Error: " << message << std::endl;
    }
};

int main() {
    RNGService service([]() {
        // Initialize configuration and seed from external service
    });

    auto requestRNG = [&](int client_id) {
        service.requestRNG(client_id, [](uint32_t rng_value) {
            // Process the RNG value here
            std::cout << "Client " << client_id << " received: " << rng_value << std::endl;
        });
    };

    for (int i = 0; i < 10; ++i) {
        requestRNG(i);
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }

    return 0;
}
