using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Threading;
using System.Threading.Tasks;

public class QueryExecutor
{
    private readonly IExternalLoggingService _loggingService;

    public QueryExecutor(IExternalLoggingService loggingService)
    {
        _loggingService = loggingService ?? throw new ArgumentNullException(nameof(loggingService));
    }

    public async Task<IDataReader> ExecuteParameterizedQueryAsync(string sqlCommand, List<DbParameter> parameters, DbConnection connection, CancellationToken cancellationToken)
    {
        if (string.IsNullOrEmpty(sqlCommand))
            throw new ArgumentException("SQL command cannot be null or empty.", nameof(sqlCommand));

        if (connection == null)
            throw new ArgumentNullException(nameof(connection));

        if (!connection.State.HasFlag(ConnectionState.Open))
            throw new InvalidOperationException("Database connection must be open.");

        if (cancellationToken.IsCancellationRequested)
            throw new OperationCanceledException(cancellationToken);

        try
        {
            _loggingService.LogQueryExecution(sqlCommand, parameters);
            using (var command = connection.CreateCommand())
            {
                command.CommandText = sqlCommand;
                command.Parameters.AddRange(parameters.ToArray());
                command.CommandTimeout = 30; // Set a reasonable timeout

                return await command.ExecuteReaderAsync(cancellationToken);
            }
        }
        catch (DbException ex)
        {
            _loggingService.LogError(ex, "Database error during query execution.");
            throw new QueryExecutionException("An error occurred while executing the query.", ex);
        }
        catch (OperationCanceledException ex) when (!cancellationToken.IsCancellationRequested)
        {
            _loggingService.LogWarning(ex, "Query execution was canceled.");
            throw;
        }
        catch (Exception ex)
        {
            _loggingService.LogError(ex, "Unexpected error during query execution.");
            throw new QueryExecutionException("An unexpected error occurred.", ex);
        }
    }
}

public class QueryExecutionException : Exception
{
    public QueryExecutionException(string message) : base(message)
    {
    }

    public QueryExecutionException(string message, Exception innerException) : base(message, innerException)
    {
    }
}

public interface IExternalLoggingService
{
    void LogQueryExecution(string sqlCommand, List<DbParameter> parameters);
    void LogError(Exception ex, string message);
    void LogWarning(Exception ex, string message);
}
```

