using log4net;

public class XmlProcessor
{
    private static readonly ILog Log = LogManager.GetLogger(typeof(XmlProcessor));
    private readonly ConcurrentDictionary<string, (DateTime ExpiresAt, string Content)> _cache = new ConcurrentDictionary<string, (DateTime ExpiresAt, string Content)>();
    private readonly HttpClient _httpClient;
    private readonly string _schemaLocation;

    public XmlProcessor(HttpClient httpClient, string schemaLocation)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _schemaLocation = schemaLocation ?? throw new ArgumentNullException(nameof(schemaLocation));
    }

    public XPathNavigator GetElement(string uri, string elementName)
    {
        if (_cache.TryGetValue(uri, out var cachedItem) && DateTime.UtcNow < cachedItem.ExpiresAt)
        {
            return ParseXml(cachedItem.Content).SelectSingleNode($"//{elementName}");
        }
        else
        {
            var content = FetchAndCacheDocument(uri);
            return ParseXml(content).SelectSingleNode($"//{elementName}");
        }
    }

    private string FetchAndCacheDocument(string uri)
    {
        var response = _httpClient.GetAsync(uri).Result;
        if (!response.IsSuccessStatusCode)
        {
            throw new Exception($"Failed to fetch document from {uri}");
        }

        var content = response.Content.ReadAsStringAsync().Result;
        ValidateSchema(content);

        _cache.TryAdd(uri, (DateTime.UtcNow.AddSeconds(3600), content)); // Cache for 1 hour
        return content;
    }

    private XPathNavigator ParseXml(string xml)
    {
        var doc = new XPathDocument(new StringReader(xml));
        return doc.CreateNavigator();
    }

    private void ValidateSchema(string xml)
    {
        // Implement schema validation logic here
    }
}

public class Program
{
    public static void Main()
    {
        var httpClient = new HttpClient();
        var processor = new XmlProcessor(httpClient, "path/to/schema.xsd");

        try
        {
            var element = processor.GetElement("http://example.com/data", "elementName");
            Console.WriteLine(element);
        }
        catch (Exception ex)
        {
            Log.Error(ex.Message);
        }
    }
}
