import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import javax.validation.Valid;

@RestController
@RequestMapping("/api/customers")
public class CustomerController {

    @Autowired
    private CustomerService customerService;

    @Autowired
    private IdentityVerificationService identityVerificationService;

    @PutMapping("/{customerId}")
    public ResponseEntity<String> updateCustomer(@PathVariable UUID customerId, 
                                                 @Valid @RequestBody CustomerUpdateRequest request,
                                                 @RequestHeader("Authorization") String token) {
        if (!identityVerificationService.verify(token)) {
            return new ResponseEntity<>("Unauthorized", HttpStatus.UNAUTHORIZED);
        }

        try {
            customerService.updateCustomer(customerId, request);
            return new ResponseEntity<>("Customer updated successfully", HttpStatus.OK);
        } catch (ValidationException e) {
            return new ResponseEntity<>(e.getMessage(), HttpStatus.BAD_REQUEST);
        }
    }

    @DeleteMapping("/{customerId}")
    public ResponseEntity<String> deleteCustomer(@PathVariable UUID customerId,
                                              @RequestHeader("Authorization") String token,
                                              @RequestParam(required = false, defaultValue = "false") boolean softDelete) {
        if (!identityVerificationService.verify(token)) {
            return new ResponseEntity<>("Unauthorized", HttpStatus.UNAUTHORIZED);
        }

        try {
            customerService.deleteCustomer(customerId, softDelete);
            return new ResponseEntity<>(softDelete ? "Customer marked as inactive" : "Customer deleted successfully", HttpStatus.OK);
        } catch (NotFoundException e) {
            return new ResponseEntity<>(e.getMessage(), HttpStatus.NOT_FOUND);
        }
    }
}

class CustomerUpdateRequest {
    private String name;
    private int age;
    // getters and setters
}

enum ValidationException extends Exception {
    AGE_LIMIT_EXCEEDED("Age must be between 18 and 90."),
    ACCOUNT_STATUS_ERROR("Invalid account status transition.");

    private final String message;

    ValidationException(String message) {
        this.message = message;
    }

    @Override
    public String getMessage() {
        return message;
    }
}

enum NotFoundException extends Exception {
    CUSTOMER_NOT_FOUND("Customer not found.");

    private final String message;

    NotFoundException(String message) {
        this.message = message;
    }

    @Override
    public String getMessage() {
        return message;
    }
}
