import org.springframework.beans.factory.annotation.Autowired;
import javax.validation.Validator;
import java.util.UUID;

@Service
public class CustomerService {

    @Autowired
    private ExternalDataStore externalDataStore;

    @Autowired
    private Validator validator;

    public void updateCustomer(UUID customerId, CustomerUpdateRequest request) {
        validate(request);
        // Perform database operation to update customer record atomically
        externalDataStore.updateCustomer(customerId, request.getName(), request.getAge());
        logAction("update", customerId, request.getName());
    }

    public void deleteCustomer(UUID customerId, boolean softDelete) {
        if (softDelete) {
            externalDataStore.markCustomerInactive(customerId);
        } else {
            externalDataStore.deleteCustomer(customerId);
        }
        logAction(softDelete ? "mark inactive" : "delete", customerId);
    }

    private void validate(CustomerUpdateRequest request) throws ValidationException {
        var violations = validator.validate(request);
        if (!violations.isEmpty()) {
            throw new ValidationException("Validation failed: " + violations.toString());
        }
    }

    private void logAction(String action, UUID customerId, String... details) {
        // Log the action with timestamp, user ID (from token), and details
    }
}

interface ExternalDataStore {
    void updateCustomer(UUID customerId, String name, int age);
    void deleteCustomer(UUID customerId);
    void markCustomerInactive(UUID customerId);
}

class IdentityVerificationService {
    public boolean verify(String token) {
        // Verify the token with the third-party identity service
        return true; // Placeholder for actual verification logic
    }
}
