```java
import static org.mockito.Mockito.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.http.MediaType;
import org.springframework.security.test.context.support.WithMockUser;
import org.springframework.test.web.servlet.MockMvc;

@WebMvcTest(CustomerController.class)
public class CustomerControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private CustomerService customerService;

    @MockBean
    private IdentityVerificationService identityVerificationService;

    @Test
    @WithMockUser(username = "admin", roles = {"ADMIN"})
    public void testUpdateCustomer() throws Exception {
        UUID customerId = UUID.randomUUID();
        String jsonRequest = "{\"name\":\"John Doe\",\"age\":30}";

        when(identityVerificationService.verify(anyString())).thenReturn(true);

        mockMvc.perform(put("/api/customers/" + customerId)
                .contentType(MediaType.APPLICATION_JSON)
                .content(jsonRequest))
                .andExpect(status().isOk());

        verify(customerService).updateCustomer(customerId, new CustomerUpdateRequest());
    }

    @Test
    public void testDeleteCustomer() throws Exception {
        UUID customerId = UUID.randomUUID();

        when(identityVerificationService.verify(anyString())).thenReturn(true);

        mockMvc.perform(delete("/api/customers/" + customerId)
                .header("Authorization", "Bearer token"))
                .andExpect(status().isOk());

        verify(customerService).deleteCustomer(customerId, false);
    }

    @Test
    public void testDeleteCustomerSoft() throws Exception {
        UUID customerId = UUID.randomUUID();

        when(identityVerificationService.verify(anyString())).thenReturn(true);

        mockMvc.perform(delete("/api/customers/" + customerId)
                .header("Authorization", "Bearer token")
                .param("softDelete", "true"))
                .andExpect(status().isOk());

        verify(customerService).deleteCustomer(customerId, true);
    }
}
