public class HtmlUpdateMiddleware : IMiddleware
{
    private readonly ConcurrentDictionary<string, HtmlTemplate> _htmlTemplates = new ConcurrentDictionary<string, HtmlTemplate>();
    private readonly Octree<GeospatialObject> _octree;
    private readonly ExternalDataService _externalDataService;
    private readonly ILogger _logger;

    public HtmlUpdateMiddleware(Octree<GeospatialObject> octree, ExternalDataService externalDataService, ILogger logger)
    {
        _octree = octree ?? throw new ArgumentNullException(nameof(octree));
        _externalDataService = externalDataService ?? throw new ArgumentNullException(nameof(externalDataService));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task InvokeAsync(HttpContext context, RequestDelegate next)
    {
        if (context.Request.Method != HttpMethods.Post)
        {
            await next(context);
            return;
        }

        var templateKey = context.Request.Query["templateKey"];
        if (string.IsNullOrEmpty(templateKey))
        {
            context.Response.StatusCode = StatusCodes.Status400BadRequest;
            await context.Response.WriteAsync("Template key is required.");
            return;
        }

        HtmlTemplate template;
        if (!_htmlTemplates.TryGetValue(templateKey, out template))
        {
            try
            {
                template = await _externalDataService.FetchHtmlTemplate(templateKey);
                if (template == null)
                {
                    context.Response.StatusCode = StatusCodes.Status404NotFound;
                    await context.Response.WriteAsync("Template not found.");
                    return;
                }

                _htmlTemplates.TryAdd(templateKey, template);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to fetch HTML template.");
                context.Response.StatusCode = StatusCodes.Status500InternalServerError;
                await context.Response.WriteAsync("Internal server error.");
                return;
            }
        }

        if (!await ValidateUserPermissions(context.Request.Headers["Authorization"]))
        {
            context.Response.StatusCode = StatusCodes.Status403Forbidden;
            await context.Response.WriteAsync("Access denied.");
            return;
        }

        var updatedHtml = UpdateHtmlElements(template, context.Request.Body);
        context.Response.ContentType = "text/html";
        await context.Response.WriteAsync(updatedHtml);

        _logger.LogInformation($"HTML template '{templateKey}' updated successfully.");
    }

    private async Task<string> UpdateHtmlElements(HtmlTemplate template, Stream requestBody)
    {
        // Read request body and update HTML elements here
        return template.Content;
    }

    private async Task<bool> ValidateUserPermissions(string authorizationHeader)
    {
        // Implement user permission validation logic here
        return true;
    }
}
