const fs = require('fs');
const path = require('path');
const http = require('http');
const crypto = require('crypto');

// External Logging API
class LoggingService {
  constructor(apiUrl, apiKey) {
    this.apiUrl = apiUrl;
    this.apiKey = apiKey;
  }

  async enrichLog(logData) {
    const options = {
      method: 'POST',
      url: this.apiUrl,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${this.apiKey}`
      },
      body: JSON.stringify(logData),
      json: true
    };

    return new Promise((resolve, reject) => {
      http.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => { data += chunk; });
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            resolve(JSON.parse(data));
          } else {
            reject(new Error(`API error: ${data}`));
          }
        });
      }).on('error', (err) => {
        reject(err);
      }).end();
    });
  }

  async detectAnomalies(logData) {
    // Placeholder for anomaly detection logic
    return { anomalies: logData.some(item => item.level === 'ERROR') };
  }
}

// File Processor
class FileProcessor {
  constructor(directory, loggingService) {
    this.directory = directory;
    this.loggingService = loggingService;
    this.cache = new Map();
    this.supportedFormats = ['json', 'csv'];
  }

  async processFiles() {
    for (const file of await fs.promises.readdir(this.directory)) {
      const filePath = path.join(this.directory, file);
      if (this.supportedFormats.includes(path.extname(filePath).slice(1))) {
        try {
          const content = await this.readAndCacheFile(filePath);
          const enrichedLog = await this.loggingService.enrichLog(content);
          const anomalies = await this.loggingService.detectAnomalies(enrichedLog);
          console.log(`Processed ${file}:`, { anomalies });
        } catch (error) {
          console.error(`Failed to process ${file}:`, error.message);
        }
      }
    }
  }

  async readAndCacheFile(filePath) {
    if (this.cache.has(filePath)) {
      return this.cache.get(filePath);
    } else {
      const content = await fs.promises.readFile(filePath, 'utf8');
      try {
        const data = JSON.parse(content); // Adjust for different file types
        this.cache.set(filePath, data);
        return data;
      } catch (error) {
        throw new Error('Invalid file format');
      }
    }
  }

  async addSupportedFormat(format) {
    if (!this.supportedFormats.includes(format)) {
      this.supportedFormats.push(format);
    }
  }
}

// Main Application
const main = async () => {
  const directory = '/path/to/log/files';
  const loggingService = new LoggingService('https://api.logging.com', 'your-api-key');
  const fileProcessor = new FileProcessor(directory, loggingService);

  await fileProcessor.processFiles();
};

main().catch(console.error);
```

