import { v4 as uuidv4 } from 'uuid';
import fetch from 'node-fetch';

const scriptCache = new Map();
let pendingRequests = {};

async function getScriptContent(url) {
  if (pendingRequests[url]) {
    return pendingRequests[url];
  }

  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error('Network response was not ok');
    return response.text();
  } catch (error) {
    console.error(`Failed to fetch script from ${url}:`, error);
    throw error;
  }
}

function isValidScript(scriptContent) {
  try {
    Function('"use strict";return (' + scriptContent + ')');
    return true;
  } catch (e) {
    return false;
  }
}

async function renderFooterScripts(scriptUrls) {
  const uniqueScripts = new Map();

  for (const url of scriptUrls) {
    if (!uniqueScripts.has(url)) {
      let scriptContent = scriptCache.get(url);
      if (!scriptContent) {
        scriptContent = await getScriptContent(url);
        scriptCache.set(url, scriptContent);
      }

      if (isValidScript(scriptContent)) {
        uniqueScripts.set(url, { url, content: scriptContent });
      } else {
        console.warn(`Invalid script from ${url}. Skipping rendering.`);
      }
    }
  }

  const scriptTags = Array.from(uniqueScripts.values()).map(script => {
    return `<script id="${uuidv4()}" src="javascript:void(0)">${script.content}</script>`;
  });

  return `<footer>${scriptTags.join('')}</footer>`;
}

// Example usage
const scriptUrls = [
  'https://example.com/script1.js',
  'https://example.com/script2.js',
  'https://example.com/script1.js' // Duplicate URL to test caching
];

renderFooterScripts(scriptUrls).then(html => {
  console.log(html);
}).catch(error => {
  console.error('Error rendering footer scripts:', error);
});
```

