app.service('BookDialogService', ['$http', '$q', 'CacheFactory', 'logger',
  function($http, $q, CacheFactory, logger) {
    var service = this;
    var cache = CacheFactory.get('bookCache') || CacheFactory.createCache('bookCache');

    // Configuration options
    service.config = {
      apiEndpoint: 'https://api.example.com/validate',
      retryInterval: 1000,
      maxRetries: 3
    };

    // Regular expression to match book names in the Old Testament
    var bookRegex = /(\b[A-Z][a-z]*\b)/g;

    // Function to extract book names from a field value
    function extractBookNames(value) {
      return value.match(bookRegex);
    }

    // Function to validate changes and send them to the parent window
    service.validateAndSendChanges = function(fieldId, newValue) {
      var deferred = $q.defer();
      var retries = 0;

      function retry() {
        if (retries >= service.config.maxRetries) {
          deferred.reject('Max retries reached');
          return;
        }

        $http.post(service.config.apiEndpoint, { fieldId: fieldId, newValue: newValue })
          .then(function(response) {
            if (response.data.success) {
              deferred.resolve(response.data);
            } else {
              logger.error('Validation failed:', response.data.message);
              retries++;
              setTimeout(retry, service.config.retryInterval);
            }
          })
          .catch(function(error) {
            logger.error('Request failed:', error);
            retries++;
            setTimeout(retry, service.config.retryInterval);
          });
      }

      retry();
      return deferred.promise;
    };

    // Function to refresh specific dialog fields
    service.refreshFields = function(fieldIds) {
      angular.forEach(fieldIds, function(fieldId) {
        var field = document.getElementById(fieldId);
        if (field) {
          var currentValue = field.value;
          var bookNames = extractBookNames(currentValue);

          service.validateAndSendChanges(fieldId, currentValue)
            .then(function(result) {
              // Update the dialog field with validation result
              field.value = result.validatedValue;
            })
            .catch(function(error) {
              // Provide user feedback for transient failures
              alert('Failed to validate changes. Please try again.');
            });
        }
      });
    };

    return service;
  }
]);

// Define a directive to use the BookDialogService
