class DataCollector {
  constructor(apiUrl, storageKey, maxCacheSize) {
    this.apiUrl = apiUrl;
    this.storageKey = storageKey;
    this.maxCacheSize = maxCacheSize;
    this.isPaused = false;
    this.cache = JSON.parse(localStorage.getItem(storageKey)) || {};
    this.metricsQueue = [];
    this.processMetricsInterval = null;
    this.setupListeners();
  }

  setupListeners() {
    window.addEventListener('storage', (event) => {
      if (event.key === this.storageKey && !this.isPaused) {
        this.processCachedMetrics();
      }
    });
  }

  async fetchData() {
    try {
      const response = await fetch(this.apiUrl);
      if (!response.ok) throw new Error('Network response was not ok');
      const data = await response.json();
      return data.metrics;
    } catch (error) {
      console.error('Failed to fetch metrics:', error);
      return [];
    }
  }

  async processMetrics() {
    while (!this.isPaused && this.metricsQueue.length > 0) {
      const metrics = this.metricsQueue.shift();
      try {
        await this.saveToStorage(metrics);
        if (Object.keys(this.cache).length > this.maxCacheSize) {
          const oldestKey = Object.keys(this.cache)[0];
          delete this.cache[oldestKey];
          localStorage.setItem(this.storageKey, JSON.stringify(this.cache));
        }
      } catch (error) {
        console.error('Error processing metrics:', error);
        this.metricsQueue.unshift(metrics); // Retry
        break;
      }
    }
  }

  async saveToStorage(metrics) {
    Object.assign(this.cache, metrics);
    localStorage.setItem(this.storageKey, JSON.stringify(this.cache));
  }

  startCollecting() {
    if (this.processMetricsInterval) return;
    this.isPaused = false;
    this.processMetrics();
    this.processMetricsInterval = setInterval(() => this.processMetrics(), 1000);
  }

  pauseCollecting() {
    this.isPaused = true;
    clearInterval(this.processMetricsInterval);
    this.processMetricsInterval = null;
  }

  addMetricsToQueue(metrics) {
    if (this.metricsQueue.length === 0) {
      this.processMetrics();
    }
    this.metricsQueue.push(metrics);
  }

  async loadCachedMetrics() {
    return Object.values(this.cache);
  }

  logIngestionRate() {
    // Implement logging logic here
  }

  customizePipeline(pipelineFunction) {
    this.pipelineFunction = pipelineFunction;
  }

  extendFeature(featureFunction) {
    this.featureFunction = featureFunction;
  }
}
```

This code provides a basic structure for the DataCollector class. It includes methods to fetch data from an API, process metrics asynchronously, manage caching, handle network failures with retry logic, and log ingestion rates. The class is designed to be scalable, asynchronous, and extensible for future features like real-time alerts or analytics reports."]

