// JavaScript function to copy a specified number of bytes from a list of buffered data chunks

function copyBufferedData(chunks, byteCount) {
    const newBuffer = Buffer.allocUnsafe(byteCount);
    let copiedBytes = 0;

    for (let i = 0; i < chunks.length && copiedBytes < byteCount; i++) {
        const chunk = chunks[i];
        const bytesToCopy = Math.min(chunk.length - chunk.copy(newBuffer, copiedBytes), byteCount - copiedBytes);
        copiedBytes += chunk.copy(newBuffer, copiedBytes, 0, bytesToCopy);
    }

    return newBuffer.slice(0, byteCount);
}

