#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

#define MAX_URL_LENGTH 1024
#define MAX_LINE_LENGTH 4096

typedef struct {
    CURL *curl_handle;
    FILE *output_file;
} ConfigFetcher;

void init_config_fetcher(ConfigFetcher *fetcher, const char *api_url) {
    fetcher->curl_handle = curl_easy_init();
    if (fetcher->curl_handle) {
        curl_easy_setopt(fetcher->curl_handle, CURLOPT_URL, api_url);
        curl_easy_setopt(fetcher->curl_handle, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(fetcher->curl_handle, CURLOPT_WRITEDATA, fetcher->output_file);
    }
}

void cleanup_config_fetcher(ConfigFetcher *fetcher) {
    if (fetcher->curl_handle) {
        curl_easy_cleanup(fetcher->curl_handle);
    }
    if (fetcher->output_file && fetcher->output_file != stdout) {
        fclose(fetcher->output_file);
    }
}

size_t write_data(void *ptr, size_t size, size_t nmemb, void *userdata) {
    ConfigFetcher *fetcher = (ConfigFetcher *)userdata;
    return fwrite(ptr, size, nmemb, fetcher->output_file);
}

int fetch_config_files(ConfigFetcher *fetcher, const char *api_url, FILE *output_file) {
    init_config_fetcher(fetcher, api_url);
    if (!fetcher->curl_handle) {
        return -1;
    }
    fetcher->output_file = output_file;
    CURLcode res = curl_easy_perform(fetcher->curl_handle);
    cleanup_config_fetcher(fetcher);
    return (res == CURLE_OK) ? 0 : -1;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <api_url>\n", argv[0]);
        return 1;
    }

    ConfigFetcher fetcher;
    FILE *output_file = stdout;

    int result = fetch_config_files(&fetcher, argv[1], output_file);
    if (result != 0) {
        fprintf(stderr, "Failed to fetch configuration files.\n");
        return 1;
    }

    printf("Configuration files fetched successfully.\n");
    return 0;
}
```

