class CoPrimeFinder {

    private final UnionFind unionFind = new UnionFind();

    public boolean isCoPrime(int[] factors) {
        for (int factor : factors) {
            if (!unionFind.union(factor)) {
                return false;
            }
        }
        return true;
    }

    private static class UnionFind {

        private int[] parent;

        public UnionFind() {
            // Initialize parent array
        }

        public boolean union(int x) {
            int rootX = find(x);
            if (rootX != 0) {
                return false;
            }
            parent[x] = x;
            return true;
        }

        private int find(int x) {
            if (parent[x] == x) {
                return x;
            }
            parent[x] = find(parent[x]);
            return parent[x];
        }
    }
}

class TransactionDetails {

    private int[] factors;

    public int[] getFactors() {
        // Return transaction factors
        return factors;
    }

    public void setFactors(int[] factors) {
        this.factors = factors;
    }
}
