	"errors"
	"fmt"
	"net/http"
	"sync"
	"time"

	"github.com/golang-jwt/jwt/v4"
)

// TokenManager manages user tokens for a microservices architecture.
type TokenManager struct {
	authServerURL string
	client        *http.Client
	cache         sync.Map
	ttl           time.Duration
}

// NewTokenManager creates a new TokenManager instance.
func NewTokenManager(authServerURL string, ttl time.Duration) *TokenManager {
	return &TokenManager{
		authServerURL: authServerURL,
		client:        http.DefaultClient,
		ttl:           ttl,
	}
}

// Authenticate validates a user token and returns the claims if valid.
func (tm *TokenManager) Authenticate(ctx context.Context, tokenString string) (*jwt.Token, error) {
	if cachedToken, ok := tm.cache.Load(tokenString); ok {
		return cachedToken.(*jwt.Token), nil
	}

	token, err := tm.fetchTokenFromAuthServer(ctx, tokenString)
	if err != nil {
		return nil, err
	}

	tm.cache.Store(tokenString, token, sync.MapEntry{Value: time.Now().Add(tm.ttl)})
	return token, nil
}

// fetchTokenFromAuthServer retrieves a token from the external authentication server.
func (tm *TokenManager) fetchTokenFromAuthServer(ctx context.Context, tokenString string) (*jwt.Token, error) {
	req, err := http.NewRequestWithContext(ctx, "POST", tm.authServerURL, nil)
	if err != nil {
		return nil, fmt.Errorf("failed to create request: %w", err)
	}

	resp, err := tm.client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("failed to make request: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode == http.StatusOK {
		var token *jwt.Token
		// Parse the token here (not shown for brevity)
		return token, nil
	}

	return nil, errors.New("authentication server returned an error")
}

// BlacklistToken invalidates a user token.
func (tm *TokenManager) BlacklistToken(ctx context.Context, tokenString string) error {
	// Logic to blacklist the token in the external authentication server
	return nil
}

func main() {
	authServerURL := "https://auth.example.com/validate"
	ttl := 5 * time.Minute

	tokenManager := NewTokenManager(authServerURL, ttl)

	// Example usage
	ctx := context.Background()
	tokenString := "example_token"
	claims, err := tokenManager.Authenticate(ctx, tokenString)
	if err != nil {
		fmt.Println("Authentication failed:", err)
	} else {
		fmt.Printf("Authenticated with claims: %+v\n", claims.Claims.(jwt.MapClaims))
	}
}
