use std::env;
use std::fs;
use std::path::PathBuf;
use std::process::{Command, Stdio};
use yaml_rust::YamlLoader;
use rustc_driver::{self, Compilation, run_compiler};
use tokio::sync::Mutex;

struct ResourceBundle {
    items: Vec<String>,
}

impl ResourceBundle {
    fn new(file_path: &str) -> Result<Self, std::io::Error> {
        let contents = fs::read_to_string(file_path)?;
        let yaml = YamlLoader::load_from_str(&contents).unwrap()[0].clone();
        let items = if let Some(items) = yaml["items"].as_vec() {
            items.iter().map(|item| item.as_str().unwrap().to_string()).collect()
        } else {
            Vec::new()
        };
        Ok(ResourceBundle { items })
    }

    fn limit_memory(&self, max_items: usize) -> Self {
        let limited_items = self.items.iter().take(max_items).cloned().collect();
        ResourceBundle { items: limited_items }
    }
}

async fn compile_and_manage_resources(config_path: &str, resource_path: &str, max_resource_items: usize) -> (i32, usize) {
    let config = match YamlLoader::load_from_str(&fs::read_to_string(config_path).unwrap()) {
        Ok(yaml) => yaml[0].clone(),
        Err(_) => return (1, 0),
    };

    let dependencies = if let Some(dependencies) = config["dependencies"].as_vec() {
        dependencies.iter().map(|dep| dep.as_str().unwrap()).collect()
    } else {
        Vec::new()
    };

    for dep in dependencies {
        match Command::new("cargo").arg("install").arg(dep).output() {
            Ok(_) => continue,
            Err(_) => return (1, 0),
        }
    }

    let resource_bundle = ResourceBundle::new(resource_path)
        .map_err(|_| 1)?
        .limit_memory(max_resource_items);

    let start_time = std::time::Instant::now();
    let res = run_compiler(
        &[""],
        &rustc_driver::default_options(),
        None,
        |cx| cx.parse_input(rustc_interface::interface::Input::File(PathBuf::from("main.rs"))),
        rustc_driver::Callbacks {
            phase_change: Box::new(|_| {}),
            after_expansion: Box::new(|_| {}),
            before_codegen: Box::new(|_| {}),
            after_analysis: Box::new(|_| {}),
            compiler_has_error: Box::new(|_| {}),
            fatal_error_occurred: Box::new(|_| {}),
            early_exit: Box::new(|_| Compilation::Stop),
        },
    );
    let elapsed_time = start_time.elapsed();

    (res, resource_bundle.items.len())
}
