<?php

class DatabaseUpdater {
    private $pdo;
    private $apiKey;

    public function __construct($dbHost, $dbName, $dbUser, $dbPass, $apiKey) {
        try {
            $this->pdo = new PDO("mysql:host=$dbHost;dbname=$dbName", $dbUser, $dbPass);
            $this->pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
            $this->apiKey = $apiKey;
        } catch (PDOException $e) {
            error_log("Database connection failed: " . $e->getMessage());
            throw new Exception("Failed to connect to the database.");
        }
    }

    public function updateClinicStatus($clinicId, $status) {
        $ipAddress = $_SERVER['REMOTE_ADDR'];
        $lastModified = date('Y-m-d H:i:s');

        try {
            $sql = "UPDATE clinics SET status = :status, last_modified_ip = :ip_address, last_modified_date = :date WHERE id = :id";
            $stmt = $this->pdo->prepare($sql);
            $stmt->execute([
                ':status' => $status,
                ':ip_address' => $ipAddress,
                ':date' => $lastModified,
                ':id' => $clinicId
            ]);
        } catch (PDOException $e) {
            error_log("Database update failed: " . $e->getMessage());
            throw new Exception("Failed to update clinic status.");
        }

        return true;
    }
}

class SemaphoreManager {
    private $semaphore;

    public function __construct($maxConnections) {
        $this->semaphore = sem_get(1234, $maxConnections, 0666);
        if ($this->semaphore === false) {
            error_log("Failed to create semaphore.");
            throw new Exception("Failed to initialize semaphore manager.");
        }
    }

    public function acquire() {
        if (!sem_acquire($this->semaphore)) {
            error_log("Failed to acquire semaphore.");
            throw new Exception("Failed to acquire semaphore.");
        }
    }

    public function release() {
        sem_release($this->semaphore);
    }

    public function destroy() {
        sem_destroy($this->semaphore);
    }
}

?>
