#include <pthread.h>

#define MAX_CONNECTIONS 10

void* updateClinicStatus(void* args) {
    int clinicId = *(int*)args;
    char status[50] = "Active";
    // Simulate API call to fetch clinic details
    // Simulate database connection and update
    printf("Updating clinic %d with status %s\n", clinicId, status);
    return NULL;
}

void* manageSemaphore(void* args) {
    int maxConnections = *(int*)args;
    SemaphoreManager* manager = (SemaphoreManager*)malloc(sizeof(SemaphoreManager));
    manager->semaphore = sem_open("/clinics_semaphore", O_CREAT, 0666, maxConnections);
    if (manager->semaphore == SEM_FAILED) {
        perror("Failed to create semaphore");
        free(manager);
        return NULL;
    }

    pthread_t threads[maxConnections];
    int ids[maxConnections];

    for (int i = 0; i < maxConnections; i++) {
        ids[i] = i + 1;
        if (pthread_create(&threads[i], NULL, updateClinicStatus, &ids[i]) != 0) {
            perror("Failed to create thread");
            sem_close(manager->semaphore);
            free(manager);
            return NULL;
        }
    }

    for (int i = 0; i < maxConnections; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_close(manager->semaphore);
    sem_unlink("/clinics_semaphore");
    free(manager);

    return NULL;
}

int main() {
    int maxConnections = MAX_CONNECTIONS;
    if (pthread_create(NULL, NULL, manageSemaphore, &maxConnections) != 0) {
        perror("Failed to create semaphore management thread");
        return 1;
    }

