CREATE PROCEDURE GetEmployeeDetails(
    @SupervisorIDs INT[],
    @PageNumber INT,
    @PageSize INT,
    @Department NVARCHAR(50) = NULL,
    @JobTitle NVARCHAR(50) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        DECLARE @Offset INT;
        SET @Offset = (@PageNumber - 1) * @PageSize;

        SELECT TOP (@PageSize)
            E.EmployeeID,
            E.Name,
            E.City,
            E.Address,
            E.Department,
            E.JobTitle
        FROM Employees E
        WHERE EXISTS (
            SELECT 1
            FROM EmployeeSupervisors ES
            WHERE ES.EmployeeID = E.EmployeeID AND ES.SupervisorID IN @SupervisorIDs
        )
        AND (@Department IS NULL OR E.Department = @Department)
        AND (@JobTitle IS NULL OR E.JobTitle = @JobTitle)
        ORDER BY E.EmployeeID OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;

        SELECT COUNT(*)
        FROM Employees E
        WHERE EXISTS (
            SELECT 1
            FROM EmployeeSupervisors ES
            WHERE ES.EmployeeID = E.EmployeeID AND ES.SupervisorID IN @SupervisorIDs
        )
        AND (@Department IS NULL OR E.Department = @Department)
        AND (@JobTitle IS NULL OR E.JobTitle = @JobTitle);
    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000);
        DECLARE @ErrorSeverity INT;
        DECLARE @ErrorState INT;

        SELECT 
            @ErrorMessage = ERROR_MESSAGE(),
            @ErrorSeverity = ERROR_SEVERITY(),
            @ErrorState = ERROR_STATE();

        RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
