typedef struct State {
    int id;
    struct State* next;
} State;

typedef struct FSA {
    // Define the structure of your FSA here
} FSA;

State* create_state(int id) {
    State* new_state = (State*)malloc(sizeof(State));
    if (!new_state) {
        return NULL; // Handle out-of-memory condition
    }
    new_state->id = id;
    new_state->next = NULL;
    return new_state;
}

State* construct_state_list(int* states, int num_states, FSA* fsa, State* last_state) {
    if (num_states <= 0 || !states || !fsa || !last_state) {
        return NULL; // Handle invalid input configurations
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    State* head = create_state(states[0]);
    if (!head) {
        pthread_mutex_destroy(&lock);
        return NULL; // Handle out-of-memory condition
    }

    State* current = head;

    for (int i = 1; i < num_states; i++) {
        State* new_state = create_state(states[i]);
        if (!new_state) {
            // Cleanup allocated states in case of failure
            while (head != NULL) {
                State* temp = head;
                head = head->next;
                free(temp);
            }
            pthread_mutex_destroy(&lock);
            return NULL; // Handle out-of-memory condition
        }

        current->next = new_state;
        current = new_state;
    }

    last_state->next = head;

    pthread_mutex_destroy(&lock);

    return head;
}

void cleanup_state_list(State* state_list) {
    State* current = state_list;
    while (current != NULL) {
        State* temp = current;
        current = current->next;
        free(temp);
    }
}
