using System;
using System.Collections.Concurrent;
using System.Globalization;
using System.Xml.Linq;

namespace RandomValueGenerator
{
    public class RandomValueGenerator : IRandomValueGenerator
    {
        private readonly ConcurrentDictionary<string, Random> _randomCache = new ConcurrentDictionary<string, Random>();
        private readonly ILogger _logger;

        public RandomValueGenerator(ILogger logger)
        {
            _logger = logger;
        }

        public int GenerateInt(int min, bool includeMin, int max, bool includeMax)
        {
            ValidateRange(min, max);
            var key = $"{min}_{max}_{includeMin}_{includeMax}";
            return GetRandom(min, max, includeMin, includeMax, key).Next();
        }

        public float GenerateFloat(float min, bool includeMin, float max, bool includeMax)
        {
            ValidateRange(min, max);
            var key = $"{min}_{max}_{includeMin}_{includeMax}";
            return (float)GetRandom(min, max, includeMin, includeMax, key).NextDouble() * (includeMax ? 1 : -1);
        }

        private Random GetRandom(int min, int max, bool includeMin, bool includeMax, string key)
        {
            if (!_randomCache.TryGetValue(key, out var random))
            {
                random = new Random();
                _randomCache.TryAdd(key, random);
            }
            return random;
        }

        private void ValidateRange(double min, double max)
        {
            if (min > max)
                throw new ArgumentException("Min value cannot be greater than max value.");
        }
    }

    public interface IRandomValueGenerator
    {
        int GenerateInt(int min, bool includeMin, int max, bool includeMax);
        float GenerateFloat(float min, bool includeMin, float max, bool includeMax);
    }

    public interface ILogger
    {
        void Log(string message);
    }
}
