using System.Net.Http;
using System.Threading.Tasks;

public abstract class ResourceLoader<T>
{
    protected readonly HttpClient _httpClient;
    private Dictionary<string, T> _cache = new Dictionary<string, T>();

    public ResourceLoader(HttpClient httpClient)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
    }

    public async Task<T> LoadAsync(string resourceUri, bool bypassCache = false)
    {
        if (string.IsNullOrEmpty(resourceUri))
            throw new ArgumentException("Resource URI cannot be null or empty.", nameof(resourceUri));

        var cachedResource = await GetCachedResourceAsync(resourceUri);
        if (cachedResource != null && !bypassCache)
            return cachedResource;

        try
        {
            var content = await _httpClient.GetStringAsync(resourceUri);
            var resource = Parse(content);
            StoreInCache(resourceUri, resource);
            return resource;
        }
        catch (HttpRequestException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            throw new ResourceNotFoundException("Resource not found.", ex);
        }
        catch (Exception ex)
        {
            throw new ResourceLoadException("Failed to load resource.", ex);
        }
    }

    protected abstract Task<T> GetCachedResourceAsync(string uri);
    protected abstract T Parse(string content);
    protected abstract void StoreInCache(string uri, T resource);

    public void ClearCache()
    {
        _cache.Clear();
    }
}

public class JsonResourceLoader : ResourceLoader<JsonResource>
{
    public JsonResourceLoader(HttpClient httpClient) : base(httpClient)
    {
    }

    protected override async Task<JsonResource> GetCachedResourceAsync(string uri)
    {
        if (_cache.TryGetValue(uri, out var cachedResource))
            return cachedResource;

        return null;
    }

    protected override JsonResource Parse(string content)
    {
        // Implement JSON parsing logic here
        throw new NotImplementedException();
    }

    protected override void StoreInCache(string uri, JsonResource resource)
    {
        _cache[uri] = resource;
    }
}

