{
    public XmlResourceLoader(HttpClient httpClient) : base(httpClient)
    {
    }

    protected override async Task<XmlResource> GetCachedResourceAsync(string uri)
    {
        if (_cache.TryGetValue(uri, out var cachedResource))
            return cachedResource;

        return null;
    }

    protected override XmlResource Parse(string content)
    {
        // Implement XML parsing logic here
        throw new NotImplementedException();
    }

    protected override void StoreInCache(string uri, XmlResource resource)
    {
        _cache[uri] = resource;
    }
}

public class ResourceNotFoundException : Exception { }
public class ResourceLoadException : Exception { }

// Example usage:
public class JsonResource { /* Define your JSON resource model here */ }
public class XmlResource { /* Define your XML resource model here */ }

class Program
{
    static async Task Main(string[] args)
    {
        var httpClient = new HttpClient();
        var jsonLoader = new JsonResourceLoader(httpClient);
        var xmlLoader = new XmlResourceLoader(httpClient);

        try
        {
            var jsonResource = await jsonLoader.LoadAsync("https://example.com/resource.json");
            var xmlResource = await xmlLoader.LoadAsync("https://example.com/resource.xml");

            // Use the loaded resources
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
