['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    pthread_mutex_t mutex;
    char *data;
    size_t length;
} ExternalDataSource;

void initDataSource(ExternalDataSource *ds) {
    pthread_mutex_init(&ds->mutex, NULL);
    ds->data = NULL;
    ds->length = 0;
}

void setDataSourceData(ExternalDataSource *ds, const char *new_data, size_t new_length) {
    pthread_mutex_lock(&ds->mutex);
    free(ds->data);
    ds->data = (char *)malloc(new_length + 1);
    strncpy(ds->data, new_data, new_length);
    ds->data[new_length] = '\0';
    ds->length = new_length;
    pthread_mutex_unlock(&ds->mutex);
}

const char* getDataSourceData(ExternalDataSource *ds) {
    pthread_mutex_lock(&ds->mutex);
    const char *result = ds->data;
    pthread_mutex_unlock(&ds->mutex);
    return result;
}

size_t getDataSourceLength(ExternalDataSource *ds) {
    pthread_mutex_lock(&ds->mutex);
    size_t length = ds->length;
    pthread_mutex_unlock(&ds->mutex);
    return length;
}

int appendStringWithLimit(const char *input, int limit, char *buffer, int bufferSize) {
    if (input == NULL || buffer == NULL || bufferSize <= 0) {
        return -1; // Invalid input
    }

    ExternalDataSource ds;
    initDataSource(&ds);

    // Simulate fetching data from an external source
    const char *externalData = "This is a long string that needs to be appended with limits.";
    setDataSourceData(&ds, externalData, strlen(externalData));

    size_t resultLength = 0;
    while (resultLength < bufferSize - 1) {
        const char *dataSegment = getDataSourceData(&ds);
        size_t segmentLength = getDataSourceLength(&ds);

        if (segmentLength == 0) {
            break; // No more data available
        }

        size_t remainingSpace = bufferSize - resultLength - 1;
        size_t segmentToCopy = (segmentLength < remainingSpace) ? segmentLength : remainingSpace;

        memcpy(buffer + resultLength, dataSegment, segmentToCopy);
        resultLength += segmentToCopy;

        // Simulate processing the fetched data
        sleep(1); // Delay to simulate external data retrieval time
    }

    if (resultLength == bufferSize - 1) {
        buffer[resultLength] = '\0'; // Ensure null termination within limit
    } else {
        buffer[resultLength] = '\0'; // Null terminate the string
    }

    free(ds.data);
    pthread_mutex_destroy(&ds.mutex);

    return 0; // Success
}
