#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024

void compute_moving_average(const char* log_file, int n) {
    FILE* file = fopen(log_file, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    char buffer[BUFFER_SIZE];
    double *moving_avg_buffer = (double *)malloc(n * sizeof(double));
    if (!moving_avg_buffer) {
        perror("Memory allocation failed");
        fclose(file);
        return;
    }

    int i, count = 0, read_count = 0;
    while (fgets(buffer, BUFFER_SIZE, file)) {
        char* token = strtok(buffer, ",");
        for (i = 0; i < n && token != NULL; i++) {
            double value = atof(token);
            moving_avg_buffer[i] = value;
            token = strtok(NULL, ",");
        }

        if (count >= n) {
            // Calculate moving average
            double sum = 0.0;
            for (i = 0; i < n; i++) {
                sum += moving_avg_buffer[i];
            }
            printf("Moving Average: %f\n", sum / n);
        }

        count++;
    }

    free(moving_avg_buffer);
    fclose(file);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <log_file> <n>\n", argv[0]);
        return 1;
    }

    const char* log_file = argv[1];
    int n = atoi(argv[2]);

    compute_moving_average(log_file, n);

    return 0;
}
