```cpp
// audio_library.cpp

#include "audio_library.h"
#include <fstream>
#include <stdexcept>

std::shared_ptr<AudioFile> AudioLibrary::createAudioFile(const std::string& filePath) {
    std::ifstream file(filePath, std::ios::binary);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open audio file: " + filePath);
    }

    // Determine the format based on the header
    char buffer[12];
    file.read(buffer, 12);

    if (strncmp(buffer, "RIFF", 4) == 0 && strncmp(buffer + 8, "WAVE", 4) == 0) {
        return std::make_shared<WAVFile>();
    } else if (strncmp(buffer, "fLaC", 4) == 0) {
        return std::make_shared<FLACFile>();
    } else if (strncmp(buffer, "FORM", 4) == 0 && strncmp(buffer + 8, "AIFF", 4) == 0) {
        return std::make_shared<AIFFFile>();
    }

    throw std::runtime_error("Unsupported audio format");
}

void AudioLibrary::addAudioFile(std::shared_ptr<AudioFile> file) {
    files.push_back(file);
}

void AudioLibrary::removeAudioFile(std::shared_ptr<AudioFile> file) {
    files.erase(std::remove(files.begin(), files.end(), file), files.end());
}

void AudioLibrary::playAllFiles() {
    for (auto& file : files) {
        file->play();
    }
}

void AudioLibrary::analyzeAllFiles() {
    for (auto& file : files) {
        file->analyze();
    }
}
