        auto wavFile = AudioLibrary::createAudioFile("example.wav");
        auto flacFile = AudioLibrary::createAudioFile("example.flac");

        library->addAudioFile(wavFile);
        library->addAudioFile(flacFile);

        library->playAllFiles();
        library->analyzeAllFiles();

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
