// Function to derive a key from a password using PBKDF2 with SHA-256
int derive_key(const unsigned char *password, size_t password_len,
              const unsigned char *salt, size_t salt_len,
              unsigned char *key, int key_len) {
    PKCS5_PBKDF2_HMAC_SHA1(password, password_len, salt, salt_len, 4096, key, key_len);
    return 0;
}

// Function to encrypt data using AES-256-CBC
int encrypt_data(const unsigned char *key, const unsigned char *iv,
                 const unsigned char *plaintext, size_t plaintext_len,
                 unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx || !EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int len;
    if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len) ||
        !EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext[len] = '\0';
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

// Function to decrypt data using AES-256-CBC
int decrypt_data(const unsigned char *key, const unsigned char *iv,
                 const unsigned char *ciphertext, size_t ciphertext_len,
                 unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx || !EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int len;
    if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len) ||
        !EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext[len] = '\0';
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

