#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <stdexcept>

class MediaProcessor {
public:
    void addFile(const std::string& filePath, const std::string& outputFormat) {
        std::lock_guard<std::mutex> lock(queueMutex);
        fileQueue.push({filePath, outputFormat});
        condition.notify_one();
    }

    void startProcessing() {
        workerThread = std::thread(&MediaProcessor::processFiles, this);
    }

    ~MediaProcessor() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

private:
    struct Task {
        std::string filePath;
        std::string outputFormat;
    };

    void processFiles() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            condition.wait(lock, [this] { return stop || !fileQueue.empty(); });
            if (stop && fileQueue.empty()) {
                break;
            }
            Task task = fileQueue.front();
            fileQueue.pop();
            lock.unlock();

            try {
                // Implement format conversion logic here
                std::cout << "Processing: " << task.filePath << " -> " << task.outputFormat << std::endl;
            } catch (const std::exception& e) {
                std::cerr << "Error processing file: " << e.what() << std::endl;
            }
        }
    }

    std::queue<Task> fileQueue;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool stop = false;
    std::thread workerThread;
};

int main() {
    MediaProcessor processor;
    processor.addFile("input.jpg", "PNG");
    processor.addFile("video.mp4", "MP4");
    processor.startProcessing();
    return 0;
}
