#include <sys/types.h>

// Define a structure for background task information
typedef struct {
    void (*task_function)(void*);
    void* task_data;
    pthread_t thread_id;
    int is_running;
} BackgroundTask;

// Function to execute the background task
void* execute_task(void* arg) {
    BackgroundTask* task = (BackgroundTask*)arg;
    task->is_running = 1;
    task->task_function(task->task_data);
    task->is_running = 0;
    return NULL;
}

// Function to initialize a new background task
void init_background_task(BackgroundTask* task, void (*func)(void*), void* data) {
    memset(task, 0, sizeof(BackgroundTask));
    task->task_function = func;
    task->task_data = data;
    pthread_create(&task->thread_id, NULL, execute_task, task);
}

// Function to check if a background task is running
int is_task_running(const BackgroundTask* task) {
    return task->is_running;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    printf("Received signal %d, terminating background tasks...\n", signum);
    // Implement termination logic here
    exit(0);
}

// Function to set up the signal handler
void setup_signal_handler() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        exit(1);
    }
}

// Example task function
void example_task(void* data) {
    int* id = (int*)data;
    printf("Task running with ID: %d\n", *id);
    sleep(5); // Simulate long-running task
    printf("Task completed with ID: %d\n", *id);
}

int main() {
    setup_signal_handler();

    BackgroundTask task1, task2;
    int id1 = 1, id2 = 2;

    init_background_task(&task1, example_task, &id1);
    init_background_task(&task2, example_task, &id2);

    while (is_task_running(&task1) || is_task_running(&task2)) {
        sleep(1); // Check task status periodically
    }

    printf("All tasks completed.\n");
    return 0;
}
```

This code provides a basic framework for creating a modular C library to manage background tasks. It includes functions to initialize, check the status of, and handle signal-based shutdown of background tasks. The `example_task` function demonstrates how task logic might be implemented.']

