typedef struct {
    char *token;
    CURL *curl_handle;
    RedisContext *redis_context;
} TokenValidationData;

void *validate_token(void *data) {
    TokenValidationData *validation_data = (TokenValidationData *)data;
    char *response_buffer = NULL;
    size_t response_size = 0;

    // Check cache first
    redisReply *reply = (redisReply *)redisCommand(validation_data->redis_context, "GET %s", validation_data->token);
    if (reply != NULL && reply->type == REDIS_REPLY_STRING) {
        freeResponse(reply);
        return (void *)true;
    }

    // Cache miss, fetch from external service
    CURLcode res = curl_easy_setopt(validation_data->curl_handle, CURLOPT_URL, "https://authservice.com/validate");
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to set URL: %s\n", curl_easy_strerror(res));
        return (void *)false;
    }

    res = curl_easy_setopt(validation_data->curl_handle, CURLOPT_POSTFIELDS, validation_data->token);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to set POST fields: %s\n", curl_easy_strerror(res));
        return (void *)false;
    }

    res = curl_easy_setopt(validation_data->curl_handle, CURLOPT_WRITEFUNCTION, write_callback);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to set write callback: %s\n", curl_easy_strerror(res));
        return (void *)false;
    }

    res = curl_easy_setopt(validation_data->curl_handle, CURLOPT_WRITEDATA, &response_buffer);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to set write data: %s\n", curl_easy_strerror(res));
        return (void *)false;
    }

    CURLcode response_code = curl_easy_perform(validation_data->curl_handle);
    if (response_code != CURLE_OK) {
        fprintf(stderr, "Curl request failed: %s\n", curl_easy_strerror(response_code));
        free(response_buffer);
        return (void *)false;
    }

    // Parse JSON response and check token validity
    bool is_valid = parse_json_response(response_buffer);

    if (is_valid) {
        redisReply *set_reply = (redisReply *)redisCommand(validation_data->redis_context, "SET %s %b EX %d", validation_data->token, response_buffer, strlen(response_buffer), TOKEN_CACHE_EXPIRY);
        if (set_reply != NULL && set_reply->type == REDIS_REPLY_STATUS) {
            freeResponse(set_reply);
        }
    }

    free(response_buffer);
    return (void *)is_valid;
}

int main() {
    CURL *curl_handle = curl_easy_init();
    RedisContext *redis_context = redisConnect("127.0.0.1", 6379);

    if (curl_handle == NULL || redis_context == NULL) {
        fprintf(stderr, "Failed to initialize CURL or Redis connection\n");
        return EXIT_FAILURE;
    }

    // Example token validation
    char *token = "example_token";
    TokenValidationData data = {token, curl_handle, redis_context};
    void *result = validate_token(&data);

    if (result != NULL) {
        printf("Token is %s\n", *(bool *)result ? "valid" : "invalid");
    }

    // Clean up
    free(result);
    curl_easy_cleanup(curl_handle);
    redisFree(redis_context);

    return EXIT_SUCCESS;
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t total_size = size * nmemb;
    char **buffer = (char **)userp;

    *buffer = realloc(*buffer, total_size + 1);
