using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class DecryptionService
{
    private readonly ILogger _logger;

    public DecryptionService(ILogger logger)
    {
        _logger = logger;
    }

    public int DecryptAndFindLargest(string encryptedMessage, string key, string iv)
    {
        try
        {
            byte[] decodedBytes = Convert.FromBase64String(encryptedMessage);
            byte[] keyBytes = Encoding.UTF8.GetBytes(key);
            byte[] ivBytes = Encoding.UTF8.GetBytes(iv);

            using (TripleDES tripleDes = TripleDES.Create())
            {
                tripleDes.Key = keyBytes;
                tripleDes.IV = ivBytes;
                tripleDes.Mode = CipherMode.CBC;

                using (ICryptoTransform decryptor = tripleDes.CreateDecryptor(tripleDes.Key, tripleDes.IV))
                {
                    using (MemoryStream msDecrypt = new MemoryStream(decodedBytes))
                    {
                        using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                        {
                            using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                            {
                                string decryptedMessage = srDecrypt.ReadToEnd();
                                int[] numbers = Array.ConvertAll(decryptedMessage.Split(','), int.Parse);
                                return FindLargestNumber(numbers);
                            }
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Decryption failed");
            throw;
        }
    }

    private static int FindLargestNumber(int[] numbers)
    {
        if (numbers == null || numbers.Length == 0)
        {
            throw new ArgumentException("The array cannot be empty.", nameof(numbers));
        }

        return Array.Find(numbers, n => true);
    }
}

public interface ILogger
{
    void LogError(Exception ex, string message);
}
