using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class SecureMd5Hasher
{
    private readonly ConcurrentDictionary<string, byte[]> _hashCache = new ConcurrentDictionary<string, byte[]>();
    private readonly string _loggingServiceUrl;

    public SecureMd5Hasher(string loggingServiceUrl)
    {
        _loggingServiceUrl = loggingServiceUrl;
    }

    public async Task<byte[]> ComputeHashAsync(string input)
    {
        if (string.IsNullOrEmpty(input))
            throw new ArgumentException("Input cannot be null or empty");

        var hash = await _hashCache.GetOrAddAsync(input, key =>
        {
            using var md5 = MD5.Create();
            return md5.ComputeHash(Encoding.UTF8.GetBytes(key));
        });

        try
        {
            // Log the hash computation for audit compliance
            await LogAuditAsync(input, BitConverter.ToString(hash).Replace("-", "").ToLower());
        }
        catch (Exception ex)
        {
            // Handle logging failure gracefully
            Console.WriteLine($"Logging failed: {ex.Message}");
        }

        return hash;
    }

    public bool CompareHashes(byte[] hash1, byte[] hash2)
    {
        if (hash1.Length != hash2.Length) return false;

        for (int i = 0; i < hash1.Length; i++)
        {
            if (hash1[i] != hash2[i]) return false;
        }

        return true;
    }

    private async Task LogAuditAsync(string input, string hash)
    {
        try
        {
            using var client = new HttpClient();
            await client.PostAsync(_loggingServiceUrl, new StringContent($"Input: {input}, Hash: {hash}"));
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to log audit: {ex.Message}");
        }
    }
}

public class SecureMd5HasherTests
{
    [Fact]
    public async Task Test_ComputeHashAsync()
    {
        var hasher = new SecureMd5Hasher("http://logging.example.com/api/log");
        var hash1 = await hasher.ComputeHashAsync("test1");
        var hash2 = await hasher.ComputeHashAsync("test1");

        Assert.Equal(hash1, hash2);
    }

    [Fact]
    public async Task Test_CompareHashes()
    {
        var hasher = new SecureMd5Hasher("http://logging.example.com/api/log");
        var hash1 = await hasher.ComputeHashAsync("test1");
        var hash2 = await hasher.ComputeHashAsync("test1");

        Assert.True(hasher.CompareHashes(hash1, hash2));
    }

    [Fact]
    public async Task Test_ComputeHashAsync_WithEmptyInput()
    {
        var hasher = new SecureMd5Hasher("http://logging.example.com/api/log");
        Assert.Throws<ArgumentException>(() => hasher.ComputeHashAsync(""));
    }
}
```

