import os
from Crypto.Cipher import AES, Camellia
from Crypto.Hash import MD5, SHA1
from Crypto.PublicKey import RSA
from Crypto.Signature import pkcs1_15
import requests

class GraphDatabase:
    def __init__(self):
        self.vertices = {}
        self.edges = {}

    def add_vertex(self, vertex_id):
        if vertex_id not in self.vertices:
            properties = self._generate_properties()
            encrypted_properties = self._encrypt_data(properties)
            hash_value = self._hash_data(encrypted_properties)
            self.vertices[vertex_id] = {'properties': encrypted_properties, 'hash': hash_value}
        else:
            raise ValueError(f"Vertex {vertex_id} already exists")

    def add_edge(self, vertex1_id, vertex2_id):
        if vertex1_id not in self.vertices or vertex2_id not in self.vertices:
            raise ValueError("One or both vertices do not exist")

        properties = self._generate_properties()
        encrypted_properties = self._encrypt_data(properties)
        hash_value = self._hash_data(encrypted_properties)

        if (vertex1_id, vertex2_id) not in self.edges and (vertex2_id, vertex1_id) not in self.edges:
            self.edges[(vertex1_id, vertex2_id)] = {'properties': encrypted_properties, 'hash': hash_value}
        else:
            raise ValueError(f"Edge between {vertex1_id} and {vertex2_id} already exists")

    def _generate_properties(self):
        return {key: os.urandom(16) for key in ['prop1', 'prop2', 'prop3']}

    def _encrypt_data(self, data):
        aes_key = os.urandom(16)
        camellia_key = os.urandom(16)

        aes_cipher = AES.new(aes_key, AES.MODE_ECB)
        camellia_cipher = Camellia.new(camellia_key, Camellia.MODE_ECB)

        encrypted_aes_key = self._rsa_encrypt(aes_key)
        encrypted_camellia_key = self._rsa_encrypt(camellia_key)

        aes_encrypted_data = aes_cipher.encrypt(os.urandom(16) + data['prop1'])
        camellia_encrypted_data = camellia_cipher.encrypt(os.urandom(16) + data['prop2'] + data['prop3'])

        return {
            'aes_key': encrypted_aes_key,
            'camellia_key': encrypted_camellia_key,
            'aes_encrypted_data': aes_encrypted_data,
            'camellia_encrypted_data': camellia_encrypted_data
        }

    def _rsa_encrypt(self, data):
        key = RSA.generate(2048)
        public_key = key.publickey()
        cipher_rsa = pkcs1_15.new(public_key)
        return cipher_rsa.encrypt(data)

    def _hash_data(self, data):
        md5_hash = MD5.new(data['aes_encrypted_data']).hexdigest()
        sha1_hash = SHA1.new(data['camellia_encrypted_data']).hexdigest()
        return f"MD5: {md5_hash}, SHA1: {sha1_hash}"

    def _rsa_sign(self, data):
        key = RSA.generate(2048)
        private_key = key
        signer_rsa = pkcs1_15.new(private_key)
        hash_object = SHA1.new(data['camellia_encrypted_data'])
        return signer_rsa.sign(hash_object)

# Example usage:
graph_db = GraphDatabase()
graph_db.add_vertex('vertex1')
graph_db.add_vertex('vertex2')
graph_db.add_edge('vertex1', 'vertex2')

response = requests.post('https://external-security-service.com/api/verify', json={
    'data': graph_db.vertices['vertex1'],
    'signature': graph_db._rsa_sign(graph_db.vertices['vertex1'])
})

print(response.text)
```']

