use std::env;
use std::fs::{self, DirBuilder};
use std::path::PathBuf;
use std::sync::{Mutex, Arc};
use std::time::Duration;
use backoff::{backoff, ExponentialBackoff};

struct DirectoryManager {
    config: Config,
    lock: Mutex<()>,
}

impl DirectoryManager {
    fn new(config: Config) -> Self {
        DirectoryManager {
            config,
            lock: Mutex::new(()),
        }
    }

    fn create_directory(&self) -> Result<(), Error> {
        let mut lock = self.lock.lock().unwrap();
        if !PathBuf::from(&self.config.dir_name).exists() {
            DirBuilder::new()
                .create(&self.config.dir_name)
                .with_context(|| format!("Failed to create directory: {}", self.config.dir_name))?;
        }
        Ok(())
    }

    fn set_env_variable(&self) -> Result<(), Error> {
        env::set_var("MY_DIR", &self.config.dir_name);
        Ok(())
    }

    fn cleanup(&self) -> Result<(), Error> {
        if PathBuf::from(&self.config.dir_name).exists() {
            fs::remove_dir_all(&self.config.dir_name)
                .with_context(|| format!("Failed to remove directory: {}", self.config.dir_name))?;
        }
        env::remove_var("MY_DIR");
        Ok(())
    }

    fn manage_directory(&self) -> Result<(), Error> {
        let mut backoff = ExponentialBackoff::default();
        while backoff.is_done() {
            match self.create_directory() {
                Ok(_) => break,
                Err(_) if backoff.is_done() => return Err(Error::new("Failed to create directory after retries")),
                _ => {
                    std::thread::sleep(backoff.next_backoff().unwrap_or(Duration::from_secs(1)));
                }
            };
        }

        self.set_env_variable()?;
        Ok(())
    }
}

struct Config {
    dir_name: String,
    logging_path: String,
}

#[derive(Debug)]
enum Error {
    Io(std::io::Error),
    Other(String),
}

impl Error {
    fn new(message: &str) -> Self {
        Error::Other(message.to_string())
    }

    fn with_context<F, R>(self, context: F) -> Self
    where
        F: FnOnce() -> String,
    {
        match self {
            Error::Io(err) => Error::Io(err),
            Error::Other(msg) => Error::Other(format!("{}: {}", context(), msg)),
        }
    }
}

impl From<std::io::Error> for Error {
    fn from(err: std::io::Error) -> Self {
        Error::Io(err)
    }
}
```

