from typing import Any, Dict, List, Optional, Type
import requests
from threading import Lock

class JsonSerializer(abc.ABC):
    @abc.abstractmethod
    def serialize(self, data: Any) -> str:
        pass

    @abc.abstractmethod
    def deserialize(self, json_str: str) -> Any:
        pass

class UserSerializer(JsonSerializer):
    def serialize(self, user: Dict[str, Any]) -> str:
        return json.dumps(user)

    def deserialize(self, json_str: str) -> Dict[str, Any]:
        return json.loads(json_str)

class PostSerializer(JsonSerializer):
    def serialize(self, post: Dict[str, Any]) -> str:
        return json.dumps(post)

    def deserialize(self, json_str: str) -> Dict[str, Any]:
        return json.loads(json_str)

class CommentSerializer(JsonSerializer):
    def serialize(self, comment: Dict[str, Any]) -> str:
        return json.dumps(comment)

    def deserialize(self, json_str: str) -> Dict[str, Any]:
        return json.loads(json_str)

class SerializerFactory:
    _serializers = {
        "user": UserSerializer(),
        "post": PostSerializer(),
        "comment": CommentSerializer()
    }
    _lock = Lock()

    @staticmethod
    def get_serializer(id: str) -> JsonSerializer:
        with SerializerFactory._lock:
            if id in SerializerFactory._serializers:
                return SerializerFactory._serializers[id]
            else:
                raise ValueError(f"Invalid serializer ID: {id}")

class ThirdPartyAPIClient:
    BASE_URL = "https://api.example.com"
    HEADERS = {"Authorization": "Bearer YOUR_API_TOKEN"}
    _session = requests.Session()

    @staticmethod
    def get_data(id: str) -> Dict[str, Any]:
        response = SerializerFactory._session.get(f"{ThirdPartyAPIClient.BASE_URL}/{id}", headers=ThirdPartyAPIClient.HEADERS)
        response.raise_for_status()
        return response.json()

class JsonSerializerCache:
    _cache = {}
    _lock = Lock()

    @staticmethod
    def get_serialized_object(id: str, serializer_id: str) -> Any:
        with JsonSerializerCache._lock:
            if id in JsonSerializerCache._cache:
                return JsonSerializerCache._cache[id]
            else:
                data = ThirdPartyAPIClient.get_data(id)
                serializer = SerializerFactory.get_serializer(serializer_id)
                serialized_data = serializer.serialize(data)
                JsonSerializerCache._cache[id] = serialized_data
                return serialized_data

    @staticmethod
    def get_deserialized_object(id: str, serializer_id: str) -> Any:
        with JsonSerializerCache._lock:
            if id in JsonSerializerCache._cache:
                serialized_data = JsonSerializerCache._cache[id]
                serializer = SerializerFactory.get_serializer(serializer_id)
                deserialized_data = serializer.deserialize(serialized_data)
                return deserialized_data
            else:
                data = ThirdPartyAPIClient.get_data(id)
                serializer = SerializerFactory.get_serializer(serializer_id)
                deserialized_data = serializer.deserialize(data)
                JsonSerializerCache._cache[id] = data
                return deserialized_data

# Example usage:
id = "123"
serializer_id = "user"
serialized_user = JsonSerializerCache.get_serialized_object(id, serializer_id)
print(serialized_user)

deserialized_user = JsonSerializerCache.get_deserialized_object(id, serializer_id)
print(deserialized_user)
