#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <chrono>
#include <atomic>
#include <fstream>
#include <sstream>
#include <string>

class dynamic_network_monitor {
public:
    dynamic_network_monitor(const std::string& config_file) : running(true), config_file(config_file) {
        load_config();
        start_workers();
    }

    ~dynamic_network_monitor() {
        stop();
    }

    void add_server(const std::string& server) {
        std::lock_guard<std::mutex> lock(mutex);
        servers.push_back(server);
        cv.notify_one();
    }

    void remove_server(const std::string& server) {
        std::lock_guard<std::mutex> lock(mutex);
        servers.erase(std::remove(servers.begin(), servers.end(), server), servers.end());
        cv.notify_one();
    }

private:
    struct ServerConfig {
        std::string address;
        int interval;
        std::vector<std::string> metrics;
    };

    void load_config() {
        std::ifstream file(config_file);
        if (file.is_open()) {
            std::string line;
            while (std::getline(file, line)) {
                ServerConfig config;
                std::istringstream iss(line);
                iss >> config.address >> config.interval;
                std::string metric;
                while (iss >> metric) {
                    config.metrics.push_back(metric);
                }
                servers_config.push_back(config);
            }
        } else {
            std::cerr << "Failed to open configuration file: " << config_file << std::endl;
        }
    }

    void start_workers() {
        for (size_t i = 0; i < num_threads; ++i) {
            workers.emplace_back(&dynamic_network_monitor::worker_thread, this);
        }
    }

    void worker_thread() {
        while (running.load()) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return !servers.empty() || !running.load(); });
            if (!servers.empty()) {
                ServerConfig config = servers.front();
                servers.pop_front();
                lock.unlock();

                collect_and_store_metrics(config.address, config.interval, config.metrics);
            }
        }
    }

    void stop() {
        running.store(false);
        cv.notify_all();
        for (auto& worker : workers) {
            if (worker.joinable()) {
                worker.join();
            }
        }
    }

    void collect_and_store_metrics(const std::string& address, int interval, const std::vector<std::string>& metrics) {
        // Simulate network and data collection
        std::this_thread::sleep_for(std::chrono::seconds(interval));

        for (const auto& metric : metrics) {
            // Simulate collecting and storing metrics
            std::cout << "Collected " << metric << " from " << address << std::endl;
            store_in_database(address, metric);
        }
    }

    void store_in_database(const std::string& server, const std::string& metric) {
        // Simulate storing in a time-series database
        std::cout << "Storing " << server << "/" << metric << " in database" << std::endl;
    }

    std::atomic<bool> running;
    std::string config_file;
    std::vector<ServerConfig> servers_config;
    std::queue<std::string> servers;
    std::mutex mutex;
    std::condition_variable cv;
    std::vector<std::thread> workers;
    const size_t num_threads = std::thread::hardware_concurrency();
};
