# Python Service Implementation (High-Level Overview)

import os
import hashlib
from datetime import datetime, timedelta
import json
import requests
from multiprocessing import Pool, Queue
from redis import Redis

# Configuration
MONITORED_DIR = '/path/to/monitored/directory'
EXTERNAL_APIS = {
    'api1': {'url': 'https://api1.example.com/report', 'token_key': 'access_token'},
    'api2': {'url': 'https://api2.example.com/report', 'token_key': 'access_token'}
}
REDIS_HOST = 'localhost'
REDIS_PORT = 6379

# Initialize Redis for token storage
redis_client = Redis(host=REDIS_HOST, port=REDIS_PORT)

def calculate_md5(file_path):
    hash_md5 = hashlib.md5()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def validate_oauth2_token(token_response):
    token_data = json.loads(token_response)
    required_fields = ['access_token', 'expires_in', 'token_type']
    if all(field in token_data for field in required_fields) and \
       token_data['token_type'] == 'Bearer' and \
       isinstance(token_data['expires_in'], int) and token_data['expires_in'] > 0:
        return True
    return False

def report_to_external_api(api_name, file_hash):
    api_config = EXTERNAL_APIS[api_name]
    url = api_config['url']
    token_key = api_config['token_key']
    access_token = redis_client.get(token_key)

    if not access_token or not validate_oauth2_token(access_token):
        # Fallback mechanism: Use secondary external service
        report_to_fallback_service(file_hash)
        return

    headers = {'Authorization': f'Bearer {access_token.decode()}'}
    payload = {'hash': file_hash}
    response = requests.post(url, headers=headers, json=payload)

    if response.status_code != 200:
        # Retry mechanism with exponential backoff
        retry_report_to_external_api(api_name, file_hash)

def report_to_fallback_service(file_hash):
    fallback_url = 'https://fallback.example.com/report'
    payload = {'hash': file_hash}
    requests.post(fallback_url, json=payload)

def worker(file_queue):
    while True:
        file_path = file_queue.get()
        if file_path is None:
            break
        file_hash = calculate_md5(file_path)
        for api_name in EXTERNAL_APIS:
            report_to_external_api(api_name, file_hash)

def main():
    file_queue = Queue()

    # Start worker processes
    with Pool(processes=4) as pool:
        for _ in range(4):
            pool.apply_async(worker, args=(file_queue,))

        # Monitor directory for file changes and add to queue
        for root, _, files in os.walk(MONITORED_DIR):
            for file_name in files:
                file_path = os.path.join(root, file_name)
                file_queue.put(file_path)

        # Signal workers to exit
        for _ in range(4):
            file_queue.put(None)

if __name__ == '__main__':
    main()
