#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>
#include <stdio.h>

// Function to derive key using PBKDF2 with SHA-512
void derive_key(const char* password, const unsigned char* salt, int iterations, unsigned char* outkey) {
    PKCS5_PBKDF2_HMAC(password, strlen(password), salt, 32, iterations, EVP_sha512(), 32, outkey);
}

// Function to encrypt data using AES-256-CBC
void encrypt(const unsigned char* plaintext, int plaintext_len, const unsigned char* key, const unsigned char* iv, unsigned char* ciphertext) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx, ciphertext + ciphertext_len, &ciphertext_len);
    EVP_CIPHER_CTX_free(ctx);
}

// Function to decrypt data using AES-256-CBC
void decrypt(const unsigned char* ciphertext, int ciphertext_len, const unsigned char* key, const unsigned char* iv, unsigned char* plaintext) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    EVP_DecryptUpdate(ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len);
    EVP_DecryptFinal_ex(ctx, plaintext + plaintext_len, &plaintext_len);
    EVP_CIPHER_CTX_free(ctx);
}

// Function to generate secure random IV
void generate_iv(unsigned char* iv) {
    RAND_bytes(iv, 16); // AES-256-CBC uses a 16-byte IV
}
