connection = pika.BlockingConnection(pika.ConnectionParameters('localhost'))
channel = connection.channel()
channel.queue_declare(queue='file_changes')

# OAuth2 Authentication for External APIs
class OAuth2Auth(requests.auth.AuthBase):
    def __init__(self, access_token):
        self.access_token = access_token

    def __call__(self, req):
        req.headers['Authorization'] = f'Bearer {self.access_token}'
        return req

# MD5 Hash Calculation
def calculate_md5(file_path):
    hash_md5 = hashlib.md5()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

# External Monitoring Platform Reporting
@retry(stop_max_attempt_number=3, wait_exponential_multiplier=1000)
def report_to_monitoring_platforms(file_path, md5_hash):
    for platform in ['platform1', 'platform2']:
        url = f'https://{platform}/api/report'
        headers = {'Content-Type': 'application/json'}
        data = {
            'file_path': file_path,
            'md5_hash': md5_hash,
            'timestamp': datetime.now().isoformat()
        }
        response = requests.post(url, headers=headers, json=data, auth=OAuth2Auth('access_token'))
        response.raise_for_status()

# File Change Handler
class FileChangeHandler(FileSystemEventHandler):
    def on_modified(self, event):
        if not event.is_directory:
            file_path = event.src_path
            md5_hash = calculate_md5(file_path)
            channel.basic_publish(exchange='', routing_key='file_changes', body=json.dumps({'file_path': file_path, 'md5_hash': md5_hash}))
            report_to_monitoring_platforms(file_path, md5_hash)

# Monitor Directory for Changes
def monitor_directory(directory):
    event_handler = FileChangeHandler()
    observer = Observer()
    observer.schedule(event_handler, directory, recursive=True)
    observer.start()
    try:
        while True:
            pass
    except KeyboardInterrupt:
        observer.stop()
    observer.join()

if __name__ == "__main__":
    directory_to_monitor = '/path/to/monitor'
    monitor_directory(directory_to_monitor)
