#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define BUFFER_SIZE 1000000

typedef struct {
    int data[BUFFER_SIZE];
    size_t head;
    size_t tail;
    sem_t items;
    sem_t spaces;
    pthread_mutex_t mutex;
} IntegerBuffer;

IntegerBuffer *create_buffer() {
    IntegerBuffer *buffer = (IntegerBuffer *)malloc(sizeof(IntegerBuffer));
    buffer->head = 0;
    buffer->tail = 0;
    sem_init(&buffer->items, 0, 0);
    sem_init(&buffer->spaces, 0, BUFFER_SIZE);
    pthread_mutex_init(&buffer->mutex, NULL);
    return buffer;
}

void enqueue(IntegerBuffer *buffer, int item) {
    sem_wait(&buffer->spaces);
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->tail] = item;
    buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer->mutex);
    sem_post(&buffer->items);
}

int dequeue(IntegerBuffer *buffer) {
    int item;
    sem_wait(&buffer->items);
    pthread_mutex_lock(&buffer->mutex);
    item = buffer->data[buffer->head];
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer->mutex);
    sem_post(&buffer->spaces);
    return item;
}

void destroy_buffer(IntegerBuffer *buffer) {
    sem_destroy(&buffer->items);
    sem_destroy(&buffer->spaces);
    pthread_mutex_destroy(&buffer->mutex);
    free(buffer);
}
```

This code defines a simple thread-safe integer buffer using C11 standard features. It includes functions to create, enqueue (add), dequeue (remove), and destroy the buffer. The use of semaphores for synchronization ensures that enqueuing and dequeuing operations are safe across multiple threads without causing race conditions or deadlocks. This basic structure can be expanded with additional functionality as needed for the full library implementation.']

