#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/stat.h>
#include <openssl/evp.h>

#define MAX_THREADS 10
#define BUFFER_SIZE 4096

typedef struct {
    char *input_file;
    char *output_file;
    int encryption_flag;
} Task;

void *process_task(void *arg) {
    Task *task = (Task *)arg;
    FILE *in = fopen(task->input_file, "rb");
    if (!in) {
        perror("Error opening input file");
        return NULL;
    }

    FILE *out = fopen(task->output_file, "wb");
    if (!out) {
        perror("Error opening output file");
        fclose(in);
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        perror("Failed to create cipher context");
        fclose(in);
        fclose(out);
        return NULL;
    }

    int key_length, iv_length;
    const unsigned char *key, *iv;

    if (task->encryption_flag) {
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    } else {
        EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    }

    unsigned char buffer[BUFFER_SIZE];
    int len, out_len;

    while ((len = fread(buffer, 1, BUFFER_SIZE, in)) > 0) {
        if (!EVP_CipherUpdate(ctx, buffer, &out_len, buffer, len)) {
            perror("Error during encryption/decryption");
            EVP_CIPHER_CTX_free(ctx);
            fclose(in);
            fclose(out);
            return NULL;
        }
        fwrite(buffer, 1, out_len, out);
    }

    if (!EVP_CipherFinal_ex(ctx, buffer, &out_len)) {
        perror("Error during finalization");
        EVP_CIPHER_CTX_free(ctx);
        fclose(in);
        fclose(out);
        return NULL;
    }
    fwrite(buffer, 1, out_len, out);

    EVP_CIPHER_CTX_free(ctx);
    fclose(in);
    fclose(out);

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    pthread_t threads[MAX_THREADS];
    Task tasks[MAX_THREADS];

    int num_files = (argc - 2) / 2;

    for (int i = 0; i < num_files; i++) {
        tasks[i].input_file = argv[(i * 2) + 1];
        tasks[i].output_file = argv[(i * 2) + 2];
        tasks[i].encryption_flag = i % 2 == 0 ? 1 : 0;

        if (pthread_create(&threads[i], NULL, process_task, &tasks[i])) {
            perror("Error creating thread");
            return 1;
        }
    }

    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
