#include <iostream>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <unordered_map>
#include <random>
#include <chrono>
#include <atomic>

class RNGService {
public:
    struct ClientConfig {
        std::string clientID;
        bool isCryptographic;
        int reseedInterval;
        // Other configuration parameters
    };

    class RNGClient {
    public:
        RNGClient(RNGService& service, const ClientConfig& config)
            : service(service), config(config) {
            uniqueSeed = GenerateUniqueSeed();
            rng.seed(uniqueSeed);
        }

        uint64_t GenerateRandomNumber() {
            if (std::chrono::steady_clock::now() - lastReseed > std::chrono::seconds(config.reseedInterval)) {
                ReseedRNG();
            }
            return rng();
        }

    private:
        RNGService& service;
        ClientConfig config;
        uint64_t uniqueSeed;
        std::minstd_rand rng;
        std::chrono::steady_clock::time_point lastReseed;

        uint64_t GenerateUniqueSeed() {
            // Combine clientID and global seed
            return std::hash<std::string>()(config.clientID) ^
                   service.GetGlobalSeed();
        }

        void ReseedRNG() {
            // Fetch new seed from external service
            auto newSeed = service.FetchSeedForClient(config.clientID);
            rng.seed(newSeed);
            lastReseed = std::chrono::steady_clock::now();
        }
    };

private:
    std::mutex globalMutex;
    uint64_t globalSeed;
    std::condition_variable reseedCV;
    std::unordered_map<std::string, RNGClient*> clients;

    uint64_t GetGlobalSeed() {
        std::lock_guard<std::mutex> lock(globalMutex);
        return globalSeed;
    }

    void SetGlobalSeed(uint64_t seed) {
        std::lock_guard<std::mutex> lock(globalMutex);
        globalSeed = seed;
        reseedCV.notify_all();
    }

    uint64_t FetchSeedForClient(const std::string& clientID) {
        // Simulate fetching seed from external service
        return std::hash<std::string>()(clientID) + GetGlobalSeed();
    }
};

int main() {
    RNGService service;
    // Example usage: Create clients and generate random numbers
    RNGService::ClientConfig config = {"client1", true, 60};
    auto client1 = new RNGService::RNGClient(service, config);
    std::cout << "Random Number (Client 1): " << client1->GenerateRandomNumber() << std::endl;

    // Simulate reseeding interval
    std::this_thread::sleep_for(std::chrono::seconds(config.reseedInterval));
    std::cout << "Random Number (Client 1 after reseed): " << client1->GenerateRandomNumber() << std::endl;

    delete client1;
    return 0;
}
```

