public class FinancialMarketDataProcessor {

    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private final DataValidator validator;
    private final TimeSeriesDatabase database;
    private final GraphQLServer graphQLServer;
    private final APIGateway apiGateway;
    private final RateLimiter rateLimiter;
    private final NetworkMonitor networkMonitor;

    public FinancialMarketDataProcessor(DataValidator validator, TimeSeriesDatabase database, 
                                        GraphQLServer graphQLServer, APIGateway apiGateway, 
                                        RateLimiter rateLimiter, NetworkMonitor networkMonitor) {
        this.validator = validator;
        this.database = database;
        this.graphQLServer = graphQLServer;
        this.apiGateway = apiGateway;
        this.rateLimiter = rateLimiter;
        this.networkMonitor = networkMonitor;

        scheduler.scheduleAtFixedRate(this::processData, 0, 1, TimeUnit.SECONDS);
    }

    private void processData() {
        if (networkMonitor.isNetworkStable()) {
            CompletableFuture.allOf(
                apiGateway.fetchDataFromExchangeA(),
                apiGateway.fetchDataFromExchangeB()
            ).thenAccept(v -> {
                String[] dataChunks = apiGateway.getDataChunks();
                for (String chunk : dataChunks) {
                    String[] fields = chunk.split(";");
                    if (validator.validate(fields)) {
                        database.storeData(fields);
                        graphQLServer.updateCache(fields);
                    }
                }
            }).exceptionally(ex -> {
                // Handle exceptions and retry logic
                return null;
            });
        } else {
            // Handle network instability
        }
    }

    public void shutdown() {
        scheduler.shutdown();
    }

    public static void main(String[] args) {
        DataValidator validator = new DataValidator();
        TimeSeriesDatabase database = new TimeSeriesDatabase();
        GraphQLServer graphQLServer = new GraphQLServer();
        APIGateway apiGateway = new APIGateway();
        RateLimiter rateLimiter = new RateLimiter();
        NetworkMonitor networkMonitor = new NetworkMonitor();

        FinancialMarketDataProcessor processor = new FinancialMarketDataProcessor(
            validator, database, graphQLServer, apiGateway, rateLimiter, networkMonitor
        );

        // Set up CI/CD pipeline and resource management here

        Runtime.getRuntime().addShutdownHook(new Thread(processor::shutdown));
    }
}
