#include <openssl/ssl.h>
#include <openssl/crypto.h>
#include <openssl/err.h>
#include <openssl/bio.h>
#include <openssl/x509_vfy.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to initialize OpenSSL
SSL_CTX *initialize_ssl_ctx() {
    SSL_library_init();
    SSL_CTX *ctx = SSL_CTX_new(TLS_client_method());
    if (!ctx) {
        fprintf(stderr, "Failed to create SSL context\n");
        return NULL;
    }
    return ctx;
}

// Function to load client certificate and private key
int load_cert_key(SSL_CTX *ctx, const char *cert_file, const char *key_file) {
    if (SSL_CTX_use_certificate_file(ctx, cert_file, SSL_FILETYPE_PEM) <= 0) {
        fprintf(stderr, "Failed to load certificate\n");
        return -1;
    }
    if (SSL_CTX_use_PrivateKey_file(ctx, key_file, SSL_FILETYPE_PEM) <= 0) {
        fprintf(stderr, "Failed to load private key\n");
        return -1;
    }
    return 0;
}

// Function to set up client certificate verification
void setup_cert_verification(SSL_CTX *ctx, const char *ca_file) {
    SSL_CTX_set_verify(ctx, SSL_VERIFY_PEER | SSL_VERIFY_FAIL_IF_NO_PEER_CERT, NULL);
    if (!SSL_CTX_load_verify_locations(ctx, ca_file, NULL)) {
        fprintf(stderr, "Failed to load CA certificate\n");
    }
}

// Function to create a new TLS connection
SSL *create_ssl_connection(SSL_CTX *ctx, BIO *bio) {
    SSL *ssl = SSL_new(ctx);
    if (!ssl) {
        fprintf(stderr, "Failed to create SSL object\n");
        return NULL;
    }
    SSL_set_bio(ssl, bio, bio);
    SSL_set_connect_state(ssl);
    return ssl;
}

// Function to perform the TLS handshake
int do_tls_handshake(SSL *ssl) {
    int ret = SSL_do_handshake(ssl);
    if (ret != 1) {
        fprintf(stderr, "TLS handshake failed\n");
        ERR_print_errors_fp(stderr);
        return -1;
    }
    return 0;
}

// Main function to demonstrate the TLS client library
int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <server_ip> <port> <cert_file>\n", argv[0]);
        return -1;
    }

    const char *server_ip = argv[1];
    int port = atoi(argv[2]);
    const char *cert_file = argv[3];

    SSL_CTX *ctx = initialize_ssl_ctx();
    if (!ctx) {
        return -1;
    }

    load_cert_key(ctx, cert_file, cert_file);

    BIO *bio = BIO_new_ssl_connect(ctx);
    if (!bio) {
        fprintf(stderr, "Failed to create BIO object\n");
        SSL_CTX_free(ctx);
        return -1;
    }
    BIO_set_conn_hostname(bio, (char *)server_ip);
    BIO_set_conn_port(bio, (char *)port);

    SSL *ssl = create_ssl_connection(ctx, bio);
    if (!ssl) {
        BIO_free_all(bio);
        SSL_CTX_free(ctx);
        return -1;
    }

    do_tls_handshake(ssl);

    // Perform communication here

    SSL_shutdown(ssl);
    SSL_free(ssl);
    BIO_free_all(bio);
    SSL_CTX_free(ctx);

    return 0;
}
```

This code provides a basic implementation of a TLS 1.3 client library in C using OpenSSL. It includes functions for initializing the SSL context, loading certificates and keys, setting up certificate verification, creating a new TLS connection, and performing the TLS handshake. The `main` function demonstrates how to use these functions to connect to a server and perform communication over a secure channel.

This implementation is designed to be modular and extensible, allowing for further customization and optimization based on specific requirements and performance considerations.']

