import os
import hashlib
import threading
from queue import Queue
from concurrent.futures import ThreadPoolExecutor
import requests

class FileMonitor:
    def __init__(self, directories, api_endpoints):
        self.directories = directories
        self.api_endpoints = api_endpoints
        self.file_queue = Queue()
        self.executor = ThreadPoolExecutor(max_workers=10)

    def start_monitoring(self):
        for directory in self.directories:
            threading.Thread(target=self.monitor_directory, args=(directory,)).start()

    def monitor_directory(self, directory):
        while True:
            for root, _, files in os.walk(directory):
                for file in files:
                    file_path = os.path.join(root, file)
                    if not self.file_queue.full():
                        self.file_queue.put(file_path)

    def process_file(self):
        while True:
            file_path = self.file_queue.get()
            if file_path is None:
                break
            md5_hash = self.compute_md5(file_path)
            for endpoint in self.api_endpoints:
                self.forward_hash_to_api(md5_hash, endpoint)
            os.rename(file_path, f"{file_path}.processed")
            self.file_queue.task_done()

    def compute_md5(self, file_path):
        hash_md5 = hashlib.md5()
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_md5.update(chunk)
        return hash_md5.hexdigest()

    def forward_hash_to_api(self, md5_hash, endpoint):
        try:
            response = requests.post(endpoint, json={"hash": md5_hash})
            response.raise_for_status()
        except requests.RequestException as e:
            print(f"Failed to forward MD5 to API: {e}")

if __name__ == "__main__":
    directories_to_monitor = ["/path/to/dir1", "/path/to/dir2"]
    api_endpoints = ["https://api1.example.com/endpoint", "https://api2.example.com/endpoint"]

    file_monitor = FileMonitor(directories_to_monitor, api_endpoints)
    file_monitor.start_monitoring()

    processing_thread = threading.Thread(target=file_monitor.process_file)
    processing_thread.start()
