#include <iostream>
#include <thread>
#include <vector>
#include <atomic>
#include <mutex>
#include <queue>
#include <memory>
#include <chrono>

class network_monitor {
public:
    struct server_info {
        std::string ip;
        int priority;
    };

    enum class metric_type {
        packet_loss,
        latency,
        throughput,
        error_rate
    };

    using metrics_callback = std::function<void(const std::vector<std::pair<server_info, double>>&)>;

    network_monitor(size_t num_threads, const std::string& db_url)
        : threads_(num_threads), db_url_(db_url) {
        for (size_t i = 0; i < num_threads; ++i) {
            workers_.emplace_back([this, i] {
                while (true) {
                    std::unique_lock<std::mutex> lock(mutex_);
                    condition_variable_.wait(lock, [this, i] { return !work_queue_.empty() || stop_; });
                    if (stop_ && work_queue_.empty()) break;
                    auto task = std::move(work_queue_.front());
                    work_queue_.pop();
                    lock.unlock();
                    task();
                }
            });
        }
    }

    ~network_monitor() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop_ = true;
        }
        condition_variable_.notify_all();
        for (auto& thread : workers_) {
            thread.join();
        }
    }

    void add_server(const server_info& server) {
        servers_.push_back(server);
    }

    void start() {
        for (const auto& server : servers_) {
            threads_.emplace_back([this, server] {
                while (true) {
                    // Simulate network data collection
                    std::this_thread::sleep_for(std::chrono::milliseconds(100));
                    collect_metrics(server);
                }
            });
        }
    }

private:
    void collect_metrics(const server_info& server) {
        // Simulate metric collection
        double packet_loss = 2.5;
        double latency = 30.0;
        double throughput = 1500.0;
        double error_rate = 0.1;

        store_metrics(server, {metric_type::packet_loss, packet_loss},
                      {metric_type::latency, latency},
                      {metric_type::throughput, throughput},
                      {metric_type::error_rate, error_rate});
    }

    void store_metrics(const server_info& server, std::initializer_list<std::pair<metric_type, double>> metrics) {
        // Simulate storing metrics in a time-series database
        for (const auto& [type, value] : metrics) {
            std::cout << "Server: " << server.ip << ", Metric: " << static_cast<int>(type)
                      << ", Value: " << value << std::endl;
        }
    }

    std::vector<std::thread> workers_;
    std::queue<std::function<void()>> work_queue_;
    std::mutex mutex_;
    std::condition_variable condition_variable_;
    std::vector<server_info> servers_;
    std::atomic<bool> stop_{false};
    size_t num_threads_;
    std::string db_url_;
};

int main() {
    network_monitor monitor(10, "http://timeseriesdb.com");

    monitor.add_server({{"192.168.1.1", 1}});
    monitor.add_server({{"192.168.1.2", 2}});
    monitor.add_server({{"192.168.1.3", 3}});

    monitor.start();

    return 0;
}
```

