import hashlib
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed

def compute_file_md5(file_path, chunk_size=65536):
    """
    Computes the MD5 hash of a file located at file_path.

    :param file_path: Path to the local file or URL of the remote file.
    :param chunk_size: Size of each chunk in bytes when reading the file.
    :return: MD5 hash as a hexadecimal string.
    """
    def read_file(file_path, chunk_size):
        if file_path.startswith(('http://', 'https://')):
            response = requests.get(file_path, stream=True)
            response.raise_for_status()
            return (chunk for chunk in response.iter_content(chunk_size=chunk_size))
        else:
            with open(file_path, 'rb') as f:
                while True:
                    data = f.read(chunk_size)
                    if not data:
                        break
                    yield data

    def hash_chunks(chunks):
        md5_hash = hashlib.md5()
        for chunk in chunks:
            md5_hash.update(chunk)
        return md5_hash.hexdigest()

    try:
        with ThreadPoolExecutor() as executor:
            future_to_chunk = {executor.submit(read_file, file_path, chunk_size): i for i, chunk in enumerate(read_file(file_path, chunk_size))}
            results = [future.result() for future in as_completed(future_to_chunk)]
            md5_hash = hash_chunks(results)
        return md5_hash
    except requests.exceptions.RequestException as e:
        raise Exception(f"Network error: {e}")
    except PermissionError as e:
        raise Exception(f"Permission denied: {e}")
    except FileNotFoundError as e:
        raise Exception(f"File not found: {e}")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}")

# Example usage
file_path = 'http://example.com/largefile.zip'  # Replace with actual URL or file path
print(compute_file_md5(file_path))
