import hashlib
import os
from concurrent.futures import ThreadPoolExecutor, as_completed
from typing import Callable, Optional

class FileHasher:
    def __init__(self, chunk_size=1024*1024):
        self.chunk_size = chunk_size

    def hash_file(self, file_path: str, encoding='utf-8') -> str:
        if not os.path.exists(file_path) or not os.path.isfile(file_path):
            raise FileNotFoundError(f"File {file_path} not found or is not a file.")

        hasher = hashlib.md5()
        with open(file_path, 'r', encoding=encoding, errors='ignore') as file:
            for chunk in iter(lambda: file.read(self.chunk_size), ''):
                hasher.update(chunk.encode(encoding))
        return hasher.hexdigest()

    def concurrent_hash_files(self, file_paths: list, progress_indicator: Optional[Callable[[int], None]] = None) -> dict:
        with ThreadPoolExecutor() as executor:
            futures = {executor.submit(self.hash_file, path): path for path in file_paths}
            results = {}
            for future in as_completed(futures):
                path = futures[future]
                try:
                    result = future.result()
                    if progress_indicator:
                        progress_indicator(int((list(results.keys()).index(path) + 1) / len(file_paths) * 100))
                    results[path] = result
                except Exception as e:
                    print(f"Error hashing {path}: {e}")
        return results

# Example usage
if __name__ == "__main__":
    hasher = FileHasher()
    file_paths = ['file1.txt', 'file2.txt']

    def progress_callback(percent):
        print(f"\rProgress: {percent}% ", end="")

    hashes = hasher.concurrent_hash_files(file_paths, progress_indicator=progress_callback)
    for path, hash_value in hashes.items():
        print(f"Hash of {path}: {hash_value}")
```']

