            raise FileNotFoundError(f"File not found: {file_path}")

        return self.executor.submit(self._read_file_in_chunks, file_path)

    def _read_file_in_chunks(self, file_path):
        md5_hash = hashlib.md5()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(self.chunk_size), b''):
                md5_hash.update(chunk)
        return md5_hash.hexdigest()

class MetadataService:
    def __init__(self, url):
        self.url = url
        self.cache = {}
        self.last_cache_update = 0

    def get_file_info(self, file_path):
        current_time = time.time()
        if file_path not in self.cache or (current_time - self.last_cache_update) > 30 * 60:
            try:
                response = requests.get(f"{self.url}/{file_path}")
                response.raise_for_status()
                self.cache[file_path] = response.json()
                self.last_cache_update = current_time
            except requests.RequestException as e:
                raise Exception("Metadata service unavailable") from e
        return self.cache[file_path]

