// Function to initialize SSL context with TLS 1.3
SSL_CTX* init_ssl_context() {
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    if (!ctx) {
        fprintf(stderr, "Unable to create SSL context\n");
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    // Enable TLS 1.3
    SSL_CTX_set_min_proto_version(ctx, TLS1_3_VERSION);
    SSL_CTX_set_max_proto_version(ctx, TLS1_3_VERSION);

    // Load client certificate and key
    if (SSL_CTX_use_certificate_file(ctx, "client.crt", SSL_FILETYPE_PEM) <= 0 ||
        SSL_CTX_use_PrivateKey_file(ctx, "client.key", SSL_FILETYPE_PEM) <= 0) {
        fprintf(stderr, "Unable to load client certificate or key\n");
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    return ctx;
}

// Function to create a new SSL connection
SSL* create_ssl_connection(SSL_CTX* ctx, const char* hostname, int port) {
    BIO* bio = BIO_new_ssl_connect(ctx);
    if (!bio) {
        fprintf(stderr, "Unable to create BIO\n");
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    BIO_set_conn_hostname(bio, hostname);
    BIO_set_conn_port(bio, itoa(port));

    SSL* ssl = SSL_new(ctx);
    if (!ssl) {
        fprintf(stderr, "Unable to create SSL object\n");
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    SSL_set_bio(ssl, bio, bio);

    // Perform the TLS handshake
    int rc = SSL_connect(ssl);
    if (rc != 1) {
        fprintf(stderr, "TLS handshake failed\n");
        ERR_print_errors_fp(stderr);
        SSL_shutdown(ssl);
        SSL_free(ssl);
        BIO_free_all(bio);
        exit(EXIT_FAILURE);
    }

    return ssl;
}

// Function to send and receive data over the TLS connection
void tls_send_receive(SSL* ssl, const char* message) {
    // Send data
    int len = SSL_write(ssl, message, strlen(message));
    if (len <= 0) {
        fprintf(stderr, "TLS write failed\n");
        ERR_print_errors_fp(stderr);
        return;
    }

    // Receive response
    char buffer[1024];
    len = SSL_read(ssl, buffer, sizeof(buffer) - 1);
    if (len <= 0) {
        fprintf(stderr, "TLS read failed\n");
        ERR_print_errors_fp(stderr);
        return;
    }
    buffer[len] = '\0';
    printf("Received response: %s\n", buffer);
}

int main() {
    SSL_CTX* ctx = init_ssl_context();
    SSL* ssl = create_ssl_connection(ctx, "example.com", 443);

    // Send a message and receive the response
    tls_send_receive(ssl, "Hello, TLS 1.3!");

    // Clean up
    SSL_shutdown(ssl);
    SSL_free(ssl);
    BIO_free_all(SSL_get_SSL_CTX(ssl));

    return 0;
}
