import hashlib
import os
import requests
from concurrent.futures import ThreadPoolExecutor

def compute_md5(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            hasher.update(chunk)
    return hasher.hexdigest()

def download_file(url, save_path):
    response = requests.get(url, stream=True)
    response.raise_for_status()
    with open(save_path, 'wb') as f:
        for chunk in response.iter_content(chunk_size=4096):
            f.write(chunk)

def process_file_with_resilience(file_source, is_remote=False):
    if is_remote:
        temp_file_path = '/tmp/temp_file'
        download_file(file_source, temp_file_path)
        file_to_process = temp_file_path
    else:
        file_to_process = file_source

    try:
        md5_hash = compute_md5(file_to_process)
    finally:
        if is_remote and os.path.exists(temp_file_path):
            os.remove(temp_file_path)

    return md5_hash
