    std::vector<std::thread> workers;
    std::queue<Task> tasks;
    std::mutex queueMutex;
    std::condition_variable condition;
    std::atomic<bool> stop;

public:
    UeContextManager(size_t numThreads) : stop(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back(&UeContextManager::workerThread, this);
        }
    }

    ~UeContextManager() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop.store(true);
        }
        condition.notify_all();
        for (auto& worker : workers) {
            worker.join();
        }
    }

    void enqueueTask(Task task) {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            tasks.push(task);
        }
        condition.notify_one();
    }

private:
    void workerThread() {
        while (true) {
            Task task;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                condition.wait(lock, [this] { return stop.load() || !tasks.empty(); });
                if (stop.load() && tasks.empty()) {
                    return;
                }
                task = std::move(tasks.front());
                tasks.pop();
            }
            task();
        }
    }
};

class SecurityModule {
public:
    void encryptData(const UeContext& ueContext) {
        // Encryption logic
        std::cout << "Encrypting data for UE context ID: " << ueContext.id << std::endl;
    }

    void decryptData(const UeContext& ueContext) {
        // Decryption logic
        std::cout << "Decrypting data for UE context ID: " << ueContext.id << std::endl;
    }
};

class PolicyEnforcementModule {
public:
    void adjustRabConfig(const UeContext& ueContext, int qoSLevel) {
        // Policy enforcement logic
        std::cout << "Adjusting RAB config for UE context ID: " << ueContext.id << " with QoS level: " << qoSLevel << std::endl;
    }
};

class AdminInterface {
public:
    void displayPerformanceMetrics(const UeContext& ueContext) {
        // Display performance metrics
        std::cout << "Displaying performance metrics for UE context ID: " << ueContext.id << std::endl;
    }

    void managePolicies() {
        // Manage policies logic
        std::cout << "Managing policies..." << std::endl;
    }
};

int main() {
    UeContextManager manager(4);
    SecurityModule securityModule;
    PolicyEnforcementModule policyModule;
    AdminInterface adminInterface;

    UeContext ueContext1(101);
    UeContext ueContext2(102);

    manager.enqueueTask([&securityModule, &ueContext1]() { securityModule.encryptData(ueContext1); });
    manager.enqueueTask([&securityModule, &ueContext2]() { securityModule.decryptData(ueContext2); });

    manager.enqueueTask([&policyModule, &ueContext1]() { policyModule.adjustRabConfig(ueContext1, 5); });
    manager.enqueueTask([&policyModule, &ueContext2]() { policyModule.adjustRabConfig(ueContext2, 3); });

    manager.enqueueTask([&adminInterface, &ueContext1]() { adminInterface.displayPerformanceMetrics(ueContext1); });
    manager.enqueueTask([&adminInterface]() { adminInterface.managePolicies(); });

    return 0;
}
