import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ConditionalLogService {
    private static final Logger logger = Logger.getLogger(ConditionalLogService.class.getName());
    private static final int MAX_LOGS_PER_MINUTE = 5;
    private static final long MINUTE_INTERVAL = 60000;
    private static final ConcurrentHashMap<String, Integer> logCounters = new ConcurrentHashMap<>();
    private static ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    static {
        scheduler.scheduleAtFixedRate(() -> logCounters.clear(), 0, MINUTE_INTERVAL, TimeUnit.MILLISECONDS);
    }

    public void logIfConditionMet(boolean condition, String format, Object... args) {
        if (condition && isWithinLimit()) {
            try {
                logger.log(Level.INFO, format, args);
            } catch (Exception e) {
                handleLogError(e);
            }
        }
    }

    private boolean isWithinLimit() {
        String serviceName = getCallerServiceName();
        logCounters.putIfAbsent(serviceName, 0);
        int currentCount = logCounters.get(serviceName);
        if (currentCount < MAX_LOGS_PER_MINUTE) {
            logCounters.replace(serviceName, currentCount + 1);
            return true;
        }
        return false;
    }

    private String getCallerServiceName() {
        // Implement logic to determine the caller service name
        return "UnknownService";
    }

    private void handleLogError(Exception e) {
        logger.log(Level.SEVERE, "Logging error: ", e);
    }

    public static void shutdown() {
        scheduler.shutdown();
    }
}
