#include <forward_list>
#include <string>
#include <cstdio>
#include <mutex>
#include <thread>

class Logger {
public:
    Logger(const char* file, int bufferSize, bool appendOnly) : logFile(file), bufferSize(bufferSize), appendOnly(appendOnly) {}
    ~Logger() { flush(); }

    void log(int level, const char* format, ...) {
        if (level > this->logLevel) return;
        std::unique_lock<std::mutex> lock(mutex);
        va_list args;
        va_start(args, format);
        vsnprintf(buffer + bufferPos, bufferSize - bufferPos, format, args);
        va_end(args);
        bufferPos = (bufferPos + strlen(buffer + bufferPos)) % bufferSize;
        if (shouldFlush()) flush();
    }

private:
    std::string logFile;
    int bufferSize;
    bool appendOnly;
    char buffer[1024];
    size_t bufferPos = 0;
    int logLevel = 1;
    std::mutex mutex;

    void flush() {
        std::unique_lock<std::mutex> lock(mutex);
        FILE* file = fopen(logFile.c_str(), (appendOnly ? "a" : "w"));
        if (file) {
            fwrite(buffer, 1, bufferPos, file);
            fclose(file);
            bufferPos = 0;
        }
    }

    bool shouldFlush() {
        return bufferPos >= bufferSize / 2;
    }
};

void insertOrLog(std::forward_list<std::string>& list, const std::string& target, const std::string& value, bool shouldLog, const char* logFile, int logLevel, int bufferSize, bool appendOnly, bool useDistributedLog) {
    static Logger logger(logFile, bufferSize, appendOnly);
    std::unique_lock<std::mutex> lock(mutex);
    auto it = list.before_begin();
    for (; it != list.end(); ++it) {
        if (*it == target) {
            it = list.insert_after(it, value);
            break;
        }
    }
    if (it == list.end()) {
        list.push_back(value);
    }

    if (shouldLog && logLevel > 0) {
        logger.log(logLevel, "Value %s %s after target %s", value.c_str(), it == list.end() ? "appended" : "inserted", target.c_str());
    }
}
