using Microsoft.Extensions.Logging;

public class DataLoadingModule : IDisposable
{
    private readonly ILogger<DataLoadingModule> _logger;
    private bool _disposed = false;

    public DataLoadingModule(ILogger<DataLoadingModule> logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    ~DataLoadingModule()
    {
        Dispose(false);
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (_disposed)
            return;

        if (disposing)
        {
            // Release managed resources
        }

        // Release unmanaged resources

        _disposed = true;
    }

    public async Task<T> LoadDataFromBinaryFileAsync<T>(string connectionString, string filePath, T dataStructureType, LoggingConfig loggingConfig = null) where T : new()
    {
        using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
        {
            var binaryFormatter = new BinaryFormatter();
            try
            {
                var dataObject = (T)binaryFormatter.Deserialize(fileStream);
                _logger.LogInformation($"Successfully loaded data into {dataStructureType.GetType().Name}");
                return dataObject;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to load data into {dataStructureType.GetType().Name}");
                throw new InvalidOperationException("Failed to deserialize binary data", ex);
            }
        }
    }

    public async Task<DbDataReader> ExecuteParameterizedQueryAsync(string connectionString, string sqlCommand, List<(string name, object value)> parameters, List<Type> parameterTypes, int timeout)
    {
        using (var connection = GetDatabaseConnection(connectionString))
        {
            await connection.OpenAsync();
            var command = new DbCommand(sqlCommand, connection);
            command.CommandTimeout = timeout;

            for (int i = 0; i < parameters.Count; i++)
            {
                var parameter = command.CreateParameter();
                parameter.ParameterName = parameters[i].name;
                parameter.Value = parameters[i].value;
                parameter.DbType = GetDbType(parameterTypes[i]);
                command.Parameters.Add(parameter);
            }

            try
            {
                return await command.ExecuteReaderAsync(CommandBehavior.Default);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to execute parameterized query");
                throw new InvalidOperationException("Failed to execute SQL command", ex);
            }
        }
    }

    private DbConnection GetDatabaseConnection(string connectionString)
    {
        // Implement connection pooling logic here
        return new SqlConnection(connectionString);
    }

    private DbType GetDbType(Type type)
    {
        switch (Type.GetTypeCode(type))
        {
            case TypeCode.String:
                return DbType.String;
            case TypeCode.Int32:
                return DbType.Int32;
            case TypeCode.Double:
                return DbType.Double;
            // Add more cases as needed
            default:
                throw new ArgumentException("Unsupported data type");
        }
    }

    public void ValidateParameters(List<(string name, object value)> parameters, List<Type> parameterTypes)
    {
        if (parameters.Count != parameterTypes.Count)
            throw new ArgumentException("Parameter count mismatch");

        for (int i = 0; i < parameters.Count; i++)
        {
            if (!parameterTypes[i].IsAssignableFrom(parameters[i].value.GetType()))
                throw new ArgumentException("Invalid parameter type");
        }
    }

    // Implement unit tests and additional methods as needed
}
