    public WeatherService(Dictionary<string, string> apiKeys, ICachingService cachingService, ILogger logger)
    {
        _apiKeys = apiKeys;
        _httpClient = new HttpClient();
        _cachingService = cachingService;
        _logger = logger;
    }

    public async Task<WeatherData> GetWeatherAsync(string location, List<string> parameters)
    {
        var cacheKey = $"{location}:{string.Join(",", parameters)}";
        if (_cachingService.TryGet(cacheKey, out WeatherData cachedWeather))
        {
            return cachedWeather;
        }

        var apiUrl = GetApiUrl(location);
        var response = await _httpClient.GetAsync(apiUrl);
        if (!response.IsSuccessStatusCode)
        {
            _logger.LogError($"Failed to fetch weather data for {location}");
            return null;
        }

        var weatherData = JsonSerializer.Deserialize<WeatherData>(await response.Content.ReadAsStringAsync());
        _cachingService.Set(cacheKey, weatherData);

        return weatherData;
    }

    private string GetApiUrl(string location)
    {
        // Implement logic to determine the most appropriate API based on user preferences and network conditions
        // Example: Use a load balancer or failover mechanism
        return "https://api.weatherapi.com/v1/current.json?key={apiKey}&q={location}";
    }
}

public class WeatherData
{
    public string Location { get; set; }
    public double Temperature { get; set; }
    public int Humidity { get; set; }
    public double WindSpeed { get; set; }
}

public interface ICachingService
{
    bool TryGet(string key, out WeatherData value);
    void Set(string key, WeatherData value);
}

public class MemoryCachingService : ICachingService
{
    private readonly Dictionary<string, WeatherData> _cache = new();

    public bool TryGet(string key, out WeatherData value)
    {
        return _cache.TryGetValue(key, out value);
    }

    public void Set(string key, WeatherData value)
    {
        _cache[key] = value;
    }
}

public interface ILogger
{
    void LogError(string message);
}

public class ConsoleLogger : ILogger
{
    public void LogError(string message)
    {
        Console.Error.WriteLine(message);
    }
}

