class DynamicTestRunner {
  constructor(externalServiceUrl) {
    this.externalServiceUrl = externalServiceUrl;
    this.tests = [];
    this.concurrencyLimit = 5;
    this.currentlyRunningTests = new Set();
  }

  async loadTests(testFiles) {
    for (const file of testFiles) {
      const module = await import(file);
      this.tests.push(...module.default);
    }
  }

  async runTests() {
    let results = [];
    for (let i = 0; i < this.tests.length; i += this.concurrencyLimit) {
      const batch = this.tests.slice(i, i + this.concurrencyLimit);
      await Promise.all(batch.map(test => this.runTest(test)))
        .then(responses => responses.forEach(response => results.push(response)))
        .catch(error => console.error('Error running tests:', error));
    }
    return results;
  }

  async runTest(test) {
    try {
      const result = await test.execute();
      if (result.success) {
        console.log(`Test passed: ${test.label}`);
      } else {
        console.error(`Test failed: ${test.label}`, result.error);
      }
      return { label: test.label, success: result.success, error: result.error };
    } catch (error) {
      console.error(`Unhandled exception in test ${test.label}:`, error);
      throw error;
    }
  }

  setConcurrencyLimit(limit) {
    this.concurrencyLimit = limit;
  }
}
