const axios = require('axios');
const { v4: uuidv4 } = require('uuid');
const LRU = require('lru-cache');

// Cache configuration
const scriptCache = new LRU({ max: 500, maxAge: 3600 * 1000 }); // 1 hour cache

async function renderFooterScripts(apiUrl) {
    try {
        const response = await axios.get(apiUrl);
        const scripts = response.data.scripts;

        for (const script of scripts) {
            await handleScript(script);
        }
    } catch (error) {
        console.error('Error fetching scripts:', error);
    }
}

async function handleScript(scriptObj) {
    const { url, content } = scriptObj;
    const scriptId = uuidv4();

    if (scriptCache.has(url)) {
        return; // Script already processed
    }

    try {
        if (!content) {
            const response = await axios.get(url);
            scriptObj.content = response.data;
        }

        if (!isValidJavaScript(scriptObj.content)) {
            console.warn(`Invalid JavaScript in script with URL: ${url}`);
            renderScriptWithWarning(scriptObj, 'Syntax error detected');
            continue;
        }

        scriptCache.set(url, true); // Mark as processed

        await renderScriptInFooter(scriptObj);
    } catch (error) {
        console.error('Error handling script:', error);
    }
}

function isValidJavaScript(code) {
    try {
        new Function(code);
        return true;
    } catch (e) {
        return false;
    }
}

async function renderScriptWithWarning(scriptObj, warningMessage) {
    const comment = `<!-- ${warningMessage} -->`;
    await appendScriptToFooter(comment + scriptObj.content);
}

function renderScriptInFooter(scriptObj) {
    return new Promise((resolve, reject) => {
        requestAnimationFrame(() => {
            try {
                const scriptElement = document.createElement('script');
                scriptElement.id = `dynamic-script-${scriptObj.url}`;
                scriptElement.textContent = scriptObj.content;
                document.body.appendChild(scriptElement);
                resolve();
            } catch (error) {
                reject(error);
            }
        });
    });
}

async function appendScriptToFooter(content) {
    return new Promise((resolve, reject) => {
        const footer = document.querySelector('footer');
        if (footer) {
            const scriptTag = document.createElement('script');
            scriptTag.textContent = content;
            footer.appendChild(scriptTag);
            resolve();
        } else {
            reject(new Error('Footer element not found'));
        }
    });
}

module.exports = { renderFooterScripts };
