// Define a class for handling third-party data streams
class DataStream {
  constructor(url) {
    this.url = url;
    this.connection = null;
    this.paused = false;
    this.cache = [];
    this.lastProcessedTime = Date.now();
  }

  async connect() {
    // Establish WebSocket connection
    this.connection = new WebSocket(this.url);
    this.connection.onmessage = this.handleMessage.bind(this);
  }

  async disconnect() {
    if (this.connection) {
      this.connection.close();
      this.connection = null;
    }
  }

  async pause() {
    this.paused = true;
  }

  async resume() {
    this.paused = false;
  }

  async handleMessage(event) {
    if (!this.paused) {
      const data = JSON.parse(event.data);
      this.cache.push(data);
      await this.processData(data);
    }
  }

  async processData(data) {
    // Implement data processing logic here
    console.log('Processing data:', data);
  }

  async retryFetch() {
    while (true) {
      try {
        const response = await fetch(this.url);
        if (!response.ok) throw new Error('Failed to fetch data');
        return await response.json();
      } catch (error) {
        console.error('Error fetching data:', error);
        await new Promise(resolve => setTimeout(resolve, Math.random() * 1000));
      }
    }
  }

  async start() {
    await this.connect();
    setInterval(async () => {
      if (!this.paused && Date.now() - this.lastProcessedTime > 1000) {
        const data = await this.retryFetch();
        this.cache.push(data);
        await this.processData(data);
        this.lastProcessedTime = Date.now();
      }
    }, 500);
  }
}

// Define a class for managing multiple data streams
class DataStreamManager {
  constructor(maxStreams) {
    this.maxStreams = maxStreams;
    this.streams = [];
    this.cache = {};
  }

  async addStream(url) {
    if (this.streams.length < this.maxStreams) {
      const stream = new DataStream(url);
      this.streams.push(stream);
      await stream.start();
      return true;
    }
    return false;
  }

  async pauseStream(url) {
    for (const stream of this.streams) {
      if (stream.url === url) {
        await stream.pause();
        return true;
      }
    }
    return false;
  }

  async resumeStream(url) {
    for (const stream of this.streams) {
      if (stream.url === url) {
        await stream.resume();
        return true;
      }
    }
    return false;
  }

  async getCache(url) {
    return this.cache[url] || [];
  }
}

