import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class VersionControl {
    private final ConcurrentHashMap<String, AtomicInteger> versionMap = new ConcurrentHashMap<>();

    public void saveVersion(String document, String content) throws Exception {
        int currentVersion = getVersion(document);
        // Code to save the new version of the document

        // Increment the version number
        versionMap.put(document, new AtomicInteger(currentVersion + 1));
    }

    private int getVersion(String document) {
        return versionMap.getOrDefault(document, new AtomicInteger(0)).get();
    }
}
