public class FinancialTransactionProcessor {

    private final ConcurrentHashMap<String, Integer> cache = new ConcurrentHashMap<>();
    private final AtomicInteger counter = new AtomicInteger(0);

    public void processTransactions(List<FinancialTransaction> transactions) {
        transactions.parallelStream().forEach(this::processTransaction);
    }

    private void processTransaction(FinancialTransaction transaction) {
        String id1 = transaction.getId1();
        String id2 = transaction.getId2();

        if (isCoPrime(id1, id2)) {
            System.out.println("Disjoint pair found: " + id1 + ", " + id2);
        }

        cache.put(transaction.getId(), counter.incrementAndGet());
    }

    private boolean isCoPrime(String id1, String id2) {
        int num1 = cache.getOrDefault(id1, 0);
        int num2 = cache.getOrDefault(id2, 0);

        return gcd(num1, num2) == 1;
    }

    private int gcd(int a, int b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }

    public static void main(String[] args) {
        FinancialTransactionProcessor processor = new FinancialTransactionProcessor();
        List<FinancialTransaction> transactions = loadTransactionsFromSources();
        processor.processTransactions(transactions);
