<?php

class ClinicManager {
    private $db;
    private $semaphore;

    public function __construct($host, $user, $password, $dbname) {
        // Initialize database connection
        $this->db = new PDO("mysql:host=$host;dbname=$dbname", $user, $password);
        $this->db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        // Initialize semaphore (C extension needed)
        $this->semaphore = sem_get(ftok(__FILE__, 'S'), 10); // Example: Max 10 concurrent connections
    }

    public function updateClinicStatus($clinicId) {
        if (!$this->acquireSemaphore()) {
            error_log("Failed to acquire semaphore");
            return false;
        }

        try {
            $apiUrl = "https://api.clinics.com/details/$clinicId";
            $response = file_get_contents($apiUrl, false, stream_context_create([
                'http' => [
                    'method' => 'GET',
                    'header' => 'Authorization: Bearer YOUR_API_TOKEN'
                ]
            ]));

            if ($response === FALSE) {
                throw new Exception("API request failed");
            }

            $clinicData = json_decode($response, true);
            $status = $clinicData['status'];
            $ipAddress = $_SERVER['REMOTE_ADDR'];
            $lastModified = date('Y-m-d H:i:s');

            $stmt = $this->db->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?");
            $stmt->execute([$status, $ipAddress, $lastModified, $clinicId]);

            return true;
        } catch (Exception $e) {
            error_log($e->getMessage());
            return false;
        } finally {
            $this->releaseSemaphore();
        }
    }

    private function acquireSemaphore() {
        $backoff = 100; // Initial backoff time in milliseconds
        $maxBackoff = 10 * 60 * 1000; // Maximum backoff time (10 minutes)

        while ($this->semaphore === FALSE) {
            usleep($backoff);
            $backoff = min($backoff * 2, $maxBackoff);
        }

        return true;
    }

    private function releaseSemaphore() {
        sem_release($this->semaphore);
    }
}

// Usage example
$manager = new ClinicManager('localhost', 'user', 'password', 'clinics_db');
if ($manager->updateClinicStatus(123)) {
    echo "Clinic status updated successfully";
} else {
    echo "Failed to update clinic status";
}
?>
