<?php

use Illuminate\Support\Facades\Cache;
use GuzzleHttp\Client;
use Monolog\Logger;
use Monolog\Handler\StreamHandler;

class AuthenticationService {
    private $clients = [];
    private $logger;

    public function __construct(array $providers, string $cachePrefix) {
        foreach ($providers as $provider => $config) {
            $this->clients[$provider] = new Client($config);
        }

        $this->logger = new Logger('auth_service');
        $this->logger->pushHandler(new StreamHandler(__DIR__.'/auth.log', Logger::DEBUG));
    }

    public function authenticateUser(string $provider, string $code) {
        $response = $this->clients[$provider]->request('POST', '/oauth/token', [
            'form_params' => [
                'grant_type' => 'authorization_code',
                'code' => $code,
                'client_id' => getenv("{$provider}_CLIENT_ID"),
                'client_secret' => getenv("{$provider}_CLIENT_SECRET")
            ],
            'http_errors' => false
        ]);

        if ($response->getStatusCode() == 200) {
            $data = json_decode($response->getBody(), true);
            Cache::put($this->getCacheKey($provider, $data['access_token']), $data['user'], now()->addMinutes($data['expires_in']));
            return ['token' => $data['access_token'], 'user' => $data['user']];
        } else {
            $this->logger->error('Authentication failed for provider: '.$provider);
            throw new \Exception('Authentication failed');
        }
    }

    public function getUserInfo(string $accessToken) {
        try {
            $cacheKey = Cache::getCacheKey($accessToken);
            if ($userInfo = Cache::get($cacheKey)) {
                return $userInfo;
            } else {
                $response = $this->clients['provider']->request('GET', '/userinfo', [
                    'headers' => ['Authorization' => "Bearer {$accessToken}"]
                ]);

                if ($response->getStatusCode() == 200) {
                    $userInfo = json_decode($response->getBody(), true);
                    Cache::put($cacheKey, $userInfo, now()->addMinutes(30));
                    return $userInfo;
                } else {
                    throw new \Exception('Failed to retrieve user info');
                }
            }
        } catch (\Exception $e) {
            $this->logger->error('Error retrieving user info: '.$e->getMessage());
            throw $e;
        }
    }

    private function getCacheKey(string $provider, string $token) {
        return $this->cachePrefix.'.'.$provider.'.'.$token;
    }
}
