        private readonly Dictionary<string, Func<T, bool>> _filters = new();
        private readonly Dictionary<string, Func<T, T>> _mappers = new();
        private readonly Dictionary<string, Func<IEnumerable<T>, T>> _aggregators = new();

        public DataProcessor()
        {
            _httpClient = new HttpClient();
        }

        public void AddFilter(string name, Func<T, bool> filter)
        {
            _filters[name] = filter;
        }

        public void AddMapper(string name, Func<T, T> mapper)
        {
            _mappers[name] = mapper;
        }

        public void AddAggregator(string name, Func<IEnumerable<T>, T> aggregator)
        {
            _aggregators[name] = aggregator;
        }

        public async Task<List<T>> ProcessDataAsync(Stream dataStream, string format)
        {
            var data = await ReadDataAsync(dataStream, format);
            return ApplyTransformations(data);
        }

        private async Task<IEnumerable<T>> ReadDataAsync(Stream dataStream, string format)
        {
            switch (format.ToLower())
            {
                case "json":
                    return await JsonReader.ReadAsync<T>(dataStream);
                case "csv":
                    return await CsvReader.ReadAsync<T>(dataStream);
                case "avro":
                    return await AvroReader.ReadAsync<T>(dataStream);
                default:
                    throw new ArgumentException("Unsupported data format");
            }
        }

        private List<T> ApplyTransformations(IEnumerable<T> data)
        {
            foreach (var filter in _filters.Values)
            {
                data = data.Where(filter).ToList();
            }

            foreach (var mapper in _mappers.Values)
            {
                data = data.Select(mapper);
            }

            return _aggregators.Any()
                ? _aggregators.First().Value(data).Cast<T>().ToList()
                : data.ToList();
        }
    }

    public static class JsonReader
    {
        public static async Task<IEnumerable<T>> ReadAsync<T>(Stream dataStream)
        {
            using (var reader = new StreamReader(dataStream))
            {
                var json = await reader.ReadToEndAsync();
                return Newtonsoft.Json.JsonConvert.DeserializeObject<List<T>>(json);
            }
        }
    }

    public static class CsvReader
    {
        public static async Task<IEnumerable<T>> ReadAsync<T>(Stream dataStream)
        {
            using (var reader = new StreamReader(dataStream))
            {
                var csv = await reader.ReadToEndAsync();
                return CsvHelper.CsvParser.Parser(csv, typeof(T)).Select(record => record.ToObject<T>()).ToList();
            }
        }
    }

    public static class AvroReader
    {
        public static async Task<IEnumerable<T>> ReadAsync<T>(Stream dataStream)
        {
