    await promisify(setTimeout)(100); // Simulate delay
  }
}

const sessionStorage = new SessionStorage();

// Reduction function using the reduce() method
async function processSessions(sessions, reducerFunction) {
  return sessions.reduce(async (accPromise, session) => {
    const acc = await accPromise;
    try {
      const result = await reducerFunction(session);
      return { ...acc, [session.sessionId]: result };
    } catch (error) {
      console.error(`Error processing session ${session.sessionId}:`, error);
      return acc; // Continue with the accumulator
    }
  }, Promise.resolve({}));
}

// Session management logic
async function manageSession(sessionData) {
  const { sessionId, data } = sessionData;
  try {
    // Generate a unique session ID (resistant to fixation)
    const newSessionId = crypto.randomBytes(16).toString('hex');

    // Store the session in external storage
    await sessionStorage.setSession(newSessionId, data);

    console.log(`Session ${newSessionId} created successfully.`);
    return { sessionId: newSessionId };
  } catch (error) {
    console.error('Error managing session:', error);
    throw error;
  }
}

// Example usage
