#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SEGMENT_SIZE 1024

typedef struct {
    char* buffer;
    size_t bufferSize;
    size_t usedSize;
} ResultBuffer;

void initializeResultBuffer(ResultBuffer* buffer, size_t initialSize) {
    buffer->buffer = (char*)malloc(initialSize);
    buffer->bufferSize = initialSize;
    buffer->usedSize = 0;
}

void appendToBuffer(ResultBuffer* buffer, const char* segment) {
    if (buffer->usedSize + strlen(segment) >= buffer->bufferSize - 1) {
        // Handle potential overflow by reallocating the buffer
        buffer->bufferSize *= 2;
        buffer->buffer = (char*)realloc(buffer->buffer, buffer->bufferSize);
    }
    strcat(buffer->buffer + buffer->usedSize, segment);
    buffer->usedSize += strlen(segment);
}

void finalizeBuffer(ResultBuffer* buffer) {
    if (buffer->usedSize < buffer->bufferSize - 1) {
        buffer->buffer[buffer->usedSize] = '\0';
    } else {
        buffer->buffer[buffer->bufferSize - 1] = '\0';
    }
}

int appendStringWithLimit(const char* input, int sizeLimit, char* resultBuffer, int bufferSize) {
    ResultBuffer buffer;
    initializeResultBuffer(&buffer, bufferSize);

    // Simulate fetching segments from an external data source
    const char* segments[] = {"Segment1 ", "Segment2", "Segment3"};
    for (size_t i = 0; i < sizeof(segments) / sizeof(segments[0]); ++i) {
        if (strlen(buffer.buffer) + strlen(segments[i]) >= sizeLimit - 1) break;
        appendToBuffer(&buffer, segments[i]);
    }

    finalizeBuffer(&buffer);
    strncpy(resultBuffer, buffer.buffer, bufferSize - 1);
    resultBuffer[bufferSize - 1] = '\0';

    free(buffer.buffer);

    return 0;
}

int main() {
    char result[2048];
    if (appendStringWithLimit("Hello, ", 2048, result, sizeof(result)) == 0) {
        printf("Result: %s\n", result);
    } else {
        printf("Error occurred.\n");
    }
    return 0;
}
