        players.push_back(std::move(player));
    }

    void parseHeader(const std::string& filePath, int& channels, int& sampleRate, int& bitDepth) {
        for (const auto& parser : parsers) {
            try {
                parser->parseHeader(filePath, channels, sampleRate, bitDepth);
                return;
            } catch (const std::exception& e) {
                logger->log("Error parsing header: " + std::string(e.what()));
            }
        }
        throw std::runtime_error("Unsupported audio format");
    }

