        for (const auto& player : players) {
            try {
                player->play(filePath);
                return;
            } catch (const std::exception& e) {
                logger->log("Error playing file: " + std::string(e.what()));
            }
        }
        throw std::runtime_error("Unsupported audio format");
    }
};

