{
    private readonly string _directoryPath;
    private readonly string _siteIdentifier;
    private WebApplicationConfiguration _webAppConfig;
    private MonitoringParameters _monitoringParams;
    private readonly List<ExternalIntegrationPoint> _integrationPoints = new();
    private int _port;
    private readonly object _lock = new();

    public DynamicWebAppManager(string directoryPath, string siteIdentifier, 
        WebApplicationConfiguration webAppConfig, MonitoringParameters monitoringParams)
    {
        _directoryPath = directoryPath;
        _siteIdentifier = siteIdentifier;
        _webAppConfig = webAppConfig;
        _monitoringParams = monitoringParams;
        InitializeIntegrationPoints();
    }

    private void InitializeIntegrationPoints()
    {
        _integrationPoints.Add(new ExternalIntegrationPoint("PostgreSQL", "ConnectionStrings:DefaultConnection"));
        _integrationPoints.Add(new ExternalIntegrationPoint("RabbitMQ", "QueueSettings"));
        // Add other integration points as needed
    }

    public Task StartAsync(CancellationToken cancellationToken)
    {
        if (!Directory.Exists(_directoryPath))
            throw new DirectoryNotFoundException($"The directory {_directoryPath} does not exist.");

        var webConfigPath = Path.Combine(_directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
            throw new FileNotFoundException("The web.config file is missing.");

        lock (_lock)
        {
            _port = FindAvailablePort();
            if (_port == -1)
                throw new InvalidOperationException("No available ports in the range.");
        }

        // Configure and start web application
        var hostBuilder = Host.CreateDefaultBuilder()
            .ConfigureServices((context, services) =>
            {
                services.AddHostedService<DynamicWebAppManager>();
                services.AddSingleton(_webAppConfig);
                services.AddSingleton(_monitoringParams);
                // Add other service registrations as needed
            })
            .UseUrls($"http://*:{_port}");

        var host = hostBuilder.Build();
        return host.StartAsync(cancellationToken);
    }

    private int FindAvailablePort()
    {
        for (int port = 8000; port <= 9999; port++)
        {
            if (!IsPortInUse(port))
                return port;
        }
        return -1;
    }

    private bool IsPortInUse(int port)
    {
        try
        {
            using (var listener = new System.Net.Sockets.TcpListener(System.Net.IPAddress.Any, port))
            {
                listener.Start();
                listener.Stop();
                return false;
            }
        }
        catch (Exception)
        {
            return true;
        }
    }

    public Task StopAsync(CancellationToken cancellationToken)
    {
        // Implement logic to stop web application and clean up resources
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        // Clean up any resources
    }

