using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

public class ImageProcessor
{
    public void ProcessImageBatch(List<string> inputFiles, Dictionary<string, object> transformationParams, string outputDir, Configuration config)
    {
        // Ensure output directory exists
        Directory.CreateDirectory(outputDir);

        var tasks = new List<Task>();

        foreach (var file in inputFiles)
        {
            tasks.Add(Task.Run(() => ProcessImage(file, transformationParams, outputDir, config)));
        }

        Task.WhenAll(tasks).Wait();
    }

    private void ProcessImage(string inputPath, Dictionary<string, object> params, string outputPath, Configuration config)
    {
        using (var image = Image.FromFile(inputPath))
        {
            // Apply transformations
            var transformedImage = ApplyTransformations(image, params);

            // Save the transformed image
            var outputFilePath = Path.Combine(outputPath, Path.GetFileName(inputPath));
            transformedImage.Save(outputFilePath, GetImageFormat(inputPath));
        }
    }

    private Image ApplyTransformations(Image image, Dictionary<string, object> params)
    {
        foreach (var param in params)
        {
            switch (param.Key)
            {
                case "resize":
                    var size = (Size)param.Value;
                    return new Bitmap(image, size);
                case "crop":
                    var rect = (Rectangle)param.Value;
                    return image.Clone(rect, image.PixelFormat);
                case "rotate":
                    float angle = (float)param.Value;
                    using (var rotatedImage = new Bitmap(image.Width, image.Height))
                    {
                        using (var graphics = Graphics.FromImage(rotatedImage))
                        {
                            graphics.TranslateTransform(image.Width / 2, image.Height / 2);
                            graphics.RotateTransform(angle);
                            graphics.TranslateTransform(-image.Width / 2, -image.Height / 2);
                            graphics.DrawImage(image, 0, 0);
                        }
                        return rotatedImage;
                    }
                case "grayscale":
                    using (var converter = new ImageConverter())
                    {
                        return (Image)converter.ConvertTo(converter.ConvertFrom(image), typeof(Image));
                    }
                case "blur":
                    int radius = (int)param.Value;
                    return ApplyBlurFilter(image, radius);
                default:
                    throw new ArgumentException($"Unknown transformation: {param.Key}");
            }
        }

        return image;
    }

    private Image ApplyBlurFilter(Image image, int radius)
    {
        using (var sourceBitmap = new Bitmap(image.Width, image.Height))
        using (var destinationBitmap = new Bitmap(image.Width, image.Height))
        {
            sourceBitmap.DrawImage(image, 0, 0);
            var filterMatrix = GenerateBlurMatrix(radius);

            for (int x = 0; x < sourceBitmap.Width; x++)
            {
                for (int y = 0; y < sourceBitmap.Height; y++)
                {
                    Color pixelColor = GetPixel(sourceBitmap, x, y, filterMatrix);
                    destinationBitmap.SetPixel(x, y, pixelColor);
                }
            }

            return destinationBitmap;
        }
    }

    private Matrix GenerateBlurMatrix(int radius)
    {
        int size = 2 * radius + 1;
        float[,] matrixValues = new float[size, size];
        float sum = 0;

        for (int i = -radius; i <= radius; i++)
        {
            for (int j = -radius; j <= radius; j++)
            {
                matrixValues[i + radius, j + radius] = 1f;
                sum += 1;
            }
        }

        for (int i = 0; i < size; i++)
        {
            for (int j = 0; j < size; j++)
            {
                matrixValues[i, j] /= sum;
            }
        }

        return new Matrix(matrixValues);
    }

    private Color GetPixel(Bitmap bitmap, int x, int y, Matrix filterMatrix)
    {
        float r = 0, g = 0, b = 0;

        for (int i = -filterMatrix.Radius; i <= filterMatrix.Radius; i++)
        {
            for (int j = -filterMatrix.Radius; j <= filterMatrix.Radius; j++)
            {
                int pixelX = x + i;
                int pixelY = y + j;

                if (pixelX >= 0 && pixelX < bitmap.Width && pixelY >= 0 && pixelY < bitmap.Height)
                {
                    Color pixelColor = bitmap.GetPixel(pixelX, pixelY);
                    r += pixelColor.R * filterMatrix.Values[i + filterMatrix.Radius, j + filterMatrix.Radius];
                    g += pixelColor.G * filterMatrix.Values[i + filterMatrix.Radius, j + filterMatrix.Radius];
                    b += pixelColor.B * filterMatrix.Values[i + filterMatrix.Radius, j + filterMatrix.Radius];
                }
            }
        }

        return Color.FromArgb((int)r, (int)g, (int)b);
    }

    private ImageFormat GetImageFormat(string filePath)
    {
        string extension = Path.GetExtension(filePath).ToLower();
        switch (extension)
        {
            case ".jpg":
            case ".jpeg":
                return ImageFormat.Jpeg;
            case ".png":
                return ImageFormat.Png;
            case ".gif":
                return ImageFormat.Gif;
            default:
                throw new ArgumentException($"Unsupported image format: {extension}");
        }
    }

    public class Configuration
    {
        public int ConcurrencyLimit { get; set; } = 10;
        public bool UseCloudStorage { get; set; } = false;
    }

    public class Matrix
    {
        public float[,] Values { get; set; }
        public int Radius => (Values.GetLength(0) - 1) / 2;

        public Matrix(float[,] values)
        {
            Values = values;
        }
    }
}
```']

