using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class AESGCMDecryptionService
{
    private readonly IKeyManagementService _keyManagementService;
    private byte[] _currentKey;
    private byte[] _currentIV;

    public AESGCMDecryptionService(IKeyManagementService keyManagementService)
    {
        _keyManagementService = keyManagementService;
        InitializeKeysAsync().Wait();
    }

    private async Task InitializeKeysAsync()
    {
        _currentKey = await _keyManagementService.GetKeyAsync();
        _currentIV = await _keyManagementService.GetIVAsync();
        StartAutomaticKeyRotation();
    }

    private void StartAutomaticKeyRotation()
    {
        Task.Run(async () =>
        {
            while (true)
            {
                await Task.Delay(TimeSpan.FromHours(24));
                _currentKey = await _keyManagementService.GetKeyAsync();
                _currentIV = await _keyManagementService.GetIVAsync();
            }
        });
    }

    public object DecryptAndDeserialize(Stream encryptedStream, string format)
    {
        switch (format.ToLower())
        {
            case "json":
                return DeserializeFromJson(Decrypt(encryptedStream));
            case "xml":
                return DeserializeFromXml(Decrypt(encryptedStream));
            case "binary":
                return DeserializeFromBinary(Decrypt(encryptedStream));
            default:
                throw new ArgumentException("Unsupported format");
        }
    }

    private byte[] Decrypt(Stream encryptedStream)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = _currentKey;
            aes.IV = _currentIV;
            aes.Mode = CipherMode.GCM;

            using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
            using (var msDecrypt = new MemoryStream())
            {
                using (var csDecrypt = new CryptoStream(encryptedStream, decryptor, CryptoStreamMode.Read))
                {
                    csDecrypt.CopyTo(msDecrypt);
                }
                return msDecrypt.ToArray();
            }
        }
    }

    private object DeserializeFromJson(byte[] data)
    {
        // Implement JSON deserialization logic here
        throw new NotImplementedException();
    }

    private object DeserializeFromXml(byte[] data)
    {
        // Implement XML deserialization logic here
        throw new NotImplementedException();
    }

    private object DeserializeFromBinary(byte[] data)
    {
        // Implement binary deserialization logic here
        throw new NotImplementedException();
    }
}

public interface IKeyManagementService
{
    Task<byte[]> GetKeyAsync();
    Task<byte[]> GetIVAsync();
}
