using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Configuration;

public class DataLibrary
{
    private readonly IConfiguration _configuration;
    private readonly IMemoryCache _cache;
    private readonly IValidationFramework _validationFramework;
    private readonly IDistributedCacheService _distributedCacheService;

    public DataLibrary(IConfiguration configuration, IMemoryCache cache, IValidationFramework validationFramework, IDistributedCacheService distributedCacheService)
    {
        _configuration = configuration;
        _cache = cache;
        _validationFramework = validationFramework;
        _distributedCacheService = distributedCacheService;
    }

    public async Task<T> LoadDataAsync<T>(string filePath)
    {
        if (_cache.TryGetValue(filePath, out T data))
            return data;

        string fileMode = _configuration.GetSection("FileMode").Value;
        var dataStream = new MemoryStream();

        if (fileMode == "Local")
        {
            using (var localFileStream = File.OpenRead(filePath))
            {
                await localFileStream.CopyToAsync(dataStream);
            }
        }
        else
        {
            using (var remoteFileStream = _distributedCacheService.GetFileAsync(filePath))
            {
                await remoteFileStream.CopyToAsync(dataStream);
            }
        }

        data = DeserializeData<T>(dataStream);

        var validationSettings = _configuration.GetSection("Validation").Get<ValidationSettings>();
        if (_validationFramework.Validate(data, validationSettings))
        {
            lock (_cache)
            {
                if (!_cache.TryGetValue(filePath, out _))
                    _cache.Set(filePath, data, new MemoryCacheEntryOptions().SetAbsoluteExpirationRelativeToNow(TimeSpan.FromMinutes(10)));
            }
        }

        return data;
    }

    private T DeserializeData<T>(MemoryStream stream)
    {
