const express = require('express');
const axios = require('axios');
const rateLimit = require('express-rate-limit');
const redis = require('redis');
const { promisify } = require('util');

const app = express();
const port = 3000;

// Redis setup for caching and rate limiting
const client = redis.createClient();
client.on('error', (err) => {
  console.log('Redis error:', err);
});
const getAsync = promisify(client.get).bind(client);

// Rate limiter configuration
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again after 15 minutes'
});

app.use(apiLimiter);

// Middleware to handle authentication tokens
const authenticateToken = async (req, res, next) => {
  const token = req.headers['authorization'];
  if (!token) return res.status(403).send('A token is required for authentication');

  try {
    // Validate token logic here (e.g., check with an external service)
    const validToken = await verifyToken(token);
    if (!validToken) return res.status(401).send('Invalid token');
    next();
  } catch (error) {
    res.status(500).send('Error verifying token');
  }
};

// Route to fetch configuration updates
app.get('/config', authenticateToken, async (req, res) => {
  try {
    const configKey = 'dynamic_config';
    let config = await getAsync(configKey);

    if (!config) {
      // Fetch configuration from external API
      const response = await axios.get('https://api.example.com/config');
      config = response.data;
      client.setex(configKey, 3600, JSON.stringify(config)); // Cache for 1 hour
    }

    res.json(JSON.parse(config));
  } catch (error) {
    console.error('Error fetching configuration:', error);
    res.status(500).send('Failed to fetch configuration');
  }
});

// Circuit breaker pattern using axios-retry
const config = {
  retries: 3,
  retryDelay: (retryCount) => Math.pow(2, retryCount) * 1000,
  retryCondition: (error) => error.response && [500, 502, 503, 504].includes(error.response.status)
};

const axiosInstance = axios.create(config);

// Function to fetch configuration with exponential backoff
const fetchConfigWithRetry = async () => {
  try {
    const response = await axiosInstance.get('https://api.example.com/config');
    return response.data;
  } catch (error) {
    console.error('Error fetching configuration:', error);
    throw error;
  }
};

app.listen(port, () => {
  console.log(`Microservice running on port ${port}`);
});
