    tokio::spawn(async move {
        loop {
            let task = get_next_task(&tasks).await?;
            perform_task(task, &client, cli.drone_id.clone(), logs.0.clone()).await;
            tokio::time::sleep(tokio::time::Duration::from_secs(60)).await; // Simulate time passing
        }
    });

    // Log system metrics and AI model predictions
    tokio::spawn(async move {
        loop {
            let metrics = get_system_metrics();
            let prediction = run_ai_model();
            logs.1.send((Local::now(), metrics, prediction)).await?;
            tokio::time::sleep(tokio::time::Duration::from_secs(30)).await; // Simulate time passing
        }
    });

    Ok(())
}

async fn get_next_task(tasks: &RwLock<Vec<Task>>) -> Result<Task, Box<dyn std::error::Error>> {
    let mut tasks = tasks.write().await;
    if tasks.is_empty() {
        return Err("No tasks available".into());
    }
    let task = tasks.remove(0);
    Ok(task)
}

