    task: Task,
    client: &Client,
    drone_id: String,
    logs: mpsc::Sender<(chrono::DateTime<Local>, SystemMetrics, AiModelPrediction)>,
) {
    match task {
        Task::CropHealthAnalysis => {
            // Perform crop health analysis
            let result = run_crop_health_analysis(&client).await?;
            log_task_result(logs.clone(), drone_id.clone(), &result).await;
