        Task::SoilMoistureMonitoring => {
            // Perform soil moisture monitoring
            let result = run_soil_moisture_monitoring(&client).await?;
            log_task_result(logs.clone(), drone_id.clone(), &result).await;
        }
        Task::PesticideSpraying => {
            // Perform pesticide spraying
            let result = run_pesticide_spraying(&client).await?;
            log_task_result(logs.clone(), drone_id.clone(), &result).await;
        }
    }
