use std::sync::{Arc, Mutex};
use tokio::net::{TcpListener, TcpStream};
use tokio::task;
use uuid::Uuid;

#[derive(Debug)]
struct UserSession {
    user_id: String,
    session_dir: Option<String>,
}

#[derive(Debug)]
struct SessionManager {
    sessions: Arc<Mutex<Vec<UserSession>>>,
}

impl SessionManager {
    fn new() -> Self {
        SessionManager {
            sessions: Arc::new(Mutex::new(Vec::new())),
        }
    }

    async fn handle_session(&self, stream: TcpStream) {
        let session_id = Uuid::new_v4().to_string();
        let mut session = UserSession {
            user_id: String::new(),
            session_dir: None,
        };

        // Read user ID from the stream
        let mut buffer = [0; 128];
        stream.read(&mut buffer).await.unwrap();
        session.user_id = String::from_utf8_lossy(&buffer).trim().to_string();

        // Check if session already exists
        {
            let sessions = self.sessions.lock().unwrap();
            for s in sessions.iter() {
                if s.user_id == session.user_id {
                    session = s.clone();
                    break;
                }
            }
        }

        // Create directory or use existing one
        if session.session_dir.is_none() {
            // Use distributed lock mechanism (e.g., etcd) to ensure only one directory is created per user
            let dir_path = format!("/path/to/directory/{}", session_id);
            // Create directory logic here

            session.session_dir = Some(dir_path);
        }

        // Set environment variable
        std::env::set_var("SESSION_DIR", &session.session_dir.unwrap());

        // Log session information
        println!("Session {} for user {} created at {:?}", session_id, session.user_id, std::time::SystemTime::now());
    }
}

#[tokio::main]
async fn main() {
    let listener = TcpListener::bind("0.0.0.0:8080").await.unwrap();
    println!("Listening on {}", listener.local_addr().unwrap());

    let session_manager = Arc::new(SessionManager::new());

    loop {
        match listener.accept().await {
            Ok((stream, addr)) => {
                println!("Accepted connection from {:?}", addr);
                let session_manager_clone = Arc::clone(&session_manager);
                task::spawn(async move {
                    session_manager_clone.handle_session(stream).await;
                });
            }
            Err(e) => {
                eprintln!("Error accepting connection: {}", e);
            }
        }
    }
}
