import hashlib
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed

def fetch_and_compute_file_md5(file_path):
    if file_path.startswith('http'):
        return fetch_and_compute_md5_from_url(file_path)
    else:
        return fetch_and_compute_md5_from_local(file_path)

def fetch_and_compute_md5_from_url(url):
    response = requests.get(url, stream=True)
    response.raise_for_status()
    md5_hash = hashlib.md5()
    for chunk in response.iter_content(chunk_size=8192):
        if chunk:
            md5_hash.update(chunk)
    return md5_hash.hexdigest()

def fetch_and_compute_md5_from_local(file_path):
    with open(file_path, 'rb') as f:
        md5_hash = hashlib.md5()
        while chunk := f.read(8192):
            md5_hash.update(chunk)
    return md5_hash.hexdigest()

# Example usage
if __name__ == "__main__":
    local_file_path = 'path/to/local/file'
    url = 'http://example.com/file'

    print(f"MD5 of local file: {fetch_and_compute_file_md5(local_file_path)}")
