import hashlib
import requests
from multiprocessing import Pool, cpu_count
from threading import Thread, Lock
from queue import Queue

def calculate_md5(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(1024*1024), b''):
            hasher.update(chunk)
    return hasher.hexdigest()

def fetch_file(url):
    response = requests.get(url, stream=True)
    return response.content

def compute_md5_from_url(url):
    file_content = fetch_file(url)
    hasher = hashlib.md5()
    hasher.update(file_content)
    return hasher.hexdigest()

def hash_files_in_parallel(files, max_workers=None):
    if max_workers is None:
        max_workers = cpu_count()

    with Pool(processes=max_workers) as pool:
        results = pool.map(calculate_md5, files)
    return results

def process_files(file_paths, url_list, cache, task_queue):
    tasks = Queue()
    for path in file_paths:
        tasks.put(path)

    def worker():
        while not tasks.empty():
            file_path = tasks.get()
            md5_hash = calculate_md5(file_path)
            cache.set(file_path, md5_hash)
            task_queue.put(md5_hash)

    threads = []
    for _ in range(cpu_count()):
        thread = Thread(target=worker)
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

def fetch_and_compute_file_md5(file_paths, url_list, cache, task_queue):
    files_to_hash = [path for path in file_paths if not cache.exists(path)]
    urls_to_hash = [url for url in url_list if not cache.exists(url)]

    md5_hashes = hash_files_in_parallel(files_to_hash)
    for path, md5_hash in zip(files_to_hash, md5_hashes):
        cache.set(path, md5_hash)

    for url in urls_to_hash:
        md5_hash = compute_md5_from_url(url)
        cache.set(url, md5_hash)

    process_files(file_paths, url_list, cache, task_queue)
