import hashlib
import os
import time
from concurrent.futures import ThreadPoolExecutor
from datetime import timedelta

class FileHasher:
    def __init__(self, encoding='utf-8', progress_callback=None):
        self.encoding = encoding
        self.progress_callback = progress_callback
        self.metadata_cache = {}
        self.cache_expiration = timedelta(minutes=15)

    def compute_md5(self, file_path):
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"File not found: {file_path}")

        hasher = hashlib.md5()
        chunk_size = 1 * 1024 * 1024  # 1 MB
        total_size = os.path.getsize(file_path)
        bytes_read = 0

        with open(file_path, 'rb') as file:
            for chunk in iter(lambda: file.read(chunk_size), b''):
                hasher.update(chunk)
                bytes_read += len(chunk)
                if self.progress_callback:
                    self.progress_callback(bytes_read / total_size)

        return hasher.hexdigest()

    def get_metadata(self, resource_id):
        current_time = time.time()
        if resource_id not in self.metadata_cache or \
           (current_time - self.metadata_cache[resource_id]['timestamp']) > self.cache_expiration.total_seconds():
            # Fetch metadata from external service
            metadata = self.fetch_metadata_from_service(resource_id)
            self.metadata_cache[resource_id] = {'data': metadata, 'timestamp': current_time}
        return self.metadata_cache[resource_id]['data']

    def fetch_metadata_from_service(self, resource_id):
        # Simulate fetching metadata from an external service
        time.sleep(1)  # Simulate network delay
        return f"Metadata for {resource_id}"

class MetadataService:
    @staticmethod
    def get_metadata(resource_id):
        return FileHasher().get_metadata(resource_id)

# C# function to compute MD5 hash
import System.Security.Cryptography

def compute_md5_csharp(input_string):
    md5 = System.Security.Cryptography.MD5.Create()
    input_bytes = System.Text.Encoding.UTF8.GetBytes(input_string)
    hash_bytes = md5.ComputeHash(input_bytes)
    hash_string = ''.join(['{0:x}'.format(b) for b in hash_bytes])
    return hash_string
