package filestorage

import (
    "crypto/md5"
    "crypto/sha256"
    "errors"
    "fmt"
    "io"
    "log"
    "net/http"
    "os"
    "strings"

    "github.com/go-redis/redis/v8"
)

const (
    chunkSize = 10 * 1024 * 1024 // 10MB
    metaPath  = "/path/to/meta"
)

type FileHasher struct {
    redisClient *redis.Client
}

func NewFileHasher(redisAddr string) (*FileHasher, error) {
    client := redis.NewClient(&redis.Options{
        Addr:     redisAddr,
        Password: "", // no password set
        DB:       0,  // use default DB
    })

    _, err := client.Ping(client.Context()).Result()
    if err != nil {
        return nil, errors.Wrap(err, "failed to connect to Redis")
    }

    return &FileHasher{
        redisClient: client,
    }, nil
}

func (fh *FileHasher) HashAndUpload(fileID string, filePath string) error {
    fileInfo, err := os.Stat(filePath)
    if err != nil {
        return errors.Wrap(err, "failed to get file info")
    }

    md5Hasher := md5.New()
    sha256Hasher := sha256.New()

    file, err := os.Open(filePath)
    if err != nil {
        return errors.Wrap(err, "failed to open file")
    }
    defer file.Close()

    startPosition, err := fh.getUploadPosition(fileID)
    if err != nil {
        return errors.Wrap(err, "failed to get upload position")
    }

    _, err = file.Seek(startPosition, io.SeekStart)
    if err != nil {
        return errors.Wrap(err, "failed to seek file")
    }

    buffer := make([]byte, chunkSize)
    for {
        n, err := file.Read(buffer)
        if err != nil && err != io.EOF {
            return errors.Wrap(err, "failed to read file")
        }
        if n == 0 {
            break
        }

        md5Hasher.Write(buffer[:n])
        sha256Hasher.Write(buffer[:n])

        startPosition += int64(n)
    }

    md5Sum := fmt.Sprintf("%x", md5Hasher.Sum(nil))
    sha256Sum := fmt.Sprintf("%x", sha256Hasher.Sum(nil))

    err = fh.storeMetadata(fileID, fileInfo.Size(), md5Sum, sha256Sum)
    if err != nil {
        return errors.Wrap(err, "failed to store metadata")
    }

    log.Printf("File %s uploaded successfully with MD5: %s, SHA-256: %s", fileID, md5Sum, sha256Sum)

    return nil
}

func (fh *FileHasher) getUploadPosition(fileID string) (int64, error) {
    value, err := fh.redisClient.Get(fh.redisClient.Context(), fileID).Result()
    if err == redis.Nil {
        return 0, nil
    } else if err != nil {
        return 0, errors.Wrap(err, "failed to get upload position from Redis")
    }

    position, err := strconv.ParseInt(value, 10, 64)
    if err != nil {
        return 0, errors.Wrap(err, "invalid upload position in Redis")
    }

    return position, nil
}

func (fh *FileHasher) storeMetadata(fileID string, fileSize int64, md5Sum, sha256Sum string) error {
    metadata := map[string]interface{}{
        "fileSize":  fileSize,
        "md5Sum":    md5Sum,
        "sha256Sum": sha256Sum,
    }

    err := fh.redisClient.HMSet(fh.redisClient.Context(), fileID, metadata).Err()
    if err != nil {
        return errors.Wrap(err, "failed to store metadata in Redis")
    }

    return nil
}

func main() {
    hasher, err := NewFileHasher("localhost:6379")
    if err != nil {
        log.Fatalf("Failed to create file hasher: %v", err)
    }

    http.HandleFunc("/upload", func(w http.ResponseWriter, r *http.Request) {
        fileID := r.URL.Query().Get("file_id")
        filePath := r.URL.Query().Get("file_path")

        if fileID == "" || filePath == "" {
            http.Error(w, "Missing file ID or file path", http.StatusBadRequest)
            return
        }

        err := hasher.HashAndUpload(fileID, filePath)
        if err != nil {
            http.Error(w, fmt.Sprintf("Failed to upload file: %v", err), http.StatusInternalServerError)
        } else {
            w.WriteHeader(http.StatusOK)
        }
    })

    log.Fatal(http.ListenAndServe(":8080", nil))
}
```

This Go code snippet defines a `FileHasher` struct that implements the required functionality for hashing files and resuming uploads in a distributed cloud storage platform. The system uses MD5 and SHA-256 hashes to ensure file integrity, reads files in chunks to manage memory efficiently, and stores the current position in a metadata file using Redis for efficient retrieval and storage. The solution includes error handling, logging, and integration with an existing microservices architecture.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONCURRENCY 100

typedef struct {
    int* data;
    size_t size;
} IntStream;

typedef struct {
    IntStream* stream;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} ThreadSafeQueue;

void init_queue(ThreadSafeQueue* queue) {
    queue->stream = (IntStream*)malloc(sizeof(IntStream));
    queue->stream->data = (int*)malloc(MAX_CONCURRENCY * sizeof(int));
    queue->stream->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond, NULL);
}

void enqueue(ThreadSafeQueue* queue, int value) {
    pthread_mutex_lock(&queue->lock);
    if (queue->stream->size < MAX_CONCURRENCY) {
        queue->stream->data[queue->stream->size++] = value;
        pthread_cond_signal(&queue->cond);
    }
    pthread_mutex_unlock(&queue->lock);
}

int dequeue(ThreadSafeQueue* queue, int* value) {
    pthread_mutex_lock(&queue->lock);
    while (queue->stream->size == 0) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }
    *value = queue->stream->data[--queue->stream->size];
    pthread_mutex_unlock(&queue->lock);
    return 1;
}

void destroy_queue(ThreadSafeQueue* queue) {
    free(queue->stream->data);
    free(queue->stream);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->cond);
}
```

This code snippet demonstrates a simple thread-safe queue implementation for an integer stream using POSIX threads and condition variables. The `enqueue` function adds integers to the queue, while the `dequeue` function removes them in a thread-safe manner. The queue has a maximum concurrency limit to prevent resource overuse.

To implement the full fault-tolerant C library as described, you would need to integrate this queue with an asynchronous message broker, develop retry mechanisms and circuit breakers, and extend it with support for configuration, error handling, metrics, logging, security, and testing. This requires a comprehensive approach that involves multiple modules and careful consideration of system constraints and performance requirements.']

