class UserMetadataService {
    private $db;
    private $redis;

    public function __construct() {
        $this->db = new PDO('mysql:host=' . config()['database']['host'] . ';dbname=' . config()['database']['name'], config()['database']['username'], config()['database']['password']);
        $this->redis = new Redis();
        $this->redis->connect(config()['redis']['host'], config()['redis']['port']);
    }

    public function handleRequest($request) {
        $data = json_decode($request, true);
        $action = $data['action'];
        $id = $data['id'];

        switch ($action) {
            case 'create':
                return $this->createMetadata($id, $data['metadata']);
            case 'update':
                return $this->updateMetadata($id, $data['metadata']);
            case 'delete':
                return $this->deleteMetadata($id);
            case 'retrieve':
                return $this->retrieveMetadata($id);
            default:
                return json_encode(['error' => 'Invalid action'], JSON_PRETTY_PRINT);
        }
    }

    private function createMetadata($id, $metadata) {
        // Validate metadata against schema
        if (!$this->validateMetadata($metadata)) {
            return json_encode(['error' => 'Validation failed'], JSON_PRETTY_PRINT);
        }

        // Check if user is authorized to modify this account
        if (!$this->isAuthorized()) {
            return json_encode(['error' => 'Unauthorized'], JSON_PRETTY_PRINT);
        }

        $stmt = $this->db->prepare('INSERT INTO metadata (user_id, data) VALUES (:id, :data)');
        $stmt->execute([
            ':id' => $id,
            ':data' => json_encode($metadata)
        ]);

        return json_encode(['status' => 'success'], JSON_PRETTY_PRINT);
    }

    private function updateMetadata($id, $metadata) {
        if (!$this->validateMetadata($metadata)) {
            return json_encode(['error' => 'Validation failed'], JSON_PRETTY_PRINT);
        }

        if (!$this->isAuthorized()) {
            return json_encode(['error' => 'Unauthorized'], JSON_PRETTY_PRINT);
        }

        $stmt = $this->db->prepare('UPDATE metadata SET data = :data WHERE user_id = :id');
        $stmt->execute([
            ':id' => $id,
            ':data' => json_encode($metadata)
        ]);

        return json_encode(['status' => 'success'], JSON_PRETTY_PRINT);
    }

    private function deleteMetadata($id) {
        if (!$this->isAuthorized()) {
            return json_encode(['error' => 'Unauthorized'], JSON_PRETTY_PRINT);
        }

        $stmt = $this->db->prepare('DELETE FROM metadata WHERE user_id = :id');
        $stmt->execute([
            ':id' => $id
        ]);

        return json_encode(['status' => 'success'], JSON_PRETTY_PRINT);
    }

    private function retrieveMetadata($id) {
        $key = "user_metadata_{$id}";
        if ($this->redis->exists($key)) {
            return $this->redis->get($key);
        } else {
            $stmt = $this->db->prepare('SELECT data FROM metadata WHERE user_id = :id');
            $stmt->execute([
                ':id' => $id
            ]);
            $result = $stmt->fetch();
            if ($result) {
                $metadata = json_decode($result['data'], true);
                $this->redis->set($key, json_encode($metadata));
                return json_encode(['status' => 'success', 'data' => $metadata], JSON_PRETTY_PRINT);
            } else {
                return json_encode(['error' => 'User not found'], JSON_PRETTY_PRINT);
            }
        }
    }

