// PHP function to generate a secure random string and hash passwords
function secureOperations($length = 10, $charactersSetId = null) {
    if (!is_numeric($length)) {
        error_log("Invalid input for length");
        return false;
    }

    // Fetch character set from external API
    $charsetUrl = "https://api.example.com/charsets/{$charactersSetId}";
    $response = @file_get_contents($charsetUrl);

    if ($response === FALSE) {
        error_log("Failed to fetch charset from API");
        return false;
    }

    $characterSet = json_decode($response, true)['charset'];
    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomString .= $characterSet[rand(0, strlen($characterSet) - 1)];
    }

    // Hash a password
    $password = "examplePassword";
    $hashedPassword = password_hash($password, PASSWORD_DEFAULT);

    if ($hashedPassword === FALSE) {
        error_log("Failed to hash the password");
        return false;
    }

    // Log the hashing process
    file_put_contents('hash_log.txt', date('Y-m-d H:i:s') . " - Hashed Password: {$hashedPassword}\n", FILE_APPEND);

    return ['randomString' => $randomString, 'hashedPassword' => $hashedPassword];
}
