    void handleUEContext(const std::string& tenantId, const UEContext& context) {
        std::lock_guard<std::mutex> lock(mutex_);
        ueContexts_[tenantId].push(context);
        condition_.notify_one();
    }

    void processUEContext() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return !ueContexts_.empty(); });

            std::string tenantId;
            UEContext context = ueContexts_[tenantId].front();
            ueContexts_[tenantId].pop();

            lock.unlock();

            // Process the UE context
            processTenantUE(tenantId, context);

            if (stop_) {
                break;
            }
        }
    }

    void stop() {
        std::lock_guard<std::mutex> lock(mutex_);
        stop_ = true;
        condition_.notify_all();
    }

