        std::string key;
        if (!kms_->retrieveKey(keyId, key)) {
            throw std::runtime_error("Failed to retrieve key from KMS");
        }

        std::lock_guard<std::mutex> lock(mutex_);
        current_operations_++;
        plaintext = decryptWithMode(key, ciphertext);
        return true;
    }

private:
