from flask import Flask, request, jsonify, abort
import hashlib
import boto3
from botocore.exceptions import BotoCoreError, ClientError
from concurrent.futures import ThreadPoolExecutor
from functools import wraps
from time import sleep

app = Flask(__name__)
s3_client = boto3.client('s3')
bucket_name = 'your-s3-bucket'

def requires_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_token = request.headers.get('Authorization')
        if not auth_token:
            abort(401)
        # Implement your authentication logic here
        return f(*args, **kwargs)
    return decorated

def rate_limiter(max_requests=10, period=60):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            with ThreadPoolExecutor(max_workers=max_requests) as executor:
                future = executor.submit(f, *args, **kwargs)
                try:
                    return future.result(timeout=period)
                except Exception as e:
                    abort(429)
        return decorated
    return decorator

@app.route('/upload', methods=['POST'])
@requires_auth
@rate_limiter(max_requests=10, period=60)
def upload_file():
    if 'file' not in request.files:
        abort(400)

    file = request.files['file']
    file_name = file.filename
    file_hash = hashlib.sha256()

    try:
        s3_client.upload_fileobj(file, bucket_name, file_name)
    except (BotoCoreError, ClientError) as e:
        app.logger.error(f"Failed to upload file to S3: {e}")
        abort(500)

    with open(file.filename, 'rb') as f:
        while chunk := f.read(64 * 1024):  # Read in chunks of 64 KB
            file_hash.update(chunk)

    local_hash = file_hash.hexdigest()
    s3_hash = get_s3_file_hash(bucket_name, file_name)

    if local_hash == s3_hash:
        verification_status = 'Success'
    else:
        verification_status = 'Failure'

    log_entry = {
        'event': 'FileUpload',
        'file_name': file_name,
        'local_hash': local_hash,
        's3_hash': s3_hash,
        'verification_status': verification_status
    }
    app.logger.info(log_entry)

    return jsonify({
        'hash': s3_hash,
        'verification_status': verification_status,
        'log': log_entry
    }), 201

def get_s3_file_hash(bucket_name, file_name):
    try:
        response = s3_client.get_object(Bucket=bucket_name, Key=file_name)
        object_data = response['Body'].read()
        return hashlib.sha256(object_data).hexdigest()
    except (BotoCoreError, ClientError) as e:
        app.logger.error(f"Failed to retrieve file from S3: {e}")
        raise

@app.route('/health', methods=['GET'])
def health_check():
    try:
        s3_client.list_buckets()
        return jsonify({'status': 'healthy'}), 200
    except (BotoCoreError, ClientError) as e:
        app.logger.error(f"Health check failed: {e}")
        return jsonify({'status': 'unhealthy'}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

