private:
    KMSClient* kms;
    std::unordered_map<std::string, std::string> cache;
    std::mutex cacheMutex;

public:
    KMSCachingEncryption(KMSClient* kms) : kms(kms) {}

    std::string encrypt(const std::string& data) override {
        std::lock_guard<std::mutex> lock(cacheMutex);
        if (cache.find(data) != cache.end()) {
            return cache[data];
        }
        auto key = kms->getKey();
        std::string encryptedData = encryptWithKey(data, key);
        cache[data] = encryptedData;
        return encryptedData;
    }

    std::string decrypt(const std::string& data) override {
        std::lock_guard<std::mutex> lock(cacheMutex);
        if (cache.find(data) != cache.end()) {
            return cache[data];
        }
        auto key = kms->getKey();
        std::string decryptedData = decryptWithKey(data, key);
        cache[data] = decryptedData;
        return decryptedData;
    }

