class MultiThreadedFileHandler {
private:
    std::queue<std::string> tasks;
    std::mutex taskMutex;
    std::condition_variable taskCondition;
    bool stop;

public:
    MultiThreadedFileHandler() : stop(false) {}

    void addTask(const std::string& data) {
        std::lock_guard<std::mutex> lock(taskMutex);
        tasks.push(data);
        taskCondition.notify_one();
    }

    ~MultiThreadedFileHandler() {
        {
            std::lock_guard<std::mutex> lock(taskMutex);
            stop = true;
        }
        taskCondition.notify_all();
        for (std::thread& worker : workers) {
            if (worker.joinable()) {
                worker.join();
            }
        }
    }

private:
    void worker() {
        while (true) {
            std::string data;
            {
                std::unique_lock<std::mutex> lock(taskMutex);
                taskCondition.wait(lock, [this] { return !tasks.empty() || stop; });
                if (stop && tasks.empty()) {
                    return;
                }
                data = tasks.front();
                tasks.pop();
            }
            // Process the data
        }
    }

    std::vector<std::thread> workers;
};

