            $this->threadPool->submitTask(function() use ($filename) {
                // Process file metadata and update extension
                echo "Processing: $filename\n";
            });
        }
    }
}

class ThreadPool {
    private $pool = [];
    private $maxWorkers;

    public function __construct($numThreads) {
        $this->maxWorkers = $numThreads;
        for ($i = 0; $i < $numThreads; $i++) {
            $this->pool[] = new Worker();
        }
    }

    public function submitTask(callable $task) {
        foreach ($this->pool as $worker) {
            if (!$worker->isBusy()) {
                $worker->execute($task);
                break;
            }
        }
    }
}

class Worker {
    private $busy = false;

    public function isBusy() {
        return $this->busy;
    }

    public function execute(callable $task) {
        $this->busy = true;
        $task();
        $this->busy = false;
    }
}
