#include <iostream>
#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <memory>
#include <unordered_map>
#include <fstream>
#include <sstream>

// Define a simple structure for data packets
struct DataPacket {
    std::string data;
    std::string source;
};

// Define an interface for data processors
class IDataProcessor {
public:
    virtual ~IDataProcessor() = default;
    virtual void process(const DataPacket& packet) = 0;
};

// Implement a concrete processor for JSON data
class JsonDataProcessor : public IDataProcessor {
public:
    void process(const DataPacket& packet) override {
        std::cout << "Processing JSON from source: " << packet.source << "\n";
        // Add actual JSON processing logic here
    }
};

// Define a generic data stream handler
class DataStreamHandler {
private:
    std::queue<DataPacket> queue;
    std::mutex mutex;
    std::condition_variable cv;
    std::vector<std::shared_ptr<IDataProcessor>> processors;
    bool running;

public:
    void add_processor(std::shared_ptr<IDataProcessor> processor) {
        processors.push_back(processor);
    }

    void start() {
        running = true;
        for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
            std::thread([this] { this->worker(); }).detach();
        }
    }

    void stop() {
        running = false;
        cv.notify_all();
    }

    void enqueue(const DataPacket& packet) {
        std::lock_guard<std::mutex> lock(mutex);
        queue.push(packet);
        cv.notify_one();
    }

private:
    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return !running || !queue.empty(); });
            if (!running && queue.empty()) break;
            DataPacket packet = queue.front();
            queue.pop();
            lock.unlock();

            for (const auto& processor : processors) {
                processor->process(packet);
            }
        }
    }
};

// Example usage
int main() {
    DataStreamHandler handler;
    handler.add_processor(std::make_shared<JsonDataProcessor>());
    handler.start();

    // Simulate data ingestion
