using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml.XPath;

public class XmlProcessingLibrary
{
    private readonly HttpClient _httpClient;
    private readonly XPathNavigator _schemaCache;
    private readonly ILogger _logger;

    public XmlProcessingLibrary(HttpClient httpClient, XPathNavigator schemaCache, ILogger logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _schemaCache = schemaCache ?? throw new ArgumentNullException(nameof(schemaCache));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task ProcessXmlAsync(string url, string xpathQuery)
    {
        try
        {
            var response = await _httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();
            var xmlContent = await response.Content.ReadAsStringAsync();

            using (var reader = XmlReader.Create(new StringReader(xmlContent)))
            {
                var navigator = new XPathDocument(reader).CreateNavigator();

                if (_schemaCache != null && navigator.SchemaInfo == null)
                {
                    navigator.Compile(_schemaCache);
                }

                if (!navigator.MoveToFragment(xpathQuery))
                {
                    throw new InvalidOperationException("XPath query did not match any nodes.");
                }

                // Process the matched nodes
                while (navigator.MoveToNext())
                {
                    var nodeValue = navigator.Value;
                    _logger.LogInformation($"Processed value: {nodeValue}");
                }
            }
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Failed to fetch XML from URL.");
            // Implement retry logic here
        }
        catch (XPathException ex)
        {
            _logger.LogError(ex, "Error in XPath query execution.");
        }
    }
}
