#include <openssl/aes.h>
#include <openssl/rand.h>
#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <openssl/conf.h>
#include <openssl/err.h>

void handle_errors() {
    ERR_print_errors_fp(stderr);
    abort();
}

void derive_key(const char *password, size_t password_len, unsigned char *key) {
    EVP_KDF_CTX *kctx = EVP_KDF_CTX_new_id(EVP_KDF_HKDF());
    if (!kctx) handle_errors();

    const unsigned char salt[] = "salt"; // Replace with a secure random salt
    if (1 != EVP_KDF_set_ctx_params(kctx, EVP_PKEY_CTX_PARAM_KDF_SALT, sizeof(salt), salt)) {
        EVP_KDF_CTX_free(kctx);
        handle_errors();
    }

    if (1 != EVP_KDF_derive(kctx, key, AES_256_KEY_LENGTH)) {
        EVP_KDF_CTX_free(kctx);
        handle_errors();
    }

    EVP_KDF_CTX_free(kctx);
}

void encrypt_data(const unsigned char *plaintext, size_t plaintext_len, unsigned char *key, unsigned char *iv, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) handle_errors();

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        handle_errors();
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        handle_errors();
    }
    size_t ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        handle_errors();
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
}

void decrypt_data(const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *key, unsigned char *iv, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) handle_errors();

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        handle_errors();
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        handle_errors();
    }
    size_t plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        handle_errors();
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
}

int main() {
    unsigned char key[AES_256_KEY_LENGTH];
    unsigned char iv[AES_BLOCK_SIZE];
    unsigned char plaintext[] = "Hello, World!";
    size_t plaintext_len = strlen((char *)plaintext);

    derive_key("password", 8, key);
    if (1 != RAND_bytes(iv, AES_BLOCK_SIZE)) handle_errors();

    unsigned char ciphertext[plaintext_len + AES_BLOCK_SIZE];
    encrypt_data(plaintext, plaintext_len, key, iv, ciphertext);

    unsigned char decryptedtext[plaintext_len];
    decrypt_data(ciphertext, plaintext_len, key, iv, decryptedtext);

    printf("Decrypted Text: %s\n", decryptedtext);

    return 0;
}
