['Here's a basic implementation of an AES-256-CBC encryption framework in C using OpenSSL:

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pem.h>
#include <stdio.h>
#include <stdlib.h>

void encrypt_file(const char *input_path, const char *output_path, const unsigned char *key, const unsigned char *iv) {
    FILE *input = fopen(input_path, "rb");
    FILE *output = fopen(output_path, "wb");

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        fclose(input);
        fclose(output);
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Error initializing encryption context\n");
        exit(EXIT_FAILURE);
    }

    unsigned char buffer[1024];
    int bytes_read;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), input)) > 0) {
        if (EVP_EncryptUpdate(ctx, buffer, &bytes_read, buffer, bytes_read) != 1) {
            fclose(input);
            fclose(output);
            EVP_CIPHER_CTX_free(ctx);
            fprintf(stderr, "Error encrypting data\n");
            exit(EXIT_FAILURE);
        }
        fwrite(buffer, 1, bytes_read, output);
    }

    int final_len;
    if (EVP_EncryptFinal_ex(ctx, buffer, &final_len) != 1) {
        fclose(input);
        fclose(output);
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Error finalizing encryption\n");
        exit(EXIT_FAILURE);
    }
    fwrite(buffer, 1, final_len, output);

    fclose(input);
    fclose(output);
    EVP_CIPHER_CTX_free(ctx);
}
```

This code initializes an AES-256-CBC context with a given key and IV, reads data from the input file in chunks, encrypts it using OpenSSL's `EVP_EncryptUpdate` function, and writes the encrypted data to the output file. The finalization step ensures any remaining data is processed.

