class UeContextManager {
public:
    UeContextManager() {}

    void addTenant(const std::string& tenantId) {
        std::lock_guard<std::mutex> lock(mutex_);
        tenants_[tenantId] = {};
    }

    void removeTenant(const std::string& tenantId) {
        std::lock_guard<std::mutex> lock(mutex_);
        tenants_.erase(tenantId);
    }

    void addUeContext(const std::string& tenantId, const std::string& ueId, const std::string& policy) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (tenants_.find(tenantId) != tenants_.end()) {
            tenants_[tenantId][ueId] = policy;
        }
    }

    void removeUeContext(const std::string& tenantId, const std::string& ueId) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (tenants_.find(tenantId) != tenants_.end()) {
            tenants_[tenantId].erase(ueId);
        }
    }

    void applyPolicy(const std::string& tenantId, const std::string& ueId, const std::string& newPolicy) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (tenants_.find(tenantId) != tenants_.end()) {
            if (tenants_[tenantId].find(ueId) != tenants_[tenantId].end()) {
                tenants_[tenantId][ueId] = newPolicy;
            }
        }
    }

private:
    std::mutex mutex_;
    std::unordered_map<std::string, std::unordered_map<std::string, std::string>> tenants_;
};

int main() {
    UeContextManager manager;
    manager.addTenant("tenant1");
    manager.addUeContext("tenant1", "ue1", "policy1");
    manager.applyPolicy("tenant1", "ue1", "new_policy1");

    return 0;
}
