import os
import hashlib
import requests
from Crypto.Cipher import Fernet

class FileHasher:
    def __init__(self, file_path):
        self.file_path = file_path

    def compute_md5(self):
        hash_md5 = hashlib.md5()
        with open(self.file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_md5.update(chunk)
        return hash_md5.hexdigest()

    def compute_sha256(self):
        hash_sha256 = hashlib.sha256()
        with open(self.file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_sha256.update(chunk)
        return hash_sha256.hexdigest()

class FileUploader:
    def __init__(self, file_hasher):
        self.file_hasher = file_hasher
        self.md5_hash = file_hasher.compute_md5()
        self.sha256_hash = file_hasher.compute_sha256()

    def upload(self, metadata_store_url, monitoring_api_url):
        # Upload hashes to metadata store
        requests.post(metadata_store_url, json={"md5": self.md5_hash, "sha256": self.sha256_hash})

        # Securely forward hashes to multiple external monitoring platforms via a RESTful API
        for platform in ["platform1", "platform2"]:
            response = requests.post(monitoring_api_url, json={"md5": self.md5_hash, "sha256": self.sha256_hash}, verify=True)
            if response.status_code != 200:
                print(f"Failed to upload to {platform}")

class FileProcessor:
    def process_files(self, directory_path):
        for filename in os.listdir(directory_path):
            file_path = os.path.join(directory_path, filename)
            hasher = FileHasher(file_path)
            uploader = FileUploader(hasher)
            uploader.upload("http://metadata-store-url", "http://monitoring-api-url")

# Example usage
processor = FileProcessor()
processor.process_files("/path/to/monitor/directory")
```

