#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_CONCURRENT_REQUESTS 100

typedef struct {
    char *url;
    char *path;
    CURL *curl;
} RequestData;

typedef struct {
    pthread_mutex_t lock;
    int request_count;
} ThreadPool;

void initializeThreadPool(ThreadPool *pool) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->request_count = 0;
}

void enqueueRequest(ThreadPool *pool, char *url, char *path) {
    pthread_mutex_lock(&pool->lock);
    if (pool->request_count < MAX_CONCURRENT_REQUESTS) {
        RequestData *data = malloc(sizeof(RequestData));
        data->url = strdup(url);
        data->path = strdup(path);
        data->curl = curl_easy_init();
        // Enqueue the request
        pool->request_count++;
    } else {
        // Handle queue full scenario
        printf("Queue is full, cannot enqueue more requests.\n");
    }
    pthread_mutex_unlock(&pool->lock);
}

void *processRequest(void *arg) {
    ThreadPool *pool = (ThreadPool *)arg;
    RequestData *data = malloc(sizeof(RequestData));
    while (1) {
        pthread_mutex_lock(&pool->lock);
        if (pool->request_count > 0) {
            data = dequeueRequest(pool); // Assume a function to dequeue
            pool->request_count--;
        } else {
            pthread_cond_wait(&pool->cond, &pool->lock);
        }
        pthread_mutex_unlock(&pool->lock);

        curl_easy_setopt(data->curl, CURLOPT_URL, data->url);
        curl_easy_setopt(data->curl, CURLOPT_WRITEDATA, data->path);

        CURLcode res = curl_easy_perform(data->curl);
        if (res != CURLE_OK) {
            printf("cURL error: %s\n", curl_easy_strerror(res));
            // Handle error and retry logic
        } else {
            processResourceBundle(data->path); // Assume a function to process resource bundle
        }

        free(data->url);
        free(data->path);
        curl_easy_cleanup(data->curl);
    }
}

void fetchAndProcessResourceBundle(char *url, char *path) {
    ThreadPool pool;
    initializeThreadPool(&pool);

    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_create(&threads[i], NULL, processRequest, &pool);
    }

    enqueueRequest(&pool, url, path); // Enqueue the current request

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_join(threads[i], NULL);
    }
}

void processResourceBundle(char *path) {
    // Implement resource processing logic
}

int main() {
    fetchAndProcessResourceBundle("http://example.com/resource", "/local/path/to/save");
    return 0;
}
