package main

import (
	"crypto/md5"
	"crypto/sha256"
	"fmt"
	"golang.org/x/net/context"
	"io"
	"os"
	"path/filepath"
	"sync"
)

type FileHasher struct {
	metadataStore MetadataStore
}

func NewFileHasher(metadataStore MetadataStore) *FileHasher {
	return &FileHasher{metadataStore}
}

func (fh *FileHasher) HashFile(filePath string, ctx context.Context) error {
	fileInfo, err := os.Stat(filePath)
	if err != nil {
		return err
	}

	file, err := os.Open(filePath)
	if err != nil {
		return err
	}
	defer file.Close()

	md5Hasher := md5.New()
	sha256Hasher := sha256.New()

	buffer := make([]byte, 10*1024*1024) // 10 MB buffer

	for {
		n, err := file.Read(buffer)
		if err == io.EOF {
			break
		}
		if err != nil {
			return err
		}

		md5Hasher.Write(buffer[:n])
		sha256Hasher.Write(buffer[:n])
	}

	fileMetadata := FileMetadata{
		Path:       filePath,
		Size:       fileInfo.Size(),
		MD5:        md5Hasher.Sum(nil),
		SHA256:     sha256Hasher.Sum(nil),
	}

	return fh.metadataStore.SaveFileMetadata(ctx, fileMetadata)
}

type MetadataStore interface {
	SaveFileMetadata(ctx context.Context, metadata FileMetadata) error
}

type FileMetadata struct {
	Path       string
	Size       int64
	MD5        []byte
	SHA256     []byte
	LastModified time.Time
}

func main() {
	metadataStore := NewMockMetadataStore()
	fileHasher := NewFileHasher(metadataStore)

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	err := fileHasher.HashFile("/path/to/file", ctx)
	if err != nil {
		fmt.Println("Error hashing file:", err)
		return
	}

	fmt.Println("File hashed successfully")
}
