// Class for managing UE contexts in a multi-tenant environment
class UeContextManager {
public:
    UeContextManager(int numTenants) : numTenants(numTenants), running(true) {}

    void start() {
        threads.resize(numTenants);
        for (int i = 0; i < numTenants; ++i) {
            threads[i] = std::thread(&UeContextManager::runTenant, this, i);
        }
    }

    void stop() {
        running.store(false);
        for (auto& t : threads) {
            if (t.joinable()) {
                t.join();
            }
        }
    }

private:
    int numTenants;
    std::vector<std::thread> threads;
    std::atomic<bool> running;

