class SecureDataHandler {
public:
    SecureDataHandler() {
        SSL_library_init();
        OpenSSL_add_all_algorithms();
        SSL_load_error_strings();
        ctx = SSL_CTX_new(TLS_server_method());
    }

    ~SecureDataHandler() {
        SSL_CTX_free(ctx);
        EVP_cleanup();
    }

    bool encrypt(const std::string& data, std::vector<unsigned char>& encrypted) {
        SSL* ssl = SSL_new(ctx);
        BIO* bio = BIO_new(BIO_s_mem());
        SSL_set_bio(ssl, NULL, bio);

        if (SSL_write(ssl, data.c_str(), data.size()) <= 0) {
            return false;
        }

        BUF_MEM* buf_ptr;
        BIO_get_mem_ptr(bio, &buf_ptr);
        encrypted.assign(buf_ptr->data, buf_ptr->length);

        BIO_free_all(bio);
        SSL_free(ssl);
        return true;
    }

private:
    SSL_CTX* ctx;
};

