from flask import Flask, request, jsonify
from redis import Redis
import requests
import os

app = Flask(__name__)
redis_client = Redis(host='redis', port=6379)
payment_gateways = {
    'stripe': 'https://api.stripe.com/v1',
    'paypal': 'https://api.paypal.com/v2'
}

@app.route('/process_transaction', methods=['POST'])
def process_transaction():
    transaction_data = request.json
    payment_method = transaction_data['payment_method']

    try:
        if payment_method in payment_gateways:
            response = requests.post(payment_gateways[payment_method], json=transaction_data)
            response.raise_for_status()
            return jsonify({'status': 'success', 'response': response.json()}), 200
        else:
            return jsonify({'status': 'error', 'message': f'Unsupported payment method: {payment_method}'}), 400
    except requests.exceptions.RequestException as e:
        redis_client.incr('transaction_failures')
        return jsonify({'status': 'error', 'message': str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
