bool validate_oauth2_token(const char *json_str) {
    struct json_object *parsed_json = NULL;
    struct json_object *access_token = NULL;
    struct json_object *expires_in = NULL;
    struct json_object *token_type = NULL;
    struct json_object *refresh_token = NULL;

    parsed_json = json_tokener_parse(json_str);
    if (!json_object_object_get_ex(parsed_json, "access_token", &access_token) ||
        !json_object_object_get_ex(parsed_json, "expires_in", &expires_in) ||
        !json_object_object_get_ex(parsed_json, "token_type", &token_type)) {
        json_object_put(parsed_json);
        return false;
    }

    if (!strcmp(json_object_get_string(token_type), "Bearer")) {
        long long expires_in_value = json_object_get_int64(expires_in);
        if (expires_in_value <= 0) {
            json_object_put(parsed_json);
            return false;
        }

        // Additional checks for refresh_token can be added here
    } else {
        json_object_put(parsed_json);
        return false;
    }

    json_object_put(parsed_json);
    return true;
}
