use tokio::sync::{mpsc, Mutex};
use std::collections::HashMap;
use serde_json::Value;

// Define a struct for the Message Queue System
struct MessageQueue {
    sender: mpsc::Sender<Value>,
    receiver: mpsc::Receiver<Value>,
    external_services: HashMap<String, Box<dyn ExternalService>>,
}

// Define a trait for interacting with external data sources
trait ExternalService {
    fn connect(&self);
    fn disconnect(&self);
    fn send_data(&self, data: &Value) -> Result<(), String>;
    fn receive_data(&self) -> Option<Value>;
}

// Implement the MessageQueue struct
impl MessageQueue {
    // Create a new instance of MessageQueue
    pub fn new() -> Self {
        let (sender, receiver) = mpsc::channel(32);
        MessageQueue {
            sender,
            receiver,
            external_services: HashMap::new(),
        }
    }

    // Add an external service to the message queue system
    pub fn add_external_service(&mut self, name: String, service: Box<dyn ExternalService>) {
        self.external_services.insert(name, service);
    }

    // Send a message to all connected services
    pub async fn send_message(&self, data: Value) -> Result<(), mpsc::error::SendError<Value>> {
        self.sender.send(data).await?;
        Ok(())
    }

    // Receive messages from the queue and process them
    pub async fn process_messages(&mut self) {
        while let Some(message) = self.receiver.recv().await {
            for (_, service) in self.external_services.iter_mut() {
                if let Err(e) = service.send_data(&message) {
                    eprintln!("Failed to send data to external service: {}", e);
                }
            }
        }
    }
}

// Implement the ExternalService trait for a MongoDB service
struct MongoDBService;

impl ExternalService for MongoDBService {
    fn connect(&self) {
        // Code to connect to MongoDB
    }

    fn disconnect(&self) {
        // Code to disconnect from MongoDB
    }

    fn send_data(&self, data: &Value) -> Result<(), String> {
        // Code to send data to MongoDB
        Ok(())
    }

    fn receive_data(&self) -> Option<Value> {
        // Code to receive data from MongoDB
        None
    }
}

// Example usage of the MessageQueue system
#[tokio::main]
async fn main() {
    let mut mq = MessageQueue::new();
    mq.add_external_service("mongodb".to_string(), Box::new(MongoDBService));
    mq.send_message(json!({"key": "value"})).await.unwrap();
    mq.process_messages().await;
}
