    class MultiTenantManager {
    private:
        std::map<std::string, Tenant> tenants;  // Map of tenant identifiers and their UE contexts
        std::mutex mtx;
        std::condition_variable cv;

    public:
        void addTenant(const std::string& tenantId) {
            std::lock_guard<std::mutex> lock(mtx);
            tenants[tenantId] = Tenant();
            cv.notify_all();
        }

        void removeTenant(const std::string& tenantId) {
            std::lock_guard<std::mutex> lock(mtx);
            tenants.erase(tenantId);
            cv.notify_all();
        }

        void addUeContextToTenant(const std::string& tenantId, const std::string& id, const std::string& data) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this, &tenantId] { return tenants.find(tenantId) != tenants.end(); });
            tenants[tenantId].addUeContext(id, data);
        }

        void removeUeContextFromTenant(const std::string& tenantId, const std::string& id) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this, &tenantId] { return tenants.find(tenantId) != tenants.end(); });
            tenants[tenantId].removeUeContext(id);
        }

        std::string getUeContextFromTenant(const std::string& tenantId, const std::string& id) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this, &tenantId] { return tenants.find(tenantId) != tenants.end(); });
            return tenants[tenantId].getUeContext(id);
