// Forward declaration of DataProcessor
class DataProcessor;

// Worker class to handle data processing tasks
class Worker {
public:
    Worker(DataProcessor& processor);
    void start();
    void stop();

private:
    DataProcessor& processor;
    std::thread thread;
    std::mutex mutex;
    std::condition_variable cv;
    bool running = false;
};

// DataProcessor class to manage data pipelines and processing
class DataProcessor {
public:
    DataProcessor(size_t numWorkers);
    ~DataProcessor();
    void addTask(const std::string& task);
    void updateConfig(const std::string& config);

private:
    std::vector<Worker> workers;
    std::queue<std::string> tasks;
    std::mutex queueMutex;
    std::condition_variable queueCv;
    bool stop = false;
};

// Worker implementation
Worker::Worker(DataProcessor& processor) : processor(processor) {}

void Worker::start() {
    running = true;
    thread = std::thread([this]() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this]{ return !running || !tasks.empty(); });
            if (!running && tasks.empty()) break;
            std::string task = std::move(tasks.front());
            tasks.pop();
            lock.unlock();

            // Process the data task
            processor.processTask(task);
        }
    });
}

void Worker::stop() {
    {
        std::unique_lock<std::mutex> lock(mutex);
        running = false;
    }
    cv.notify_all();
    thread.join();
}

// DataProcessor implementation
DataProcessor::DataProcessor(size_t numWorkers) : workers(numWorkers) {
    for (auto& worker : workers) {
        worker.start();
    }
}

DataProcessor::~DataProcessor() {
    stop = true;
    for (auto& worker : workers) {
        worker.stop();
    }
}

void DataProcessor::addTask(const std::string& task) {
    {
        std::unique_lock<std::mutex> lock(queueMutex);
        tasks.push(task);
    }
    queueCv.notify_one();
}

void DataProcessor::updateConfig(const std::string& config) {
    // Logic to update configuration and handle potential race conditions
    std::lock_guard<std::mutex> lock(mutex);
    // Update internal state based on the new configuration
}

// Example usage
int main() {
    DataProcessor processor(4);

    // Add tasks to the pipeline
    processor.addTask("Process data 1");
    processor.addTask("Process data 2");

    // Simulate updating configuration
    processor.updateConfig("New transformation rules");

    return 0;
}
```

