public class XmlLibrary
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, string> _cache = new();
    private static readonly object CacheLock = new();

    public XmlLibrary(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<string> GetXmlDocumentAsync(string url)
    {
        if (_cache.TryGetValue(url, out var cachedDocument))
        {
            return cachedDocument;
        }

        try
        {
            var response = await _httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();
            var xmlDocument = await response.Content.ReadAsStringAsync();

            lock (CacheLock)
            {
                if (!_cache.ContainsKey(url)) // Double-check locking
                {
                    _cache[url] = xmlDocument;
                }
            }

            return xmlDocument;
        }
        catch
        {
            throw new Exception("Failed to fetch XML document.");
        }
    }

