class RetryMechanism {
public:
    template<typename Func, typename... Args>
    auto retry(Func func, Args&&... args) -> std::future<std::result_of_t<Func(Args...)>> {
        return std::async(std::launch::deferred, [func, args...] {
            int attempts = 0;
            while (true) {
                try {
                    return std::make_shared<std::promise<std::result_of_t<Func(Args...)>>>()->set_value(func(args...));
                } catch (...) {
                    if (++attempts >= maxAttempts_) break;
                    std::this_thread::sleep_for(backoffStrategy_(attempts - 1));
                }
            }
            throw; // Re-throw last exception
        });
    }

private:
    int maxAttempts_ = 3;
    std::function<std::chrono::milliseconds(int)> backoffStrategy_ = [](int attempt) {
        return std::chrono::milliseconds(100 * (1 << attempt));
    };
};

class Configuration {
public:
    static Configuration& getInstance() {
        static Configuration instance;
        return instance;
    }

    void setDeploymentEnvironment(const std::string& environment) {
        deploymentEnvironment_ = environment;
    }

    const std::string& getDeploymentEnvironment() const {
        return deploymentEnvironment_;
    }

private:
    Configuration() {}
    Configuration(const Configuration&) = delete;
    Configuration& operator=(const Configuration&) = delete;

    std::string deploymentEnvironment_;
};

