#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int RNTI;
} UE_INFO;

void log_error(const char *message) {
    printf("ERROR: %s\n", message);
}

void log_performance(const char *message, clock_t start, clock_t end, size_t memory_usage) {
    double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC;
    printf("%s. Time taken: %.6f seconds, Memory usage: %zu bytes\n", message, time_taken, memory_usage);
}

int validate_rnti(int rnti, UE_INFO *ue_info_list, int count) {
    for (int i = 0; i < count; ++i) {
        if (ue_info_list[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}

void populateNfalists(NFAPI_CRC_INDICATION_PDU_T *nfapi_list, UE_INFO *ue_info_list, int *count, size_t memory_usage) {
    clock_t start = clock();

    srand(time(NULL));

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        nfapi_list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        nfapi_list[i].RNTI = rand() % 65536;

        if (!validate_rnti(nfapi_list[i].RNTI, ue_info_list, *count)) {
            log_error("Duplicate RNTI detected. Skipping.");
            i--;
            continue;
        }

        nfapi_list[i].CRC_INDICATION_REL8_TAG = rand() % 2;

        ue_info_list[*count].RNTI = nfapi_list[i].RNTI;
        (*count)++;
    }

    clock_t end = clock();
    log_performance("NFAPI List Population", start, end, memory_usage);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T nfapi_list[MAX_ELEMENTS];
    UE_INFO ue_info_list[MAX_ELEMENTS];
    int count = 0;
    size_t memory_usage = sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_ELEMENTS + sizeof(UE_INFO) * MAX_ELEMENTS;

    populateNfalists(nfapi_list, ue_info_list, &count, memory_usage);

    return 0;
}
