<?php

// Define the base namespace for the application
namespace App\Service;

use App\Model\UserMetadata;
use App\Validator\MetadataValidator;
use App\Auth\OAuth2TokenValidator;
use App\Cache\RedisCacheManager;
use App\Queue\RabbitMQMessageQueue;
use App\ExternalService\PaymentGateway;
use App\ExternalService\EmailProvider;
use App\ExternalService\AnalyticsPlatform;

class UserMetadataService
{
    private $metadataValidator;
    private $tokenValidator;
    private $cacheManager;
    private $messageQueue;
    private $paymentGateway;
    private $emailProvider;
    private $analyticsPlatform;

    public function __construct(
        MetadataValidator $metadataValidator,
        OAuth2TokenValidator $tokenValidator,
        RedisCacheManager $cacheManager,
        RabbitMQMessageQueue $messageQueue,
        PaymentGateway $paymentGateway,
        EmailProvider $emailProvider,
        AnalyticsPlatform $analyticsPlatform
    ) {
        $this->metadataValidator = $metadataValidator;
        $this->tokenValidator = $tokenValidator;
        $this->cacheManager = $cacheManager;
        $this->messageQueue = $messageQueue;
        $this->paymentGateway = $paymentGateway;
        $this->emailProvider = $emailProvider;
        $this->analyticsPlatform = $analyticsPlatform;
    }

    public function handleAction(array $request): array
    {
        $action = $request['action'];
        $id = $request['id'] ?? null;
        $metadata = $request['metadata'] ?? [];

        // Validate token and user role
        if (!$this->tokenValidator->isValid($request['token'])) {
            return ['error' => 'Invalid authentication token', 'code' => 401];
        }

        switch ($action) {
            case 'create':
                return $this->createMetadata($id, $metadata);
            case 'update':
                return $this->updateMetadata($id, $metadata);
            case 'delete':
                return $this->deleteMetadata($id);
            case 'retrieve':
                return $this->retrieveMetadata($id);
            default:
                return ['error' => 'Invalid action', 'code' => 400];
        }
    }

    private function createMetadata(string $id, array $metadata): array
    {
        if (!$this->metadataValidator->validate($metadata)) {
            return ['error' => 'Invalid metadata format', 'code' => 400];
        }

        $userMetadata = new UserMetadata();
        $userMetadata->setId($id);
        $userMetadata->setMetadata($metadata);

        // Save to database and cache
        $this->cacheManager->save($id, $userMetadata);
        $this->messageQueue->push('create', ['id' => $id, 'metadata' => $metadata]);

        return ['message' => 'User metadata created successfully', 'code' => 201];
    }

    private function updateMetadata(string $id, array $metadata): array
    {
        if (!$this->cacheManager->exists($id)) {
            return ['error' => 'User metadata not found', 'code' => 404];
        }

        if (!$this->metadataValidator->validate($metadata)) {
            return ['error' => 'Invalid metadata format', 'code' => 400];
        }

        $userMetadata = $this->cacheManager->get($id);
        $userMetadata->setMetadata($metadata);

        // Update database and cache
        $this->cacheManager->save($id, $userMetadata);
        $this->messageQueue->push('update', ['id' => $id, 'metadata' => $metadata]);

        return ['message' => 'User metadata updated successfully', 'code' => 200];
    }

    private function deleteMetadata(string $id): array
    {
        if (!$this->cacheManager->exists($id)) {
            return ['error' => 'User metadata not found', 'code' => 404];
        }

        // Delete from database and cache
        $this->cacheManager->delete($id);
        $this->messageQueue->push('delete', ['id' => $id]);

        return ['message' => 'User metadata deleted successfully', 'code' => 200];
    }

    private function retrieveMetadata(string $id): array
    {
        if (!$this->cacheManager->exists($id)) {
            return ['error' => 'User metadata not found', 'code' => 404];
        }

        // Retrieve from cache
        $userMetadata = $this->cacheManager->get($id);

        return ['metadata' => $userMetadata->getMetadata(), 'code' => 200];
    }
}
```

This code defines a `UserMetadataService` class in the `App\Service` namespace, which handles CRUD operations for user metadata. It uses various dependencies such as validators, token authenticators, cache managers, message queues, and external service integrations. The methods handle different actions like creating, updating, deleting, and retrieving user metadata."]

