package resourcebundlemanager

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"sync"
	"time"

	"github.com/go-redis/redis/v8"
)

type ResourceBundleManager struct {
	client     *redis.Client
	httpClient *http.Client
	cache      map[string]string
	mutex      sync.RWMutex
}

func NewResourceBundleManager(redisURL string, timeout time.Duration) (*ResourceBundleManager, error) {
	client := redis.NewClient(&redis.Options{
		Addr:     redisURL,
		Password: "", // no password set
		DB:       0,  // use default DB
	})
	if err := client.Ping(context.Background()).Err(); err != nil {
		return nil, fmt.Errorf("failed to connect to Redis: %w", err)
	}

	httpClient := &http.Client{
		Timeout: timeout,
	}

	return &ResourceBundleManager{
		client:     client,
		httpClient: httpClient,
		cache:      make(map[string]string),
	}, nil
}

func (rbm *ResourceBundleManager) GetResourceBundle(ctx context.Context, bundleID string) (string, error) {
	rbm.mutex.RLock()
	bundle, ok := rbm.cache[bundleID]
	rbm.mutex.RUnlock()

	if ok {
		return bundle, nil
	}

	data, err := rbm.fetchResourceBundleFromAPI(ctx, bundleID)
	if err != nil {
		return "", err
	}

	rbm.mutex.Lock()
	defer rbm.mutex.Unlock()

	rbm.cache[bundleID] = data

	return data, nil
}

func (rbm *ResourceBundleManager) fetchResourceBundleFromAPI(ctx context.Context, bundleID string) (string, error) {
	url := fmt.Sprintf("https://api.example.com/bundles/%s", bundleID)
	req, err := http.NewRequestWithContext(ctx, "GET", url, nil)
	if err != nil {
		return "", fmt.Errorf("failed to create request: %w", err)
	}

	resp, err := rbm.httpClient.Do(req)
	if err != nil {
		return "", fmt.Errorf("failed to fetch resource bundle: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return "", errors.New("resource not found")
	}

	data, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		return "", fmt.Errorf("failed to read response body: %w", err)
	}

	return string(data), nil
}

func (rbm *ResourceBundleManager) Close() error {
	return rbm.client.Close()
}
```']

