public class XmlProcessor
{
    private readonly HttpClient _httpClient;
    private readonly string _apiUrl;
    private readonly XDocumentCache _cache;

    public XmlProcessor(string apiUrl, string cacheConnectionString)
    {
        _httpClient = new HttpClient();
        _apiUrl = apiUrl;
        _cache = new XDocumentCache(cacheConnectionString);
    }

    public async Task<XDocument> GetXmlAsync(string documentId)
    {
        if (_cache.TryGetValue(documentId, out var cachedDocument))
        {
            return cachedDocument;
        }

        var response = await _httpClient.GetAsync($"{_apiUrl}/{documentId}");
        response.EnsureSuccessStatusCode();
        var xmlString = await response.Content.ReadAsStringAsync();

        var xmlDoc = XDocument.Parse(xmlString);
        _cache.Set(documentId, xmlDoc);

        return xmlDoc;
    }
}

