// Define a system manager class
class SystemManager {
private:
    TenantManager tenantManager;
    MLModel mlModel;
    std::atomic<bool> running{true};
    std::mutex taskQueueMutex;
    std::condition_variable taskQueueCondVar;
    std::queue<std::function<void()>> taskQueue;

public:
    void startSystem() {
        std::thread([this]() {
            while (running) {
                std::unique_lock<std::mutex> lock(taskQueueMutex);
                taskQueueCondVar.wait(lock, [this] { return !taskQueue.empty(); });
                auto task = taskQueue.front();
                taskQueue.pop();
                lock.unlock();

                // Execute the task
                task();
            }
        }).detach();
    }

    void stopSystem() {
        running = false;
        taskQueueCondVar.notify_all();
    }

    void addTask(const std::function<void()>& task) {
        std::lock_guard<std::mutex> lock(taskQueueMutex);
        taskQueue.push(task);
        taskQueueCondVar.notify_one();
    }
};

// Example usage
int main() {
    SystemManager systemManager;
    systemManager.startSystem();

    // Add tasks to the system manager
    systemManager.addTask([]() {
        // Perform some task
    });

    // Stop the system when done
    systemManager.stopSystem();

    return 0;
}
