    'service1': 'your_api_key',
    'service2': 'your_api_key'
}
BASE_URLS = {
    'service1': 'https://api.service1.com/weather',
    'service2': 'https://api.service2.com/weather'
}

# Function to fetch weather data from a specific service
def fetch_weather_data(service, coordinates, date):
    url = f"{BASE_URLS[service]}?lat={coordinates['latitude']}&lon={coordinates['longitude']}&date={date}"
    headers = {'Authorization': f'Bearer {WEATHER_API_KEYS[service]}'}
    response = session.get(url, headers=headers)
    return response.json()

# Route to handle weather requests
@app.route('/weather', methods=['GET'])
def get_weather():
    coordinates = request.args.get('coordinates', type=float, nargs=2)
    start_date = request.args.get('start_date', type=lambda x: datetime.strptime(x, '%Y-%m-%d'))
    end_date = request.args.get('end_date', type=lambda x: datetime.strptime(x, '%Y-%m-%d'))
    output_format = request.args.get('output_format', default='json')

    weather_data = []
    for date in pd.date_range(start=start_date, end=end_date):
        try:
            service = 'service1'  # Use a strategy to dynamically select the best service
            data = fetch_weather_data(service, coordinates, date.strftime('%Y-%m-%d'))
            weather_data.append(data)
        except requests.exceptions.RequestException as e:
            print(f"Error fetching data from {service}: {e}")

    if output_format == 'json':
        return jsonify(weather_data)
    elif output_format == 'csv':
        df = pd.DataFrame(weather_data)
        return df.to_csv(index=False), 200, {'Content-Type': 'text/csv'}
    else:
        return jsonify({'error': 'Invalid output format'}), 400

if __name__ == '__main__':
    app.run(debug=True)
