import java.util.concurrent.*;
import java.util.function.Function;

public class DynamicTaskExecutor {

    private final ExecutorService executor;
    private final BlockingQueue<Runnable> queue;
    private final ConcurrentHashMap<String, TaskStatus> taskStatusMap;
    private final CircuitBreaker circuitBreaker;

    public DynamicTaskExecutor(int maxThreads) {
        this.executor = Executors.newFixedThreadPool(maxThreads);
        this.queue = new ArrayBlockingQueue<>(1024);
        this.taskStatusMap = new ConcurrentHashMap<>();
        this.circuitBreaker = new CircuitBreaker();
    }

    public void submitTask(String taskId, Runnable task, Priority priority) {
        if (circuitBreaker.isOpen()) {
            throw new RuntimeException("Circuit breaker is open");
        }
        TaskWrapper wrapper = new TaskWrapper(taskId, task, priority);
        queue.offer(wrapper);
        executor.execute(this::processQueue);
    }

    private void processQueue() {
        while (!queue.isEmpty()) {
            try {
                TaskWrapper wrapper = queue.poll(100, TimeUnit.MILLISECONDS);
                if (wrapper != null) {
                    executeTask(wrapper);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private void executeTask(TaskWrapper wrapper) {
        String taskId = wrapper.taskId;
        Runnable task = wrapper.task;
        Priority priority = wrapper.priority;

        if (!circuitBreaker.isPermitted()) {
            log("Circuit breaker is not permitted for task: " + taskId);
            return;
        }

        long startTime = System.currentTimeMillis();
        try {
            task.run();
            updateTaskStatus(taskId, TaskOutcome.SUCCESS, null);
            logExecutionMetrics(taskId, startTime, priority);
        } catch (Exception e) {
            handleException(taskId, e);
        }
    }

    private void updateTaskStatus(String taskId, TaskOutcome outcome, Exception error) {
        taskStatusMap.put(taskId, new TaskStatus(outcome, error));
    }

    private void logExecutionMetrics(String taskId, long startTime, Priority priority) {
        // Asynchronous logging implementation
        System.out.println("Task ID: " + taskId + ", Outcome: " + outcome +
                ", Duration: " + (System.currentTimeMillis() - startTime) + "ms, Priority: " + priority);
    }

    private void handleException(String taskId, Exception e) {
        if (circuitBreaker.shouldTrip(e)) {
            circuitBreaker.trip();
        }
        updateTaskStatus(taskId, TaskOutcome.FAILURE, e);
        log("Error executing task: " + taskId + ", Error: " + e.getMessage());
    }

    public void cancelTask(String taskId) {
        // Logic to cancel a running or scheduled task
    }

    public void close() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    private static class TaskWrapper implements Runnable {
        final String taskId;
        final Runnable task;
        final Priority priority;

        public TaskWrapper(String taskId, Runnable task, Priority priority) {
            this.taskId = taskId;
            this.task = task;
            this.priority = priority;
        }

        @Override
        public void run() {
            task.run();
        }
    }

    private enum TaskOutcome { SUCCESS, FAILURE }

    private static class TaskStatus {
        final TaskOutcome outcome;
        final Exception error;

        public TaskStatus(TaskOutcome outcome, Exception error) {
            this.outcome = outcome;
            this.error = error;
        }
    }

    private static class CircuitBreaker {
        private boolean open;
        private int failureCount;
        private long lastFailureTime;

        public CircuitBreaker() {
            this.open = false;
            this.failureCount = 0;
            this.lastFailureTime = 0;
        }

        public boolean isOpen() {
            return open;
        }

        public boolean isPermitted() {
            if (open) {
                long now = System.currentTimeMillis();
                if (now - lastFailureTime > getResetTimeout()) {
                    open = false;
                } else {
                    return false;
                }
            }
            return true;
        }

        private int getResetTimeout() {
            // Implement logic to calculate reset timeout based on failure rate
            return 1000; // Example: 1 second
        }

        public boolean shouldTrip(Exception e) {
            if (e instanceof TransientFailureException) {
                failureCount++;
                lastFailureTime = System.currentTimeMillis();
                if (failureCount >= getMaxFailuresBeforeTripping()) {
                    open = true;
                }
                return true;
            }
            return false;
        }

        private int getMaxFailuresBeforeTripping() {
            // Implement logic to calculate max failures before tripping
            return 5; // Example: 5 failures
        }

        public void trip() {
            open = true;
        }
    }

    private static class TransientFailureException extends Exception {
        public TransientFailureException(String message) {
            super(message);
        }
    }

    private enum Priority { LOW, MEDIUM, HIGH }

    // Additional methods and classes for error handling, metadata integration, etc.
}
```

