// Import necessary libraries and frameworks
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.connector.kafka.source.KafkaSource;
import org.apache.flink.connector.kafka.source.enumerator.initializer.OffsetsInitializer;
import org.apache.flink.formats.json.JsonFormatOptions;
import org.apache.flink.formats.protobuf.ProtobufDeserializationSchema;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.connectors.elasticsearch.ElasticsearchSinkFunction;
import org.apache.flink.streaming.connectors.elasticsearch.RequestIndexer;
import org.apache.http.HttpHost;
import com.fasterxml.jackson.databind.JsonNode;
import com.google.protobuf.InvalidProtocolBufferException;

public class RealTimeDataIngestionPipeline {

    public static void main(String[] args) throws Exception {
        // Set up the Flink execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // Define Kafka source for IoT devices
        KafkaSource<String> kafkaSource = KafkaSource.<String>builder()
                .setBootstrapServers("kafka1:9092,kafka2:9092")
                .setTopics("iot-data")
                .setGroupId("data-ingestion-group")
                .setStartingOffsets(OffsetsInitializer.earliest())
                .setValueOnlyDeserializer(new KafkaDeserializationSchema<String>() {
                    @Override
                    public boolean isEndOfStream(String nextElement) {
                        return false;
                    }

                    @Override
                    public String deserialize(org.apache.kafka.clients.consumer.ConsumerRecord<byte[], byte[]> record) throws Exception {
                        // Deserialize the message content
                        return new String(record.value());
                    }

                    @Override
                    public org.apache.flink.api.common.typeinfo.TypeInformation<String> getProducedType() {
                        return org.apache.flink.api.common.typeinfo.Types.STRING;
                    }
                })
                .build();

        // Process data from Kafka source
        DataStream<String> inputStream = env.fromSource(kafkaSource, WatermarkStrategy.noWatermarks(), "Kafka Source");

        // Add transformations and enrichments as needed

        // Write the processed data to Elasticsearch for long-term storage and analytics
        List<HttpHost> httpHosts = Arrays.asList(new HttpHost("localhost", 9200, "http"));
        ElasticsearchSink.Builder<String> esSinkBuilder = new ElasticsearchSink.Builder<>(
                httpHosts,
                new ElasticsearchSinkFunction<String>() {
                    public IndexRequest createIndexRequest(String element) {
                        // Create an index request
                        return Requests.indexRequest()
                                .index("iot-data")
                                .source(element);
                    }

                    @Override
                    public void process(String element, RuntimeContext ctx, RequestIndexer indexer) {
                        indexer.add(createIndexRequest(element));
                    }
                });

        esSinkBuilder.setBulkFlushMaxActions(1000);

        inputStream.addSink(esSinkBuilder.build());

        // Execute the Flink job
        env.execute("Real-Time IoT Data Ingestion Pipeline");
    }
}
```

