using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class StoredProcedureExecutor
{
    private readonly string _connectionString;

    public StoredProcedureExecutor(string connectionString)
    {
        _connectionString = connectionString;
    }

    public IEnumerable<SqlDataReader> ExecuteStoredProcedureSync(string procedureName, Dictionary<string, object> parameters)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            connection.Open();
            var command = new SqlCommand(procedureName, connection);
            command.CommandType = CommandType.StoredProcedure;

            foreach (var param in parameters)
            {
                command.Parameters.AddWithValue(param.Key, param.Value);
            }

            return command.ExecuteReader(CommandBehavior.CloseConnection);
        }
    }

    public async Task<IEnumerable<SqlDataReader>> ExecuteStoredProcedureAsync(string procedureName, Dictionary<string, object> parameters)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            var command = new SqlCommand(procedureName, connection);
            command.CommandType = CommandType.StoredProcedure;

            foreach (var param in parameters)
            {
                command.Parameters.AddWithValue(param.Key, param.Value);
            }

            return await command.ExecuteReaderAsync(CommandBehavior.CloseConnection);
        }
    }

    // Additional methods for distributed transactions, caching, error handling, and logging
}
