import java.util.UUID;
import javax.ws.rs.DELETE;
import javax.ws.rs.PUT;
import javax.ws.rs.Path;
import javax.ws.rs.PathParam;
import javax.ws.rs.core.Response;

@Path("/customers")
public class CustomerService {

    private NoSQLDatabase noSqlDatabase;
    private IdentityVerificationService identityService;
    private boolean softDeletionEnabled = false;
    private Logger logger;

    public CustomerService(NoSQLDatabase noSqlDatabase, IdentityVerificationService identityService, Logger logger) {
        this.noSqlDatabase = noSqlDatabase;
        this.identityService = identityService;
        this.logger = logger;
    }

    @PUT
    @Path("/{customerId}")
    public Response updateCustomer(@PathParam("customerId") UUID customerId, Customer customer) {
        try {
            boolean isUserAuthenticated = identityService.authenticateRequest();
            if (!isUserAuthenticated) {
                return Response.status(Response.Status.UNAUTHORIZED).entity("Unauthorized access").build();
            }

            noSqlDatabase.updateCustomer(customerId, customer);
            logger.logAction(customerId, "UPDATE", customer, System.currentTimeMillis());
            return Response.ok().build();
        } catch (Exception e) {
            logger.logError(customerId, "UPDATE_ERROR", e.getMessage(), System.currentTimeMillis());
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Failed to update customer").build();
        }
    }

    @DELETE
    @Path("/{customerId}")
    public Response deleteCustomer(@PathParam("customerId") UUID customerId) {
        try {
            boolean isUserAuthenticated = identityService.authenticateRequest();
            if (!isUserAuthenticated) {
                return Response.status(Response.Status.UNAUTHORIZED).entity("Unauthorized access").build();
            }

            if (softDeletionEnabled) {
                noSqlDatabase.softDeleteCustomer(customerId);
            } else {
                noSqlDatabase.deleteCustomer(customerId);
            }
            logger.logAction(customerId, "DELETE", softDeletionEnabled ? "SOFT_DELETION" : "PERMANENT_DELETE", System.currentTimeMillis());
            return Response.ok().build();
        } catch (Exception e) {
            logger.logError(customerId, "DELETE_ERROR", e.getMessage(), System.currentTimeMillis());
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Failed to delete customer").build();
        }
    }
}
