    std::lock_guard<std::mutex> lock(mutex_);
    for (auto& store : stores_) {
        Value value = static_cast<StoreInterface*>(store.second.get())->get(key);
        if (!value.empty()) return value;
    }
    // Fallback or error handling
    return "";
}

void DistributedCache::Put(const Key& key, const Value& value) {
    std::lock_guard<std::mutex> lock(mutex_);
    for (auto& store : stores_) {
        static_cast<StoreInterface*>(store.second.get())->put(key, value);
    }
    // Notify brokers
}

