typedef struct {
    long offset;
} record;

void initialize_records(record** records, int size) {
    *records = (record*)malloc(size * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < size; i++) {
        (*records)[i].offset = 0;
    }
}

void free_records(record** records) {
    free(*records);
    *records = NULL;
}

int main() {
    int num_records = 10;
    record* records;

    initialize_records(&records, num_records);

    // Use the records array...

    free_records(&records);

    return 0;
}
