    void fetchConfig(const std::string& repoUrl, const std::string& branch) {
        git_repository* repo;
        git_repository_init(&repo, nullptr, true);
        // Clone repository or open existing
        git_repository_open_ext(&repo, repoUrl.c_str(), &git_repository_default_callbacks, 0);

        git_index* index = git_repository_index(repo);
        git_tree* tree = git_tree_lookup_prefix(repo, nullptr, nullptr, 0);
        git_blob* blob;
        int error = git_tree_entry_to_blobs(index, tree, "config", strlen("config"), &blob);
        if (error == 0) {
            // Process the config blob
            git_blob_data(blob);
        }
        git_blob_free(blob);
        git_tree_free(tree);
        git_index_free(index);
        git_repository_close(repo);
    }

