    void encryptData(const std::string& data, std::string& encryptedData) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        unsigned char key[32], iv[16];
        RAND_bytes(key, sizeof(key));
        RAND_bytes(iv, sizeof(iv));

        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
            // Handle error
        }
        encryptedData.resize(sizeof(data) + 16);
        int len;
        if (EVP_EncryptUpdate(ctx, reinterpret_cast<unsigned char*>(&encryptedData[0]), &len, reinterpret_cast<const unsigned char*>(data.c_str()), data.size()) != 1) {
            // Handle error
        }
        int finalLen;
        EVP_EncryptFinal_ex(ctx, reinterpret_cast<unsigned char*>(&encryptedData[len]), &finalLen);
        encryptedData.resize(len + finalLen);

        EVP_CIPHER_CTX_free(ctx);
    }

    void decryptData(const std::string& encryptedData, std::string& decryptedData) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        unsigned char key[32], iv[16];
        // Assume key and iv are known or retrieved from a secure source
        RAND_bytes(key, sizeof(key));
        RAND_bytes(iv, sizeof(iv));

        if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
            // Handle error
        }
        decryptedData.resize(encryptedData.size());
        int len;
        if (EVP_DecryptUpdate(ctx, reinterpret_cast<unsigned char*>(&decryptedData[0]), &len, reinterpret_cast<const unsigned char*>(encryptedData.c_str()), encryptedData.size()) != 1) {
            // Handle error
        }
        int finalLen;
        EVP_DecryptFinal_ex(ctx, reinterpret_cast<unsigned char*>(&decryptedData[len]), &finalLen);
        decryptedData.resize(len + finalLen);

        EVP_CIPHER_CTX_free(ctx);
    }

