int main() {
    char *resource_data;
    size_t data_length;

    if (load_resource("http://example.com/resource.json", &resource_data, &data_length) == 0) {
        // Process the resource data
        printf("Resource loaded successfully.\n");
        free(resource_data);
    } else {
        printf("Failed to load resource.\n");
    }

    return 0;
}

size_t write_data(void *ptr, size_t size, size_t nmemb, void *userdata) {
    // Implement the callback function for writing data
    return size * nmemb;
}

int load_resource(char *url, char **data, size_t *length) {
    CURL *curl_handle = curl_easy_init();
    if (!curl_handle) {
        fprintf(stderr, "Failed to initialize libcurl.\n");
        return -1;
    }

    // Set up the URL and data pointers
    curl_easy_setopt(curl_handle, CURLOPT_URL, url);
    curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, write_data);
    curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, data);

    // Perform the request
    CURLcode res = curl_easy_perform(curl_handle);
    if (res != CURLE_OK) {
        fprintf(stderr, "libcurl error: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl_handle);
        return -1;
    }

    // Get the length of the data received
    long response_code;
    curl_easy_getinfo(curl_handle, CURLINFO_RESPONSE_CODE, &response_code);
    if (response_code != 200) {
        fprintf(stderr, "HTTP error: %ld\n", response_code);
        curl_easy_cleanup(curl_handle);
        return -1;
    }

    // Clean up
    curl_easy_cleanup(curl_handle);

    return 0;
}
