#include <iostream>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <chrono>

class Connection {
public:
    Connection() { /* Initialize connection */ }
    ~Connection() { /* Clean up connection */ }

    void useConnection() { /* Use the connection for a database operation */ }
};

class ConnectionPool {
private:
    std::queue<Connection> pool;
    std::mutex poolMutex;
    std::condition_variable notFull, notEmpty;
    size_t maxSize;

public:
    explicit ConnectionPool(size_t max) : maxSize(max) {}

    void createConnections(size_t num) {
        for (size_t i = 0; i < num; ++i) {
            std::lock_guard<std::mutex> lock(poolMutex);
            pool.push(Connection());
            notEmpty.notify_one();
        }
    }

    Connection getConnection() {
        std::unique_lock<std::mutex> lock(poolMutex);
        notEmpty.wait(lock, [this] { return !pool.empty(); });
        Connection conn = pool.front();
        pool.pop();
        notFull.notify_one();
        return conn;
    }

    void releaseConnection(Connection conn) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (pool.size() < maxSize) {
            pool.push(conn);
            notEmpty.notify_one();
        }
    }
};

class ConnectionPoolManager {
private:
    ConnectionPool pool;
    std::vector<Connection*> activeConnections;

public:
    explicit ConnectionPoolManager(size_t initialSize) : pool(initialSize), activeConnections() {
        pool.createConnections(initialSize);
    }

    Connection* getConnection() {
        if (activeConnections.empty()) {
            if (!pool.notEmpty.wait_for(std::chrono::milliseconds(100), [this] { return !activeConnections.empty(); })) {
                throw std::runtime_error("No connections available");
            }
        }
        Connection* conn = activeConnections.back();
        activeConnections.pop_back();
        return conn;
    }

    void releaseConnection(Connection* conn) {
        std::lock_guard<std::mutex> lock(pool.poolMutex);
        if (pool.pool.size() < pool.maxSize) {
            pool.releaseConnection(*conn);
            activeConnections.push_back(conn);
        } else {
            delete conn; // Handle overflow or other strategies
        }
    }

    ~ConnectionPoolManager() {
        for (auto& conn : activeConnections) {
            delete conn;
        }
    }
};
