import os
import hashlib
import threading
from queue import Queue
import cloud_storage_client  # Hypothetical cloud storage client library
import c_module  # Hypothetical C module for file size validation

class FileProcessor:
    def __init__(self, chunk_size=1024*1024, max_threads=5):
        self.chunk_size = chunk_size
        self.max_threads = max_threads
        self.file_queue = Queue()
        self.threads = []
        self.lock = threading.Lock()

    def start(self, file_path):
        if not c_module.validate_file_size(file_path):
            raise ValueError("File size exceeds limit")
        self.file_queue.put(file_path)
        for _ in range(min(self.max_threads, os.cpu_count())):
            thread = threading.Thread(target=self.process_files)
            thread.start()
            self.threads.append(thread)

    def process_files(self):
        while True:
            file_path = self.file_queue.get()
            if file_path is None:
                break
            try:
                md5_hash, metadata = self.process_file(file_path)
                self.store_data(md5_hash, metadata)
            except Exception as e:
                print(f"Error processing {file_path}: {e}")
            finally:
                self.file_queue.task_done()

    def process_file(self, file_path):
        with open(file_path, 'rb') as f:
            md5_hash = hashlib.md5()
            metadata = {'size': os.path.getsize(file_path)}
            while chunk := f.read(self.chunk_size):
                md5_hash.update(chunk)
        return md5_hash.hexdigest(), metadata

    def store_data(self, md5_hash, metadata):
        cloud_storage_client.store_data(md5_hash, metadata)

    def stop(self):
        for _ in range(len(self.threads)):
            self.file_queue.put(None)
        for thread in self.threads:
            thread.join()

if __name__ == "__main__":
    processor = FileProcessor(max_threads=10)
    processor.start('large_file.txt')
