#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_BUFFER_SIZE 1024

typedef struct {
    char *buffer;
    size_t buffer_size;
    pthread_mutex_t lock;
} SafeStringBuffer;

SafeStringBuffer *safe_string_buffer_create(size_t initial_size) {
    SafeStringBuffer *sb = (SafeStringBuffer *)malloc(sizeof(SafeStringBuffer));
    if (!sb) return NULL;

    sb->buffer = (char *)calloc(1, initial_size);
    if (!sb->buffer) {
        free(sb);
        return NULL;
    }

    sb->buffer_size = initial_size;
    pthread_mutex_init(&sb->lock, NULL);

    return sb;
}

int safe_string_buffer_append(SafeStringBuffer *sb, const char *str) {
    if (!sb || !str) {
        fprintf(stderr, "Error: Null pointer provided.\n");
        return -1;
    }

    pthread_mutex_lock(&sb->lock);

    size_t len = strlen(sb->buffer);
    size_t str_len = strlen(str);

    if (len + str_len + 1 > sb->buffer_size) {
        char *new_buffer = realloc(sb->buffer, sb->buffer_size + MAX_BUFFER_SIZE);
        if (!new_buffer) {
            pthread_mutex_unlock(&sb->lock);
            fprintf(stderr, "Error: Memory reallocation failed.\n");
            return -1;
        }

        sb->buffer = new_buffer;
        sb->buffer_size += MAX_BUFFER_SIZE;
    }

    strcpy(sb->buffer + len, str);

    pthread_mutex_unlock(&sb->lock);
    return 0;
}

void safe_string_buffer_destroy(SafeStringBuffer *sb) {
    if (!sb) return;

    pthread_mutex_destroy(&sb->lock);
    free(sb->buffer);
    free(sb);
}

// Unit test suite
#include <assert.h>

void test_safe_string_buffer_create() {
    SafeStringBuffer *sb = safe_string_buffer_create(10);
    assert(sb != NULL);
    assert(sb->buffer_size == 10);
    safe_string_buffer_destroy(sb);
}

void test_safe_string_buffer_append() {
    SafeStringBuffer *sb = safe_string_buffer_create(20);
    assert(safe_string_buffer_append(sb, "Hello") == 0);
    assert(strcmp(sb->buffer, "Hello") == 0);
    assert(safe_string_buffer_append(sb, ", World!") == 0);
    assert(strcmp(sb->buffer, "Hello, World!") == 0);
    safe_string_buffer_destroy(sb);
}

void test_safe_string_buffer_null_pointer() {
    int result = safe_string_buffer_append(NULL, "Test");
    assert(result == -1);

    SafeStringBuffer *sb = safe_string_buffer_create(10);
    result = safe_string_buffer_append(sb, NULL);
    assert(result == -1);
    safe_string_buffer_destroy(sb);
}

void test_safe_string_buffer_concurrency() {
    SafeStringBuffer *sb = safe_string_buffer_create(20);

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, (void *(*)(void *))safe_string_buffer_append, sb);
    pthread_create(&thread2, NULL, (void *(*)(void *))safe_string_buffer_append, sb);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    assert(strcmp(sb->buffer, "Hello, World!") == 0);
    safe_string_buffer_destroy(sb);
}

int main() {
    test_safe_string_buffer_create();
    test_safe_string_buffer_append();
    test_safe_string_buffer_null_pointer();
    test_safe_string_buffer_concurrency();

    printf("All tests passed.\n");
    return 0;
}
