#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRINGS 1024
#define DEFAULT_TTL 3600 // 1 hour in seconds

typedef struct {
    char* data;
    time_t timestamp;
} StringVersion;

typedef struct {
    StringVersion versions[MAX_STRINGS];
    int version_count;
    pthread_mutex_t lock;
    time_t ttl;
} DynamicStringBuffer;

DynamicStringBuffer buffer = { .ttl = DEFAULT_TTL };

void init_buffer() {
    pthread_mutex_init(&buffer.lock, NULL);
}

void destroy_buffer() {
    pthread_mutex_destroy(&buffer.lock);
}

int append_string(const char* str) {
    pthread_mutex_lock(&buffer.lock);
    if (buffer.version_count >= MAX_STRINGS) {
        pthread_mutex_unlock(&buffer.lock);
        return -1; // Buffer is full
    }
    buffer.versions[buffer.version_count].data = strdup(str);
    buffer.versions[buffer.version_count].timestamp = time(NULL);
    buffer.version_count++;
    pthread_mutex_unlock(&buffer.lock);
    return 0;
}

int delete_string(const char* str) {
    pthread_mutex_lock(&buffer.lock);
    for (int i = 0; i < buffer.version_count; i++) {
        if (strcmp(buffer.versions[i].data, str) == 0) {
            free(buffer.versions[i].data);
            for (int j = i; j < buffer.version_count - 1; j++) {
                buffer.versions[j] = buffer.versions[j + 1];
            }
            buffer.version_count--;
            pthread_mutex_unlock(&buffer.lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&buffer.lock);
    return -1; // String not found
}

const char* get_string_version(int version_index) {
    if (version_index < 0 || version_index >= buffer.version_count) {
        return NULL; // Invalid version index
    }
    return buffer.versions[version_index].data;
}

void expire_strings() {
    pthread_mutex_lock(&buffer.lock);
    time_t current_time = time(NULL);
    for (int i = 0; i < buffer.version_count; i++) {
        if (current_time - buffer.versions[i].timestamp > buffer.ttl) {
            free(buffer.versions[i].data);
            for (int j = i; j < buffer.version_count - 1; j++) {
                buffer.versions[j] = buffer.versions[j + 1];
            }
            buffer.version_count--;
        }
    }
    pthread_mutex_unlock(&buffer.lock);
}

void set_ttl(time_t new_ttl) {
    pthread_mutex_lock(&buffer.lock);
    buffer.ttl = new_ttl;
    pthread_mutex_unlock(&buffer.lock);
}
