import os
import uuid
from datetime import datetime
from PIL import Image
import moviepy.editor as mp
from retrying import retry

class FileProcessor:
    def __init__(self, max_filename_length=255, uuid_version=4):
        self.max_filename_length = max_filename_length
        self.uuid_version = uuid_version

    @retry(stop_max_attempt_number=3, wait_exponential_multiplier=1000)
    def generate_uuid(self):
        return str(uuid.uuid4(version=self.uuid_version))

    def validate_file_type(self, file_path):
        _, ext = os.path.splitext(file_path)
        supported_formats = ['.jpg', '.jpeg', '.png', '.mp4', '.avi']
        if ext.lower() not in supported_formats:
            raise ValueError(f"Unsupported file format: {ext}")

    @retry(stop_max_attempt_number=3, wait_exponential_multiplier=1000)
    def get_timestamp(self):
        return datetime.now().strftime('%Y%m%d%H%M%S')

    def process_directory(self, directory_path):
        for root, _, files in os.walk(directory_path):
            for file_name in files:
                self.process_file(os.path.join(root, file_name))

    @retry(stop_max_attempt_number=3, wait_exponential_multiplier=1000)
    def process_file(self, file_path):
        try:
            self.validate_file_type(file_path)
            timestamp = self.get_timestamp()
            unique_id = self.generate_uuid()

            if file_path.lower().endswith(('.mp4', '.avi')):
                frames = self.extract_video_frames(file_path)
                for i, frame in enumerate(frames):
                    self.save_image(frame, f"{timestamp}_{unique_id}_frame{i}.jpg")
            else:
                image = Image.open(file_path)
                new_filename = self.generate_new_filename(image, timestamp, unique_id)
                image.save(new_filename)

        except Exception as e:
            print(f"Failed to process file: {file_path}. Error: {e}")

    @retry(stop_max_attempt_number=3, wait_exponential_multiplier=1000)
    def extract_video_frames(self, video_path):
        clip = mp.VideoFileClip(video_path)
        frames = [clip.get_frame(t) for t in range(clip.duration)]
        return frames

    @retry(stop_max_attempt_number=3, wait_exponential_multiplier=1000)
    def save_image(self, frame, filename):
        image = Image.fromarray(frame)
        image.save(filename)

    def generate_new_filename(self, image, timestamp, unique_id):
        width, height = image.size
        metadata = f"_w{width}_h{height}_{timestamp}_{unique_id}"
        new_filename = f"{os.path.splitext(os.path.basename(image.filename))[0]}{metadata}.jpg"
        if len(new_filename) > self.max_filename_length:
            base_name = os.path.splitext(os.path.basename(image.filename))[0]
            extension = os.path.splitext(os.path.basename(image.filename))[1]
            new_filename = f"{base_name[:self.max_filename_length-len(extension)-len(metadata)]}{metadata}{extension}"
        return new_filename

# Example usage
processor = FileProcessor(max_filename_length=255, uuid_version=4)
processor.process_directory('/path/to/directory')
