public class PipelineCoordinator {
    private DataIngestionService ingestionService;
    private DataTransformationService transformationService;
    private DataAggregationService aggregationService;

    public PipelineCoordinator(DataIngestionService ingestionService, DataTransformationService transformationService, DataAggregationService aggregationService) {
        this.ingestionService = ingestionService;
        this.transformationService = transformationService;
        this.aggregationService = aggregationService;
    }

    public void processData() {
        String rawData = ingestionService.ingestData();
        String transformedData = transformationService.transformData(rawData);
        aggregationService.aggregateData(transformedData);
    }
}

