```cpp
// MediaProcessor.cpp
#include "MediaProcessor.h"
#include <iostream>
#include <memory>

std::mutex MediaProcessor::registryMutex;
std::vector<std::function<MediaProcessor*()>> MediaProcessor::factories;

void MediaProcessor::registerFactory(int id, std::function<MediaProcessor*()> factory) {
    std::lock_guard<std::mutex> lock(registryMutex);
    if (id >= factories.size()) {
        factories.resize(id + 1);
    }
    factories[id] = factory;
}

MediaProcessor* MediaProcessor::createInstance(int id) {
    std::lock_guard<std::mutex> lock(registryMutex);
    if (id < 0 || id >= factories.size() || !factories[id]) {
        return nullptr;
    }
    return factories[id]();
}
