const express = require('express');
const multer = require('multer');
const AWS = require('aws-sdk');
const GoogleCloudStorage = require('@google-cloud/storage');
const AzureStorage = require('azure-storage');

const app = express();
const upload = multer({ storage: multer.memoryStorage() });

// Middleware to validate files
function validateFile(req, file, cb) {
  // Implement dynamic validation logic here
  cb(null, true);
}

app.post('/upload', upload.single('file'), validateFile, async (req, res) => {
  try {
    const file = req.file;
    if (!file) return res.status(400).send('No file uploaded.');

    // Implement logic to select the appropriate cloud storage provider based on policy
    let storageClient;
    switch (config.storageProvider) {
      case 'aws':
        AWS.config.update({ accessKeyId: process.env.AWS_ACCESS_KEY_ID, secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY });
        storageClient = new AWS.S3();
        break;
      case 'google':
        GoogleCloudStorage.auth.GoogleAuth.fromApplicationDefault();
        storageClient = new GoogleCloudStorage.Storage();
        break;
      case 'azure':
        AzureStorage.setEnvironment(AzureStorage.AzureEnvironment.AZURE_PUBLIC_CLOUD);
        const blobService = AzureStorage.createBlobService(process.env.AZURE_STORAGE_CONNECTION_STRING);
        storageClient = blobService;
        break;
      default:
        return res.status(500).send('Unsupported cloud storage provider.');
    }

    // Implement logic to upload file and store metadata
    const metadata = {
      originalUrl: req.originalUrl,
      fileName: file.originalname,
      mimeType: file.mimetype,
      uploadTimestamp: new Date(),
      userId: req.userId,
      customTags: req.customTags,
      deviceLocation: req.deviceLocation
    };

    await storageClient.upload(file.buffer, { metadata });
    res.send('File uploaded successfully.');
  } catch (error) {
    console.error(error);
    res.status(500).send('Error uploading file.');
  }
});

// Implement real-time progress updates using WebSocket
const io = require('socket.io')(app);

io.on('connection', (socket) => {
  socket.emit('progress', { message: 'Upload started' });
  // Implement logic to send progress updates to the client
  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

// Securely manage API keys and sensitive data
app.use((req, res, next) => {
  if (!process.env.API_KEY) return res.status(401).send('API key not provided.');
  // Implement logic to validate the API key
  next();
});

app.listen(config.port, () => {
  console.log(`Server running on port ${config.port}`);
});
```

