use tokio::net::{TcpListener, TcpStream};
use tokio::sync::mpsc;
use tokio::task;
use std::collections::HashMap;
use std::env;
use std::error::Error;
use std::time::{Duration, Instant};

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    // Initialize configuration
    let config = load_config();

    // Setup logging
    setup_logging(&config);

    // Start network listener
    let listener = TcpListener::bind("0.0.0.0:8080").await?;
    println!("Server listening on port 8080");

    // Create channels for task queue and results
    let (task_tx, task_rx) = mpsc::channel(config.max_simultaneous_ops);

    // Spawn task processor
    tokio::spawn(task_processor(task_rx));

    // Main loop to accept connections
    while let Ok((stream, addr)) = listener.accept().await {
        println!("New connection from {}", addr);

        // Spawn a new task for each connection
        tokio::spawn(handle_connection(stream, &task_tx));
    }

    Ok(())
}

async fn handle_connection(mut stream: TcpStream, task_tx: &mpsc::Sender<Task>) -> Result<(), Box<dyn Error>> {
    // Handle incoming data from the client
    let mut buffer = [0; 1024];
    while let Ok(n) = stream.read(&mut buffer).await {
        if n == 0 {
            break;
        }

        // Parse task and send to processor
        let task = parse_task(&buffer[..n]);
        task_tx.send(task).await?;
    }

    Ok(())
}

async fn task_processor(mut task_rx: mpsc::Receiver<Task>) {
    while let Some(task) = task_rx.recv().await {
        match task {
