impl ConfigurationManager {
    async fn new(base_url: String) -> Self {
        ConfigurationManager { base_url }
    }

    async fn get_config(&self) -> Result<(String, String, String), ReqwestError> {
        let response = reqwest::get(format!("{}/config", self.base_url)).await?;
        response.json::<Config>().await.map(|c| (c.directory_name, c.logging_path, c.escalation_service_url))
