impl DirectoryManager {
    async fn new(base_url: String) -> Self {
        let config_manager = ConfigurationManager::new(base_url).await;
        DirectoryManager { lock: Mutex::new(()), config_manager }
    }

    async fn create_directory(&self, path: &Path) -> Result<(), std::io::Error> {
