import hashlib
import os
import time
from concurrent.futures import ThreadPoolExecutor

class FileHasher:
    def __init__(self):
        self.executor = ThreadPoolExecutor(max_workers=10)

    def hash_file(self, file_path, hash_type='md5'):
        hasher = hashlib.new(hash_type)
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                hasher.update(chunk)
        return hasher.hexdigest()

    def compute_hashes(self, directory):
        results = {}
        for root, _, files in os.walk(directory):
            for file in files:
                file_path = os.path.join(root, file)
                hash_value = self.hash_file(file_path)
                results[file_path] = hash_value
        return results

class FileUploader:
    def __init__(self, monitoring_platforms):
        self.monitoring_platforms = monitoring_platforms

    def upload_to_monitoring(self, file_path, hash_value, platform):
        # Simulate uploading to a monitoring platform
        print(f"Uploading {file_path} with hash {hash_value} to {platform}")

    def forward_hashes(self, hashes):
        for file_path, hash_value in hashes.items():
            for platform in self.monitoring_platforms:
                self.upload_to_monitoring(file_path, hash_value, platform)

class FileWatcher:
    def __init__(self, directory, uploader):
        self.directory = directory
        self.uploader = uploader

    def monitor_directory(self):
        while True:
            hashes = self.uploader.hasher.compute_hashes(self.directory)
            self.uploader.forward_hashes(hashes)
            time.sleep(10)  # Monitor every 10 seconds

if __name__ == "__main__":
    monitoring_platforms = ['PlatformA', 'PlatformB']
    hasher = FileHasher()
    uploader = FileUploader(monitoring_platforms, hasher=hasher)
    watcher = FileWatcher('/path/to/watch', uploader)
    watcher.monitor_directory()
```

