    std::string data = "sensitive_data";
    std::string encryptedData, decryptedData;
    manager.encryptData(data, encryptedData);
    manager.decryptData(encryptedData, decryptedData);

    std::cout << "Original: " << data << std::endl;
    std::cout << "Decrypted: " << decryptedData << std::endl;

