#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define N 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T queue[N];
int front = -1, rear = -1;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void enqueue(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&mutex);
    while ((rear + 1) % N == front) {
        pthread_cond_wait(&cond, &mutex);
    }
    rear = (rear + 1) % N;
    queue[rear] = pdu;
    if (front == -1) {
        front = 0;
    }
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T dequeue() {
    pthread_mutex_lock(&mutex);
    while (front == -1) {
        pthread_cond_wait(&cond, &mutex);
    }
    NFAPI_CRC_INDICATION_PDU_T pdu = queue[front];
    if (front == rear) {
        front = -1;
        rear = -1;
    } else {
        front = (front + 1) % N;
    }
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
    return pdu;
}

void* process_images(void* arg) {
    // Simulate image processing
    int image_count = *(int*)arg;
    for (int i = 0; i < image_count; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu.RNTI = rand() % 1000;
        pdu.CRC_INDICATION_REL8_TAG = (rand() % 2) == 0 ? 1 : 0;
        enqueue(pdu);
    }
    return NULL;
}

int main() {
    srand(time(NULL));

    pthread_t threads[5];
    int image_counts[] = {30, 20, 40, 10, 5};

    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, process_images, &image_counts[i]);
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    while (front != -1) {
        NFAPI_CRC_INDICATION_PDU_T pdu = dequeue();
        printf("Processed: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n",
               pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG);
    }

    return 0;
}
