#include <iostream>
#include <string>
#include <vector>
#include <mutex>
#include <atomic>
#include <condition_variable>
#include <queue>
#include <thread>
#include <functional>
#include <nlohmann/json.hpp>

namespace {
    const size_t N = 100; // Maximum events per minute

    struct Event {
        std::string event_id;
        std::chrono::system_clock::time_point timestamp;
        std::string provider_metadata;
        nlohmann::json payload;
    };

    class LoggingFramework {
    public:
        virtual ~LoggingFramework() = default;
        virtual void logEvent(const Event& event) = 0;
    };

    class DatabaseSystem {
    public:
        virtual ~DatabaseSystem() = default;
        virtual void storeEvent(const Event& event) = 0;
        virtual std::vector<Event> queryEvents(const std::string& criteria) const = 0;
    };

    class AsyncProcessor {
    public:
        AsyncProcessor(std::shared_ptr<LoggingFramework> logging_framework, std::shared_ptr<DatabaseSystem> database_system)
            : logging_framework_(logging_framework), database_system_(database_system) {}

        void processEvent(const Event& event) {
            logging_framework_->logEvent(event);
            database_system_->storeEvent(event);
        }

    private:
        std::shared_ptr<LoggingFramework> logging_framework_;
        std::shared_ptr<DatabaseSystem> database_system_;
    };

    class EventQueue {
    public:
        void enqueueEvent(const Event& event) {
            std::lock_guard<std::mutex> lock(mutex_);
            queue_.push(event);
            cv_.notify_one();
        }

        Event dequeueEvent() {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !queue_.empty(); });
            Event event = queue_.front();
            queue_.pop();
            return event;
        }

    private:
        std::queue<Event> queue_;
        std::mutex mutex_;
        std::condition_variable cv_;
    };

    class EventProcessor {
    public:
        EventProcessor(std::shared_ptr<AsyncProcessor> async_processor, size_t num_threads)
            : async_processor_(async_processor), num_threads_(num_threads) {
            for (size_t i = 0; i < num_threads_; ++i) {
                workers_.emplace_back([this] { this->worker_thread(); });
            }
        }

        ~EventProcessor() {
            stop_.store(true);
            cv_.notify_all();
            for (auto& worker : workers_) {
                worker.join();
            }
        }

        void submitEvent(const Event& event) {
            queue_.enqueueEvent(event);
        }

    private:
        std::shared_ptr<AsyncProcessor> async_processor_;
        size_t num_threads_;
        std::vector<std::thread> workers_;
        EventQueue queue_;
        std::atomic<bool> stop_{false};
        std::condition_variable cv_;

        void worker_thread() {
            while (!stop_.load()) {
                Event event = queue_.dequeueEvent();
                async_processor_->processEvent(event);
            }
        }
    };
}
