public:
    void addUeContext(int tenantId, UeContext* context) {
        std::lock_guard<std::mutex> lock(mutex);
        tenantContexts[tenantId].push(context);
    }

    UeContext* getUeContext(int tenantId) {
        std::lock_guard<std::mutex> lock(mutex);
        if (!tenantContexts[tenantId].empty()) {
            UeContext* context = tenantContexts[tenantId].front();
            tenantContexts[tenantId].pop();
            return context;
        }
        return nullptr;
