void appendStringWithLimit(const char* input, int sizeLimit, char* resultBuffer, int bufferSize) {
    if (!input || !resultBuffer || bufferSize <= 0) {
        fprintf(stderr, "Invalid input or buffer\n");
        return;
    }

    // Initialize variables
    size_t totalLength = strlen(input);
    int remainingSize = bufferSize - totalLength;

    // Check if input string fits within the limit
    if (totalLength >= sizeLimit) {
        strncpy(resultBuffer, input, sizeLimit - 1);
        resultBuffer[sizeLimit - 1] = '\0';
        return;
    }

    // Append input to the buffer
    strcpy(resultBuffer, input);

    // Fetch string from API endpoints and append
