        char* buffer;
        size_t bufferSize;

        if (fetchStringFromApi(apiConfigs[i].url, &buffer, &bufferSize) == 0) {
            size_t availableSpace = remainingSize - totalLength;
            if (availableSpace > 0) {
                if (availableSpace < bufferSize) {
                    bufferSize = availableSpace;
                }
                strncat(resultBuffer + totalLength, buffer, bufferSize);
                totalLength += bufferSize;
            }
        }

        // Free allocated memory for API response
        free(buffer);
    }

    // Null-terminate the result string
    if (totalLength < sizeLimit) {
        resultBuffer[totalLength] = '\0';
    }
}

// Example usage
int main() {
    char result[1024];
    appendStringWithLimit("Initial string", 1024, result, sizeof(result));
    printf("Result: %s\n", result);
