#include "log_framework.h" // Assume this is the external logging framework

typedef struct {
    int* records;
    size_t size;
    size_t capacity;
    int min_value;
    int max_value;
    pthread_mutex_t mutex; // Mutex for thread safety
} record_array;

record_array* manage_records(config* cfg) {
    record_array* arr = (record_array*)malloc(sizeof(record_array));
    if (!arr) {
        log_error("Failed to allocate memory for record array");
        return NULL;
    }

    pthread_mutex_init(&arr->mutex, NULL);
    arr->size = 0;
    arr->capacity = cfg->initial_size;
    arr->records = (int*)malloc(arr->capacity * sizeof(int));
    if (!arr->records) {
        log_error("Failed to allocate memory for records");
        pthread_mutex_destroy(&arr->mutex);
        free(arr);
        return NULL;
    }

    srand(cfg->seed);
    int range = cfg->max_value - cfg->min_value + 1;
    for (size_t i = 0; i < arr->capacity; ++i) {
        arr->records[i] = rand() % range + cfg->min_value;
    }

    arr->min_value = cfg->min_value;
    arr->max_value = cfg->max_value;

    return arr;
}

void destroy_record_array(record_array* arr) {
    if (!arr) return;

    pthread_mutex_lock(&arr->mutex);
    free(arr->records);
    arr->records = NULL;
    arr->size = 0;
    arr->capacity = 0;
    pthread_mutex_unlock(&arr->mutex);

    pthread_mutex_destroy(&arr->mutex);
    free(arr);
}
