        Record record;
        record.key = rand() % 1000;
        record.offset = rand() % 1000000L;
        enqueue_record(queue, record);
    }
}

// Function to start the data processing pipeline
void *start_data_pipeline(void *arg) {
    RecordQueue *queue = (RecordQueue *)arg;
    int max_connections = 5;
    int load_threshold = 80; // Example threshold
    manage_data_processing(queue, max_connections, load_threshold);
