# Define a class for a weather API client
class WeatherAPIClient:
    def __init__(self, api_key):
        self.api_key = api_key
        self.base_url = "https://api.weather.com/v1/"

    @lru_cache(maxsize=128)
    def get_weather(self, location, date):
        params = {
            'apiKey': self.api_key,
            'units': 'metric',
            'date': date.strftime('%Y%m%d')
        }
        response = requests.get(f"{self.base_url}/forecast/daily/5day?location={location}", params=params)
        return response.json()

# Define a class for the weather aggregation platform
class WeatherAggregationPlatform:
    def __init__(self):
        self.clients = {}
        self.failed_clients = set()
        self.alert_thresholds = {
            'high': 30,
            'low': -10
        }

    def add_client(self, api_key, client_name):
        self.clients[client_name] = WeatherAPIClient(api_key)

    def get_weather_data(self, location, date):
        for client_name, client in self.clients.items():
            if client_name not in self.failed_clients:
                try:
                    data = client.get_weather(location, date)
                    return data
                except requests.RequestException as e:
                    print(f"Failed to fetch weather data from {client_name}: {e}")
                    self.failed_clients.add(client_name)
        raise Exception("No available clients for fetching weather data")

    def check_alerts(self, location):
        current_date = datetime.now().strftime('%Y%m%d')
        weather_data = self.get_weather_data(location, current_date)
        high_temp = max([day['maxTemp'] for day in weather_data['forecasts']])
        low_temp = min([day['minTemp'] for day in weather_data['forecasts']])

        if high_temp > self.alert_thresholds['high']:
            self.send_alert('High temperature alert!', location, high_temp)
        elif low_temp < self.alert_thresholds['low']:
            self.send_alert('Low temperature alert!', location, low_temp)

    def send_alert(self, message, location, temp):
        # Implement SMS or email sending logic here
        print(f"Alert: {message} - Location: {location}, Temp: {temp}")

# Example usage
if __name__ == "__main__":
    platform = WeatherAggregationPlatform()
    platform.add_client('your_api_key_1', 'Client1')
    platform.add_client('your_api_key_2', 'Client2')
    platform.check_alerts('New York,US')
