typedef struct {
    int *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} record_array;

record_array* create_record_array(size_t initial_size) {
    record_array *arr = malloc(sizeof(record_array));
    if (!arr) return NULL;

    arr->data = malloc(initial_size * sizeof(int));
    if (!arr->data) {
        free(arr);
        return NULL;
    }

    arr->size = 0;
    arr->capacity = initial_size;
    pthread_mutex_init(&arr->mutex, NULL);

    return arr;
}

void destroy_record_array(record_array *arr) {
    if (arr) {
        pthread_mutex_destroy(&arr->mutex);
        free(arr->data);
        free(arr);
    }
}

int add_record(record_array *arr, int value) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size >= arr->capacity) {
        size_t new_capacity = arr->capacity ? arr->capacity * 2 : 1;
        int *new_data = realloc(arr->data, new_capacity * sizeof(int));
        if (!new_data) {
            pthread_mutex_unlock(&arr->mutex);
            return -1; // Memory allocation failure
        }
        arr->data = new_data;
        arr->capacity = new_capacity;
    }
    arr->data[arr->size++] = value;
    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

// Other functions for managing records can be added here

