Job jobs[MAX_JOBS];
int job_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void parse_config(const char* file_path) {
    pthread_mutex_lock(&mutex);
    FILE* file = fopen(file_path, "r");
    if (file == NULL) {
        perror("Failed to open config file");
        return;
    }

    // Parse the XML file and populate the jobs array
