    // while ((job = parse_next_job(file)) != NULL) {
    //     jobs[job_count++] = *job;
    // }

    fclose(file);
    pthread_mutex_unlock(&mutex);
}

void validate_config() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < job_count; i++) {
        // Validate each job's parameters
        if (jobs[i].resource_requirements > MAX_RESOURCE) {
            printf("Job %d exceeds maximum resource requirements\n", i);
            // Handle validation error
        }
    }
    pthread_mutex_unlock(&mutex);
}

void transform_config() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < job_count; i++) {
        // Transform job parameters as needed
        if (jobs[i].frequency > MAX_FREQUENCY) {
            jobs[i].frequency = MAX_FREQUENCY;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void* worker_thread(void* arg) {
    int thread_id = *(int*)arg;
    while (1) {
        pthread_mutex_lock(&mutex);
        if (job_count > 0) {
            Job job = jobs[--job_count];
            pthread_mutex_unlock(&mutex);

            // Process the job
            printf("Thread %d processing job: type=%s, freq=%d, res_req=%d\n", thread_id, job.job_type, job.frequency, job.resource_requirements);
        } else {
            pthread_mutex_unlock(&mutex);
            break;
        }
    }
    return NULL;
}

int main() {
    parse_config("config.xml");
    validate_config();
    transform_config();

    int num_threads = 4;
    pthread_t threads[num_threads];
    int thread_ids[num_threads];

    for (int i = 0; i < num_threads; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, worker_thread, &thread_ids[i]);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

