        case PARSING_ERROR:
            reportRuntimeAnomaly("Parsing error occurred: " message);
            break;
        case TRANSFORMATION_ERROR:
            reportRuntimeAnomaly("Transformation error occurred: " message);
            break;
        default:
            // Handle other errors
            break;
    }
    return errorCode;
}

// Function to dynamically load and unload dependencies
void* load_dependency(const char* dependencyName) {
    void* handle = dlopen(dependencyName, RTLD_LAZY);
    if (!handle) {
        reportRuntimeAnomaly("Failed to load dependency: " dlerror());
        return NULL;
    }
    return handle;
}

void unload_dependency(void* handle) {
    dlclose(handle);
}

// Function to reconfigure the library
