#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <condition_variable>
#include <mutex>
#include <future>

class DataPipeline {
public:
    void start() {
        producer_thread = std::thread(&DataPipeline::producer, this);
        consumer_thread = std::thread(&DataPipeline::consumer, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            running = false;
        }
        condition.notify_all();
        if (producer_thread.joinable()) producer_thread.join();
        if (consumer_thread.joinable()) consumer_thread.join();
    }

private:
    std::thread producer_thread;
    std::thread consumer_thread;
    std::queue<std::string> data_queue;
    std::mutex mutex;
    std::condition_variable condition;
    bool running = true;

    void producer() {
        while (running) {
            // Simulate data ingestion
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            std::lock_guard<std::mutex> lock(mutex);
            data_queue.push("New data");
            condition.notify_one();
        }
    }

    void consumer() {
        while (running) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this]{ return !data_queue.empty() || !running; });
            if (!running && data_queue.empty()) break;
            auto data = data_queue.front();
            data_queue.pop();
            lock.unlock();

            // Simulate data processing
            std::cout << "Processing: " << data << std::endl;
        }
    }
};

int main() {
    DataPipeline pipeline;
    pipeline.start();

    // Simulate running for 5 seconds
    std::this_thread::sleep_for(std::chrono::seconds(5));

    pipeline.stop();
    return 0;
}
