public class XmlProcessor
{
    private readonly ConcurrentDictionary<string, XmlDocument> _cache = new ConcurrentDictionary<string, XmlDocument>();
    private readonly HttpClient _httpClient;

    public XmlProcessor(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<XmlDocument> GetXmlAsync(string url, string schemaUrl)
    {
        if (!_cache.TryGetValue(url, out var document))
        {
            document = await FetchAndParseXmlAsync(url);
            ValidateSchema(document, schemaUrl);

            _cache.TryAdd(url, document);
        }
        return document;
    }

    private async Task<XmlDocument> FetchAndParseXmlAsync(string url)
    {
        using (var response = await _httpClient.GetAsync(url))
        {
            response.EnsureSuccessStatusCode();
            var content = await response.Content.ReadAsStringAsync();
            // Parse XML content
            return new XmlDocument(content);
        }
    }

