typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} MemoryPool;

void init_memory_pool(MemoryPool *pool, size_t initial_size) {
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pool->pool == NULL) {
        // Handle error: memory allocation failed
    }
    pool->pool_size = initial_size;
    pool->used_count = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T *allocate_from_pool(MemoryPool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->used_count < pool->pool_size) {
        pdu = &pool->pool[pool->used_count++];
    }
    pthread_mutex_unlock(&pool->lock);
    return pdu;
}

void free_to_pool(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool->lock);
    // Assuming all pointers in the pool are valid and contiguous
    for (size_t i = 0; i < pool->used_count; ++i) {
        if (&pool->pool[i] == pdu) {
            pool->used_count--;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void process_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, /* Other parameters */) {
    // Process the PDU
}

void *worker_thread(void *arg) {
    MemoryPool *pool = (MemoryPool *)arg;
    NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_from_pool(pool);
    if (pdu != NULL) {
        process_pdu(pdu, /* Other parameters */);
        free_to_pool(pool, pdu);
    }
    return NULL;
}

int main() {
    MemoryPool pool;
    init_memory_pool(&pool, 10000); // Adjust size based on expected load

    pthread_t threads[100]; // Example: 100 threads
    for (size_t i = 0; i < 100; ++i) {
        if (pthread_create(&threads[i], NULL, worker_thread, &pool) != 0) {
            // Handle error: thread creation failed
        }
    }

    for (size_t i = 0; i < 100; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&pool.lock);
    free(pool.pool);

    return 0;
}
