#define NFAPI_CRC_INDICATION_PDU_T /* Define the structure as per requirements */

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *buffer;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->buffer = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->size = 0;
    pool->capacity = initial_capacity;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* memory_pool_alloc(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= pool->capacity) {
        pool->buffer = realloc(pool->buffer, pool->capacity * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pool->capacity *= 2;
    }
    NFAPI_CRC_INDICATION_PDU_T* item = &pool->buffer[pool->size++];
    pthread_mutex_unlock(&pool->lock);
    return item;
}

void memory_pool_free(MemoryPool *pool) {
    free(pool->buffer);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}
