using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml.Linq;

public class XmlParser
{
    private readonly ConcurrentDictionary<string, XDocument> _cache = new ConcurrentDictionary<string, XDocument>();
    private readonly HttpClient _httpClient;
    private readonly LogLevel _logLevel;

    public enum LogLevel
    {
        Debug,
        Info,
        Error
    }

    public XmlParser(LogLevel logLevel)
    {
        _httpClient = new HttpClient();
        _logLevel = logLevel;
    }

    ~XmlParser()
    {
        _httpClient.Dispose();
    }

    public async Task<XDocument> ParseFromFilePathAsync(string filePath, bool validateWellFormedness = true)
    {
        if (_cache.TryGetValue(filePath, out var document))
            return document;

        try
        {
            var content = await File.ReadAllTextAsync(filePath);
            if (validateWellFormedness)
                XDocument.Parse(content); // Validate well-formedness

            _cache.TryAdd(filePath, XDocument.Parse(content));
            Log(LogLevel.Info, $"Parsed XML from file: {filePath}");
            return document;
        }
        catch (Exception ex)
        {
            Log(LogLevel.Error, $"Error parsing XML from file: {ex.Message}");
            throw;
        }
    }

    public async Task<XDocument> ParseFromUrlAsync(string url, bool validateWellFormedness = true)
    {
        if (_cache.TryGetValue(url, out var document))
            return document;

        try
        {
            var content = await _httpClient.GetStringAsync(url);
            if (validateWellFormedness)
                XDocument.Parse(content); // Validate well-formedness

            _cache.TryAdd(url, XDocument.Parse(content));
            Log(LogLevel.Info, $"Parsed XML from URL: {url}");
            return document;
        }
        catch (Exception ex)
        {
            Log(LogLevel.Error, $"Error parsing XML from URL: {ex.Message}");
            throw;
        }
    }

    public async Task<XDocument> ParseFromStringAsync(string xmlString, bool validateWellFormedness = true)
    {
        try
        {
            if (validateWellFormedness)
                XDocument.Parse(xmlString); // Validate well-formedness

            Log(LogLevel.Info, "Parsed XML from string");
            return XDocument.Parse(xmlString);
        }
        catch (Exception ex)
        {
            Log(LogLevel.Error, $"Error parsing XML from string: {ex.Message}");
            throw;
        }
    }

    public async Task<XElement> FetchAdditionalMetadataAsync(XElement element)
    {
        try
        {
            var metadataUrl = GetMetadataUrl(element);
            var metadataContent = await _httpClient.GetStringAsync(metadataUrl);
            return XElement.Parse(metadataContent);
        }
        catch (Exception ex)
        {
            Log(LogLevel.Error, $"Error fetching metadata: {ex.Message}");
            throw;
        }
    }

    private string GetMetadataUrl(XElement element)
    {
        // Implement logic to generate metadata URL based on element attributes
        return "https://example.com/metadata";
    }

    private void Log(LogLevel level, string message)
    {
        if (level >= _logLevel)
        {
            Console.WriteLine($"{DateTime.Now}: [{level}] {message}");
        }
    }
}
