import hashlib
import threading
import queue
from concurrent.futures import ThreadPoolExecutor
import logging
import os

# Set up logging configuration
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class FileHasher:
    def __init__(self, chunk_size=4096, db_connection=None):
        self.chunk_size = chunk_size
        self.db_connection = db_connection

    def hash_file(self, file_path):
        hasher = hashlib.md5()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(self.chunk_size), b''):
                hasher.update(chunk)
        return hasher.hexdigest()

    def process_files_concurrently(self, files_queue):
        def worker():
            while True:
                file_path, metadata = files_queue.get()
                if file_path is None:
                    break
                try:
                    md5_hash = self.hash_file(file_path)
                    # Assuming a function store_in_db exists to handle database storage
                    store_in_db(self.db_connection, md5_hash, metadata)
                    logging.info(f"Processed {file_path} with hash {md5_hash}")
                except Exception as e:
                    logging.error(f"Error processing {file_path}: {e}")
                finally:
                    files_queue.task_done()

        num_threads = os.cpu_count() or 4
        with ThreadPoolExecutor(max_workers=num_threads) as executor:
            for _ in range(num_threads):
                executor.submit(worker)
            for file_path, metadata in files_queue:
                files_queue.put((file_path, metadata))
            files_queue.join()

def fallback_parser(file_path):
    try:
        # Attempt to parse the file
        pass
    except Exception as e:
        logging.error(f"Error parsing {file_path}: {e}")
        return None

def store_in_db(db_connection, md5_hash, metadata):
    cursor = db_connection.cursor()
    cursor.execute("INSERT INTO file_hashes (md5_hash, metadata) VALUES (%s, %s)", (md5_hash, metadata))
    db_connection.commit()

# Example usage
if __name__ == "__main__":
    files_queue = queue.Queue()
    for root, _, files in os.walk('path/to/files'):
        for file in files:
            file_path = os.path.join(root, file)
            metadata = fallback_parser(file_path)
            if metadata is not None:
                files_queue.put((file_path, metadata))

    hasher = FileHasher(db_connection=your_db_connection)
    hasher.process_files_concurrently(files_queue)
```

