        EVP_DecryptUpdate(ctx, (unsigned char*)decryptedData.data(), &len, (const unsigned char*)encryptedData.data(), encryptedData.size());
        EVP_DecryptFinal_ex(ctx, (unsigned char*)decryptedData.data() + len, &final_len);
        EVP_CIPHER_CTX_free(ctx);
    }
