    RNTI,
    CRC_INDICATION_REL8_TAG,
    CRCFLAG
} LogTag;

typedef struct {
    LogTag tag;
    void *data;
} LogEntry;

LogEntry log_queue[LOG_QUEUE_SIZE];
sem_t log_queue_full, log_queue_empty, log_mutex;
int log_head = 0, log_tail = 0;

void *log_producer(void *arg) {
    int file_fd = *(int *)arg;
    while (1) {
        // Read data from file
        LogEntry entry;
        entry.tag = RX_UE_INFORMATION_TAG; // Placeholder for actual data reading
        entry.data = malloc(sizeof(int)); // Allocate memory for data
        *(int *)entry.data = 42; // Placeholder for actual data

        sem_wait(&log_queue_empty);
        pthread_mutex_lock(&log_mutex);

        log_queue[log_tail] = entry;
        log_tail = (log_tail + 1) % LOG_QUEUE_SIZE;

        pthread_mutex_unlock(&log_mutex);
        sem_post(&log_queue_full);
    }
}

void *log_consumer(void *arg) {
    while (1) {
        sem_wait(&log_queue_full);
        pthread_mutex_lock(&log_mutex);

        LogEntry entry = log_queue[log_head];
        log_head = (log_head + 1) % LOG_QUEUE_SIZE;

        pthread_mutex_unlock(&log_mutex);
        sem_post(&log_queue_empty);

        // Process data
        switch (entry.tag) {
            case RX_UE_INFORMATION_TAG:
                printf("Processing RX_UE_INFORMATION_TAG: %d\n", *(int *)entry.data);
                break;
            case RNTI:
                printf("Processing RNTI: %d\n", *(int *)entry.data);
                break;
            case CRC_INDICATION_REL8_TAG:
                printf("Processing CRC_INDICATION_REL8_TAG: %d\n", *(int *)entry.data);
                break;
            case CRCFLAG:
                printf("Processing CRCFLAG: %d\n", *(int *)entry.data);
                break;
        }

        free(entry.data); // Free allocated memory for data
    }
}

int main() {
    sem_init(&log_queue_full, 0, LOG_QUEUE_SIZE - 1);
    sem_init(&log_queue_empty, 0, 0);
    pthread_mutex_init(&log_mutex, NULL);

    pthread_t producer[MAX_FILES], consumer;
    int file_fds[MAX_FILES];

    // Open log files and start producers
    for (int i = 0; i < MAX_FILES; i++) {
        char filename[20];
        snprintf(filename, sizeof(filename), "log_%d.txt", i);
        file_fds[i] = open(filename, O_RDONLY);
        pthread_create(&producer[i], NULL, log_producer, &file_fds[i]);
    }

    // Start consumer
    pthread_create(&consumer, NULL, log_consumer, NULL);

    // Wait for producers and consumer to finish (not shown)
    for (int i = 0; i < MAX_FILES; i++) {
        pthread_join(producer[i], NULL);
    }
    pthread_join(consumer, NULL);

    sem_destroy(&log_queue_full);
    sem_destroy(&log_queue_empty);
    pthread_mutex_destroy(&log_mutex);

    return 0;
}
