#include <pthread.h>
#include <errno.h>

static ClinicStatus *clinic_statuses = NULL;
static size_t num_clinics = 0;
static size_t max_clinics = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int clinic_status_manager_init(const ClinicStatusConfig *config) {
    if (config->initial_size == 0 || config->min_clinic_id >= config->max_clinic_id ||
        config->rng_seed == 0 || config->max_concurrent_modifications == 0) {
        return -1; // Invalid configuration
    }

    clinic_statuses = malloc(config->initial_size * sizeof(ClinicStatus));
    if (!clinic_statuses) {
        return -2; // Memory allocation failed
    }
    num_clinics = config->initial_size;
    max_clinics = config->initial_size;

    srand(config->rng_seed);
    return 0;
}

void clinic_status_manager_cleanup() {
    free(clinic_statuses);
    clinic_statuses = NULL;
    num_clinics = 0;
    max_clinics = 0;
    pthread_mutex_destroy(&mutex);
}

bool clinic_status_update(uint32_t clinic_id, const char *last_modified_ip, int64_t last_modified_date) {
    pthread_mutex_lock(&mutex);
    if (clinic_id < config.min_clinic_id || clinic_id >= config.max_clinic_id ||
        clinic_statuses[clinic_id - config.min_clinic_id].last_modified_date > last_modified_date) {
        pthread_mutex_unlock(&mutex);
        return false; // Invalid or outdated update
    }

    clinic_statuses[clinic_id - config.min_clinic_id].last_modified_ip = strcpy(last_modified_ip, last_modified_ip);
    clinic_statuses[clinic_id - config.min_clinic_id].last_modified_date = last_modified_date;
    pthread_mutex_unlock(&mutex);
    return true;
}

int clinic_status_get(uint32_t clinic_id, ClinicStatus *status) {
    pthread_mutex_lock(&mutex);
    if (clinic_id < config.min_clinic_id || clinic_id >= config.max_clinic_id ||
        clinic_statuses[clinic_id - config.min_clinic_id].last_modified_date == 0) {
        pthread_mutex_unlock(&mutex);
        return -1; // Invalid or non-existent entry
    }

    *status = clinic_statuses[clinic_id - config.min_clinic_id];
    pthread_mutex_unlock(&mutex);
    return 0;
}
