    pthread_mutex_destroy(&manager->lock);
    free(manager->status_array);
    free(manager);
}

int add_clinic_status(ClinicStatusManager *manager, ClinicStatus status) {
    pthread_mutex_lock(&manager->lock);

    // Validate clinic_id
    if (status.clinic_id < manager->min_clinic_id || status.clinic_id > manager->max_clinic_id) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Invalid clinic_id
    }

    // Check for space
    if (manager->size >= manager->capacity) {
        // Resize the array or handle as necessary
        pthread_mutex_unlock(&manager->lock);
        return -2; // No space available
    }

    // Add status to array
    manager->status_array[manager->size++] = status;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
