import os
import hashlib
from concurrent.futures import ThreadPoolExecutor
from pydantic import BaseModel, validator
from dotenv import load_dotenv
from redis import Redis
from kombu import Connection, Queue

load_dotenv()

class Config(BaseModel):
    storage_endpoint: str = os.getenv("STORAGE_ENDPOINT")
    message_queue_url: str = os.getenv("MESSAGE_QUEUE_URL")
    max_concurrent_tasks: int = int(os.getenv("MAX_CONCURRENT_TASKS", 10))

config = Config()

def calculate_md5(file_path):
    """Calculate the MD5 hash of a file."""
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hasher.update(chunk)
    return hasher.hexdigest()

def process_file_task(task_id, file_path):
    """Process a single file and store the MD5 hash."""
    try:
        md5_hash = calculate_md5(file_path)
        # Store the result in the database or external storage
        print(f"Processed {file_path} with MD5: {md5_hash}")
    except Exception as e:
        # Log error details and retry logic if needed
        print(f"Error processing {file_path}: {e}")

def scan_directory(directory, extension):
    """Recursively list files matching a given extension."""
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith(extension) and not file.startswith('.'):
                yield os.path.join(root, file)

def main():
    redis = Redis()
    with Connection(config.message_queue_url) as conn:
        queue = Queue('file_tasks', connection=conn)
        with ThreadPoolExecutor(max_workers=config.max_concurrent_tasks) as executor:
            for task_id, file_path in enumerate(scan_directory('/path/to/directory', '.txt')):
                executor.submit(process_file_task, task_id, file_path)

if __name__ == "__main__":
    main()
