using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class ContentUpdateService
{
    private readonly HttpClient _httpClient;

    public ContentUpdateService()
    {
        _httpClient = new HttpClient();
    }

    public async Task UpdateElementWithFileContentAsync(int pageSectionId, int elementId, string filePath)
    {
        try
        {
            // Read file content in chunks
            using (var stream = File.Open(filePath, FileMode.Open, FileAccess.Read, FileShare.Read))
            {
                var content = await ReadFileContentAsync(stream);
                var hash = CalculateHash(content);

                // Prepare HTML update command
                var htmlUpdateCommand = GenerateHtmlUpdateCommand(elementId, hash);

                // Update CMS content
                await _httpClient.PostAsync($"https://cmsapi.example.com/update?pageSectionId={pageSectionId}", new StringContent(htmlUpdateCommand));
            }
        }
        catch (Exception ex)
        {
            // Log error and handle gracefully
            Console.WriteLine($"Error updating element with file content: {ex.Message}");
        }
    }

    private async Task<byte[]> ReadFileContentAsync(Stream stream)
    {
        using (var memoryStream = new MemoryStream())
        {
            await stream.CopyToAsync(memoryStream);
            return memoryStream.ToArray();
        }
    }

    private string CalculateHash(byte[] content)
    {
        using (var sha256 = SHA256.Create())
        {
            var hashBytes = sha256.ComputeHash(content);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
        }
    }

    private string GenerateHtmlUpdateCommand(int elementId, string hash)
    {
        // Example: <div id="elementId">SHA256_hash</div>
        return $"<div id=\"{elementId}\">{hash}</div>";
    }
}
```

