import os
from typing import List, Dict
from concurrent.futures import ThreadPoolExecutor

class DocumentProcessingService:
    def __init__(self, database_client, message_queue_client):
        self.database_client = database_client
        self.message_queue_client = message_queue_client
        self.thread_pool = ThreadPoolExecutor(max_workers=os.cpu_count() * 2)

    def process_document(self, document_id: str) -> Dict[str, any]:
        # Retrieve document from database
        document = self.database_client.get(document_id)

        # Process document (placeholder for actual processing logic)
        processed_document = {"content": "Processed content", "version": document["version"] + 1}

        # Update document version and save back to database
        optimistic_lock = document["optimistic_lock"]
        result = self.database_client.update(document_id, processed_document, optimistic_lock)

        if not result:
            return self.handle_conflict(document_id, document["version"])

        # Publish notification about the document update
        self.message_queue_client.publish("document_updated", {"document_id": document_id})

        return processed_document

    def handle_conflict(self, document_id: str, current_version: int) -> Dict[str, any]:
        # Fetch latest version of document from database
        latest_document = self.database_client.get(document_id)

        if latest_document["version"] > current_version:
            return {
                "error": "Conflict",
                "message": "Document was updated by another process. Please retry the operation."
            }

        # Retry processing with updated version
        return self.process_document(document_id)

    def upload_document(self, tenant_id: str, document_data: bytes) -> Dict[str, any]:
        document_id = f"{tenant_id}_{os.urandom(8).hex()}"
        optimistic_lock = 0

        while True:
            try:
                # Store document in database with initial version and lock
                self.database_client.insert(document_id, {"content": document_data, "version": 1, "optimistic_lock": optimistic_lock})
                break
            except Exception as e:
                if "Duplicate key" not in str(e):
                    raise
                # Handle race condition by incrementing lock version and retrying
                optimistic_lock += 1

        return {"document_id": document_id}

    def download_document(self, document_id: str) -> bytes:
        document = self.database_client.get(document_id)
        return document["content"]
