package main

import (
    "context"
    "fmt"
    "log"
    "net/http"
    "sync"

    "github.com/Shopify/sarama"
    "github.com/gomodule/redigo/redis"
)

type StreamProcessor struct {
    kafkaConsumer sarama.ConsumerGroup
    redisClient   *redis.Client
    workers       int
}

func NewStreamProcessor(brokers []string, groupId string, workers int) (*StreamProcessor, error) {
    consumerConfig := sarama.NewConfig()
    consumerConfig.Version = sarama.V2_3_0_0
    consumerConfig.Consumer.Return.Errors = true

    redisClient, err := redis.DialURL("redis://localhost:6379")
    if err != nil {
        return nil, fmt.Errorf("failed to connect to Redis: %w", err)
    }

    consumerGroup, err := sarama.NewConsumerGroup(brokers, groupId, consumerConfig)
    if err != nil {
        return nil, fmt.Errorf("failed to create consumer group: %w", err)
    }

    return &StreamProcessor{
        kafkaConsumer: consumerGroup,
        redisClient:   redisClient,
        workers:       workers,
    }, nil
}

func (sp *StreamProcessor) Start() error {
    ctx := context.Background()

    for i := 0; i < sp.workers; i++ {
        go func() {
            for {
                err := sp.kafkaConsumer.Consume(ctx, []string{"iot", "socialmedia", "logs"}, sp)
                if err != nil && err != sarama.ErrClosed {
                    log.Printf("Error from consumer: %v", err)
                }
            }
        }()
    }

    return nil
}

func (sp *StreamProcessor) Cleanup(_ context.Context, members sarama.ConsumerGroupMembers) error {
    return nil
}

func (sp *StreamProcessor) CommitOffsets(_ context.Context, claims sarama.ConsumerGroupSession) error {
    return claims.Commit()
}

func (sp *StreamProcessor) ProcessMessage(session sarama.ConsumerGroupSession, msg *sarama.ConsumerMessage) error {
    // Process the message here
    data := string(msg.Value)
    log.Printf("Processing message: %s", data)

    // Store processed data in Redis for caching
    _, err := sp.redisClient.Set(msg.Topic, data, 0).Result()
    if err != nil {
        return fmt.Errorf("failed to store data in Redis: %w", err)
    }

    session.MarkMessage(msg, "")
    return nil
}

func main() {
    brokers := []string{"localhost:9092"}
    groupId := "stream_processor_group"
    workers := 5

    streamProcessor, err := NewStreamProcessor(brokers, groupId, workers)
    if err != nil {
        log.Fatalf("Failed to create stream processor: %v", err)
    }

    log.Println("Starting stream processor...")
    if err := streamProcessor.Start(); err != nil {
        log.Fatalf("Failed to start stream processor: %v", err)
    }

    http.HandleFunc("/shutdown", func(w http.ResponseWriter, r *http.Request) {
        // Handle shutdown gracefully
    })

    http.ListenAndServe(":8080", nil)
}
