using Neo4j.Driver;

class GraphDatabaseManager
{
    private IDriver _driver;

    public GraphDatabaseManager(string uri, string user, string password)
    {
        _driver = GraphDatabase.Driver(uri, AuthTokens.Basic(user, password));
    }

    public void AddVertex(string label, Dictionary<string, object> properties)
    {
        using (var session = _driver.Session())
        {
            var query = $"CREATE (:Node {properties}) RETURN id(n) AS nodeId";
            var result = session.Run(query);
            foreach (var record in result)
            {
                Console.WriteLine($"Vertex added with ID: {record["nodeId"]}");
            }
        }
    }

    public void AddEdge(string sourceLabel, string targetLabel, Dictionary<string, object> properties)
    {
        using (var session = _driver.Session())
        {
            var query = $"MATCH (a:{sourceLabel}), (b:{targetLabel}) MERGE (a)-[:RELATIONSHIP]->(b) ON CREATE SET rel += {properties} RETURN id(rel) AS edgeId";
            var result = session.Run(query);
            foreach (var record in result)
            {
                Console.WriteLine($"Edge added with ID: {record["edgeId"]}");
            }
        }
    }

