using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;

public class FileService : IFileService
{
    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;
    private readonly ILogger<FileService> _logger;

    public FileService(HttpClient httpClient, IMemoryCache cache, ILogger<FileService> logger)
    {
        _httpClient = httpClient;
        _cache = cache;
        _logger = logger;
    }

    public async Task UpdateElementWithFileContentAsync(int pageSectionId, int elementId, string filePath, CancellationToken cancellationToken)
    {
        try
        {
            // Check if the hash is already in cache
            var cachedHash = _cache.Get<string>(filePath);
            if (cachedHash != null)
            {
                await UpdateElementAsync(pageSectionId, elementId, cachedHash, cancellationToken);
                return;
            }

            // Read file content in chunks and calculate hash
            using (var stream = File.OpenRead(filePath))
            using (var sha256 = SHA256.Create())
            {
                var buffer = new byte[8192];
                int bytesRead;
                while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length, cancellationToken)) > 0)
                {
                    sha256.TransformBlock(buffer, 0, bytesRead, null, 0);
                }
                sha256.TransformFinalBlock(Array.Empty<byte>(), 0, 0);

                cachedHash = BitConverter.ToString(sha256.Hash).Replace("-", "").ToLower();
            }

            // Cache the hash
            _cache.Set(filePath, cachedHash, new MemoryCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(1)
            });

            // Update element with the hash
            await UpdateElementAsync(pageSectionId, elementId, cachedHash, cancellationToken);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating file content for page section {PageSectionId} and element {ElementId}", pageSectionId, elementId);
            throw;
        }
    }

    private async Task UpdateElementAsync(int pageSectionId, int elementId, string hash, CancellationToken cancellationToken)
    {
        // Simulate updating an HTML element with the hash
        var url = $"https://example.com/api/updateElement?sectionId={pageSectionId}&elementId={elementId}&hash={hash}";
        await _httpClient.PutAsync(url, null, cancellationToken);
    }
}

public interface IFileService
{
    Task UpdateElementWithFileContentAsync(int pageSectionId, int elementId, string filePath, CancellationToken cancellationToken);
}
