#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <unordered_map>

class CacheManager {
public:
    void set(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_[key] = value;
        notifyReplication();
    }

    std::string get(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            return it->second;
        }
        return "";
    }

private:
    void notifyReplication() {
        for (auto& node : replicas_) {
            // Implement replication logic here
            std::thread([this, &node]() { replicateTo(node); }).detach();
        }
    }

    void replicateTo(const std::string& node) {
        // Implement replication to a specific node
    }

    std::unordered_map<std::string, std::string> cache_;
    std::vector<std::string> replicas_;
    std::mutex mutex_;
};

// gRPC Service Definition
syntax = "proto3";

service CacheService {
    rpc Get (GetRequest) returns (GetResponse);
    rpc Set (SetRequest) returns (SetResponse);
}

message GetRequest {
    string key = 1;
}

message GetResponse {
    string value = 2;
}

message SetRequest {
