#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* record_manager_init(size_t initial_capacity) {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void record_manager_free(RecordManager* manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        // Perform any necessary cleanup on each record
    }
    free(manager->records);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int record_manager_add(RecordManager* manager, int key, long offset) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size + 1 > manager->capacity * 1.2) {
        size_t new_capacity = manager->capacity * 2;
        Record* new_records = (Record*)realloc(manager->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Out of memory
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    manager->records[manager->size].key = key;
    manager->records[manager->size].offset = offset;
    ++manager->size;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int record_manager_update(RecordManager* manager, int key, long new_offset) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i].key == key) {
            manager->records[i].offset = new_offset;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Key not found
}

int record_manager_get(RecordManager* manager, int key, long* offset) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i].key == key) {
            *offset = manager->records[i].offset;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Key not found
}

void* record_manager_pull_data(void* arg) {
    RecordManager* manager = (RecordManager*)arg;

    while (1) {
        // Simulate data retrieval from an external source
        int key;
        long offset;
        if (retrieve_from_external_source(&key, &offset)) {
            pthread_mutex_lock(&manager->lock);
            record_manager_add(manager, key, offset);
            pthread_mutex_unlock(&manager->lock);
        }

        // Add a delay before the next pull attempt
        sleep(5);
    }

    return NULL;
}

int main() {
    RecordManager* manager = record_manager_init(10);

    if (!manager) {
        fprintf(stderr, "Failed to initialize record manager\n");
        return 1;
    }

    // Example usage
    record_manager_add(manager, 1, 42);
    record_manager_add(manager, 2, 99);

    long offset;
    if (record_manager_get(manager, 1, &offset) == 0) {
        printf("Offset for key 1: %ld\n", offset);
    }

    pthread_t pull_thread;
    if (pthread_create(&pull_thread, NULL, record_manager_pull_data, manager) != 0) {
        fprintf(stderr, "Failed to create pull thread\n");
        record_manager_free(manager);
        return 1;
    }

    // Simulate running the application
    sleep(30);

    pthread_cancel(pull_thread);
    pthread_join(pull_thread, NULL);

    record_manager_free(manager);
    return 0;
}
