// liblte_management_system.cpp

#include "liblte_management_system.h"
#include <iostream>
#include <chrono>

bool LTEUEContext::removeBearer(int bearerId) {
    auto it = bearers.find(bearerId);
    if (it != bearers.end()) {
        bearers.erase(it);
        return true;
    }
    return false;
}

void LTENetworkManager::addUEContext(const LTEUEContext& ueContext) {
    std::lock_guard<std::mutex> lock(mutex);
    ueContexts[ueContext.getCellIdentity()] = std::make_unique<LTEUEContext>(ueContext);
    cv.notify_one();
}

bool LTENetworkManager::removeUEContext(int ci) {
    std::lock_guard<std::mutex> lock(mutex);
    auto it = ueContexts.find(ci);
    if (it != ueContexts.end()) {
        ueContexts.erase(it);
        return true;
    }
    return false;
}

LTEUEContext* LTENetworkManager::getUEContext(int ci) {
    std::lock_guard<std::mutex> lock(mutex);
    auto it = ueContexts.find(ci);
    if (it != ueContexts.end()) {
        return it->second.get();
    }
    return nullptr;
}

void LTENetworkManager::backgroundTask() {
    while (true) {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return !ueContexts.empty(); });

        // Perform background tasks such as resource management
        // For example, adaptive resource allocation based on traffic patterns

        lock.unlock();

        // Simulate a task completion after 1 second
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }
}

// Start the background thread when the manager is created
LTENetworkManager::LTENetworkManager() {
    std::thread(&LTENetworkManager::backgroundTask, this).detach();
}
