#include <iostream>
#include <string>
#include <fstream>
#include <thread>
#include <future>
#include <mutex>
#include <openssl/md5.h>

class MD5Hasher {
public:
    std::string fetch_and_compute_file_md5(const std::string& file_path) {
        std::ifstream file(file_path, std::ios::binary);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file");
        }

        const size_t buffer_size = 1024 * 1024; // 1MB
        char buffer[buffer_size];
        MD5_CTX md5;
        MD5_Init(&md5);

        while (file.read(buffer, buffer_size)) {
            MD5_Update(&md5, buffer, file.gcount());
        }

        size_t remaining = file.gcount();
        if (remaining > 0) {
            MD5_Update(&md5, buffer, remaining);
        }

        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5_Final(digest, &md5);

        std::ostringstream oss;
        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            oss << std::hex << std::setw(2) << std::setfill('0') << (int)digest[i];
        }

        return oss.str();
    }
};

int main() {
    MD5Hasher hasher;
    try {
        std::string md5_hash = hasher.fetch_and_compute_file_md5("example.txt");
        std::cout << "MD5 Hash: " << md5_hash << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
