app = Flask(__name__)

# Define caching for external API calls
cache = TTLCache(maxsize=100, ttl=3600)

@app.route('/weather', methods=['GET'])
@cached(cache)
def get_weather():
    # Extract query parameters from request
    date_range = request.args.get('date_range')
    weather_type = request.args.get('weather_type')
    coordinates = request.args.get('coordinates')
    output_format = request.args.get('output_format')

    # Dynamically integrate with external weather APIs based on availability
    api_urls = {
        'public_api_1': 'https://api.public1.com/weather',
        'public_api_2': 'https://api.public2.com/weather'
    }

    data = {}
    for api_url in api_urls.values():
        try:
            response = requests.get(api_url, params={
                'date_range': date_range,
                'weather_type': weather_type,
                'coordinates': coordinates
            })
            response.raise_for_status()
            data.update(response.json())
        except requests.exceptions.RequestException as e:
            # Log the error and continue with other APIs
            print(f"Failed to fetch weather data from {api_url}: {e}")

    # Return the aggregated weather data
    return jsonify(data)

if __name__ == '__main__':
    app.run(debug=True)
