// Define ClinicStatus structure
typedef struct {
    int clinic_id;
    char last_modified_ip[16];
    long last_modified_date;
} ClinicStatus;

// Define ClinicStatusManager structure
typedef struct {
    ClinicStatus *array;
    size_t array_size;
    size_t min_clinic_id;
    size_t max_clinic_id;
    unsigned int random_seed;
    size_t max_concurrent_modifications;
    pthread_mutex_t mutex;
} ClinicStatusManager;

// Function to initialize the manager
int init_clinic_status_manager(ClinicStatusManager *manager, size_t initial_size, size_t min_clinic_id, size_t max_clinic_id, unsigned int random_seed, size_t max_concurrent_modifications) {
    // Initialize array and mutex
    manager->array = (ClinicStatus *)malloc(initial_size * sizeof(ClinicStatus));
    if (!manager->array) {
        return -1; // Memory allocation failed
    }
    memset(manager->array, 0, initial_size * sizeof(ClinicStatus));
    manager->array_size = initial_size;
    manager->min_clinic_id = min_clinic_id;
    manager->max_clinic_id = max_clinic_id;
    manager->random_seed = random_seed;
    manager->max_concurrent_modifications = max_concurrent_modifications;
    pthread_mutex_init(&manager->mutex, NULL);
    return 0;
}

// Function to update clinic status
void update_clinic_status(ClinicStatusManager *manager, int clinic_id, char *last_modified_ip, long last_modified_date) {
    pthread_mutex_lock(&manager->mutex);
    // Check if the clinic_id is within valid range and not already updated recently
    for (size_t i = 0; i < manager->array_size; ++i) {
        if (manager->array[i].clinic_id == clinic_id && strcmp(manager->array[i].last_modified_ip, last_modified_ip) == 0 && manager->array[i].last_modified_date == last_modified_date) {
            pthread_mutex_unlock(&manager->mutex);
            return; // Duplicate update
        }
    }
    // Find an empty slot or resize if necessary
    if (manager->array_size == manager->max_concurrent_modifications) {
        // Resize array (simple example, real implementation may use memory pooling)
        ClinicStatus *new_array = (ClinicStatus *)realloc(manager->array, 2 * manager->array_size * sizeof(ClinicStatus));
        if (!new_array) {
            pthread_mutex_unlock(&manager->mutex);
            return; // Memory allocation failed
        }
        memset(new_array + manager->array_size, 0, manager->array_size * sizeof(ClinicStatus));
        manager->array = new_array;
        manager->array_size *= 2;
    }
    // Add new update
    for (size_t i = 0; i < manager->array_size; ++i) {
        if (manager->array[i].clinic_id == -1) { // Assuming clinic_id of -1 is unused
            manager->array[i].clinic_id = clinic_id;
            strcpy(manager->array[i].last_modified_ip, last_modified_ip);
            manager->array[i].last_modified_date = last_modified_date;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

// Function to clean up the manager
void cleanup_clinic_status_manager(ClinicStatusManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    free(manager->array);
    pthread_mutex_destroy(&manager->mutex);
    pthread_mutex_unlock(&manager->mutex);
}
