    LogProcessor(size_t numThreads, const std::string& storageServiceUrl, const std::string& alertingApiUrl, 
                 const std::string& mlModelUrl)
        : numThreads(numThreads), storageServiceUrl(storageServiceUrl), alertingApiUrl(alertingApiUrl), mlModelUrl(mlModelUrl) {
