# unified_log_manager.py

class UnifiedLogManager:
    def __init__(self):
        self.log_sources = []
        self.storage_backends = []
        self.parsers = {}
        self.monitoring_service = None
        self.alerting_service = None

    def add_log_source(self, source):
        self.log_sources.append(source)

    def remove_log_source(self, source):
        self.log_sources.remove(source)

    def register_parser(self, log_type, parser):
        self.parsers[log_type] = parser

    def add_storage_backend(self, backend):
        self.storage_backends.append(backend)

    def remove_storage_backend(self, backend):
        self.storage_backends.remove(backend)

    def set_monitoring_service(self, service):
        self.monitoring_service = service

    def set_alerting_service(self, service):
        self.alerting_service = service

    def process_logs(self):
        for source in self.log_sources:
            logs = source.ingest_logs()
            for log_type, log in logs.items():
                if log_type in self.parsers:
                    processed_log = self.parsers[log_type](log)
                    for backend in self.storage_backends:
                        backend.store_log(processed_log)

    def monitor(self):
        if self.monitoring_service:
            self.monitoring_service.collect_metrics()
            self.monitoring_service.generate_dashboards()

    def alert_on_anomalies(self):
        if self.alerting_service:
            anomalies = self.monitoring_service.detect_anomalies()
            for anomaly in anomalies:
                self.alerting_service.send_alert(anomaly)
