use std::fs::{File, OpenOptions};
use std::io::{Read, Write};
use std::path::Path;
use openssl::pkey::{PKey, PrivateKeyInfo};
use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize)]
struct OAuthRequest {
    client_id: String,
    private_key_url: String,
    certificate_url: String,
}

fn fetch_and_combine_keys(oauth_request: &OAuthRequest) -> Result<String, String> {
    let mut private_key = String::new();
    let mut certificate = String::new();

    match reqwest::get(&oauth_request.private_key_url) {
        Ok(mut response) => response.read_to_string(&mut private_key)?,
        Err(_) => return Err("Failed to fetch private key".to_string()),
    }

    match reqwest::get(&oauth_request.certificate_url) {
        Ok(mut response) => response.read_to_string(&mut certificate)?,
        Err(_) => return Err("Failed to fetch certificate".to_string()),
    }

    let pem_file_path = Path::new("/path/to/pem/file");
    if let Err(_) = OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .open(pem_file_path)?
        .write_all(format!("{}\n{}", private_key, certificate).as_bytes())
    {
        return Err("Failed to write PEM file".to_string());
    }

    Ok(pem_file_path.display().to_string())
}

fn main() {
    let oauth_request = OAuthRequest {
        client_id: "your_client_id".to_string(),
        private_key_url: "https://example.com/private-key.pem".to_string(),
        certificate_url: "https://example.com/certificate.pem".to_string(),
    };

    match fetch_and_combine_keys(&oauth_request) {
        Ok(pem_path) => println!("PEM file created at: {}", pem_path),
        Err(e) => eprintln!("Error: {}", e),
    }
}
