class DistributedLogger {
public:
    void log(const std::string& message, int level) {
        std::lock_guard<std::mutex> lock(mutex);
        if (level <= currentLevel) {
            writeToFile(message);
            rotateLog();
        }
    }

private:
    std::mutex mutex;
    std::condition_variable cv;
    std::ofstream logFile;
    std::vector<std::string> buffer;
    int bufferSize = 1000;
    int currentLevel = 1; // Default logging level
    int nodeIndex;

    void writeToFile(const std::string& message) {
        if (logFile.is_open()) {
            logFile << message << std::endl;
        }
    }

    void rotateLog() {
        if (buffer.size() >= bufferSize) {
            buffer.clear();
            // Implement log file rotation logic here
        }
    }
};

void insertOrLog(std::forward_list<std::string>& list, const std::string& target, const std::string& value, bool shouldLog, const char* logFile, int logLevel, int bufferSize, bool appendOnly, bool useDistributedLog, int nodeIndex) {
    static DistributedLogger logger(logFile, bufferSize, logLevel, nodeIndex);

    if (useDistributedLog) {
        // Implement distributed logging logic here
        logger.log("Inserting or appending operation", logLevel);
    } else {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = list.before_begin();
        for (; it != list.end(); ++it) {
            if (*it == target) {
                break;
            }
        }

        if (it != list.end()) {
            list.insert_after(it, value);
            logger.log("Value inserted after target", logLevel);
        } else {
            list.push_back(value);
            logger.log("Value appended to the end", logLevel);
        }
    }
}
