#include <memory>

// Mock API Client for demonstration purposes
class ApiClient {
public:
    std::optional<std::string> getUserProfile(const std::string& userId) const {
        // Simulate API request with a delay
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
        if (userId == "123") return "User 1 Profile";
        if (userId == "456") return "User 2 Profile";
        return std::nullopt;
    }
};

// In-memory cache using an unordered_map
class UserProfileCache {
private:
    std::unordered_map<std::string, std::future<std::optional<std::string>>> cache;
    mutable std::mutex mutex;

public:
    std::optional<std::string> getUserProfile(const std::string& userId) {
        std::lock_guard lock(mutex);
        if (cache.find(userId) == cache.end()) {
            auto result = std::async(std::launch::async, [this, userId]() {
                return ApiClient().getUserProfile(userId);
            });
            cache[userId] = std::move(result);
        }
        return cache[userId].get();
    }

    void evictUser(const std::string& userId) {
        std::lock_guard lock(mutex);
        cache.erase(userId);
    }
};

// Main application class
class UserProfileService {
private:
    UserProfileCache cache;

public:
    std::optional<std::string> getUserProfile(const std::string& userId) {
        return cache.getUserProfile(userId);
    }

    void evictUser(const std::string& userId) {
        cache.evictUser(userId);
    }
};

int main() {
    UserProfileService service;
    std::vector<std::string> userIds = {"123", "456", "789"};

    for (const auto& id : userIds) {
        if (auto profile = service.getUserProfile(id)) {
            std::cout << "User Profile: " << *profile << std::endl;
        } else {
            std::cerr << "Failed to retrieve user profile for ID: " << id << std::endl;
        }
    }

    return 0;
}
```

