namespace DynamicQueryExecutor
{
    public interface IDynamicQueryExecutor
    {
        Task<DbDataReader> ExecuteAsync(string query, Dictionary<string, object> parameters);
    }

    public class DynamicQueryExecutor : IDynamicQueryExecutor
    {
        private readonly IDbConnection _dbConnection;
        private readonly IHttpClientFactory _httpClientFactory;
        private readonly ILogger<DynamicQueryExecutor> _logger;
        private readonly ConnectionMultiplexer _redis;

        public DynamicQueryExecutor(IDbConnection dbConnection, IHttpClientFactory httpClientFactory, ILogger<DynamicQueryExecutor> logger, ConnectionMultiplexer redis)
        {
            _dbConnection = dbConnection;
            _httpClientFactory = httpClientFactory;
            _logger = logger;
            _redis = redis;
        }

        public async Task<DbDataReader> ExecuteAsync(string query, Dictionary<string, object> parameters)
        {
            try
            {
                var cacheKey = CacheKeyFromQuery(query, parameters);
                if (await IsCacheHit(cacheKey))
                {
                    return await FetchFromCacheAsync(cacheKey);
                }

                using (var command = _dbConnection.CreateCommand())
                {
                    command.CommandText = query;
                    foreach (var param in parameters)
                    {
                        command.Parameters.Add(param.Key, param.Value);
                    }

                    var result = await command.ExecuteReaderAsync();
                    if (await IsCacheable(query))
                    {
                        await CacheResultAsync(cacheKey, result);
                    }
                    return result;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error executing query: {Query}", query);
                throw;
            }
        }

        private string CacheKeyFromQuery(string query, Dictionary<string, object> parameters)
        {
            // Generate a unique cache key based on the query and parameters
            return $"{query}_{string.Join(",", parameters.Select(p => $"{p.Key}={p.Value}"))}";
        }

        private async Task<bool> IsCacheHit(string cacheKey)
