function refreshDialogFields(resourceId, url) {
    var dialogFields = document.querySelectorAll('.dialog-field');
    var updatedValues = [];

    dialogFields.forEach(function(field) {
        if (field.name.includes(resourceId)) {
            // Send request to update field value
            fetch(url + '?resource=' + resourceId)
                .then(response => response.json())
                .then(data => {
                    if (data.success) {
                        field.value = data.newValue;
                        updatedValues.push(field);
                    }
                });
        }
    });

    window.parent.postMessage({ updatedFields: updatedValues }, '*');
}
