use actix_web::{web, App, HttpResponse, HttpServer};
use serde_json::json;
use tokio::sync::Mutex;

#[derive(Deserialize)]
struct CustomerProfile {
    id: String,
    name: String,
    email: String,
    region: String,
}

async fn get_customer_profile(data: web::Data<Mutex<Vec<CustomerProfile>>>, path: web::Path<String>) -> HttpResponse {
    let profiles = data.lock().await;
    if let Some(profile) = profiles.iter().find(|p| p.id == *path) {
        HttpResponse::Ok().json(json!({ "profile": profile }))
    } else {
        HttpResponse::NotFound().json(json!({ "error": "Customer profile not found" }))
    }
}

async fn create_customer_profile(data: web::Data<Mutex<Vec<CustomerProfile>>>, payload: web::Json<CustomerProfile>) -> HttpResponse {
    let mut profiles = data.lock().await;
    profiles.push(payload.into_inner());
    HttpResponse::Created().json(json!({ "message": "Customer profile created successfully" }))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .app_data(web::Data::new(Mutex::new(vec![])))
            .service(web::resource("/profile/{id}").route(web::get().to(get_customer_profile)))
            .service(web::resource("/profile").route(web::post().to(create_customer_profile)))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
```

