#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate a unique RNTI value
int generateUniqueRNTI(int *usedRNTIs, int count) {
    int rnti;
    do {
        rnti = rand() % 1000; // Assuming a range for RNTI values
    } while (rnti < 0 || rnti >= 1000 || usedRNTIs[rnti]);
    usedRNTIs[rnti] = 1;
    return rnti;
}

// Function to populate the linked list with NFAPI_CRC_INDICATION_PDU_T structures
void populateLinkedList(NFAPI_CRC_INDICATION_PDU_T **head, int N) {
    srand(time(NULL));
    int *usedRNTIs = (int *)calloc(1000, sizeof(int)); // Assuming a range for RNTI values

    NFAPI_CRC_INDICATION_PDU_T *current = NULL;
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *newNode = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        newNode->RX_UE_INFORMATION_TAG = rand() % 100; // Assuming a range for RX_UE_INFORMATION_TAG values
        newNode->RNTI = generateUniqueRNTI(usedRNTIs, 1000); // Generate unique RNTI
        newNode->CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG

        newNode->next = NULL;
        if (!*head) {
            *head = newNode;
        } else {
            current->next = newNode;
        }
        current = newNode;
    }

    free(usedRNTIs);
}

// Function to clean up allocated resources
void cleanup(NFAPI_CRC_INDICATION_PDU_T **head) {
    NFAPI_CRC_INDICATION_PDU_T *current = *head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}

// Example usage
int main() {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    int N = 10; // Number of elements to generate

    populateLinkedList(&head, N);

    // Process the linked list as needed

    cleanup(&head);
    return 0;
}
```

