const { v4: uuidv4 } = require('uuid');
const LRU = require('lru-cache');

// Create an LRU cache for storing sessions with a maximum size and expiration time
const sessionCache = new LRU({ max: 100, maxAge: 1000 * 60 * 5 });

async function fetchSession(sessionId) {
    // Simulate fetching a session from an external identity service
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            const mockData = {
                sessionId,
                userId: Math.random().toString(36).substr(2, 9),
                role: 'user',
                valid: true
            };
            resolve(mockData);
        }, Math.random() * 5000); // Random delay simulating network latency
    });
}

async function validateSession(session) {
    try {
        JSON.parse(JSON.stringify(session));
        return { isValid: true, session };
    } catch (error) {
        return { isValid: false, session };
    }
}

function renderFooter(sessions) {
    const footerElement = document.querySelector('footer');
    if (!footerElement) {
        console.warn('Footer element not found');
        return;
    }

    footerElement.innerHTML = ''; // Clear existing content

    sessions.forEach(session => {
        if (session.isValid) {
            const sessionDiv = document.createElement('div');
            sessionDiv.textContent = `Session ID: ${session.sessionId}, User: ${session.userId}`;
            footerElement.appendChild(sessionDiv);
        } else {
            const warningComment = document.createComment(`Invalid session: ${JSON.stringify(session)} warnings=1`);
            footerElement.appendChild(warningComment);
        }
    });
}

async function sessionManager() {
    try {
        // Fetch sessions from the external identity service
        const response = await fetch('https://identity-service.com/sessions');
        const sessionObjects = await response.json();

        const processedSessions = [];

        for (const session of sessionObjects) {
            const sessionId = uuidv4();
            if (!sessionCache.has(sessionId)) {
                session.sessionId = sessionId;
                const sessionData = await fetchSession(sessionId);
                sessionCache.set(sessionId, sessionData);

                const validationResult = validateSession(sessionData);
                processedSessions.push(validationResult);
            } else {
                processedSessions.push({ isValid: true, session: sessionCache.get(sessionId) });
            }
        }

        // Render the sessions in the footer
        renderFooter(processedSessions);
    } catch (error) {
        console.error('Error fetching or processing sessions:', error);
        const errorDiv = document.createElement('div');
        errorDiv.textContent = 'Failed to load session data. Please try again later.';
        document.querySelector('footer').appendChild(errorDiv);
    }
}

// Set up a periodic task to refresh the session manager
setInterval(sessionManager, 60 * 1000); // Refresh every minute

// Simulate network conditions for testing
sessionManager();
