["```javascript
// Node.js Microservice Architecture Code Block

const express = require('express');
const axios = require('axios');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const app = express();
app.use(express.json());

// Middleware for error handling
function errorHandler(err, req, res, next) {
  console.error(err.stack);
  res.status(500).send('Something broke!');
}

// Route to dynamically load and execute JavaScript modules
app.post('/executeModule', async (req, res) => {
  const { moduleUrl } = req.body;

  try {
    if (moduleUrl.startsWith('http')) {
      const response = await axios.get(moduleUrl);
      const moduleCode = response.data;
      // Execute the module dynamically
      eval(moduleCode); // Not recommended for production use due to security risks
      res.send('Module executed successfully');
    } else {
      const modulePath = path.resolve(__dirname, moduleUrl);
      if (fs.existsSync(modulePath)) {
        require(modulePath); // Dynamically load local module
        res.send('Local module loaded and executed');
      } else {
        res.status(404).send('Module not found');
      }
    }
  } catch (error) {
    errorHandler(error, req, res);
  }
});

// Route to calculate MD5 hash of a string
app.post('/calculateMD5', async (req, res) => {
  const { inputString } = req.body;

  try {
    const md5Hash = crypto.createHash('md5').update(inputString).digest('hex');
    res.send(md5Hash);
  } catch (error) {
    errorHandler(error, req, res);
  }
});

app.use(errorHandler);

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Microservice running on port ${PORT}`);
});
```

