function findElements(element, selector, testFn) {
  const result = [];

  if (testFn(element)) {
    result.push(element);
  }

  for (let i = 0; i < element.children.length; i++) {
    result.push(...findElements(element.children[i], selector, testFn));
  }

  return result;
}
