package com.iot.device.management.service;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.List;
import org.springframework.stereotype.Service;

@Service
public class DeviceManagementService {

    private final ConcurrentHashMap<String, DeviceContext> deviceMap = new ConcurrentHashMap<>();
    private final ExecutorService executorService = Executors.newFixedThreadPool(10);

    public void addDevice(DeviceContext device) {
        deviceMap.put(device.getUid(), device);
        // Asynchronously initialize data channels and QoS levels
        executorService.submit(() -> initDeviceChannels(device));
    }

    public DeviceContext getDevice(String uid) {
        return deviceMap.get(uid);
    }

    public void updateDevice(DeviceContext device) {
        deviceMap.replace(device.getUid(), device);
    }

    public void deleteDevice(String uid) {
        deviceMap.remove(uid);
    }

    private void initDeviceChannels(DeviceContext device) {
        // Simulate channel initialization and QoS settings
        for (DataChannel channel : device.getDataChannels()) {
            System.out.println("Initializing channel: " + channel.getChannelId());
        }
    }

    public List<DataChannel> getDeviceData(String uid) {
        DeviceContext device = deviceMap.get(uid);
        return device != null ? device.getDataChannels() : null;
    }
}

