use async_trait::async_trait;
use reqwest::{Client, Url};
use tokio::sync::{mpsc, RwLock};
use std::sync::Arc;
use std::time::{Duration, Instant};

pub struct HttpClient {
    client: Client,
    retry_policy: RetryPolicy,
    connection_pool: Arc<RwLock<ConnectionPool>>,
}

impl HttpClient {
    pub fn new() -> Self {
        HttpClient {
            client: Client::new(),
            retry_policy: RetryPolicy::default(),
            connection_pool: Arc::new(RwLock::new(ConnectionPool::default())),
        }
    }

    pub async fn request(&self, url: Url, method: reqwest::Method) -> Result<reqwest::Response, Error> {
        let mut retries = 0;
        loop {
            let start_time = Instant::now();
            match self.client.request(method.clone(), url.clone()).send().await {
                Ok(response) => {
                    if response.status().is_success() {
                        return Ok(response);
                    } else {
                        log::warn!("Request failed with status: {}", response.status());
                        retries += 1;
                    }
                }
                Err(e) => {
                    log::error!("Request error: {:?}", e);
                    retries += 1;
                }
            }

            if retries >= self.retry_policy.max_retries {
                return Err(Error::from("Max retries exceeded"));
            }

            let retry_interval = self.retry_policy.calculate_retry_interval(retries);
            log::info!("Retrying in {}ms", retry_interval.as_millis());
            tokio::time::sleep(retry_interval).await;
        }
    }
}

pub struct RetryPolicy {
    max_retries: u32,
    initial_delay: Duration,
    backoff_factor: f64,
}

impl Default for RetryPolicy {
    fn default() -> Self {
        RetryPolicy {
            max_retries: 5,
            initial_delay: Duration::from_secs(1),
            backoff_factor: 2.0,
        }
    }
}

impl RetryPolicy {
    pub fn calculate_retry_interval(&self, retries: u32) -> Duration {
        let delay = self.initial_delay * (self.backoff_factor.powi(retries as i32 - 1));
        delay.min(Duration::from_secs(60))
    }
}

pub struct ConnectionPool {
    pool_size: usize,
    idle_timeout: Duration,
}

impl Default for ConnectionPool {
    fn default() -> Self {
        ConnectionPool {
            pool_size: 10,
            idle_timeout: Duration::from_secs(30),
        }
    }
}

