impl ErrorHandler {
    fn new() -> Self {
        Self {}
    }

    fn log_error(&self, error: &dyn std::error::Error) {
        eprintln!("Error: {}", error);
    }

    async fn retry_task<T>(&self, task: impl Future<Output = Result<T, Box<dyn std::error::Error>>>, max_retries: u32) -> Result<T, Box<dyn std::error::Error>> {
        let mut retries = 0;
        loop {
            match task.await {
                Ok(result) => return Ok(result),
                Err(_) if retries >= max_retries => return Err(task.await.err().unwrap()),
                Err(_) => {
                    retries += 1;
                    tokio::time::sleep(std::time::Duration::from_secs(1)).await;
                }
            }
        }
    }
}

struct TaskQueue {
    queue: Mutex<Vec<task::JoinHandle<Result<(), Box<dyn std::error::Error>>>>>,
}

impl TaskQueue {
    fn new() -> Self {
        Self {
            queue: Mutex::new(Vec::new()),
        }
    }

    async fn enqueue_task<F>(&self, task: F)
    where
        F: Future<Output = Result<(), Box<dyn std::error::Error>>> + Send + 'static,
    {
        self.queue.lock().push(task.boxed());
    }

    async fn run_all_tasks(&self) -> Result<(), Box<dyn std::error::Error>> {
        while let Some(handle) = self.queue.lock().pop() {
            handle.await?;
        }
        Ok(())
    }
}
