#include <stdio.h>
#include <stdlib.h>

// Define the state structure for FSA
typedef struct State {
    int id;
    struct State* next;
} State;

// Define the FSA structure
typedef struct FSA {
    State** states;
    int numStates;
} FSA;

// Callback function prototype
typedef void (*StateCallback)(State*);

// Function to create a new state
State* createState(int id) {
    State* newState = (State*)malloc(sizeof(State));
    if (newState == NULL) return NULL;
    newState->id = id;
    newState->next = NULL;
    return newState;
}

// Function to initialize the FSA
FSA* initFSA(int numStates) {
    FSA* fsa = (FSA*)malloc(sizeof(FSA));
    if (fsa == NULL) return NULL;
    fsa->numStates = numStates;
    fsa->states = (State**)calloc(numStates, sizeof(State*));
    if (fsa->states == NULL) {
        free(fsa);
        return NULL;
    }
    return fsa;
}

// Function to transition states
State* transitionStates(int* initialStates, int numInitialStates, FSA* fsa, int startStateId, int lastStateId, StateCallback callback) {
    if (initialStates == NULL || fsa == NULL || startStateId < 0 || lastStateId >= fsa->numStates) return NULL;

    State* currentState = fsa->states[startStateId];
    if (currentState == NULL) return NULL;

    for (int i = 1; i <= numInitialStates; ++i) {
        int nextStateId = initialStates[i - 1];
        if (nextStateId < 0 || nextStateId >= fsa->numStates) continue;

        State* nextState = fsa->states[nextStateId];
        if (nextState == NULL) continue;

        currentState->next = nextState;
        currentState = nextState;

        if (callback != NULL) {
            callback(nextState);
        }
    }

    return currentState;
}

// Example usage
void printState(State* state) {
    printf("State ID: %d\n", state->id);
}

int main() {
    int initialStates[] = {0, 1, 2};
    int numInitialStates = sizeof(initialStates) / sizeof(initialStates[0]);
    FSA* fsa = initFSA(3);
    if (fsa == NULL) return -1;

    // Initialize states in the FSA
    for (int i = 0; i < 3; ++i) {
        fsa->states[i] = createState(i);
    }

    State* finalState = transitionStates(initialStates, numInitialStates, fsa, 0, 2, printState);
    if (finalState != NULL) {
        printf("Final state ID: %d\n", finalState->id);
    } else {
        printf("Transition failed.\n");
    }

    // Clean up
    for (int i = 0; i < 3; ++i) {
        State* state = fsa->states[i];
        while (state != NULL) {
            State* next = state->next;
            free(state);
            state = next;
        }
    }
    free(fsa->states);
    free(fsa);

    return 0;
}
