#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <functional>

class DataProcessor {
public:
    void addTask(std::function<void()> task) {
        std::unique_lock<std::mutex> lock(mutex_);
        tasks_.push(task);
        lock.unlock();
        condition_.notify_one();
    }

private:
    std::queue<std::function<void()>> tasks_;
    std::mutex mutex_;
    std::condition_variable condition_;
};

class DataPipelineManager {
public:
    DataPipelineManager(size_t numThreads) : dataProcessor_(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers_.emplace_back([this]() {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(dataProcessor_.mutex_);
                        dataProcessor_.condition_.wait(lock, [this] { return !dataProcessor_.tasks_.empty(); });
                        task = std::move(dataProcessor_.tasks_.front());
                        dataProcessor_.tasks_.pop();
                    }
                    task();
                }
            });
        }
    }

    ~DataPipelineManager() {
        for (auto& worker : workers_) {
            worker.join();
        }
    }

private:
    DataProcessor dataProcessor_;
    std::vector<std::thread> workers_;
};

int main() {
    DataPipelineManager manager(10);
    manager.addTask([]() { std::cout << "Processing task 1" << std::endl; });
    manager.addTask([]() { std::cout << "Processing task 2" << std::endl; });
    return 0;
}
