// Define a simple video format enum
enum class VideoFormat { MP4, AVI, MOV };

// Interface for transcoding operations
class Transcoder {
public:
    virtual void transcode(const std::string& inputPath, const std::string& outputPath, VideoFormat outputFormat) = 0;
};

// Concrete implementation of Transcoder using FFmpeg
class FFmpegTranscoder : public Transcoder {
public:
    void transcode(const std::string& inputPath, const std::string& outputPath, VideoFormat outputFormat) override {
        // Placeholder for actual transcoding logic using FFmpeg
        std::cout << "Transcoding from " << inputPath << " to " << outputPath << " with format: " << static_cast<int>(outputFormat) << std::endl;
    }
};

// Transcoding library that manages multiple transcoder instances and threads
class VideoTranscodingLibrary {
public:
    void addTranscoder(std::unique_ptr<Transcoder> transcoder) {
        transcoders_.emplace_back(std::move(transcoder));
    }

    void startTranscoding(const std::string& inputPath, const std::string& outputPath, VideoFormat outputFormat) {
        std::lock_guard<std::mutex> lock(mutex_);
        jobs_.push({inputPath, outputPath, outputFormat});
        cv_.notify_one();
    }

    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !jobs_.empty(); });

            Job job = jobs_.front();
            jobs_.pop();

            lock.unlock();

            std::thread([this, job]() {
                for (const auto& transcoder : transcoders_) {
                    try {
                        transcoder->transcode(job.inputPath, job.outputPath, job.outputFormat);
                    } catch (...) {
                        // Handle errors or log them
                    }
                }

                std::lock_guard<std::mutex> lock(mutex_);
                completedJobs_.push_back(job);
                cv_.notify_one();
            }).detach();
        }
    }

private:
    struct Job {
        std::string inputPath;
        std::string outputPath;
        VideoFormat outputFormat;
    };

    std::vector<std::unique_ptr<Transcoder>> transcoders_;
    std::queue<Job> jobs_;
    std::vector<Job> completedJobs_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

int main() {
    FFmpegTranscoder ffmpegTranscoder;
    VideoTranscodingLibrary library;
    library.addTranscoder(std::make_unique<FFmpegTranscoder>());

    // Start transcoding jobs
    library.startTranscoding("input.mp4", "output.avi", VideoFormat::AVI);
    library.startTranscoding("input.mov", "output.mp4", VideoFormat::MP4);

    // Run the library's transcoder threads
    library.run();

    return 0;
}
