class MediaProcessor {
public:
    static MediaProcessor* getInstance() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (instance_ == nullptr) {
            instance_ = new MediaProcessor();
        }
        return instance_;
    }

    void processFile(const std::string& file, const std::string& format) {
        std::unique_lock<std::mutex> lock(queue_mutex_);
        work_queue_.push({file, format});
        condition_variable_.notify_one();
    }

    static EVP_CIPHER_CTX* initCipher(const char* password) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (ctx == nullptr) return nullptr;

        unsigned char key[32];
        unsigned char iv[16];
        SHA256((unsigned char*)password, strlen(password), key);

        if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return nullptr;
        }

        return ctx;
    }

    static void cleanupCipher(EVP_CIPHER_CTX* ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }

private:
    MediaProcessor() : running_(true) {
        for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
            worker_threads_.emplace_back(&MediaProcessor::workerThread, this);
        }
    }

    ~MediaProcessor() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex_);
            running_ = false;
        }
        condition_variable_.notify_all();
        for (auto& thread : worker_threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void workerThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(queue_mutex_);
            condition_variable_.wait(lock, [this] { return !work_queue_.empty() || !running_; });

            if (!running_ && work_queue_.empty()) {
                break;
            }

            auto task = work_queue_.front();
            work_queue_.pop();
            lock.unlock();

            // Process file and format conversion here
            process(task.file, task.format);
        }
    }

    void process(const std::string& file, const std::string& format) {
        // Implement the actual processing logic here
    }

private:
    static std::mutex mutex_;
    static MediaProcessor* instance_;

    bool running_;
    std::queue<std::pair<std::string, std::string>> work_queue_;
    std::vector<std::thread> worker_threads_;
    std::condition_variable condition_variable_;
};

