import asyncio
from aiohttp import ClientSession, ClientConnectorError
from datetime import datetime, timedelta

class EventProcessor:
    def __init__(self):
        self.events = {}

    async def process_event(self, event_id, data):
        if event_id not in self.events:
            self.events[event_id] = {'data': data, 'processed_at': datetime.now()}
            await asyncio.sleep(1)  # Simulate processing time
        else:
            print(f"Duplicate event {event_id} ignored.")

    async def consume_events(self, source):
        session = ClientSession()
        while True:
            try:
                async with session.get(source['url']) as response:
                    if response.status == 200:
                        data = await response.json()
                        for event in data['events']:
                            await self.process_event(event['id'], event['data'])
                    else:
                        print(f"Failed to fetch events from {source['name']}. Status code: {response.status}")
            except (ClientConnectorError, asyncio.TimeoutError):
                print(f"Connection error while fetching events from {source['name']}. Retrying...")
            await asyncio.sleep(source['retry_interval'])

async def main():
    event_processor = EventProcessor()

    sources = [
        {'name': 'RESTful API', 'url': 'https://api.example.com/events', 'retry_interval': 5},
        {'name': 'WebSocket', 'url': 'wss://ws.example.com/events', 'retry_interval': 10},
        {'name': 'MQTT', 'url': 'mqtt://mqtt.example.com/events', 'retry_interval': 20},
        {'name': 'gRPC', 'url': 'grpc://grpc.example.com/events', 'retry_interval': 30},
        {'name': 'HTTP/2', 'url': 'https://http2.example.com/events', 'retry_interval': 40}
    ]

    tasks = [event_processor.consume_events(source) for source in sources]
    await asyncio.gather(*tasks)

if __name__ == "__main__":
    asyncio.run(main())
