        static UePool instance;
        return instance;
    }

    void addUserEquipment(int ci) {
        std::lock_guard<std::mutex> lock(mutex);
        if (ueMap.find(ci) == ueMap.end()) {
            ueMap[ci] = std::make_shared<UserEquipment>(ci);
        }
    }

    void removeUserEquipment(int ci) {
        std::lock_guard<std::mutex> lock(mutex);
        if (ueMap.find(ci) != ueMap.end()) {
            ueMap.erase(ci);
        }
    }

    void updateBearer(int ci, int bearerId, int qos) {
        std::lock_guard<std::mutex> lock(mutex);
        if (ueMap.find(ci) != ueMap.end()) {
            ueMap[ci]->addBearer(bearerId, qos);
        }
    }

