    uePool[CI] = std::make_shared<UEContext>();
    uePool[CI]->CI = CI;
}

void LTENetworkLibrary::removeUE(int CI) {
    std::lock_guard<std::mutex> lock(ueMutex);
    uePool.erase(CI);
}

void LTENetworkLibrary::updateUE(int CI, int bearerID, const QoS& newQosParams) {
    std::lock_guard<std::mutex> lock(ueMutex);
