    async fn new(drone_ids: Vec<String>) -> Self {
        let (task_tx, task_rx) = mpsc::channel(100);
        tokio::spawn(Self::drone_task_handler(task_rx));
        DroneManager {
            drone_ids,
            drone_status: RwLock::new(HashMap::new()),
            task_queue: task_tx,
        }
    }

    async fn add_drone(&self, drone_id: String) {
        self.drone_ids.push(drone_id);
    }

    async fn remove_drone(&self, drone_id: &str) {
        if let Some(pos) = self.drone_ids.iter().position(|d| d == drone_id) {
            self.drone_ids.remove(pos);
        }
    }

    async fn start_mission_for_all(&self) {
        for drone_id in &self.drone_ids {
            if let Err(_) = self.task_queue.send(DroneCommand::StartMission).await {
                println!("Failed to send command to drone {}", drone_id);
            }
        }
    }

    async fn stop_mission_for_all(&self) {
        for drone_id in &self.drone_ids {
            if let Err(_) = self.task_queue.send(DroneCommand::StopMission).await {
                println!("Failed to send command to drone {}", drone_id);
            }
        }
    }

    async fn update_drone_status(&self, drone_id: String, status: DroneStatus) {
        self.drone_status.write().await.insert(drone_id, status);
    }

    async fn check_drone_health(&self) -> Vec<String> {
        let mut unhealthy_drones = vec![];
        for (drone_id, status) in self.drone_status.read().await.iter() {
            if status.health < 50 || status.battery_level < 20 {
                unhealthy_drones.push(drone_id.clone());
            }
        }
        unhealthy_drones
    }

    async fn drone_task_handler(mut task_rx: mpsc::Receiver<DroneCommand>) {
        while let Some(command) = task_rx.recv().await {
            match command {
                DroneCommand::StartMission => println!("Starting mission for all drones"),
                DroneCommand::StopMission => println!("Stopping mission for all drones"),
            }
        }
    }
}

#[tokio::main]
async fn main() {
    let drone_ids = vec![
        "drone-001".to_string(),
        "drone-002".to_string(),
        // Add more drone IDs as needed
    ];

    let manager = DroneManager::new(drone_ids).await;

    // Simulate adding a new drone dynamically
    manager.add_drone("drone-003".to_string()).await;

    // Start mission for all drones
    manager.start_mission_for_all().await;

    tokio::time::sleep(Duration::from_secs(1)).await;

    // Stop mission for all drones
    manager.stop_mission_for_all().await;

    let unhealthy_drones = manager.check_drone_health().await;
    println!("Unhealthy drones: {:?}", unhealthy_drones);
}
