    println!("Environment variable set: {}={}", var_name, var_value);
    Ok(())
}

fn rollback_env_var(var_name: &str) -> Result<(), env::VarError> {
    if let Some(previous_value) = env::var_os(var_name) {
        env::set_var(var_name, previous_value);
        println!("Environment variable rolled back to previous value: {}", var_name);
    } else {
        env::remove_var(var_name);
        println!("Environment variable removed: {}", var_name);
    }
    Ok(())
}

fn main() {
    const RETRY_LIMIT: u32 = 5;
    let mut retries = 0;

    while retries < RETRY_LIMIT {
        match fetch_config() {
            Ok((dir_name, log_path, escalation_url)) => {
                let dir_path = Path::new(&dir_name);
                create_directory(dir_path).unwrap();
                set_env_var("DATA_DIR", &dir_name).unwrap();
                // Additional operations with the fetched config
                break;
            },
            Err(ConfigError::NetworkIssue) | Err(ConfigError::Timeout) => {
                retries += 1;
                println!("Attempt {} failed, retrying...", retries);
                std::thread::sleep(Duration::from_secs(2));
            },
            Err(ConfigError::IncorrectData) => {
                // Handle incorrect or outdated config data
                break;
            }
        }
    }

    if retries == RETRY_LIMIT {
        eprintln!("Failed to fetch configuration after {} attempts", RETRY_LIMIT);
    } else {
        println!("Configuration fetched successfully");
        // Cleanup and rollback logic as needed
    }
}
