class UEContext {
public:
    UEContext(int CI) : cellIdentity(CI), bearers({}) {}

    void addRAB(const RAB& rab) {
        bearers.push_back(rab);
    }

    void removeRAB(int bearerID) {
        bearers.erase(std::remove_if(bearers.begin(), bearers.end(),
                                      [bearerID](const RAB& rab) { return rab.bearerID == bearerID; }),
                      bearers.end());
    }

    void updateRAB(int bearerID, const std::string& newQoS) {
        for (auto& rab : bearers) {
            if (rab.bearerID == bearerID) {
                rab.QoS = newQoS;
                return;
            }
        }
    }

    bool hasBearer(int bearerID) const {
        return std::any_of(bearers.begin(), bearers.end(),
                           [bearerID](const RAB& rab) { return rab.bearerID == bearerID; });
    }

private:
    int cellIdentity;
    std::vector<RAB> bearers;
};

class UEManager {
public:
    void addUE(int CI) {
        std::lock_guard<std::mutex> lock(mutex);
        if (ues.find(CI) == ues.end()) {
            ues[CI] = std::make_unique<UEContext>(CI);
            cv.notify_all();
        }
    }

    void removeUE(int CI) {
        std::lock_guard<std::mutex> lock(mutex);
        if (ues.find(CI) != ues.end()) {
            ues.erase(CI);
            cv.notify_all();
        }
    }

    bool hasUE(int CI) const {
        std::lock_guard<std::mutex> lock(mutex);
        return ues.find(CI) != ues.end();
    }

private:
    mutable std::mutex mutex;
    std::condition_variable cv;
    std::map<int, std::unique_ptr<UEContext>> ues;
};

