    cv_.notify_one();
}

void UeContextManager::removeUeContext(int cellIdentity) {
    std::unique_lock<std::mutex> lock(mutex_);
    auto it = ueContexts.find(cellIdentity);
    if (it == ueContexts.end()) {
        // Handle error: UE context not found
        return;
    }
    ueContexts.erase(it);
    cv_.notify_one();
}

void UeContextManager::updateUeContext(int cellIdentity, const Rab& rab) {
    std::unique_lock<std::mutex> lock(mutex_);
    auto it = ueContexts.find(cellIdentity);
    if (it == ueContexts.end()) {
        // Handle error: UE context not found
        return;
    }
    for (auto& existingRab : it->second.rabList) {
        if (existingRab.bearerId == rab.bearerId) {
            existingRab = rab;
            cv_.notify_one();
            return;
        }
    }
    // Handle error: RAB not found
}

UeContext UeContextManager::getUeContext(int cellIdentity) {
    std::unique_lock<std::mutex> lock(mutex_);
    auto it = ueContexts.find(cellIdentity);
    if (it == ueContexts.end()) {
        // Handle error: UE context not found
        return UeContext{};
    }
    return it->second;
}

// Example usage
int main() {
    UeContextManager manager;
    UeContext ueContext = {123, {{1, QoS{}, true}}};
    manager.addUeContext(ueContext);
    UeContext updatedUeContext = manager.getUeContext(123);
    std::cout << "UE Context: Cell ID - " << updatedUeContext.cellIdentity << ", RABs - " << updatedUeContext.rabList.size() << std::endl;
    return 0;
}
