} ConnectionPool;

void init_connection_pool(ConnectionPool *pool, int size) {
    pool->connections = malloc(size * sizeof(Connection));
    pool->num_connections = size;
    pthread_mutex_init(&pool->lock, NULL);
}

void destroy_connection_pool(ConnectionPool *pool) {
    free(pool->connections);
    pthread_mutex_destroy(&pool->lock);
}

int acquire_connection(ConnectionPool *pool) {
    int index = -1;
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->num_connections; i++) {
        if (!pool->connections[i].in_use) {
            pool->connections[i].in_use = 1;
            index = i;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return index;
}

void release_connection(ConnectionPool *pool, int index) {
    pthread_mutex_lock(&pool->lock);
    if (index >= 0 && index < pool->num_connections) {
        pool->connections[index].in_use = 0;
    }
    pthread_mutex_unlock(&pool->lock);
}

