void* async_io_thread(void *arg) {
    ConnectionPool *pool = (ConnectionPool*) arg;
    while (1) {
        int index = acquire_connection(pool);
        if (index != -1) {
            // Perform asynchronous I/O operation using the connection
            release_connection(pool, index);
        }
        usleep(100); // Sleep for a short duration before checking again
    }
}

