#ifndef CACHE_LIBRARY_H
#define CACHE_LIBRARY_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

typedef struct {
    char* key;
    void* data;
    size_t length;
    time_t last_updated;
} CacheEntry;

typedef struct {
    pthread_mutex_t lock;
    CacheEntry** entries;
    size_t capacity;
    size_t size;
} Cache;

// Initialize cache with a given capacity
Cache* init_cache(size_t capacity);

// Get data from cache or fetch from API if not present
void* get_data(Cache* cache, const char* key, CURL* curl_handle);

// Invalidate cache entry for a given key
void invalidate_cache_entry(Cache* cache, const char* key);

// Clean up and free resources allocated by the cache
void destroy_cache(Cache* cache);

#endif // CACHE_LIBRARY_H

// Define the C library source file: cache_library.c

#include "cache_library.h"

Cache* init_cache(size_t capacity) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    if (!cache) return NULL;

    cache->capacity = capacity;
    cache->size = 0;
    cache->entries = (CacheEntry**)calloc(capacity, sizeof(CacheEntry*));
    if (!cache->entries) {
        free(cache);
        return NULL;
    }

    pthread_mutex_init(&cache->lock, NULL);

    return cache;
}

void* get_data(Cache* cache, const char* key, CURL* curl_handle) {
    pthread_mutex_lock(&cache->lock);

    for (size_t i = 0; i < cache->capacity; ++i) {
        if (cache->entries[i] && strcmp(cache->entries[i]->key, key) == 0) {
            time_t current_time = time(NULL);
            if (current_time - cache->entries[i]->last_updated <= 60) { // Cache entry is valid for 1 minute
                pthread_mutex_unlock(&cache->lock);
                return cache->entries[i]->data;
            }
        }
    }

    // Fetch data from API and store in cache
    CURLcode res = curl_easy_setopt(curl_handle, CURLOPT_URL, "https://api.example.com/data");
    if (res != CURLE_OK) {
        pthread_mutex_unlock(&cache->lock);
        return NULL;
    }

    size_t data_size = 0;
    char* buffer = NULL;
    res = curl_easy_perform(curl_handle);
    if (res == CURLE_OK) {
        res = curl_easy_getinfo(curl_handle, CURLINFO_SIZE_DOWNLOAD_T, &data_size);
        if (res == CURLE_OK) {
            buffer = (char*)malloc(data_size + 1);
            if (!buffer) {
                pthread_mutex_unlock(&cache->lock);
                return NULL;
            }
            res = curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, (curl_write_callback)memcpy);
            res = curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, buffer);
            if (res == CURLE_OK) {
                res = curl_easy_perform(curl_handle);
                if (res == CURLE_OK) {
                    CacheEntry* new_entry = (CacheEntry*)malloc(sizeof(CacheEntry));
                    if (!new_entry) {
                        free(buffer);
                        pthread_mutex_unlock(&cache->lock);
                        return NULL;
                    }
                    new_entry->key = strdup(key);
                    new_entry->data = buffer;
                    new_entry->length = data_size;
                    new_entry->last_updated = time(NULL);

                    cache->entries[cache->size++] = new_entry;

                    if (cache->size == cache->capacity) {
                        // Resize the cache or handle overflow
                    }
                } else {
                    free(buffer);
                }
            }
        }
    }

    pthread_mutex_unlock(&cache->lock);
    return buffer;
}

void invalidate_cache_entry(Cache* cache, const char* key) {
    pthread_mutex_lock(&cache->lock);

    for (size_t i = 0; i < cache->capacity; ++i) {
        if (cache->entries[i] && strcmp(cache->entries[i]->key, key) == 0) {
            free(cache->entries[i]->key);
            free(cache->entries[i]->data);
            free(cache->entries[i]);
            cache->entries[i] = NULL;
            --cache->size;
            break;
        }
    }

    pthread_mutex_unlock(&cache->lock);
}

void destroy_cache(Cache* cache) {
    if (!cache) return;

    pthread_mutex_lock(&cache->lock);

    for (size_t i = 0; i < cache->capacity; ++i) {
        if (cache->entries[i]) {
            free(cache->entries[i]->key);
            free(cache->entries[i]->data);
            free(cache->entries[i]);
        }
    }

    pthread_mutex_unlock(&cache->lock);

    pthread_mutex_destroy(&cache->lock);
    free(cache->entries);
    free(cache);
}
