namespace SensorDataProcessing {

class DataStream {
public:
    DataStream(const std::string& source) : source_(source), stopped_(false) {}

    void start() {
        worker_ = std::thread(&DataStream::process, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stopped_ = true;
        }
        condition_.notify_all();
        if (worker_.joinable()) {
            worker_.join();
        }
    }

    void enqueue(const std::string& data) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(data);
        condition_.notify_one();
    }

private:
    void process() {
        while (!stopped_) {
            std::string data;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                condition_.wait(lock, [this] { return !queue_.empty() || stopped_; });
                if (stopped_ && queue_.empty()) break;
                data = queue_.front();
                queue_.pop();
            }

            try {
                processData(data);
            } catch (const std::exception& e) {
                std::cerr << "Error processing data: " << e.what() << std::endl;
            }
        }
    }

    void processData(const std::string& data) {
        // Implement data processing logic here
        // Example: Parse JSON, validate data, apply caching and compression strategies
    }

private:
    std::string source_;
    std::queue<std::string> queue_;
    std::mutex mutex_;
    std::condition_variable condition_;
    std::thread worker_;
    bool stopped_;
};

