// Interface for cryptographic algorithms
class ICryptoAlgorithm {
public:
    virtual ~ICryptoAlgorithm() {}
    virtual void encrypt(const std::string& data, std::string& result) = 0;
    virtual void decrypt(const std::string& data, std::string& result) = 0;
};

// Example of a concrete cryptographic algorithm
class AES : public ICryptoAlgorithm {
public:
    void encrypt(const std::string& data, std::string& result) override {
        // Implementation of AES encryption
    }

    void decrypt(const std::string& data, std::string& result) override {
        // Implementation of AES decryption
    }
};

// Plugin system for loading algorithms dynamically
class CryptoPluginManager {
public:
    static CryptoPluginManager& getInstance() {
        static CryptoPluginManager instance;
        return instance;
    }

    void loadAlgorithm(const std::string& algorithmName, std::shared_ptr<ICryptoAlgorithm> algo) {
        algorithms[algorithmName] = algo;
    }

    std::shared_ptr<ICryptoAlgorithm> getAlgorithm(const std::string& algorithmName) {
        if (algorithms.find(algorithmName) != algorithms.end()) {
            return algorithms[algorithmName];
        }
        return nullptr;
    }

private:
    CryptoPluginManager() {}
    ~CryptoPluginManager() {}

    std::map<std::string, std::shared_ptr<ICryptoAlgorithm>> algorithms;
};

// Example usage of the CSP
int main() {
    CryptoPluginManager& manager = CryptoPluginManager::getInstance();

    // Load a concrete algorithm dynamically
    manager.loadAlgorithm("AES", std::make_shared<AES>());

    // Get the loaded algorithm and use it
    auto algo = manager.getAlgorithm("AES");
    if (algo) {
        std::string data = "sensitive information";
        std::string encryptedData;
        algo->encrypt(data, encryptedData);

        std::string decryptedData;
        algo->decrypt(encryptedData, decryptedData);

        std::cout << "Decrypted Data: " << decryptedData << std::endl;
    } else {
        std::cerr << "Algorithm not found" << std::endl;
    }

    return 0;
}
