#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct Record {
    long offset;
    int key;
} Record;

typedef struct RecordCollection {
    Record *records;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    sem_t sem;
} RecordCollection;

void init_record_collection(RecordCollection *collection) {
    collection->records = NULL;
    collection->size = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);
    sem_init(&collection->sem, 0, 1);
}

void destroy_record_collection(RecordCollection *collection) {
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    sem_destroy(&collection->sem);
}

void add_record(RecordCollection *collection, long offset, int key) {
    sem_wait(&collection->sem);
    pthread_mutex_lock(&collection->lock);

    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            sem_post(&collection->sem);
            return;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->size].offset = offset;
    collection->records[collection->size].key = key;
    collection->size++;

    pthread_mutex_unlock(&collection->lock);
    sem_post(&collection->sem);
}

void update_record(RecordCollection *collection, int key, long new_offset) {
    sem_wait(&collection->sem);
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; i++) {
        if (collection->records[i].key == key) {
            collection->records[i].offset = new_offset;
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    sem_post(&collection->sem);
}

Record *get_record(RecordCollection *collection, int key) {
    Record *record = NULL;

    sem_wait(&collection->sem);
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; i++) {
        if (collection->records[i].key == key) {
            record = &collection->records[i];
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    sem_post(&collection->sem);

    return record;
}
