#include <functional>

class EventProcessor {
public:
    void addConsumer(const std::function<void(const std::string&)>& consumer) {
        std::lock_guard<std::mutex> lock(mutex_);
        consumers_.push_back(consumer);
        cv_.notify_one();
    }

    void removeConsumer(const std::function<void(const std::string&)>& consumer) {
        std::lock_guard<std::mutex> lock(mutex_);
        consumers_.erase(std::remove(consumers_.begin(), consumers_.end(), consumer), consumers_.end());
    }

    void processEvent(const std::string& event) {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this]{ return !events_.empty() || stop_; });
            if (stop_) return;
            events_.push(event);
        }
        cv_.notify_one();
    }

private:
    void worker() {
        while (true) {
            std::string event;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                cv_.wait(lock, [this]{ return !events_.empty() || stop_; });
                if (stop_ && events_.empty()) break;
                event = events_.front();
                events_.pop();
            }
            for (const auto& consumer : consumers_) {
                try {
                    consumer(event);
                } catch (const std::exception& e) {
                    std::cerr << "Consumer error: " << e.what() << std::endl;
                }
            }
        }
    }

    std::vector<std::function<void(const std::string&)>> consumers_;
    std::queue<std::string> events_;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool stop_ = false;
};

int main() {
    EventProcessor processor;

    processor.addConsumer([](const std::string& event) {
        std::cout << "Processing event: " << event << std::endl;
    });

    processor.processEvent("Event1");
    processor.processEvent("Event2");

    return 0;
}
