#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* addElement(void* arg) {
    int *nfaipdu = (int*)arg;
    pthread_mutex_lock(&mutex);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Failed to allocate memory");
        return NULL;
    }
    memcpy(&newNode->data, nfaipdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* removeElement(void* arg) {
    int rnti = *(int*)arg;
    pthread_mutex_lock(&mutex);
    Node* current = head;
    Node* previous = NULL;
    while (current != NULL && current->data.RNTI != rnti) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        printf("Element not found\n");
    } else {
        if (previous == NULL) {
            head = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* getElement(void* arg) {
    int rnti = *(int*)arg;
    pthread_mutex_lock(&mutex);
    Node* current = head;
    while (current != NULL && current->data.RNTI != rnti) {
        current = current->next;
    }
    if (current == NULL) {
        printf("Element not found\n");
    } else {
        printf("Found element: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n",
               current->data.RX_UE_INFORMATION_TAG, current->data.RNTI, current->data.CRC_INDICATION_REL8_TAG);
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main() {
    int N;
    printf("Enter the number of elements: ");
    scanf("%d", &N);

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T nfaipdu;
        printf("Enter RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG for element %d: ", i);
        scanf("%d %d %d", &nfaipdu.RX_UE_INFORMATION_TAG, &nfaipdu.RNTI, &nfaipdu.CRC_INDICATION_REL8_TAG);

        pthread_t thread;
        if (pthread_create(&thread, NULL, addElement, &nfaipdu) != 0) {
            perror("Failed to create thread");
        }
        pthread_join(thread, NULL);
    }

    int command, rnti;
    while (1) {
        printf("\nEnter command (1: Add, 2: Remove, 3: Retrieve, 4: Exit): ");
        scanf("%d", &command);

        switch (command) {
            case 1:
                NFAPI_CRC_INDICATION_PDU_T nfaipdu;
                printf("Enter RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG for new element: ");
                scanf("%d %d %d", &nfaipdu.RX_UE_INFORMATION_TAG, &nfaipdu.RNTI, &nfaipdu.CRC_INDICATION_REL8_TAG);

                pthread_t addThread;
                if (pthread_create(&addThread, NULL, addElement, &nfaipdu) != 0) {
                    perror("Failed to create thread");
                }
                pthread_join(addThread, NULL);
                break;

            case 2:
                printf("Enter RNTI of element to remove: ");
                scanf("%d", &rnti);

                pthread_t removeThread;
                if (pthread_create(&removeThread, NULL, removeElement, &rnti) != 0) {
                    perror("Failed to create thread");
                }
                pthread_join(removeThread, NULL);
                break;

            case 3:
                printf("Enter RNTI of element to retrieve: ");
                scanf("%d", &rnti);

                pthread_t getThread;
                if (pthread_create(&getThread, NULL, getElement, &rnti) != 0) {
                    perror("Failed to create thread");
                }
                pthread_join(getThread, NULL);
                break;

            case 4:
                exit(0);

            default:
                printf("Invalid command\n");
        }
    }

    return 0;
}
