typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define your structure members here
} NFAPI_CRC_INDICATION_PDU_T;

struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
};

struct LinkedList {
    struct Node* head;
    pthread_mutex_t lock;
};

void initializeLinkedList(struct LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void insertElement(struct LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        struct Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

void removeElement(struct LinkedList* list, int rnti) {
    pthread_mutex_lock(&list->lock);
    struct Node* current = list->head;
    struct Node* previous = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* getElement(struct LinkedList* list, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* result = NULL;
    pthread_mutex_lock(&list->lock);
    struct Node* current = list->head;

    while (current != NULL && current->data.RNTI != rnti) {
        current = current->next;
    }

    if (current != NULL) {
        result = &current->data;
    }

    pthread_mutex_unlock(&list->lock);
    return result;
}

void freeLinkedList(struct LinkedList* list) {
    struct Node* current = list->head;
    while (current != NULL) {
        struct Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_destroy(&list->lock);
}

int main() {
    // Example usage
    struct LinkedList list;
    initializeLinkedList(&list);

    NFAPI_CRC_INDICATION_PDU_T pdu;
    // Initialize pdu fields...

    insertElement(&list, pdu);

    NFAPI_CRC_INDICATION_PDU_T* retrievedPdu = getElement(&list, pdu.RNTI);
    if (retrievedPdu != NULL) {
        // Process retrieved PDU
    }

    removeElement(&list, pdu.RNTI);

    freeLinkedList(&list);
    return 0;
}
