using Polly;
using Polly.CircuitBreaker;
using Polly.Retry;

public class XmlProcessingService
{
    private readonly HttpClient _httpClient;
    private readonly AsyncCircuitBreakerPolicy _breakerPolicy;
    private readonly AsyncRetryPolicy _retryPolicy;

    public XmlProcessingService(HttpClient httpClient)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));

        var breakerSettings = new CircuitBreakerPolicyOptions
        {
            FailureThresholdPercentage = 50,
            BreakDuration = TimeSpan.FromSeconds(30),
            MinimumThroughput = 10,
            ThroughputSuccessRate = 95
        };

        _breakerPolicy = Policy.BreakerAsync(breakerSettings);

        var retrySettings = new RetryPolicyOptions
        {
            WaitAndRetryAsync = new[]
            {
                TimeSpan.FromSeconds(2),
                TimeSpan.FromSeconds(4),
                TimeSpan.FromSeconds(8)
            }
        };

        _retryPolicy = Policy.RetryAsync(retrySettings);
    }

    public async Task ProcessXmlDocumentAsync(string xmlContent, string apiEndpoint)
    {
        try
        {
            await _breakerPolicy.ExecuteAsync(async () =>
            {
                var response = await _httpClient.PostAsync(apiEndpoint, new StringContent(xmlContent));
                response.EnsureSuccessStatusCode();
            });
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing XML document: {ex.Message}");
        }
    }
}

