#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define ProductInventory structure
typedef struct {
    int product_id;
    int stock_quantity;
    time_t last_updated;
    // Add more fields as needed
} ProductInventory;

// Define OrderHistory structure
typedef struct {
    int order_id;
    int customer_id;
    time_t order_date;
    double total_amount;
    char delivery_status[20];
    // Add more fields as needed
} OrderHistory;

// Define ProductInventoryNode structure for the tree
typedef struct ProductInventoryNode {
    ProductInventory data;
    struct ProductInventoryNode* left;
    struct ProductInventoryNode* right;
} ProductInventoryNode;

// Function to create a new ProductInventoryNode
ProductInventoryNode* create_product_inventory_node(ProductInventory data) {
    ProductInventoryNode* node = (ProductInventoryNode*)malloc(sizeof(ProductInventoryNode));
    if (!node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    node->data = data;
    node->left = NULL;
    node->right = NULL;
    return node;
}

// Function to insert a new ProductInventory into the tree
void insert_product_inventory(ProductInventoryNode** root, ProductInventory data) {
    if (*root == NULL) {
        *root = create_product_inventory_node(data);
    } else {
        if (data.product_id < (*root)->data.product_id) {
            insert_product_inventory(&(*root)->left, data);
        } else {
            insert_product_inventory(&(*root)->right, data);
        }
    }
}

// Function to serialize the tree into XML format
void serialize_to_xml(ProductInventoryNode* root, FILE* file) {
    if (root == NULL) return;
    fprintf(file, "<product>\n");
    fprintf(file, "  <id>%d</id>\n", root->data.product_id);
    fprintf(file, "  <stock_quantity>%d</stock_quantity>\n", root->data.stock_quantity);
    fprintf(file, "  <last_updated>%ld</last_updated>\n", (long)root->data.last_updated);
    // Serialize OrderHistory entries
    serialize_to_xml(root->left, file);
    serialize_to_xml(root->right, file);
    fprintf(file, "</product>\n");
}

// Function to deserialize XML into ProductInventoryNode tree
ProductInventoryNode* deserialize_from_xml(FILE* file) {
    char buffer[256];
    ProductInventoryNode* root = NULL;

    while (fgets(buffer, sizeof(buffer), file)) {
        if (strstr(buffer, "<product>")) {
            ProductInventory data;
            fscanf(file, "  <id>%d</id>\n", &data.product_id);
            fscanf(file, "  <stock_quantity>%d</stock_quantity>\n", &data.stock_quantity);
            fscanf(file, "  <last_updated>%ld</last_updated>\n", (long*)&data.last_updated);
            root = create_product_inventory_node(data);
        } else if (strstr(buffer, "<product>")) {
            // Deserialize OrderHistory entries
        }
    }

    return root;
}

// Function to free the memory allocated for the tree
void free_tree(ProductInventoryNode* root) {
    if (root != NULL) {
        free_tree(root->left);
        free_tree(root->right);
        free(root);
    }
}

int main() {
    ProductInventory inventory = {1, 100, time(NULL)};
    OrderHistory order = {101, 1001, time(NULL), 50.99, "Delivered"};
    inventory.order_history = &order;

    ProductInventoryNode* root = NULL;
    insert_product_inventory(&root, inventory);

    FILE* file = fopen("inventory.xml", "w");
    serialize_to_xml(root, file);
    fclose(file);

    // Deserialize from XML
    FILE* read_file = fopen("inventory.xml", "r");
    ProductInventoryNode* deserialized_root = deserialize_from_xml(read_file);
    fclose(read_file);

    free_tree(deserialized_root);

    return 0;
}
```

