    pthread_mutex_t lock;
} UserSession;

typedef struct LinkedListNode {
    UserSession* session;
    struct LinkedListNode* next;
} LinkedListNode;

typedef struct DynamicLinkedList {
    LinkedListNode* head;
    pthread_mutex_t list_lock;
} DynamicLinkedList;

// Function to create a new UserSession
UserSession* user_session_create(const char* uuid, time_t start_time) {
    UserSession* session = (UserSession*)malloc(sizeof(UserSession));
    if (!session) return NULL;
    strcpy(session->uuid, uuid);
    session->start_time = start_time;
    session->messages = NULL;
    session->message_count = 0;
    pthread_mutex_init(&session->lock, NULL);
    return session;
}

// Function to create a new Message
Message* message_create(const char* timestamp, const char* content, int status) {
    Message* msg = (Message*)malloc(sizeof(Message));
    if (!msg) return NULL;
    strcpy(msg->timestamp, timestamp);
    strcpy(msg->content, content);
    msg->status = status;
    return msg;
}

