    // Implementation to add message to the session
    pthread_mutex_unlock(&session->lock);
}

// Function to create a new LinkedListNode
LinkedListNode* linked_list_node_create(UserSession* session) {
    LinkedListNode* node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (!node) return NULL;
    node->session = session;
    node->next = NULL;
    return node;
}

// Function to add a UserSession to the DynamicLinkedList
void dynamic_linked_list_add(DynamicLinkedList* list, UserSession* session) {
    pthread_mutex_lock(&list->list_lock);
    LinkedListNode* new_node = linked_list_node_create(session);
    if (!new_node) {
        pthread_mutex_unlock(&list->list_lock);
        return;
    }
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->list_lock);
}

