#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <uuid/uuid.h>

typedef struct Message {
    char content[256];
    time_t timestamp;
    int delivery_status;
} Message;

typedef struct UserSession {
    uuid_t uuid;
    time_t start_time;
    Message *messages;
    size_t message_count;
} UserSession;

typedef struct SessionManager {
    pthread_mutex_t lock;
    UserSession **sessions;
    size_t session_count;
} SessionManager;

// Initialize a new session manager
SessionManager* sm_init() {
    SessionManager *sm = (SessionManager*)malloc(sizeof(SessionManager));
    if (sm == NULL) return NULL;
    pthread_mutex_init(&sm->lock, NULL);
    sm->sessions = NULL;
    sm->session_count = 0;
    return sm;
}

// Add a new user session
int sm_add_session(SessionManager *sm, uuid_t uuid, time_t start_time) {
    pthread_mutex_lock(&sm->lock);
    UserSession *new_session = (UserSession*)malloc(sizeof(UserSession));
    if (new_session == NULL) {
        pthread_mutex_unlock(&sm->lock);
        return -1;
    }
    memcpy(new_session->uuid, uuid, sizeof(uuid_t));
    new_session->start_time = start_time;
    new_session->messages = NULL;
    new_session->message_count = 0;

    UserSession **new_sessions = (UserSession**)realloc(sm->sessions, (sm->session_count + 1) * sizeof(UserSession*));
    if (new_sessions == NULL) {
        free(new_session);
        pthread_mutex_unlock(&sm->lock);
        return -1;
    }
    sm->sessions = new_sessions;
    sm->sessions[sm->session_count++] = new_session;

    pthread_mutex_unlock(&sm->lock);
    return 0;
}

// Add a message to an existing session
int sm_add_message(SessionManager *sm, uuid_t uuid, const char *content) {
    pthread_mutex_lock(&sm->lock);
    for (size_t i = 0; i < sm->session_count; i++) {
        if (memcmp(sm->sessions[i]->uuid, uuid, sizeof(uuid_t)) == 0) {
            Message new_message;
            time_t current_time = time(NULL);
            memcpy(new_message.content, content, sizeof(content));
            new_message.timestamp = current_time;
            new_message.delivery_status = 0;

            Message **new_messages = (Message**)realloc(sm->sessions[i]->messages, (sm->sessions[i]->message_count + 1) * sizeof(Message*));
            if (new_messages == NULL) {
                pthread_mutex_unlock(&sm->lock);
                return -1;
            }
            sm->sessions[i]->messages = new_messages;
            sm->sessions[i]->messages[sm->sessions[i]->message_count++] = &new_message;
            break;
        }
    }
    pthread_mutex_unlock(&sm->lock);
    return 0;
}

// Free the session manager and all associated sessions
void sm_free(SessionManager *sm) {
    if (sm == NULL) return;

    pthread_mutex_lock(&sm->lock);
    for (size_t i = 0; i < sm->session_count; i++) {
        free(sm->sessions[i]->messages);
        free(sm->sessions[i]);
    }
    free(sm->sessions);
    pthread_mutex_unlock(&sm->lock);

    pthread_mutex_destroy(&sm->lock);
    free(sm);
}
