#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int packet_id;
    size_t data_length;
    void* data_buffer;
} DataPacket;

typedef struct {
    pthread_mutex_t lock;
    DataPacket** packets;
    size_t count;
} PacketManager;

void initialize_packet_manager(PacketManager* manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->packets = NULL;
    manager->count = 0;
}

void free_packet(DataPacket* packet) {
    if (packet->data_buffer) {
        free(packet->data_buffer);
        packet->data_buffer = NULL;
    }
    free(packet);
}

void add_packet(PacketManager* manager, DataPacket* packet) {
    pthread_mutex_lock(&manager->lock);
    manager->packets = realloc(manager->packets, (manager->count + 1) * sizeof(DataPacket*));
    if (manager->packets == NULL) {
        perror("Failed to allocate memory for packets");
        free_packet(packet);
        return;
    }
    manager->packets[manager->count++] = packet;
    pthread_mutex_unlock(&manager->lock);
}

void remove_packet(PacketManager* manager, int packet_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i]->packet_id == packet_id) {
            free_packet(manager->packets[i]);
            memmove(&manager->packets[i], &manager->packets[i + 1], (manager->count - i - 1) * sizeof(DataPacket*));
            manager->count--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void serialize_packet(const DataPacket* packet, char** buffer, size_t* length) {
    *length = sizeof(int) + sizeof(size_t) + packet->data_length;
    *buffer = (char*)malloc(*length);
    if (*buffer == NULL) {
        perror("Failed to allocate memory for serialized data");
        return;
    }
    memcpy(*buffer, &packet->packet_id, sizeof(int));
    memcpy(*buffer + sizeof(int), &packet->data_length, sizeof(size_t));
    memcpy(*buffer + sizeof(int) + sizeof(size_t), packet->data_buffer, packet->data_length);
}

int deserialize_packet(const char* buffer, size_t length, DataPacket** packet) {
    if (length < sizeof(int) + sizeof(size_t)) {
        fprintf(stderr, "Invalid serialized data\n");
        return -1;
    }
    int packet_id;
    size_t data_length;
    memcpy(&packet_id, buffer, sizeof(int));
    memcpy(&data_length, buffer + sizeof(int), sizeof(size_t));
    if (length < sizeof(int) + sizeof(size_t) + data_length) {
        fprintf(stderr, "Invalid serialized data\n");
        return -1;
    }
    *packet = (DataPacket*)malloc(sizeof(DataPacket));
    if (*packet == NULL) {
        perror("Failed to allocate memory for packet");
        return -1;
    }
    (*packet)->packet_id = packet_id;
    (*packet)->data_length = data_length;
    (*packet)->data_buffer = malloc(data_length);
    if ((*packet)->data_buffer == NULL) {
        perror("Failed to allocate memory for data buffer");
        free(*packet);
        return -1;
    }
    memcpy((*packet)->data_buffer, buffer + sizeof(int) + sizeof(size_t), data_length);
    return 0;
}

void* packet_processing_thread(void* arg) {
    PacketManager* manager = (PacketManager*)arg;
    while (1) {
        pthread_mutex_lock(&manager->lock);
        if (manager->count > 0) {
            DataPacket* packet = manager->packets[0];
            memmove(manager->packets, &manager->packets[1], (--manager->count) * sizeof(DataPacket*));
            pthread_mutex_unlock(&manager->lock);
            // Process the packet here
            free_packet(packet);
        } else {
            pthread_mutex_unlock(&manager->lock);
            sleep(1); // Sleep for a while if no packets are available
        }
    }
    return NULL;
}
