#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct DataPacket {
    int packet_id;
    size_t data_length;
    char* buffer;
} DataPacket;

DataPacket* create_packet(int id, const void* data, size_t length) {
    DataPacket* packet = malloc(sizeof(DataPacket));
    if (packet == NULL) return NULL;

    packet->packet_id = id;
    packet->data_length = length;
    packet->buffer = malloc(length);
    if (packet->buffer == NULL) {
        free(packet);
        return NULL;
    }

    memcpy(packet->buffer, data, length);
    return packet;
}

void free_packet(DataPacket* packet) {
    if (packet != NULL) {
        free(packet->buffer);
        free(packet);
    }
}

size_t serialize_packet(const DataPacket* packet, char** output) {
    size_t total_size = sizeof(int) + sizeof(size_t) + packet->data_length;
    *output = malloc(total_size);
    if (*output == NULL) return 0;

    memcpy(*output, &packet->packet_id, sizeof(int));
    memcpy(*output + sizeof(int), &packet->data_length, sizeof(size_t));
    memcpy(*output + sizeof(int) + sizeof(size_t), packet->buffer, packet->data_length);

    return total_size;
}

DataPacket* deserialize_packet(const char* input, size_t length) {
    if (length < sizeof(int) + sizeof(size_t)) return NULL;

    DataPacket* packet = malloc(sizeof(DataPacket));
    if (packet == NULL) return NULL;

    memcpy(&packet->packet_id, input, sizeof(int));
    memcpy(&packet->data_length, input + sizeof(int), sizeof(size_t));

    packet->buffer = malloc(packet->data_length);
    if (packet->buffer == NULL) {
        free(packet);
        return NULL;
    }

    memcpy(packet->buffer, input + sizeof(int) + sizeof(size_t), packet->data_length);
    return packet;
}

int main() {
    const char* data = "Hello, World!";
    DataPacket* packet = create_packet(12345, data, strlen(data));
    if (packet == NULL) {
        fprintf(stderr, "Failed to create packet\n");
        return 1;
    }

    char* serialized;
    size_t serialized_size = serialize_packet(packet, &serialized);
    if (serialized == NULL) {
        free_packet(packet);
        fprintf(stderr, "Failed to serialize packet\n");
        return 1;
    }

    DataPacket* deserialized = deserialize_packet(serialized, serialized_size);
    if (deserialized == NULL) {
        free(serialized);
        free_packet(packet);
        fprintf(stderr, "Failed to deserialize packet\n");
        return 1;
    }

    printf("Deserialized packet data: %s\n", deserialized->buffer);

    free(serialized);
    free_packet(deserialized);
    free_packet(packet);

    return 0;
}
