class LogAggregator {
public:
    LogAggregator(int numThreads) : stop(false), threadCount(numThreads) {
        for (int i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] { worker(); });
        }
    }

    ~LogAggregator() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void addLog(const std::string& log) {
        std::unique_lock<std::mutex> lock(mutex);
        queue.push(log);
        condition.notify_one();
    }

private:
    void worker() {
        while (true) {
            std::string log;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this] { return stop || !queue.empty(); });
                if (stop && queue.empty()) {
                    return;
                }
                log = std::move(queue.front());
                queue.pop();
            }
            processLog(log);
        }
    }

    void processLog(const std::string& log) {
        // Implement JSON parsing and field extraction logic here
        Json::Value root;
        Json::CharReaderBuilder builder;
        std::unique_ptr<Json::CharReader> reader(builder.newCharReader());
        std::string errors;
        if (!reader->parse(log.c_str(), log.c_str() + log.size(), &root, &errors)) {
            std::cerr << "Failed to parse JSON: " << errors << std::endl;
            return;
        }

        // Process and store extracted fields into a database
        // Implement database connection and insert logic here
    }

    std::mutex mutex;
    std::condition_variable condition;
    std::queue<std::string> queue;
    std::vector<std::thread> workers;
    std::atomic<bool> stop;
    int threadCount;
};

int main() {
    LogAggregator aggregator(4);
    aggregator.addLog("{\"service\":\"auth\", \"event\":\"login\", \"user\":\"john_doe\"}");
    aggregator.addLog("{\"service\":\"payment\", \"event\":\"purchase\", \"amount\":100.00}");
    return 0;
}
