// Define an interface for device instances
class DeviceInstance {
public:
    virtual ~DeviceInstance() = default;
    virtual std::string getMetadata(const std::string& key) const = 0;
    virtual void updateMetadata(const std::string& key, const std::string& value) = 0;
    virtual void readData() = 0;
    virtual void writeData(const std::string& data) = 0;
    virtual void deleteData() = 0;
};

// Define a concrete implementation of DeviceInstance
class ConcreteDevice : public DeviceInstance {
public:
    std::map<std::string, std::string> metadata;

    std::string getMetadata(const std::string& key) const override {
        return metadata[key];
    }

    void updateMetadata(const std::string& key, const std::string& value) override {
        metadata[key] = value;
    }

    void readData() override {
        // Implementation for reading data
    }

    void writeData(const std::string& data) override {
        // Implementation for writing data
    }

    void deleteData() override {
        // Implementation for deleting data
    }
};

// Define a class to manage the dynamic pool of device instances
class DevicePool {
private:
    std::vector<std::unique_ptr<DeviceInstance>> devices;
    mutable std::mutex mutex;
    std::condition_variable cv;

public:
    void addDevice(std::unique_ptr<DeviceInstance> device) {
        std::lock_guard<std::mutex> lock(mutex);
        devices.push_back(std::move(device));
        cv.notify_all();
    }

    void removeDevice(const DeviceInstance* device) {
        std::lock_guard<std::mutex> lock(mutex);
        devices.erase(std::remove_if(devices.begin(), devices.end(),
                                      [device](const std::unique_ptr<DeviceInstance>& d) { return d.get() == device; }),
                      devices.end());
        cv.notify_all();
    }

    void updateDeviceMetadata(const DeviceInstance* device, const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto& d : devices) {
            if (d.get() == device) {
                d->updateMetadata(key, value);
                break;
            }
        }
    }

    void performOperation(DeviceInstance* device, const std::string& operation) {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto& d : devices) {
            if (d.get() == device) {
                if (operation == "read") {
                    d->readData();
                } else if (operation == "write") {
                    d->writeData("new data");
                } else if (operation == "delete") {
                    d->deleteData();
                }
                break;
            }
        }
    }

    void waitForDevice() {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return !devices.empty(); });
    }
};

int main() {
    DevicePool pool;

    // Add devices to the pool
    auto device1 = std::make_unique<ConcreteDevice>();
    auto device2 = std::make_unique<ConcreteDevice>();
    pool.addDevice(std::move(device1));
    pool.addDevice(std::move(device2));

    // Perform operations on devices
    DeviceInstance* device = pool.devices.front().get();
    pool.performOperation(device, "read");

    return 0;
}
