using System;
using System.Collections.Concurrent;
using System.IO;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Distributed;
using RabbitMQ.Client;

public class FileUploadService
{
    private readonly IDistributedCache _cache;
    private readonly IConnection _rabbitConnection;
    private readonly string _queueName;

    public FileUploadService(IDistributedCache cache, ConnectionFactory factory, string queueName)
    {
        _cache = cache;
        _rabbitConnection = factory.CreateConnection();
        _queueName = queueName;
    }

    public async Task UploadFileAsync(string filePath, long fileSize, string uploadId)
    {
        using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read))
        {
            await ProcessFileChunksAsync(fileStream, fileSize, uploadId);
        }
    }

    private async IAsyncEnumerable<byte[]> ReadFileChunksAsync(Stream fileStream, long fileSize)
    {
        const int chunkSize = 1024 * 1024; // 1 MB
        byte[] buffer = new byte[chunkSize];
        while (fileStream.Position < fileSize)
        {
            int bytesRead = await fileStream.ReadAsync(buffer, 0, chunkSize);
            if (bytesRead == 0) break;
            yield return buffer.Take(bytesRead).ToArray();
        }
    }

    private async Task ProcessFileChunksAsync(Stream fileStream, long fileSize, string uploadId)
    {
        var channel = _rabbitConnection.CreateModel();
        channel.QueueDeclare(queue: _queueName,
                             durable: true,
                             exclusive: false,
                             autoDelete: false,
                             arguments: null);

        string currentPositionKey = $"{uploadId}:position";
        long position = await GetPositionAsync(currentPositionKey, fileSize);

        foreach (var chunk in ReadFileChunksAsync(fileStream, fileSize))
        {
            if (position >= fileSize) break;

            var messageBody = new byte[chunk.Length + 8]; // 4 bytes for chunk index, 4 bytes for position
            BitConverter.GetBytes((int)(fileSize - position)).CopyTo(messageBody, 0); // Chunk size
            BitConverter.GetBytes((int)position).CopyTo(messageBody, 4); // Current position
            chunk.CopyTo(messageBody, 8);

            channel.BasicPublish(exchange: "",
                                 routingKey: _queueName,
                                 basicProperties: null,
                                 body: messageBody);

            await UpdatePositionAsync(currentPositionKey, position + chunk.Length);
        }

        channel.Close();
    }

    private async Task<long> GetPositionAsync(string key, long fileSize)
    {
        var currentPosition = await _cache.GetStringAsync(key);
        return currentPosition == null ? 0 : (long)Convert.ToInt64(currentPosition);
    }

    private async Task UpdatePositionAsync(string key, long position)
    {
        await _cache.SetStringAsync(key, position.ToString());
    }
}
```

This code block provides a basic implementation of the file upload and resumption system. It uses RabbitMQ for message broker communication, an in-memory distributed cache for storing the current upload position, and handles file chunks efficiently to manage memory usage. The system is designed to be scalable and resilient to downtime and external network issues by leveraging asynchronous processing and fault-tolerant caching mechanisms.']

