class InventoryManager {
public:
    void updateStock(const std::string& itemId, int quantity) {
        std::lock_guard<std::mutex> lock(mutex_);
        stock_[itemId] += quantity;
        condition_.notify_all();
    }

    bool fulfillOrder(const std::string& itemId, int quantity) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (condition_.wait_for(lock, std::chrono::seconds(1), [this, itemId, quantity]{ 
            return stock_[itemId] >= quantity; })) {
            stock_[itemId] -= quantity;
            return true;
        }
        return false;
    }

private:
    std::mutex mutex_;
    std::condition_variable condition_;
    std::unordered_map<std::string, int> stock_;
};

int main() {
    InventoryManager manager;

    // Example usage
    manager.updateStock("12345", 10);

    if (manager.fulfillOrder("12345", 5)) {
        std::cout << "Order fulfilled successfully." << std::endl;
    } else {
        std::cout << "Failed to fulfill order." << std::endl;
    }

