import hashlib
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from urllib.parse import urlparse

def calculate_md5(file_path):
    hash_md5 = hashlib.md5()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def fetch_file_from_url(url):
    response = requests.get(url, stream=True)
    if response.status_code == 200:
        return response.iter_content(chunk_size=4096)
    else:
        raise Exception(f"Failed to fetch file from {url}")

def fetch_and_compute_file_md5(file_path_or_url):
    try:
        if urlparse(file_path_or_url).scheme in ('http', 'https'):
            with ThreadPoolExecutor(max_workers=1) as executor:
                future = executor.submit(fetch_file_from_url, file_path_or_url)
                content_generator = future.result()
        else:
            content_generator = calculate_md5(file_path_or_url)

        hash_md5 = hashlib.md5()
        for chunk in content_generator:
            hash_md5.update(chunk)
        return hash_md5.hexdigest()
    except Exception as e:
        print(f"Error fetching or computing MD5: {e}")
        raise
