        self.storage = storage
        self.message_queue = message_queue

    def process_files(self, directory):
        for root, _, files in os.walk(directory):
            for file in files:
                file_path = os.path.join(root, file)
                with open(file_path, 'rb') as f:
                    md5_hash = hashlib.md5(f.read()).hexdigest()
                self.message_queue.put((file_path, md5_hash))

class ExternalStorage:
    def __init__(self, connection_string):
        self.connection_string = connection_string

    def store(self, key, value):
        # Implementation to store data in external storage
        pass

class MessageQueue:
    def __init__(self, broker_url):
        self.broker_url = broker_url
        self.connection = pika.BlockingConnection(pika.URLParameters(broker_url))
        self.channel = self.connection.channel()
        self.channel.queue_declare(queue='file_hashes')

    def put(self, message):
        self.channel.basic_publish(exchange='',
                                  routing_key='file_hashes',
                                  body=str(message))

    def consume(self, callback):
        self.channel.basic_consume(queue='file_hashes', on_message_callback=callback)
        self.channel.start_consuming()

def file_hash_processor(storage_url, mq_broker_url, directory):
    storage = ExternalStorage(storage_url)
    message_queue = MessageQueue(mq_broker_url)
    processor = FileProcessor(storage, message_queue)
    processor.process_files(directory)

