class DevicePool {
public:
    void addDevice(const Device::Metadata& metadata) {
        std::lock_guard<std::mutex> lock(mutex);
        devices[metadata.key] = std::make_unique<Device>(metadata);
        cv.notify_all();
    }

    void removeDevice(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex);
        devices.erase(key);
        cv.notify_all();
    }

    void updateDevice(const std::string& key, const Device::Metadata& newMetadata) {
        std::lock_guard<std::mutex> lock(mutex);
        if (devices.find(key) != devices.end()) {
            devices[key]->updateMetadata(newMetadata);
        }
        cv.notify_all();
    }

    Device* getDevice(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this, &key] { return devices.find(key) != devices.end(); });
        return devices[key].get();
    }

private:
    std::unordered_map<std::string, std::unique_ptr<Device>> devices;
    mutable std::mutex mutex;
    std::condition_variable cv;
};

