import hashlib
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
import logging

# Initialize logger
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def fetch_and_compute_file_md5(file_path):
    if file_path.startswith('http://') or file_path.startswith('https://'):
        return compute_md5_from_url(file_path)
    else:
        return compute_md5_from_local_file(file_path)

def compute_md5_from_local_file(file_path, chunk_size=8192):
    md5 = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b''):
            md5.update(chunk)
    return md5.hexdigest()

def compute_md5_from_url(url):
    response = requests.get(url, stream=True)
    md5 = hashlib.md5()
    for chunk in response.iter_content(chunk_size=8192):
        if chunk:
            md5.update(chunk)
    return md5.hexdigest()

# Example usage
if __name__ == "__main__":
    file_path_local = 'path/to/local/file'
    url = 'https://example.com/largefile.zip'

    local_md5 = fetch_and_compute_file_md5(file_path_local)
    remote_md5 = fetch_and_compute_file_md5(url)

    logger.info(f"Local File MD5: {local_md5}")
    logger.info(f"Remote URL MD5: {remote_md5}")
```

