    private DataIngestionService ingestionService = new DataIngestionService(executorService);
    private DataBatchingAndCompressionService batchingAndCompressionService = new DataBatchingAndCompressionService();
    private InMemoryProcessingService inMemoryProcessingService = new InMemoryProcessingService(batchingAndCompressionService);
    private StorageService storageService = new StorageService(inMemoryProcessingService);
