import redis
from sqlalchemy import create_engine, Column, Integer, String, LargeBinary
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker
import boto3
from botocore.exceptions import NoCredentialsError, PartialCredentialsError
from retrying import retry

Base = declarative_base()

class FileMetadata(Base):
    __tablename__ = 'file_metadata'
    id = Column(Integer, primary_key=True)
    file_name = Column(String, unique=True)
    md5_hash = Column(LargeBinary)

def compute_md5(file_path):
    hash_md5 = hashlib.md5()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

@retry(stop_max_attempt_number=3, wait_fixed=2000)
def upload_to_s3(file_name, md5_hash):
    s3 = boto3.client('s3')
    try:
        s3.put_object(Bucket='your-bucket-name', Key=file_name, Body='')
        return True
    except (NoCredentialsError, PartialCredentialsError) as e:
        print(f"Failed to upload {file_name} due to credentials error: {e}")
        return False

def store_md5_in_db(file_name, md5_hash):
    engine = create_engine('sqlite:///your-database.db')
    Session = sessionmaker(bind=engine)
    session = Session()
    try:
        metadata = FileMetadata(file_name=file_name, md5_hash=md5_hash)
        session.add(metadata)
        session.commit()
    except Exception as e:
        print(f"Failed to store {file_name} in database: {e}")
        session.rollback()
    finally:
        session.close()

def process_file(file_path):
    file_name = file_path.split('/')[-1]
    md5_hash = compute_md5(file_path)
    if upload_to_s3(file_name, md5_hash):
        store_md5_in_db(file_name, md5_hash)

def main():
    files = ['path/to/large/file1', 'path/to/large/file2']  # List of file paths
    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = {executor.submit(process_file, file): file for file in files}
        for future in as_completed(futures):
            file_path = futures[future]
            try:
                future.result()
            except Exception as e:
                print(f"Error processing {file_path}: {e}")

if __name__ == "__main__":
    main()
