@app.route('/token', methods=['POST'])
@limiter.limit("10 per minute")
def get_token():
    grant_type = request.form['grant_type']
    oauth_client = oauth_clients[grant_type]

    if not oauth_client:
        return jsonify({'error': 'Invalid grant type'}), 400

    token_url = 'https://api.example.com/oauth/token'

    if grant_type == 'client_credentials':
        token_data = {
            'grant_type': grant_type,
            'client_id': clients['client_id'],
            'client_secret': clients['client_secret']
        }
    else:
        return jsonify({'error': 'Unsupported grant type'}), 400

    response = requests.post(token_url, data=token_data)

    if response.status_code == 200:
        access_token = response.json().get('access_token')
        token_type = response.json().get('token_type')
        expires_in = response.json().get('expires_in')

        # Cache the token
        redis_client.setex(f'token:{access_token}', expires_in, '1')

        return jsonify({'access_token': access_token, 'token_type': token_type, 'expires_in': expires_in}), 200
    else:
        return jsonify({'error': response.json().get('error') or 'Invalid credentials'}), response.status_code

# Implement a fallback strategy for primary APIs
@app.route('/api/data', methods=['GET'])
@limiter.limit("10 per minute")
def get_data():
    token = request.args.get('access_token')

    if not token:
        return jsonify({'error': 'Missing access token'}), 401

    # Check cache first
    cached_data = redis_client.get(f'data:{token}')

    if cached_data:
        return jsonify(cached_data.decode()), 200

    # If not in cache, try to fetch from primary API
    api_url = 'https://api.example.com/data'

    headers = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json'
    }

    response = requests.get(api_url, headers=headers)

    if response.status_code == 200:
        data = response.json()

        # Cache the data
        redis_client.setex(f'data:{token}', 3600, json.dumps(data))

        return jsonify(data), 200
    else:
        return jsonify({'error': 'Failed to fetch data'}), response.status_code

# Run the Flask application
if __name__ == '__main__':
    app.run(debug=True)
