def rate_limit(max_requests_per_minute):
    def decorator(func):
        last_request_time = [time.time()]
        request_count = [0]

        def wrapper(*args, **kwargs):
            current_time = time.time()
            if (current_time - last_request_time[0]) > 60:
                request_count[0] = 0
                last_request_time[0] = current_time

            if request_count[0] >= max_requests_per_minute:
                abort(429, description="Too Many Requests")

            request_count[0] += 1
            return func(*args, **kwargs)

        return wrapper

    return decorator

