import hashlib
import os
from concurrent.futures import ThreadPoolExecutor, as_completed

class FileHasher:
    def __init__(self, directories, storage_system, message_queue):
        self.directories = directories
        self.storage_system = storage_system
        self.message_queue = message_queue

    def hash_file(self, file_path):
        with open(file_path, 'rb') as file:
            data = file.read()
            return hashlib.md5(data).hexdigest()

    def process_directory(self, directory):
        for root, _, files in os.walk(directory):
            for file_name in files:
                file_path = os.path.join(root, file_name)
                future = self.message_queue.submit(self.hash_file, file_path)
                yield future

    def start_processing(self):
        with ThreadPoolExecutor(max_workers=10) as executor:
            futures = []
            for directory in self.directories:
                futures.extend(executor.submit(self.process_directory, directory))

            for future in as_completed(futures):
                try:
                    hashes = future.result()
                    for hash_result in hashes:
                        self.storage_system.store(hash_result)
                except Exception as e:
                    print(f"Error processing file: {e}")

# Example usage
