// Define UserSession structure
typedef struct {
    char uuid[37]; // UUID format is 36 characters + null terminator
    time_t start_time;
    struct Message *messages;
} UserSession;

// Define Message structure
typedef struct Message {
    time_t timestamp;
    char content[1024];
    int delivery_status;
    struct Message *next;
} Message;

// Define NFAPI_CRC_INDICATION_PDU_T structure
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create a new UserSession
UserSession* create_user_session(const char *uuid, time_t start_time) {
    UserSession *session = (UserSession*)malloc(sizeof(UserSession));
    if (session == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    strncpy(session->uuid, uuid, 37);
    session->start_time = start_time;
    session->messages = NULL;
    return session;
}

// Function to create a new Message
Message* create_message(time_t timestamp, const char *content, int delivery_status) {
    Message *msg = (Message*)malloc(sizeof(Message));
    if (msg == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    msg->timestamp = timestamp;
    strncpy(msg->content, content, 1024);
    msg->delivery_status = delivery_status;
    msg->next = NULL;
    return msg;
}

// Function to add a message to a UserSession
void add_message_to_session(UserSession *session, Message *msg) {
    if (session == NULL || msg == NULL) {
        fprintf(stderr, "Invalid session or message\n");
        return;
    }
    msg->next = session->messages;
    session->messages = msg;
}

// Function to create NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(unsigned int RX_UE_INFORMATION_TAG, unsigned short RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 256; // Randomly set CRCFLAG
    return pdu;
}

// Function to serialize UserSession into JSON format
