    return json_str;
}

// Function to deserialize JSON back into UserSession
UserSession* deserialize_session_from_json(const char *json) {
    // Implement JSON deserialization logic here
    UserSession *session = create_user_session("00000000-0000-0000-0000-000000000000", time(NULL));
    // Deserialize messages and CRC_INDICATION_PDU_T structures
    // ...
    return session;
}

// Example usage
int main() {
    UserSession *session = create_user_session("123e4567-e89b-12d3-a456-426614174000", time(NULL));
    Message *msg = create_message(time(NULL), "Hello, World!", 0);
    add_message_to_session(session, msg);

    NFAPI_CRC_INDICATION_PDU_T *pdu = create_crc_indication_pdu(1, 2);

