TENANTS = {
    'tenant1': {'api_url': 'https://api.tenant1.com', 'client_id': 'client-id-t1', 'client_secret': 'secret-t1'},
    'tenant2': {'api_url': 'https://api.tenant2.com', 'client_id': 'client-id-t2', 'client_secret': 'secret-t2'}
}

# Cache configuration
CACHE_TTL = 300  # seconds

# Load balancer and retry mechanism
class LoadBalancer:
    def __init__(self, targets):
        self.targets = targets
        self.index = 0

    def get_target(self):
        target = self.targets[self.index]
        self.index = (self.index + 1) % len(self.targets)
        return target

# Fallback strategy for external metadata services
def fetch_metadata(fallback_url, primary_url):
    try:
        response = requests.get(primary_url)
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception("Primary service is down")
    except:
        return requests.get(fallback_url).json()

# Secure file hashing component
def hash_large_file(file_path, encoding='utf-8'):
    try:
        with open(file_path, 'rb') as f:
            while chunk := f.read(1024 * 1024):
                md5_hash.update(chunk)
        return md5_hash.hexdigest()
    except Exception as e:
        raise e

# Dynamic load balancing and retry mechanism
def compute_md5_with_retry(file_path, encoding='utf-8', max_retries=3, backoff_factor=1.5):
    lb = LoadBalancer(list(TENANTS.values()))
    for _ in range(max_retries):
        try:
            return hash_large_file(file_path, encoding)
        except Exception as e:
            time.sleep(backoff_factor * 2 ** _)
    raise Exception("Failed to compute MD5 after multiple retries")

# Auditing mechanisms
def log_access(user_id, activity):
    # Log access to file or database
    pass

# Main application routes
@app.route('/login', methods=['POST'])
def login():
    tenant = request.json.get('tenant')
    username = request.json.get('username')
    password = request.json.get('password')

    if tenant not in TENANTS:
        return jsonify({'error': 'Invalid tenant'}), 403

    api_url = TENANTS[tenant]['api_url']
    client_id = TENANTS[tenant]['client_id']
    client_secret = TENANTS[tenant]['client_secret']

    response = requests.post(f"{api_url}/token", data={
        'grant_type': 'password',
        'username': username,
        'password': password,
        'client_id': client_id,
        'client_secret': client_secret
    })

    if response.status_code == 200:
        token_info = response.json()
        access_token = token_info['access_token']
        refresh_token = token_info['refresh_token']

        # Cache access token and refresh token
        cache.set(f"{tenant}_{username}_access_token", access_token, CACHE_TTL)
        cache.set(f"{tenant}_{username}_refresh_token", refresh_token, CACHE_TTL)

        return jsonify({'message': 'Login successful', 'token': access_token}), 200

    else:
        return jsonify({'error': 'Invalid credentials'}), 403

@app.route('/hash_file', methods=['POST'])
def hash_file():
    file_path = request.json.get('file_path')
    encoding = request.json.get('encoding', 'utf-8')

    try:
        md5_hash = compute_md5_with_retry(file_path, encoding)
        log_access(request.user_id, f"Computed MD5 for {file_path}")
        return jsonify({'md5_hash': md5_hash}), 200

    except Exception as e:
        return jsonify({'error': str(e)}), 500

# Entry point
if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0', port=80)
