import time
from typing import List, Dict, Any
import hashlib
import requests
from urllib.parse import urlparse

class FileUploader:
    def __init__(self):
        self.cached_hashes = {}

    def upload_file(self, file_data: bytes) -> str:
        md5_hash = hashlib.md5(file_data).hexdigest()
        if md5_hash in self.cached_hashes:
            return self.cached_hashes[md5_hash]

        # Simulate uploading to external source
        time.sleep(0.1)
        response = requests.post('https://api.example.com/upload', data=file_data, headers={'Authorization': 'Bearer token'})
        if response.status_code == 200:
            self.cached_hashes[md5_hash] = md5_hash
            return md5_hash
        else:
            raise Exception(f"Failed to upload file: {response.status_code}")

class MonitoringPlatform:
    def __init__(self, api_url: str, access_token: str):
        self.api_url = api_url
        self.access_token = access_token

    def report_md5(self, md5_hash: str) -> None:
        headers = {'Authorization': f'Bearer {self.access_token}'}
        requests.post(f'{self.api_url}/report', json={'md5': md5_hash}, headers=headers)

class FileProcessingService:
    def __init__(self, uploader: FileUploader, platforms: List[MonitoringPlatform]):
        self.uploader = uploader
        self.platforms = platforms

    def process_files(self, files: List[bytes]) -> None:
        for file in files:
            md5_hash = self.uploader.upload_file(file)
            for platform in self.platforms:
                platform.report_md5(md5_hash)

# Example usage
uploader = FileUploader()
platform1 = MonitoringPlatform('https://api.platform1.com', 'token1')
