#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU {
    int RNTI;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node_T;

typedef struct LinkedList {
    Node_T* head;
    Node_T* tail;
    size_t size;
    size_t max_size;
    FILE* log_file;
    pthread_mutex_t lock;
} LinkedList_T;

LinkedList_T* create_linked_list(size_t max_size, const char* log_path) {
    LinkedList_T* list = (LinkedList_T*)malloc(sizeof(LinkedList_T));
    if (!list) {
        perror("Failed to allocate memory for linked list");
        return NULL;
    }

    list->head = list->tail = NULL;
    list->size = 0;
    list->max_size = max_size;

    // Open log file
    list->log_file = fopen(log_path, "a");
    if (!list->log_file) {
        perror("Failed to open log file");
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void log_error(LinkedList_T* list, const char* message) {
    time_t now = time(NULL);
    fprintf(list->log_file, "%s: %s\n", ctime(&now), message);
    fflush(list->log_file);
}

int insert_node(LinkedList_T* list, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->max_size) {
        log_error(list, "Attempted to insert into a full linked list");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node_T* new_node = (Node_T*)malloc(sizeof(Node_T));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        log_error(list, "Memory allocation failed");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = new_data;
    new_node->next = NULL;

    if (list->size == 0) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void destroy_linked_list(LinkedList_T* list) {
    pthread_mutex_lock(&list->lock);

    Node_T* current = list->head;
    while (current) {
        Node_T* next = current->next;
        free(current);
        current = next;
    }

    fclose(list->log_file);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
