        }

        try
        {
            var response = await _httpClient.GetAsync(apiEndpoint);
            response.EnsureSuccessStatusCode();
            var weatherData = await response.Content.ReadAsAsync<WeatherData>();

            if (!weatherData.Parameters.Contains(parameter))
            {
                throw new ArgumentException("The requested parameter is not available from this API.");
            }

            return new WeatherForecast
            {
                Region = region,
                Parameter = parameter,
                Value = weatherData.Values[parameter]
            };
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Failed to retrieve weather data for region {Region} and parameter {Parameter}.", region, parameter);
            throw;
        }
    }

