    void deallocate(NFAPI_CRC_INDICATION_PDU_T* pdu);

private:
    struct ApiHandle {
        // Define API handle and related data here
    };

    std::mutex poolMutex;
    std::condition_variable notFull, notEmpty;
    std::queue<NFAPI_CRC_INDICATION_PDU_T*> freePool;
    std::vector<ApiHandle> apiHandles;
    size_t maxSize;
    std::atomic<bool> running;

    void workerThread(ApiHandle& handle);
    void monitorAPIHealth();
};

NFAPICRCIndicationPduPool::NFAPICRCIndicationPduPool(size_t size, const std::vector<std::string>& apiEndpoints)
    : freePool(), apiHandles(apiEndpoints.size()), maxSize(size), running(true) {
    for (auto& endpoint : apiEndpoints) {
        // Initialize API handle
        apiHandles.emplace_back(endpoint);
    }

    for (size_t i = 0; i < size; ++i) {
        freePool.push(new NFAPI_CRC_INDICATION_PDU_T());
    }

    for (auto& handle : apiHandles) {
        std::thread t(&NFAPICRCIndicationPduPool::workerThread, this, std::ref(handle));
        t.detach();
    }
}

NFAPICRCIndicationPduPool::~NFAPICRCIndicationPduPool() {
    running = false;
    notFull.notify_all();

    for (auto& handle : apiHandles) {
        if (handle.thread.joinable()) {
            handle.thread.join();
        }
    }

    while (!freePool.empty()) {
        delete freePool.front();
        freePool.pop();
    }
}

