    std::unique_lock<std::mutex> lock(poolMutex);
    notEmpty.wait(lock, [this]{ return !freePool.empty() || !running; });

    if (!running) {
        throw std::runtime_error("Pool is shutting down");
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = freePool.front();
    freePool.pop();
    notFull.notify_one();

    // Perform resource allocation and monitoring logic here
    return pdu;
}

void NFAPICRCIndicationPduPool::deallocate(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    std::unique_lock<std::mutex> lock(poolMutex);
    notFull.wait(lock, [this]{ return freePool.size() < maxSize; });

    freePool.push(pdu);
    notEmpty.notify_one();

    // Perform resource deallocation and monitoring logic here
}

