class ResourcePool {
public:
    ResourcePool(size_t size, std::vector<APIClient*>& clients)
        : pool_(size), clients_(clients), currentClientIndex_(0) {
        for (auto& client : clients_) {
            if (client->isHealthy()) {
                client->allocateResource(pool_[currentClientIndex_]);
                currentClientIndex_ = (currentClientIndex_ + 1) % clients_.size();
            }
        }
