    void releaseResource(NFAPICRCIndicationPDU& pdu) {
        std::lock_guard<std::mutex> lock(mutex_);
        pool_.push(pdu);
        cv_.notify_one();
    }

private:
    std::queue<NFAPICRCIndicationPDU> pool_;
    std::vector<APIClient*> clients_;
    APIClient* currentClient_ = nullptr;
    APIClient* fallbackClient_ = new FallbackAPIClient();
    std::mutex mutex_;
    std::condition_variable cv_;
    size_t currentClientIndex_;
};

