import hashlib
from cryptography.fernet import Fernet
from concurrent.futures import ThreadPoolExecutor, as_completed
from redis import Redis

class FileHashProcessor:
    def __init__(self, key_manager, cache_client, api_client):
        self.key_manager = key_manager
        self.cache_client = cache_client
        self.api_client = api_client

    def process_file_with_resilience(self, file_path, chunk_size=1024*1024*5):  # Default chunk size: 5MB
        if not os.path.exists(file_path):
            raise FileNotFoundError("File does not exist")

        file_size = os.path.getsize(file_path)
        md5_hash = hashlib.md5()
        fernet_key = self.key_manager.generate_encryption_key()

        with open(file_path, 'rb') as file:
            while True:
                data = file.read(chunk_size)
                if not data:
                    break

                encrypted_data = Fernet(fernet_key).encrypt(data)
                md5_hash.update(encrypted_data)

        return md5_hash.hexdigest()

