# Import necessary libraries
from flask import Flask, request, jsonify
import hashlib
import os
import threading
import time
from concurrent.futures import ThreadPoolExecutor

app = Flask(__name__)

# Define a dictionary to store file hashes
file_hashes = {}

# Define a lock for thread-safe operations on file_hashes
hash_lock = threading.Lock()

# Function to compute MD5 and SHA-256 hash of a file
def compute_hashes(file_path):
    md5_hash = hashlib.md5()
    sha256_hash = hashlib.sha256()

    with open(file_path, 'rb') as f:
        # Read the file in chunks of 10MB to handle large files efficiently
        while chunk := f.read(10 * 1024 * 1024):
            md5_hash.update(chunk)
            sha256_hash.update(chunk)

    return md5_hash.hexdigest(), sha256_hash.hexdigest()

# Route to compute and store file hashes
@app.route('/compute_hashes', methods=['POST'])
def post_file():
    data = request.json
    file_path = data.get('file_path')

    if not os.path.exists(file_path):
        return jsonify({'error': 'File does not exist'}), 400

    md5, sha256 = compute_hashes(file_path)

    with hash_lock:
        file_hashes[file_path] = {'md5': md5, 'sha256': sha256}

    return jsonify({'md5': md5, 'sha256': sha256}), 200

# Route to retrieve file hashes
@app.route('/get_hash', methods=['GET'])
def get_file():
    data = request.args.get('file_path')

    if data not in file_hashes:
        return jsonify({'error': 'File hash not found'}), 404

    return jsonify(file_hashes[data]), 200

# Function to monitor directories for file changes and compute hashes
def monitor_directories(directories):
    while True:
        for directory in directories:
            for root, _, files in os.walk(directory):
                for file in files:
                    file_path = os.path.join(root, file)

                    if file_path not in file_hashes:
                        md5, sha256 = compute_hashes(file_path)

                        with hash_lock:
                            file_hashes[file_path] = {'md5': md5, 'sha256': sha256}

        time.sleep(10)

# Start monitoring directories
directories_to_monitor = ['/path/to/monitor']
executor = ThreadPoolExecutor(max_workers=4)
executor.submit(monitor_directories, directories_to_monitor)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

This code snippet provides a basic implementation of an API gateway and file hashing system using Flask. It includes routes to compute and store file hashes and retrieve them, as well as a function to monitor directories for file changes and compute hashes dynamically. The use of a lock ensures thread-safe operations on the `file_hashes` dictionary."]

