#include <iostream>
#include <fstream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <future>
#include <algorithm>

// Define a class for file processing task
class FileProcessingTask {
public:
    virtual ~FileProcessingTask() = default;
    virtual void process(const std::string& filePath) = 0;
};

// Example implementation of a specific file processing task
class CSVProcessingTask : public FileProcessingTask {
public:
    void process(const std::string& filePath) override {
        // Implementation for processing CSV files with newline delimiters
        std::ifstream file(filePath);
        if (file.is_open()) {
            std::string line;
            while (std::getline(file, line)) {
                // Process each line as needed
                std::cout << "Processing line: " << line << std::endl;
            }
            file.close();
        } else {
            std::cerr << "Failed to open file: " << filePath << std::endl;
        }
    }
};

// Class for managing a pool of worker threads
class WorkerPool {
public:
    WorkerPool(size_t numThreads) : stop(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->queue_mutex);
                        this->condition.wait(lock, [this]{ return this->stop || !this->tasks.empty(); });
                        if (this->stop && this->tasks.empty()) {
                            return;
                        }
                        task = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    ~WorkerPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    template<class F, class... Args>
    auto enqueue(F&& f, Args&&... args) -> std::future<typename std::result_of<F(Args...)>::type> {
        using return_type = typename std::result_of<F(Args...)>::type;

        auto task = std::make_shared<std::packaged_task<return_type()>>(
            std::bind(std::forward<F>(f), std::forward<Args>(args)...)
        );

        std::future<return_type> res = task->get_future();
        {
            std::unique_lock<std::mutex> lock(queue_mutex);

            // don't allow enqueueing after stopping the pool
            if (stop)
                throw std::runtime_error("enqueue on stopped ThreadPool");

            tasks.emplace([task]() { (*task)(); });
        }
        condition.notify_one();
        return res;
    }

private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queue_mutex;
    std::condition_variable condition;
    bool stop;
};

// Example usage
int main() {
    WorkerPool pool(4);
    CSVProcessingTask csvTask;

    // Submit tasks to the worker pool
    for (int i = 0; i < 10; ++i) {
        std::string filePath = "file" + std::to_string(i) + ".csv";
        pool.enqueue(&FileProcessingTask::process, &csvTask, filePath);
    }

    return 0;
}
