#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LUTRA_PDUS 1024

typedef struct {
    uint16_t rnti;
    size_t block_size;
    uint8_t mcs;
} LUTRA_PDU;

typedef struct {
    LUTRA_PDU *pdus;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} LUTRA_List;

void lutra_list_init(LUTRA_List *list) {
    list->pdus = malloc(MAX_LUTRA_PDUS * sizeof(LUTRA_PDU));
    if (!list->pdus) {
        perror("Failed to allocate memory for LUTRA PDU list");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = MAX_LUTRA_PDUS;
    pthread_mutex_init(&list->lock, NULL);
}

void lutra_list_destroy(LUTRA_List *list) {
    free(list->pdus);
    pthread_mutex_destroy(&list->lock);
}

int lutra_list_add_pdu(LUTRA_List *list, LUTRA_PDU *pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        LUTRA_PDU *new_pdus = realloc(list->pdus, list->capacity * 2 * sizeof(LUTRA_PDU));
        if (!new_pdus) {
            perror("Failed to reallocate memory for LUTRA PDU list");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->pdus = new_pdus;
        list->capacity *= 2;
    }
    memcpy(&list->pdus[list->count], pdu, sizeof(LUTRA_PDU));
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int lutra_list_get_pdu_by_rnti(const LUTRA_List *list, uint16_t rnti, LUTRA_PDU **pdu) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; i++) {
        if (list->pdus[i].rnti == rnti) {
            *pdu = &list->pdus[i];
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1;
}

