app = FastAPI()

# Configuration for service discovery and circuit breaker
services = {
    "service1": "http://service1.example.com",
    "service2": "http://service2.example.com"
}

# Circuit breaker state
circuit_breaker_open = False
circuit_breaker_failure_count = 0

# Redis for caching
redis_client = Redis(host='localhost', port=6379, db=0)

class RequestData(BaseModel):
    data: dict

@app.post("/gateway")
async def gateway(request_data: RequestData):
    try:
        # Check if circuit breaker is open
        if circuit_breaker_open:
            raise HTTPException(status_code=503, detail="Service unavailable")

        # Dynamic service selection based on SLA and availability
        selected_service = select_service()

        # Caching layer
        cache_key = f"cache:{selected_service}"
        cached_response = await redis_client.get(cache_key)
        if cached_response:
            return {"response": cached_response.decode()}

        # Send request to selected service
        response = await send_request(selected_service, request_data.data)

        # Cache the response
        await redis_client.setex(cache_key, 3600, response)  # Cache for 1 hour

        return {"response": response}
    except Exception as e:
        handle_error(e)
        raise HTTPException(status_code=500, detail="Internal server error")

@retry(wait=wait_random_exponential(multiplier=2), stop=stop_after_attempt(3))
async def send_request(service_url: str, data: dict):
    async with aiohttp.ClientSession() as session:
        headers = {"Content-Type": "application/json"}
        response = await session.post(f"{service_url}/endpoint", json=data, headers=headers)
        if response.status != 200:
            raise HTTPException(status_code=response.status, detail=await response.text())
        return await response.text()

def select_service():
    # Implement logic to select service based on SLA and availability
    pass

def handle_error(e):
    global circuit_breaker_open, circuit_breaker_failure_count

    if isinstance(e, HTTPException) and e.status_code >= 500:
        circuit_breaker_failure_count += 1
        if circuit_breaker_failure_count >= 3:
            circuit_breaker_open = True
    else:
        circuit_breaker_failure_count = 0

# Example usage of the gateway endpoint
@app.get("/")
async def read_root():
    return {"message": "Welcome to the API Gateway"}
