class UserEquipmentContext {
public:
    UserEquipmentContext(int userId) : userId(userId), status("ACTIVE") {}

    void addBearer(const std::string& bearerId, int qosParams) {
        std::lock_guard<std::mutex> lock(mutex);
        bearers[bearerId] = {qosParams, "UP"};
    }

    void removeBearer(const std::string& bearerId) {
        std::lock_guard<std::mutex> lock(mutex);
        if (bearers.find(bearerId) != bearers.end()) {
            bearers.erase(bearerId);
        }
    }

    void updateBearerQoS(const std::string& bearerId, int newQosParams) {
        std::lock_guard<std::mutex> lock(mutex);
        if (bearers.find(bearerId) != bearers.end()) {
            bearers[bearerId].first = newQosParams;
        }
    }

    void updateStatus(const std::string& newState) {
        std::lock_guard<std::mutex> lock(mutex);
        status = newState;
    }

    void processRequests() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !requests.empty(); });
            auto request = requests.front();
            requests.pop();

            lock.unlock();
            handleRequest(request);

            // Simulate processing time
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }

private:
    int userId;
    std::string status;
    std::unordered_map<std::string, std::pair<int, std::string>> bearers;
    std::queue<std::function<void()>> requests;
    std::mutex mutex;
    std::condition_variable condition;

    void handleRequest(const std::function<void()>& request) {
        request();
    }
};

int main() {
    UserEquipmentContext ueContext(12345);
    ueContext.addBearer("RAB1", 5);

    // Simulate processing requests
    std::thread processor(&UserEquipmentContext::processRequests, &ueContext);
    processor.detach();

    // Simulate adding a new bearer
    ueContext.updateBearerQoS("RAB1", 10);
    ueContext.addBearer("RAB2", 7);

    // Simulate removing a bearer
    std::this_thread::sleep_for(std::chrono::milliseconds(50));
    ueContext.removeBearer("RAB1");

    return 0;
}
```

