    void processDocument(const Document& doc) {
        // Simulate document processing here
        std::cout << "Processing document: " << doc.getId() << std::endl;
        // Store the processed document in DMS
        dms->storeDocument(doc);
        // Deliver the document through CDN
        cdn->deliverContent(doc);
    }

    void startProcessing() {
        for (int i = 0; i < numThreads; ++i) {
            workers.emplace_back([this]() {
                while (true) {
                    Document doc;
                    {
                        std::unique_lock<std::mutex> lock(mutex);
                        condition.wait(lock, [this] { return !stop || !queue.empty(); });
                        if (stop && queue.empty()) break;
                        doc = queue.front();
                        queue.pop();
                    }
                    processDocument(doc);
                }
            });
        }
    }

    void stopProcessing() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void addDocument(const Document& doc) {
        {
            std::lock_guard<std::mutex> lock(mutex);
            queue.push(doc);
        }
        condition.notify_one();
    }

private:
    DMSAdapter* dms;
    CDNAdapter* cdn;
    bool stop;
    std::vector<std::thread> workers;
    std::queue<Document> queue;
    std::mutex mutex;
    std::condition_variable condition;
    size_t numThreads = 4; // Number of worker threads
};

// Example DMSAdapter implementation using a simple in-memory store
class SimpleDMS : public DMSAdapter {
public:
    void storeDocument(const Document& doc) override {
        documents[doc.getId()] = doc.getContent();
    }

    bool retrieveDocument(const std::string& id, Document& doc) override {
        auto it = documents.find(id);
        if (it != documents.end()) {
            doc = Document(it->first, it->second);
            return true;
        }
        return false;
    }

private:
    std::unordered_map<std::string, std::string> documents;
};

// Example CDNAdapter implementation using simple output
class SimpleCDN : public CDNAdapter {
public:
    void deliverContent(const Document& doc) override {
        std::cout << "Delivered content for document: " << doc.getId() << std::endl;
    }
};

int main() {
    // Create DMS and CDN adapters
    SimpleDMS dms;
    SimpleCDN cdn;

    // Create DocumentProcessor with the adapters
    DocumentProcessor processor(&dms, &cdn);

    // Start processing documents in separate threads
    processor.startProcessing();

    // Add some documents to process
    processor.addDocument(Document("1", "Sample document content"));
    processor.addDocument(Document("2", "Another document content"));

    // Stop processing after adding documents
    std::this_thread::sleep_for(std::chrono::seconds(5));
    processor.stopProcessing();

    return 0;
}
```

This code provides a basic structure for a modular, extendable C++ library to manage a dynamic document processing pipeline. It includes interfaces for document management systems (DMS) and content delivery networks (CDN), a `DocumentProcessor` class that manages the processing pipeline, and example implementations of DMS and CDN adapters using simple in-memory stores and output. The main function demonstrates how to use these components to start processing documents and stop them gracefully.']

