    std::mutex poolMutex;
    std::condition_variable poolCond;

public:
    void addUE(int CI) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (uePool.find(CI) == uePool.end()) {
            uePool[CI] = UserEquipment{CI, {}};
            poolCond.notify_one();
        }
