    bool removeUE(int CI) {
        std::unique_lock<std::mutex> lock(poolMutex);
        while (uePool.find(CI) == uePool.end()) {
            poolCond.wait(lock);
        }
        uePool.erase(CI);
        return true;
    }

    void updateUE(int CI, const UserEquipment& updatedUE) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (uePool.find(CI) != uePool.end()) {
            uePool[CI] = updatedUE;
        }
    }

