from flask import Flask, request, jsonify
from redis import Redis
import json

app = Flask(__name__)
redis_client = Redis(host='localhost', port=6379, db=0)

@app.route('/order', methods=['POST'])
def create_order():
    order_data = request.get_json()
    # Validate input data using JSON Schema
    if not validate_input(order_data):
        return jsonify({"error": "Invalid input"}), 400

    # Process order and update inventory
    try:
        process_order(order_data)
        return jsonify({"message": "Order processed successfully"}), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500

def validate_input(data):
    # Implement input validation using JSON Schema
    schema = {
        "type": "object",
        "properties": {
            "order_id": {"type": "string"},
            "customer_id": {"type": "string"},
            "items": {"type": "array", "items": {"type": "object"}}
        },
        "required": ["order_id", "customer_id", "items"]
    }
    return validate(data, schema)

def process_order(order_data):
    # Update inventory and record transaction
    update_inventory(order_data['items'])
    record_transaction(order_data)
    cache_order(order_data['order_id'], order_data)

def update_inventory(items):
    # Update inventory in real-time using Redis transactions
    with redis_client.pipeline() as pipe:
        for item in items:
            pipe.decr(f'inventory:{item["product_id"]}', item["quantity"])
        pipe.execute()

def record_transaction(order_data):
    # Record transaction details
    transaction_id = generate_transaction_id()
    redis_client.set(f'transaction:{transaction_id}', json.dumps(order_data))

def cache_order(order_id, order_data):
    # Cache the order for quick retrieval
    redis_client.setex(f'order:{order_id}', 3600, json.dumps(order_data))  # Cache for 1 hour

if __name__ == '__main__':
    app.run(debug=True)
