#define MAX_ENTRIES 10000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicListT;

DynamicListT* dynamic_list_init() {
    DynamicListT* list = (DynamicListT*)malloc(sizeof(DynamicListT));
    if (!list) return NULL;

    list->entries = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = MAX_ENTRIES;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void dynamic_list_destroy(DynamicListT* list) {
    free(list->entries);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int dynamic_list_add_entry(DynamicListT* list, RX_UE_INFORMATION_TAG ue_info, uint16_t RNTI, CRC_INDICATION_REL8_TAG crc_indication) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_entries = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }

    list->entries[list->count].ue_info = ue_info;
    list->entries[list->count].RNTI = RNTI;
    list->entries[list->count].crc_indication = crc_indication;
    list->entries[list->count].CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    list->count++;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

