#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <functional>
#include <atomic>

class DynamicNFCStatsCollector {
public:
    DynamicNFCStatsCollector(size_t maxNodes = 50000);
    ~DynamicNFCStatsCollector();

    void addNodeConfig(const std::string& nodeId, const std::map<std::string, double>& metrics);
    void removeNodeConfig(const std::string& nodeId);

    void startCollection();
    void stopCollection();

    void setLoggingCallback(std::function<void(const std::string& message)> callback);

private:
    struct NodeConfig {
        std::string id;
        std::map<std::string, double> metrics;
    };

    std::vector<NodeConfig> nodes;
    std::mutex nodesMutex;

    std::atomic<bool> running;
    std::thread collectionThread;

    void collectStats();
    void logMessage(const std::string& message);
};

DynamicNFCStatsCollector::DynamicNFCStatsCollector(size_t maxNodes)
    : nodes(maxNodes), running(false) {}

DynamicNFCStatsCollector::~DynamicNFCStatsCollector() {
    stopCollection();
}

void DynamicNFCStatsCollector::addNodeConfig(const std::string& nodeId, const std::map<std::string, double>& metrics) {
    std::lock_guard<std::mutex> lock(nodesMutex);
    NodeConfig node;
    node.id = nodeId;
    node.metrics = metrics;
    nodes.push_back(node);
}

void DynamicNFCStatsCollector::removeNodeConfig(const std::string& nodeId) {
    std::lock_guard<std::mutex> lock(nodesMutex);
    auto it = std::find_if(nodes.begin(), nodes.end(), [&](const NodeConfig& n) { return n.id == nodeId; });
    if (it != nodes.end()) {
        nodes.erase(it);
    }
}

void DynamicNFCStatsCollector::startCollection() {
    running = true;
    collectionThread = std::thread(&DynamicNFCStatsCollector::collectStats, this);
}

void DynamicNFCStatsCollector::stopCollection() {
    running.store(false);
    if (collectionThread.joinable()) {
        collectionThread.join();
    }
}

