#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <string>
#include <openssl/evp.h>
#include <openssl/rand.h>

class DynamicNFCStatsCollector {
public:
    DynamicNFCStatsCollector(size_t maxNodes = 100000) : maxNodes(maxNodes), nodeStats(maxNodes), statsQueue() {}

    void collectStats(int nodeId, const std::string& metrics) {
        std::lock_guard<std::mutex> lock(mutex);
        if (nodeId < maxNodes) {
            nodeStats[nodeId] = metrics;
            statsQueue.push(metrics);
        }
    }

    void startEncryptionThread() {
        encryptionThread = std::thread(&DynamicNFCStatsCollector::encryptStats, this);
    }

private:
    size_t maxNodes;
    std::vector<std::string> nodeStats;
    std::queue<std::string> statsQueue;
    std::mutex mutex;
    std::condition_variable cv;
    std::thread encryptionThread;

    void encryptStats() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return !statsQueue.empty(); });
            std::string metrics = statsQueue.front();
            statsQueue.pop();
            lock.unlock();

            std::string encryptedMetrics = encrypt(metrics);
            std::cout << "Encrypted Metrics: " << encryptedMetrics << std::endl;
        }
    }

    std::string encrypt(const std::string& data) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        unsigned char key[32], iv[16];
        // Generate secure key and IV
        RAND_bytes(key, sizeof(key));
        RAND_bytes(iv, sizeof(iv));

        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return "";
        }

        std::string encryptedData;
        int len, written;
        unsigned char buffer[1024];

        if (EVP_EncryptUpdate(ctx, buffer, &len, reinterpret_cast<const unsigned char*>(data.c_str()), data.size()) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return "";
        }
        encryptedData.append(reinterpret_cast<char*>(buffer), len);

        if (EVP_EncryptFinal_ex(ctx, buffer, &written) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return "";
        }
        encryptedData.append(reinterpret_cast<char*>(buffer), written);

        EVP_CIPHER_CTX_free(ctx);
        return encryptedData;
    }
};

int main() {
    DynamicNFCStatsCollector collector;
    collector.startEncryptionThread();

    // Simulate collecting metrics from nodes
    for (int i = 0; i < 10; ++i) {
        std::string metrics = "Node " + std::to_string(i) + " Metrics";
        collector.collectStats(i, metrics);
    }

    collector.encryptionThread.join();
    return 0;
}
