#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <unordered_map>
#include <atomic>

// Define a basic message structure
struct Message {
    int id;
    std::string content;
};

// Class to manage service consumers and producers
class Middleware {
public:
    Middleware(size_t poolSize) : poolSize_(poolSize), running_(true) {
        // Initialize worker threads
        for (size_t i = 0; i < poolSize_; ++i) {
            workers_.emplace_back([this, i] { workerThread(i); });
        }
    }

    ~Middleware() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            running_ = false;
        }
        condition_.notify_all();
        for (auto& thread : workers_) {
            thread.join();
        }
    }

    void produce(const Message& message) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(message);
        condition_.notify_one();
    }

private:
    void workerThread(size_t id) {
        while (true) {
            Message message;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                condition_.wait(lock, [this] { return !queue_.empty() || !running_; });
                if (!running_) break;
                message = queue_.front();
                queue_.pop();
            }
            processMessage(message);
        }
    }

    void processMessage(const Message& message) {
        // Simulate message processing
        std::cout << "Thread " << std::this_thread::get_id() << " processed message with ID: " << message.id << std::endl;
    }

    size_t poolSize_;
    std::vector<std::thread> workers_;
    std::queue<Message> queue_;
    std::mutex mutex_;
    std::condition_variable condition_;
    std::atomic<bool> running_;
};

int main() {
    Middleware middleware(5);

    // Simulate message production
    for (int i = 0; i < 10; ++i) {
        Message msg{i, "Sample content"};
        middleware.produce(msg);
    }

    return 0;
}
```

This code provides a basic framework for a middleware application using C++. It includes a `Middleware` class that manages a pool of worker threads to process messages asynchronously. The `produce` method adds messages to the queue and notifies one of the worker threads, which then processes the message in its own thread.

This example demonstrates the core concepts of producer-consumer pattern, multi-threading, and basic synchronization mechanisms using mutexes and condition variables. It can be extended with additional features such as message deduplication, ordering mechanisms, error handling, and real-time monitoring to meet the requirements specified in the task.']

['```go
package main

import (
	"crypto/md5"
	"errors"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"path/filepath"
)

type FileHasher struct {
	baseURL    string
	client     *http.Client
	checkpoint map[string]int64
}

func NewFileHasher(baseURL string) *FileHasher {
	return &FileHasher{
		baseURL: baseURL,
		client:  http.DefaultClient,
		checkpoint: make(map[string]int64),
	}
}

func (fh *FileHasher) CalculateMD5(fileID, url string) (string, error) {
	filePath := fh.downloadFile(url)
	if filePath == "" {
		return "", errors.New("file download failed")
	}
	defer os.Remove(filePath)

	hash := md5.New()
	f, err := os.Open(filePath)
	if err != nil {
		return "", fmt.Errorf("failed to open file: %w", err)
	}
	defer f.Close()

	checkpoint, ok := fh.checkpoint[fileID]
	if !ok {
		checkpoint = 0
	}

	for {
		_, err := f.Seek(checkpoint, os.SEEK_SET)
		if err != nil {
			return "", fmt.Errorf("failed to seek file: %w", err)
		}

		buf := make([]byte, 1024*1024) // 1MB buffer
		n, err := io.ReadFull(f, buf)
		if n > 0 {
			hash.Write(buf[:n])
			checkpoint += int64(n)
		}
		if err == io.EOF || n < len(buf) {
			break
		} else if err != nil {
			return "", fmt.Errorf("failed to read file: %w", err)
		}
	}

	fh.checkpoint[fileID] = checkpoint
	return fmt.Sprintf("%x", hash.Sum(nil)), nil
}

func (fh *FileHasher) downloadFile(url string) string {
	resp, err := fh.client.Get(url)
	if err != nil {
		log.Printf("Failed to download file: %v", err)
		return ""
	}
	defer resp.Body.Close()

	filePath := filepath.Join(os.TempDir(), "file_chunk")
	f, err := os.Create(filePath)
	if err != nil {
		log.Printf("Failed to create file: %v", err)
		return ""
	}
	defer f.Close()

	_, err = io.Copy(f, resp.Body)
	if err != nil {
		log.Printf("Failed to copy file content: %v", err)
		os.Remove(filePath)
		return ""
	}

	return filePath
}

func main() {
	hasher := NewFileHasher("https://example.com/storage")
	hash, err := hasher.CalculateMD5("file123", "http://example.com/file123.txt")
	if err != nil {
		log.Fatalf("Failed to calculate MD5: %v", err)
	}
	fmt.Printf("MD5 hash of the file: %s\n", hash)
}
