// Import necessary libraries
use actix_web::{web, App, HttpResponse, HttpServer};
use async_trait::async_trait;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::Mutex;

// Define a struct to represent the framework
struct WebService {
    api_router: ApiRouter,
    cache: Cache,
}

impl WebService {
    // Create a new instance of the framework
    fn new(api_router: ApiRouter, cache: Cache) -> Self {
        Self { api_router, cache }
    }

    // Start the HTTP server
    async fn start(&self, port: u16) -> std::io::Result<()> {
        HttpServer::new(move || {
            App::new()
                .route("/api/*path", web::get().to(self.api_router.handle_request))
        })
        .bind(format!("0.0.0.0:{}", port))?
        .run()
        .await
    }
}

// Define a struct to represent the API router
struct ApiRouter {
    api_clients: HashMap<String, Box<dyn ApiClient>>,
}

impl ApiRouter {
    // Create a new instance of the API router
    fn new(api_clients: HashMap<String, Box<dyn ApiClient>>) -> Self {
        Self { api_clients }
    }

    // Handle incoming requests and route them to the appropriate API client
    async fn handle_request(&self, path: web::Path<String>) -> HttpResponse {
        if let Some(path) = path.into_inner().split_once('/') {
            if let Some(api_client) = self.api_clients.get(path.0) {
                match api_client.send_request(path.1).await {
                    Ok(response) => HttpResponse::Ok().json(response),
                    Err(_) => HttpResponse::InternalServerError().finish(),
                }
            } else {
                HttpResponse::NotFound().finish()
            }
        } else {
            HttpResponse::BadRequest().finish()
        }
    }
}

// Define a trait for API clients
#[async_trait]
trait ApiClient {
    // Send an HTTP request to the external API and return the response
    async fn send_request(&self, path: &str) -> Result<serde_json::Value, reqwest::Error>;
}

// Implement the trait for a sample API client
struct SampleApiClient;

#[async_trait]
impl ApiClient for SampleApiClient {
    async fn send_request(&self, path: &str) -> Result<serde_json::Value, reqwest::Error> {
        let response = reqwest::get(format!("https://api.example.com/{}", path)).await?;
        response.json().await
    }
}

// Define a struct to represent the cache
struct Cache {
    data: Mutex<HashMap<String, serde_json::Value>>,
}

impl Cache {
    // Create a new instance of the cache
    fn new() -> Self {
        Self {
            data: Mutex::new(HashMap::new()),
        }
    }

    // Retrieve data from the cache or fetch it from the API if not present
    async fn get_or_fetch(&self, key: &str, api_client: Box<dyn ApiClient>) -> Result<serde_json::Value, reqwest::Error> {
        let mut data = self.data.lock().unwrap();
        if let Some(value) = data.get(key) {
            Ok(value.clone())
        } else {
            let value = api_client.send_request(key).await?;
            data.insert(key.to_string(), value.clone());
            Ok(value)
        }
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    // Create a sample API client
    let api_client: Box<dyn ApiClient> = Box::new(SampleApiClient);

    // Create the cache
    let cache = Cache::new();

    // Create the API router with the sample API client
    let api_router = ApiRouter::new(HashMap::from([("sample".to_string(), api_client)]));

    // Create and start the web service
    WebService::new(api_router, cache).start(8080).await
}
