class UEContext {
public:
    int CI;
    std::vector<RAB> RABS;

    UEContext(int ci) : CI(ci) {}
};

class RAB {
public:
    int bearerID;
    QoSParameters qosParams;
    ConnectionStatus status;

    RAB(int id, QoSParameters params, ConnectionStatus status)
        : bearerID(id), qosParams(params), status(status) {}
};

class QoSParameters {
    // Define QoS parameters here
};

enum class ConnectionStatus { ACTIVE, INACTIVE };

class UELibrary {
private:
    std::unordered_map<int, UEContext> uePool;
    std::mutex poolMutex;
    std::condition_variable cv;

public:
    void addUE(int CI) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (uePool.find(CI) == uePool.end()) {
            uePool[CI] = UEContext(CI);
            cv.notify_one();
        }
    }

    void removeUE(int CI) {
        std::unique_lock<std::mutex> lock(poolMutex);
        cv.wait(lock, [this, CI] { return uePool.find(CI) != uePool.end(); });
        uePool.erase(CI);
    }

    void updateRAB(int CI, int bearerID, QoSParameters params, ConnectionStatus status) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (uePool.find(CI) != uePool.end()) {
            for (auto& rab : uePool[CI].RABS) {
                if (rab.bearerID == bearerID) {
                    rab.qosParams = params;
                    rab.status = status;
                    return;
                }
            }
            uePool[CI].RABS.emplace_back(bearerID, params, status);
        }
    }

    void addRAB(int CI, int bearerID, QoSParameters params, ConnectionStatus status) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (uePool.find(CI) != uePool.end()) {
            uePool[CI].RABS.emplace_back(bearerID, params, status);
        }
    }

    void removeRAB(int CI, int bearerID) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (uePool.find(CI) != uePool.end()) {
            auto& rabs = uePool[CI].RABS;
            for (auto it = rabs.begin(); it != rabs.end(); ++it) {
                if (it->bearerID == bearerID) {
                    rabs.erase(it);
                    return;
                }
            }
        }
    }

    UEContext* getUE(int CI) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (uePool.find(CI) != uePool.end()) {
            return &uePool[CI];
        }
        return nullptr;
    }
};

class ExternalAPIClient {
public:
    bool connect() {
        // Simulate external API connection
        return true;
    }

    void disconnect() {
        // Simulate external API disconnection
    }

    bool callAPI() {
        // Simulate external API call
        return true;
    }
};

class UELibraryWithAPIClient : public UELibrary {
private:
    ExternalAPIClient apiClient;

public:
    void manageUE(int CI, bool add) {
        if (add) {
            addUE(CI);
        } else {
            removeUE(CI);
        }

        // Call external API
        if (apiClient.connect()) {
            apiClient.callAPI();
            apiClient.disconnect();
        }
    }

    void updateRAB(int CI, int bearerID, QoSParameters params, ConnectionStatus status) {
        UELibrary::updateRAB(CI, bearerID, params, status);

        // Call external API
        if (apiClient.connect()) {
            apiClient.callAPI();
            apiClient.disconnect();
        }
    }

    void addRAB(int CI, int bearerID, QoSParameters params, ConnectionStatus status) {
        UELibrary::addRAB(CI, bearerID, params, status);

        // Call external API
        if (apiClient.connect()) {
            apiClient.callAPI();
            apiClient.disconnect();
        }
    }

    void removeRAB(int CI, int bearerID) {
        UELibrary::removeRAB(CI, bearerID);

        // Call external API
        if (apiClient.connect()) {
