#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <atomic>
#include <stdexcept>

class NetworkStreamProcessor {
public:
    NetworkStreamProcessor(size_t max_size) : max_size_(max_size), running_(true), buffer(new int[max_size]), buffer_size(0), buffer_head(0), buffer_tail(0) {}

    ~NetworkStreamProcessor() {
        stop();
        delete[] buffer;
    }

    void start() {
        consumer_thread = std::thread(&NetworkStreamProcessor::consumer, this);
    }

    void stop() {
        running_.store(false);
        if (consumer_thread.joinable()) {
            consumer_thread.join();
        }
    }

    void add(int value) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return buffer_size < max_size_; });
        buffer[buffer_head] = value;
        buffer_head = (buffer_head + 1) % max_size_;
        ++buffer_size;
        cv_.notify_one();
    }

private:
    void consumer() {
        while (running_) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return buffer_size > 0 || !running_; });
            if (!running_ && buffer_size == 0) break;
            int value = buffer[buffer_tail];
            buffer_tail = (buffer_tail + 1) % max_size_;
            --buffer_size;
            lock.unlock();
            process(value);
        }
    }

    void process(int value) {
        // Process the value
    }

    size_t max_size_;
    std::atomic<bool> running_;
    int* buffer;
    size_t buffer_size;
    size_t buffer_head;
    size_t buffer_tail;
    mutable std::mutex mutex_;
    std::condition_variable cv_;
    std::thread consumer_thread;
};
