#include <iostream>
#include <unordered_map>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <memory>

class RAB {
public:
    RAB(int id, int qos) : bearerID(id), QoS(qos), connectionStatus(false) {}
    void connect() { connectionStatus = true; }
    void disconnect() { connectionStatus = false; }
    bool isConnected() const { return connectionStatus; }
    int getBearerID() const { return bearerID; }
private:
    int bearerID;
    int QoS;
    bool connectionStatus;
};

class UEContext {
public:
    UEContext(int CI) : cellIdentity(CI), bearers() {}
    void addRAB(std::shared_ptr<RAB> rab) {
        std::lock_guard<std::mutex> lock(mutex);
        bearers.push_back(rab);
    }
    void removeRAB(int rabID) {
        std::lock_guard<std::mutex> lock(mutex);
        bearers.erase(std::remove_if(bearers.begin(), bearers.end(),
                                       [rabID](const std::shared_ptr<RAB>& rab) { return rab->getBearerID() == rabID; }),
                      bearers.end());
    }
    void updateRAB(int rabID, int newQoS) {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto& rab : bearers) {
            if (rab->getBearerID() == rabID) {
                rab->disconnect();
                rab = std::make_shared<RAB>(rabID, newQoS);
                rab->connect();
                break;
            }
        }
    }
    bool hasRAB(int rabID) const {
        std::lock_guard<std::mutex> lock(mutex);
        return std::find_if(bearers.begin(), bearers.end(),
                            [rabID](const std::shared_ptr<RAB>& rab) { return rab->getBearerID() == rabID; }) != bearers.end();
    }
private:
    int cellIdentity;
    mutable std::mutex mutex;
    std::vector<std::shared_ptr<RAB>> bearers;
};

class UELibrary {
public:
    void addUE(int CI) {
        std::lock_guard<std::mutex> lock(mutex);
        if (ues.find(CI) == ues.end()) {
            ues[CI] = std::make_shared<UEContext>(CI);
        }
    }
    void removeUE(int CI) {
        std::lock_guard<std::mutex> lock(mutex);
        ues.erase(ues.find(CI));
    }
    void addRAB(int CI, int rabID, int qos) {
        std::lock_guard<std::mutex> lock(mutex);
        if (ues.find(CI) != ues.end()) {
            ues[CI]->addRAB(std::make_shared<RAB>(rabID, qos));
        }
    }
    void removeRAB(int CI, int rabID) {
        std::lock_guard<std::mutex> lock(mutex);
        if (ues.find(CI) != ues.end()) {
            ues[CI]->removeRAB(rabID);
        }
    }
    void updateRAB(int CI, int rabID, int newQoS) {
        std::lock_guard<std::mutex> lock(mutex);
        if (ues.find(CI) != ues.end()) {
            ues[CI]->updateRAB(rabID, newQoS);
        }
    }
    bool hasRAB(int CI, int rabID) const {
        std::lock_guard<std::mutex> lock(mutex);
        if (ues.find(CI) != ues.end()) {
            return ues[CI]->hasRAB(rabID);
        }
        return false;
    }
private:
    mutable std::mutex mutex;
    std::unordered_map<int, std::shared_ptr<UEContext>> ues;
};

int main() {
    UELibrary library;
    library.addUE(12345);
    library.addRAB(12345, 1, 10);
    library.updateRAB(12345, 1, 20);
    std::cout << "Has RAB: " << (library.hasRAB(12345, 1) ? "Yes" : "No") << std::endl;
    library.removeRAB(12345, 1);
    return 0;
}
