#include <iostream>
#include <vector>
#include <memory>

// Define an interface for cryptographic algorithms
class CryptoAlgorithm {
public:
    virtual ~CryptoAlgorithm() {}
    virtual std::string hash(const std::string& data) = 0;
    virtual std::string encrypt(const std::string& data, const std::string& key) = 0;
};

// Implement specific cryptographic algorithms
class SHA256 : public CryptoAlgorithm {
public:
    std::string hash(const std::string& data) override {
        // Implementation of SHA-256 hashing algorithm
        return "SHA256(" + data + ")";
    }

    std::string encrypt(const std::string& data, const std::string& key) override {
        // Implementation of symmetric encryption using a key
        return "Encrypted(" + data + ", " + key + ")";
    }
};

class AES : public CryptoAlgorithm {
public:
    std::string hash(const std::string& data) override {
        throw std::runtime_error("AES does not support hashing.");
    }

    std::string encrypt(const std::string& data, const std::string& key) override {
        // Implementation of AES encryption
        return "Encrypted(AES, " + data + ", " + key + ")";
    }
};

// Cryptographic Service Provider (CSP)
class CSP {
public:
    void loadAlgorithms() {
        algorithms_.push_back(std::make_unique<SHA256>());
        algorithms_.push_back(std::make_unique<AES>());
        // Dynamically load other supported algorithms
    }

    std::string hash(const std::string& data) {
        for (auto& algo : algorithms_) {
            try {
                return algo->hash(data);
            } catch (const std::exception&) {}
        }
        throw std::runtime_error("No suitable hashing algorithm available.");
    }

    std::string encrypt(const std::string& data, const std::string& key) {
        for (auto& algo : algorithms_) {
            try {
                return algo->encrypt(data, key);
            } catch (const std::exception&) {}
        }
        throw std::runtime_error("No suitable encryption algorithm available.");
    }

private:
    std::vector<std::unique_ptr<CryptoAlgorithm>> algorithms_;
};

int main() {
    CSP csp;
    csp.loadAlgorithms();

    try {
        std::string hashResult = csp.hash("Hello, World!");
        std::string encryptResult = csp.encrypt("Secret data", "Key123");

        std::cout << "Hash: " << hashResult << std::endl;
        std::cout << "Encrypt: " << encryptResult << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
```

