#include <thread>
#include <atomic>
#include <chrono>
#include <mutex>
#include <condition_variable>

class DistributedCache {
public:
    struct Config {
        int maxRetries = 5;
        std::chrono::milliseconds retryInterval = std::chrono::seconds(1);
        double jitterFactor = 0.2;
        size_t initialCapacity = 1024;
        size_t maxCapacity = 1024 * 1024;
    };

private:
    Config config_;
    std::unordered_map<std::string, std::string> cache_;
    std::mutex mtx_;
    std::condition_variable cv_;
    std::atomic<bool> isDegraded_{false};

public:
    DistributedCache(const Config& config) : config_(config), cache_(config.initialCapacity) {}

    void set(const std::string& key, const std::string& value) {
        while (true) {
            if (!isDegraded_.load()) {
                std::lock_guard<std::mutex> lock(mtx_);
                auto it = cache_.find(key);
                if (it != cache_.end()) {
                    it->second = value;
                } else {
                    cache_[key] = value;
                }
                break;
            } else {
                // Degraded state handling
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        }
    }

    std::string get(const std::string& key) {
        while (true) {
            if (!isDegraded_.load()) {
                std::lock_guard<std::mutex> lock(mtx_);
                auto it = cache_.find(key);
                if (it != cache_.end()) {
                    return it->second;
                }
                break;
            } else {
                // Degraded state handling
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        }
        return "";
    }

private:
    void handleServiceFailure() {
        isDegraded_.store(true);
        // Log service failure and notify users
    }

    void handleServiceRecovery() {
        isDegraded_.store(false);
        // Log service recovery
    }

    bool retryOperation(int attempt) {
        if (attempt >= config_.maxRetries) {
            return false;
        }
        std::this_thread::sleep_for(config_.retryInterval +
                                      std::chrono::milliseconds(static_cast<int>(config_.jitterFactor * 
                                                                               (std::rand() % 1000))));
        return true;
    }

    void healthCheck() {
        while (true) {
            // Perform health check and notify if service is down
            if (!isServiceAvailable()) {
                handleServiceFailure();
            } else {
                handleServiceRecovery();
            }
            std::this_thread::sleep_for(std::chrono::seconds(10));
        }
    }

    bool isServiceAvailable() {
        // Simulate service availability check
        return true;
    }
};

int main() {
    DistributedCache::Config config = {5, std::chrono::seconds(1), 0.2};
    DistributedCache cache(config);

    std::thread healthThread(&DistributedCache::healthCheck, &cache);
    healthThread.detach();

    cache.set("key1", "value1");
    std::cout << "Value for key1: " << cache.get("key1") << std::endl;

    return 0;
}
