        _monitoringSources.Add(source);
    }

    public async Task ProcessDataAsync()
    {
        var dataPoints = new List<MonitoringDataPoint>();

        foreach (var source in _monitoringSources)
        {
            try
            {
                dataPoints.AddRange(await source.GetDataAsync());
            }
            catch (Exception ex)
            {
                // Log and handle exceptions from individual sources
                Console.WriteLine($"Error processing data from {source.GetType().Name}: {ex.Message}");
            }
        }

        var aggregatedData = AggregateData(dataPoints);
        await HandleAggregatedDataAsync(aggregatedData);
    }

    private MonitoringDataPoint AggregateData(List<MonitoringDataPoint> dataPoints)
    {
        // Implement data aggregation logic here
        return new MonitoringDataPoint();
    }

    private async Task HandleAggregatedDataAsync(MonitoringDataPoint aggregatedData)
