// Define the secure file encryption tool in C
#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <openssl/rand.h>

// Function to encrypt files using AES-256-GCM
int encryptFile(const char *inputFile, const char *outputFile, const unsigned char *key, const unsigned char *iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) return -1;

    FILE *inFile = fopen(inputFile, "rb");
    FILE *outFile = fopen(outputFile, "wb");

    // Read input file and encrypt data
    unsigned char in[1024], out[1024];
    int inLen, outLen;
    while ((inLen = fread(in, 1, sizeof(in), inFile)) > 0) {
        if (1 != EVP_EncryptUpdate(ctx, out, &outLen, in, inLen)) return -1;
        fwrite(out, 1, outLen, outFile);
    }

    unsigned char tag[EVP_GCM_TAG_LEN];
    int tagLen;
    if (1 != EVP_EncryptFinal_ex(ctx, out, &outLen, NULL, 0)) return -1;
    memcpy(tag, EVP_CIPHER_CTX_bufnoiv(ctx), sizeof(tag));

    fwrite(tag, 1, sizeof(tag), outFile);
    fclose(inFile);
    fclose(outFile);

    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

// Function to decrypt files using AES-256-GCM
int decryptFile(const char *inputFile, const char *outputFile, const unsigned char *key, const unsigned char *iv) {
    // Similar implementation as encryption but with decryption functions
}
