// Define a thread pool for concurrent data processing
class ThreadPool {
public:
    ThreadPool(size_t size) : stop_(false) {
        for(size_t i = 0; i < size; ++i)
            workers_.emplace_back([this] {
                while(true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->queue_mutex_);
                        this->condition_.wait(lock, [this]{ return this->stop_ || !this->tasks.empty(); });
                        if(this->stop_ && this->tasks.empty())
                            return;
                        task = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    task();
                }
            });
    }

    template<class F, class... Args>
    auto enqueue(F&& f, Args&&... args)
        -> std::future<typename std::result_of<F(Args...)>::type> {
        using return_type = typename std::result_of<F(Args...)>::type;

        auto task = std::make_shared<std::packaged_task<return_type()>>(
            std::bind(std::forward<F>(f), std::forward<Args>(args)...)
        );

        std::future<return_type> res = task->get_future();
        {
            std::unique_lock<std::mutex> lock(queue_mutex_);

            // don't allow enqueueing after stopping the pool
            if(stop_)
                throw std::runtime_error("enqueue on stopped ThreadPool");

            tasks.emplace([task](){ (*task)(); });
        }
        condition_.notify_one();
        return res;
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex_);
            stop_ = true;
        }
        condition_.notify_all();
        for(std::thread &worker: workers_)
            worker.join();
    }

private:
    // need to keep track of threads so we can join them
    std::vector<std::thread> workers_;
    // the task queue
    std::queue<std::function<void()>> tasks;

    // synchronization
    std::mutex queue_mutex_;
    std::condition_variable condition_;
    bool stop_;
};

// Define a class for managing sensor data ingestion and processing
class SensorDataIngestor {
public:
    SensorDataIngestor(size_t poolSize)
        : processor_(std::make_shared<SensorDataProcessor>(std::make_shared<InMemoryDB>(), std::make_shared<InMemoryStream>())),
          threadPool_(poolSize) {}

    void ingest(const SensorData& data) {
        threadPool_.enqueue([this, &data]() { processor_->process(data); });
    }

private:
    std::shared_ptr<SensorDataProcessor> processor_;
    ThreadPool threadPool_;
};

int main() {
    SensorDataIngestor ingester(4);
    // Simulate sensor data ingestion
    for(int i = 0; i < 100; ++i) {
        SensorData data;
        data.id = "sensor" + std::to_string(i);
        data.value = static_cast<double>(i);
        ingester.ingest(data);
    }
    return 0;
}
