use std::sync::{Arc, Mutex};
use tokio::task;

pub struct DSLToLLVM {
    grammar_config: Arc<Mutex<config::Config>>,
    resource_tracker: Arc<resource_tracker::ResourceTracker>,
}

impl DSLToLLVM {
    pub fn new() -> Self {
        let grammar_config = config::Config::default();
        let resource_tracker = resource_tracker::ResourceTracker::new();

        DSLToLLVM {
            grammar_config: Arc::new(Mutex::new(grammar_config)),
            resource_tracker,
        }
    }

    pub async fn convert(&self, input_file_path: &str) -> Result<String, Box<dyn std::error::Error>> {
        let mut grammar_lock = self.grammar_config.lock().unwrap();
        let grammar_version = grammar_lock.get_latest_version();

        let content = parser::parse_file(input_file_path)?;
        let llvm_ir = llvm_ir_generator::generate_llvm_ir(&content, grammar_version);

        Ok(llvm_ir)
    }

    pub async fn select_grammar_version(&self, version: &str) -> Result<(), Box<dyn std::error::Error>> {
        let mut grammar_lock = self.grammar_config.lock().unwrap();
        grammar_lock.set_version(version)?;

        Ok(())
    }
}

// src/parser.rs
pub mod parser {
    use std::fs;

    pub fn parse_file(file_path: &str) -> Result<String, Box<dyn std::error::Error>> {
