import redis
import boto3
from google.cloud import storage
from azure.storage.blob import BlobServiceClient

class CloudStorageManager:
    def __init__(self, config):
        self.config = config
        self.redis_client = redis.StrictRedis.from_url(config['redis_url'])
        self.circuit_breaker = CircuitBreaker()
        self.retry_policy = RetryPolicy()

    @abstractmethod
    def upload_file(self, file_path, storage_key):
        pass

    @abstractmethod
    def download_file(self, storage_key, local_path):
        pass

class AWSStorageManager(CloudStorageManager):
    def __init__(self, config):
        super().__init__(config)
        self.s3_client = boto3.client('s3', aws_access_key_id=config['aws_access_key'], aws_secret_access_key=config['aws_secret_key'])

    def upload_file(self, file_path, storage_key):
        if self.circuit_breaker.is_open():
            raise Exception("Circuit breaker is open")
        try:
            self.s3_client.upload_file(file_path, config['bucket_name'], storage_key)
        except Exception as e:
            if self.retry_policy.should_retry(e):
                time.sleep(self.retry_policy.calculate_backoff())
                return self.upload_file(file_path, storage_key)
            else:
                raise

    def download_file(self, storage_key, local_path):
        if self.circuit_breaker.is_open():
            raise Exception("Circuit breaker is open")
        try:
            self.s3_client.download_file(config['bucket_name'], storage_key, local_path)
        except Exception as e:
            if self.retry_policy.should_retry(e):
                time.sleep(self.retry_policy.calculate_backoff())
                return self.download_file(storage_key, local_path)
            else:
                raise

class GoogleCloudStorageManager(CloudStorageManager):
    def __init__(self, config):
        super().__init__(config)
        self.storage_client = storage.Client.from_service_account_json(config['google_credentials'])

    def upload_file(self, file_path, storage_key):
        if self.circuit_breaker.is_open():
            raise Exception("Circuit breaker is open")
        try:
            bucket = self.storage_client.bucket(config['bucket_name'])
            blob = bucket.blob(storage_key)
            blob.upload_from_filename(file_path)
        except Exception as e:
            if self.retry_policy.should_retry(e):
                time.sleep(self.retry_policy.calculate_backoff())
                return self.upload_file(file_path, storage_key)
            else:
                raise

    def download_file(self, storage_key, local_path):
        if self.circuit_breaker.is_open():
            raise Exception("Circuit breaker is open")
        try:
            bucket = self.storage_client.bucket(config['bucket_name'])
            blob = bucket.blob(storage_key)
            blob.download_to_filename(local_path)
        except Exception as e:
            if self.retry_policy.should_retry(e):
                time.sleep(self.retry_policy.calculate_backoff())
                return self.download_file(storage_key, local_path)
            else:
                raise

class AzureBlobStorageManager(CloudStorageManager):
    def __init__(self, config):
        super().__init__(config)
        self.blob_service_client = BlobServiceClient.from_connection_string(config['azure_connection_string'])

    def upload_file(self, file_path, storage_key):
        if self.circuit_breaker.is_open():
            raise Exception("Circuit breaker is open")
        try:
            container_client = self.blob_service_client.get_container_client(config['container_name'])
            blob_client = container_client.get_blob_client(storage_key)
            with open(file_path, "rb") as data:
                blob_client.upload_blob(data)
        except Exception as e:
            if self.retry_policy.should_retry(e):
                time.sleep(self.retry_policy.calculate_backoff())
                return self.upload_file(file_path, storage_key)
            else:
                raise

    def download_file(self, storage_key, local_path):
        if self.circuit_breaker.is_open():
            raise Exception("Circuit breaker is open")
        try:
            container_client = self.blob_service_client.get_container_client(config['container_name'])
            blob_client = container_client.get_blob_client(storage_key)
            with open(local_path, "wb") as download_file:
                download_file.write(blob_client.download_blob().readall())
        except Exception as e:
            if self.retry_policy.should_retry(e):
                time.sleep(self.retry_policy.calculate_backoff())
                return self.download_file(storage_key, local_path)
            else:
                raise

class CircuitBreaker:
    def __init__(self):
        self.open = False
        self.failure_count = 0

    def is_open(self):
        return self.open

    def open_circuit(self):
        self.open = True
        self.failure_count += 1

    def close_circuit(self):
        self.open = False

class RetryPolicy:
    def __init__(self, max_retries=5, initial_delay=1, max_delay=60):
        self.max_retries = max_retries
        self.initial_delay = initial_delay
        self.max_delay = max_delay

