// Define a structure to represent a Radio Access Bearer (RAB)
struct RAB {
    int bearerID;
    std::string QoSParameters;
    bool connectionStatus;
};

// Define a class to represent a User Equipment (UE) context
class UEContext {
private:
    int CI;
    std::vector<RAB> RABS;

public:
    UEContext(int ci) : CI(ci) {}

    // Method to add a new RAB to the UE context
    void AddRAB(const RAB& rab) {
        RABS.push_back(rab);
    }

    // Method to remove an RAB from the UE context
    bool RemoveRAB(int bearerID) {
        for (auto it = RABS.begin(); it != RABS.end(); ++it) {
            if (it->bearerID == bearerID) {
                RABS.erase(it);
                return true;
            }
        }
        return false;
    }

    // Method to update an existing RAB
    bool UpdateRAB(int bearerID, const std::string& newQoSParameters) {
        for (auto& rab : RABS) {
            if (rab.bearerID == bearerID) {
                rab.QoSParameters = newQoSParameters;
                return true;
            }
        }
        return false;
    }

    // Other methods to handle UE context lifecycle management
};

// Define a class to manage the dynamic pool of UE contexts
class UEMgr {
private:
    std::unordered_map<int, UEContext> uePool;

public:
    // Method to add a new UE context
    void AddUE(int ci) {
        if (uePool.find(ci) == uePool.end()) {
            uePool[ci] = UEContext(ci);
        }
    }

    // Method to remove an UE context
    bool RemoveUE(int ci) {
        if (uePool.find(ci) != uePool.end()) {
            uePool.erase(ci);
            return true;
        }
        return false;
    }

    // Method to update an existing UE context
    bool UpdateUE(int ci, int bearerID, const std::string& newQoSParameters) {
        if (uePool.find(ci) != uePool.end()) {
            return uePool[ci].UpdateRAB(bearerID, newQoSParameters);
        }
        return false;
    }

    // Other methods to handle UE context management
};
```

