class CloudServiceAdapter {
public:
    virtual ~CloudServiceAdapter() {}
    virtual void uploadData(const IoTDevice* device, const std::string& data) = 0;
    virtual void processCommand(const IoTDevice* device, const std::string& command) = 0;
};

class DistributedDatabase {
public:
    void addDevice(std::shared_ptr<IoTDevice> device) {
        std::lock_guard<std::mutex> lock(mutex_);
        devices_.push_back(device);
    }

    void removeDevice(std::shared_ptr<IoTDevice> device) {
        std::lock_guard<std::mutex> lock(mutex_);
        devices_.erase(std::remove(devices_.begin(), devices_.end(), device), devices_.end());
    }

    void handleData(const IoTDevice* device, const std::string& data) {
        for (auto& adapter : adapters_) {
            adapter->uploadData(device, data);
        }
    }

    void handleCommand(const IoTDevice* device, const std::string& command) {
        for (auto& adapter : adapters_) {
            adapter->processCommand(device, command);
        }
    }

    void addCloudServiceAdapter(std::shared_ptr<CloudServiceAdapter> adapter) {
        std::lock_guard<std::mutex> lock(mutex_);
        adapters_.push_back(adapter);
    }

private:
    std::vector<std::shared_ptr<IoTDevice>> devices_;
    std::vector<std::shared_ptr<CloudServiceAdapter>> adapters_;
    std::mutex mutex_;
