function renderFooterScripts(scripts, config = { async: false, defer: true }) {
  const scriptTags = scripts.map(script => {
    if (typeof script.content !== 'string') return null;
    const attrs = [
      `src="${script.src}"`,
      config.async ? 'async' : '',
      config.defer ? 'defer' : ''
    ].filter(Boolean).join(' ');
    return `<script ${attrs}>${sanitizeScriptContent(script.content)}</script>`;
  }).filter(script => script !== null);

  return `<footer>${scriptTags.join('')}</footer>`;
}

function sanitizeScriptContent(content) {
  // Implement a simple sanitization logic here, e.g., using DOMParser
  const parser = new DOMParser();
  const doc = parser.parseFromString(content, 'text/html');
  return doc.body.textContent;
}
