import java.io.File;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ThemeCacheSystem {
    private final File cacheRootDirectory;
    private final ConcurrentHashMap<String, Bitmap> cache = new ConcurrentHashMap<>();
    private final ExecutorService executorService;
    private final ImageProcessingService imageProcessingService;

    public ThemeCacheSystem(File cacheRootDirectory, ImageProcessingService imageProcessingService) {
        this.cacheRootDirectory = cacheRootDirectory;
        this.imageProcessingService = imageProcessingService;
        this.executorService = Executors.newCachedThreadPool();
    }

    public Bitmap getTheme(String themeName) throws IOException {
        Bitmap cachedBitmap = cache.get(themeName);
        if (cachedBitmap != null) {
            return cachedBitmap;
        }

        File file = new File(cacheRootDirectory, themeName + ".png");
        if (!file.exists()) {
            throw new FileNotFoundException("File not found: " + file.getAbsolutePath());
        }

        Bitmap bitmap = loadImageFromFile(file);
        cache.put(themeName, bitmap);
        return bitmap;
    }

    private Bitmap loadImageFromFile(File file) throws IOException {
        byte[] data = Files.readAllBytes(file.toPath());
        Bitmap bitmap = BitmapFactory.decodeByteArray(data, 0, data.length);

        executorService.submit(() -> {
            try {
                Bitmap optimizedBitmap = imageProcessingService.compress(bitmap);
                cache.put(file.getName(), optimizedBitmap);
            } catch (Exception e) {
                logError("Failed to compress image: " + file.getAbsolutePath(), e);
            }
        });

        return bitmap;
    }

    private void logError(String message, Throwable throwable) {
        // Log the error with detailed information
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}
```

