#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONCURRENT_MODIFICATIONS 100

typedef struct {
    int clinic_id;
    char last_modified_ip[16];
    time_t last_modified_date;
} ClinicStatus;

typedef struct {
    ClinicStatus *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    int seed;
    int min_clinic_id;
    int max_clinic_id;
} ClinicStatusManager;

ClinicStatusManager* clinic_status_manager_init(size_t initial_size, int min_clinic_id, int max_clinic_id, int seed) {
    ClinicStatusManager *manager = (ClinicStatusManager*)malloc(sizeof(ClinicStatusManager));
    if (!manager) return NULL;

    manager->array = (ClinicStatus*)calloc(initial_size, sizeof(ClinicStatus));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_size;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->seed = seed;
    manager->min_clinic_id = min_clinic_id;
    manager->max_clinic_id = max_clinic_id;

    return manager;
}

void clinic_status_manager_free(ClinicStatusManager *manager) {
    if (manager) {
        free(manager->array);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int clinic_status_manager_add_or_update(ClinicStatusManager *manager, ClinicStatus *status) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].clinic_id == status->clinic_id &&
            strcmp(manager->array[i].last_modified_ip, status->last_modified_ip) == 0 &&
            manager->array[i].last_modified_date >= status->last_modified_date) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Duplicate or older update
        }
    }

    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        ClinicStatus *new_array = (ClinicStatus*)realloc(manager->array, new_capacity * sizeof(ClinicStatus));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failure
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    memcpy(&manager->array[manager->size], status, sizeof(ClinicStatus));
    manager->size++;

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

