                                          MessageQueue messageQueue,
                                          ResourceMonitor resourceMonitor) {
        this.externalService = externalService;
        this.loggingService = loggingService;
        this.cache = cache;
        this.persistence = persistence;
        this.messageQueue = messageQueue;
        this.resourceMonitor = resourceMonitor;
    }

    public void processTransaction(byte[] transactionData) {
        try {
            // Deserialize the transaction data
            Transaction transaction = deserialize(transactionData);

            // Validate and handle transaction anomalies
            if (isAnomaly(transaction)) {
                loggingService.logAnomaly(transaction);
                return;
            }

            // Check for duplicates and enforce frequency limits
            if (!cache.isDuplicateOrOverFrequencyLimit(transaction)) {
                processTransactionLogically(transaction);
                persistence.storeTransaction(transaction);
            } else {
                loggingService.logRejection(transaction);
            }
        } catch (Exception e) {
            handleException(e, transactionData);
        }
    }

    private Transaction deserialize(byte[] data) throws SerializationException {
