public class DynamicDataPipeline
{
    private readonly Dictionary<string, IDataProcessor> _dataProcessors = new Dictionary<string, IDataProcessor>();
    private readonly ILogger _logger;

    public DynamicDataPipeline(ILogger logger)
    {
        _logger = logger;
    }

    public void RegisterDataProcessor<T>(string format, Func<T, Task> processor)
    {
        _dataProcessors[format] = new DataProcessorAdapter<T>(processor);
    }

    public async Task ProcessAsync(string data, string format)
    {
        if (!_dataProcessors.ContainsKey(format))
        {
            _logger.LogError($"No processor registered for format: {format}");
            throw new ArgumentException("Invalid data format");
        }

        await _dataProcessors[format].ProcessAsync(data);
    }
}

public interface IDataProcessor
{
    Task ProcessAsync(string data);
}

internal class DataProcessorAdapter<T> : IDataProcessor
{
    private readonly Func<T, Task> _processor;

    public DataProcessorAdapter(Func<T, Task> processor)
    {
        _processor = processor;
    }

    public async Task ProcessAsync(string data)
    {
        T parsedData = ParseData<T>(data);
        await _processor(parsedData);
    }

    private T ParseData<T>(string data)
    {
        // Implement parsing logic based on the data format
        throw new NotImplementedException();
    }
}

public interface ILogger
{
    void LogError(string message);
}

internal class ConsoleLogger : ILogger
{
    public void LogError(string message)
    {
        Console.WriteLine($"ERROR: {message}");
    }
}
