['```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <atomic>
#include <future>
#include <condition_variable>
#include <queue>
#include <functional>

class ImageProcessor {
public:
    void addTask(const std::function<void()>& task) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            tasks_.push(task);
        }
        condition_.notify_one();
    }

    void start(int numThreads = 1) {
        for (int i = 0; i < numThreads; ++i) {
            workers_.emplace_back([this]() {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(mutex_);
                        condition_.wait(lock, [this] { return !tasks_.empty() || stopping_; });
                        if (stopping_ && tasks_.empty()) {
                            return;
                        }
                        task = std::move(tasks_.front());
                        tasks_.pop();
                    }
                    task();
                }
            });
        }
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            stopping_ = true;
        }
        condition_.notify_all();
        for (std::thread& worker : workers_) {
            worker.join();
        }
    }

private:
    std::vector<std::thread> workers_;
    std::queue<std::function<void()>> tasks_;
    std::mutex mutex_;
    std::condition_variable condition_;
    bool stopping_ = false;
};

// Example usage
int main() {
    ImageProcessor processor;

    // Add tasks to the processor
    for (int i = 0; i < 10; ++i) {
        int taskId = i;
        processor.addTask([taskId]() {
            std::cout << "Processing task " << taskId << std::endl;
        });
    }

    // Start processing with 4 threads
    processor.start(4);

    // Wait for all tasks to complete
    processor.stop();

    return 0;
}
```

