# FileProcessingFramework.py

import os
import uuid
from datetime import datetime
from concurrent.futures import ThreadPoolExecutor
import asyncio
from queue import Queue
import logging

class FileProcessor:
    def __init__(self, max_filename_length=100, supported_formats=['jpg', 'png', 'mp4'], uuid_format='uuid4'):
        self.max_filename_length = max_filename_length
        self.supported_formats = supported_formats
        self.uuid_format = uuid_format
        self.executor = ThreadPoolExecutor(max_workers=5)
        self.queue = Queue()
        self.logger = logging.getLogger('FileProcessor')

    def process_directory(self, directory_path):
        for filename in os.listdir(directory_path):
            file_path = os.path.join(directory_path, filename)
            if os.path.isfile(file_path) and any(filename.endswith(ext) for ext in self.supported_formats):
                self.queue.put((file_path, filename))

    async def process_file(self):
        while True:
            item = self.queue.get()
            if item is None:
                break
            file_path, filename = item
            try:
                await asyncio.to_thread(self._process_file, file_path, filename)
            except Exception as e:
                self.logger.error(f"Error processing file {filename}: {e}")
            finally:
                self.queue.task_done()

    def _process_file(self, file_path, filename):
        new_filename = self.generate_new_filename(filename)
        if new_filename:
            # Simulate file processing
            os.rename(file_path, os.path.join(os.path.dirname(file_path), new_filename))
            self.logger.info(f"Processed {filename} as {new_filename}")
        else:
            self.logger.warning(f"Failed to process {filename}")

    def generate_new_filename(self, filename):
        try:
            if len(filename) > self.max_filename_length:
                filename = filename[:self.max_filename_length]
            new_uuid = getattr(uuid, self.uuid_format)()
            timestamp = datetime.now().strftime('%Y%m%d%H%M%S')
            return f"{filename}_{new_uuid}_{timestamp}"
        except Exception as e:
            self.logger.error(f"Error generating UUID: {e}")
            return None

    def update_config(self, max_filename_length=None, supported_formats=None, uuid_format=None):
        if max_filename_length is not None:
            self.max_filename_length = max_filename_length
        if supported_formats is not None:
            self.supported_formats = supported_formats
        if uuid_format is not None:
            self.uuid_format = uuid_format

# Usage example
if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    processor = FileProcessor()
    processor.update_config(max_filename_length=150, supported_formats=['jpg', 'png', 'mp4', 'mov'])
    processor.process_directory('/path/to/directory')
    processor.executor.shutdown(wait=True)

```

