public class DataIngestService
{
    private readonly IConnectionMultiplexer _redis;
    private readonly HttpClient _httpClient;

    public DataIngestService(IConnectionMultiplexer redis, HttpClient httpClient)
    {
        _redis = redis;
        _httpClient = httpClient;
    }

    public async Task IngestData(Stream jsonDataStream)
    {
        var batchSize = 100; // Define your batch size
        using (var reader = new StreamReader(jsonDataStream))
        {
            while (!reader.EndOfStream)
            {
                var batch = await reader.ReadBatchAsync(batchSize);
                foreach (var json in batch)
                {
                    if (await ValidateJson(json))
                    {
                        await StoreDataInRedis(json);
                    }
                }
            }
        }
    }

    private async Task<bool> ValidateJson(string json)
    {
        // Fetch the schema from external API
        var response = await _httpClient.GetAsync("https://api.example.com/schema");
        var schema = await response.Content.ReadAsStringAsync();

        // Perform validation (simplified example using Newtonsoft.Json.Schema)
        try
        {
            var validator = new JSchemaValidatingReader(new JsonTextReader(new StringReader(json)))
            {
                Schema = JSchema.Parse(schema),
                ValidateMode = ValidateMode.Strict
            };

            while (validator.Read()) { }

            return true;
        }
        catch
        {
            return false;
        }
    }

    private async Task StoreDataInRedis(string json)
    {
        var db = _redis.GetDatabase();
        await db.StringSetAsync(Guid.NewGuid().ToString(), json);
    }

    public async Task<decimal> GetHealthCheck()
    {
        // Implement your health check logic here
        return await _redis.GetDatabase().PingAsync() ? 1.0m : 0.0m;
    }
}
