public class DocumentProcessor : IDocumentProcessor
{
    private readonly ICloudStorageService _cloudStorageService;
    private readonly ITransformationService _transformationService;
    private readonly ILogger _logger;

    public DocumentProcessor(ICloudStorageService cloudStorageService, ITransformationService transformationService, ILogger logger)
    {
        _cloudStorageService = cloudStorageService;
        _transformationService = transformationService;
        _logger = logger;
    }

    public async Task ProcessDocumentBatchAsync(string inputFolder, string outputFolder)
    {
        try
        {
            var documents = await _cloudStorageService.ListDocumentsAsync(inputFolder);

            foreach (var document in documents)
            {
                var processedDocument = await _transformationService.TransformDocumentAsync(document);
                await _cloudStorageService.SaveDocumentAsync(outputFolder, processedDocument);
            }

            _logger.LogInformation("Batch processing completed successfully.");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred during batch processing.");
            throw;
        }
    }
}

