    private ICloudStorageProvider _currentProvider;

    public CloudStorageManager(Dictionary<string, ICloudStorageProvider> providers)
    {
        _providers = providers;
        SetProvider("default"); // Default provider can be configured elsewhere
    }

    public void SetProvider(string providerName)
    {
        if (_providers.ContainsKey(providerName))
            _currentProvider = _providers[providerName];
        else
            throw new ArgumentException("Invalid provider name");
    }

    public async Task UploadFileAsync(string filePath, string remotePath)
    {
        await _currentProvider.UploadFileAsync(filePath, remotePath);
    }

    public async Task DownloadFileAsync(string remotePath, string localPath)
    {
        await _currentProvider.DownloadFileAsync(remotePath, localPath);
    }

    public async Task<IEnumerable<string>> ListFilesAsync(string directoryPath)
    {
        return await _currentProvider.ListFilesAsync(directoryPath);
    }

    public async Task<bool> FileExistsAsync(string remotePath)
    {
        return await _currentProvider.FileExistsAsync(remotePath);
    }

    public async Task DeleteFileAsync(string remotePath)
    {
        await _currentProvider.DeleteFileAsync(remotePath);
