class ResourceNode {
public:
    virtual ~ResourceNode() = default;
    virtual std::string getType() const = 0;
    virtual void provision() = 0;
    virtual void scaleUp() = 0;
    virtual void scaleDown() = 0;
    virtual void monitor() = 0;
};

class AWSNode : public ResourceNode {
public:
    std::string getType() const override { return "AWS"; }
    void provision() override { /* Provision on AWS */ }
    void scaleUp() override { /* Scale up on AWS */ }
    void scaleDown() override { /* Scale down on AWS */ }
    void monitor() override { /* Monitor on AWS */ }
};

class GCPNode : public ResourceNode {
public:
    std::string getType() const override { return "GCP"; }
    void provision() override { /* Provision on GCP */ }
    void scaleUp() override { /* Scale up on GCP */ }
    void scaleDown() override { /* Scale down on GCP */ }
    void monitor() override { /* Monitor on GCP */ }
};

class AzureNode : public ResourceNode {
public:
    std::string getType() const override { return "Azure"; }
    void provision() override { /* Provision on Azure */ }
    void scaleUp() override { /* Scale up on Azure */ }
    void scaleDown() override { /* Scale down on Azure */ }
    void monitor() override { /* Monitor on Azure */ }
};

class GraphManager {
private:
    std::vector<std::shared_ptr<ResourceNode>> nodes;
    mutable std::mutex mutex_;
    std::condition_variable cv_;

public:
    void addNode(std::shared_ptr<ResourceNode> node) {
        std::lock_guard<std::mutex> lock(mutex_);
        nodes.push_back(node);
    }

    void provisionAll() {
        std::unique_lock<std::mutex> lock(mutex_);
        for (auto& node : nodes) {
            node->provision();
        }
    }

    void scaleUpNode(const std::string& type) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& node : nodes) {
            if (node->getType() == type) {
                node->scaleUp();
                break;
            }
        }
    }

    void scaleDownNode(const std::string& type) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& node : nodes) {
            if (node->getType() == type) {
                node->scaleDown();
                break;
            }
        }
    }

    void monitorAll() {
        std::unique_lock<std::mutex> lock(mutex_);
        for (auto& node : nodes) {
            node->monitor();
        }
    }
};

int main() {
    GraphManager manager;

    auto awsNode = std::make_shared<AWSNode>();
    auto gcpNode = std::make_shared<GCPNode>();
    auto azureNode = std::make_shared<AzureNode>();

    manager.addNode(awsNode);
    manager.addNode(gcpNode);
    manager.addNode(azureNode);

    manager.provisionAll();
    manager.scaleUpNode("AWS");
    manager.monitorAll();

    return 0;
}
