def stream_and_analyze_video(video_source, chunk_size=1024*1024*5):  # 5MB chunks by default
    if video_source.startswith('http'):
        response = requests.head(video_source)
        content_length = int(response.headers.get('content-length', 0))

        def download_range():
            for start in range(0, content_length, chunk_size):
                end = min(start + chunk_size - 1, content_length - 1)
                yield download_chunk(video_source, start, end)

        with ThreadPoolExecutor(max_workers=cpu_count()) as executor:
            futures = {executor.submit(process_video_chunk, chunk): chunk for chunk in download_range()}
            for future in concurrent.futures.as_completed(futures):
                try:
                    result = future.result()
                except Exception as e:
                    print(f"Error processing chunk: {e}")
    else:
        with open(video_source, 'rb') as file:
            while True:
                data = file.read(chunk_size)
                if not data:
                    break
                process_video_chunk(data)

