#include <openssl/aes.h>
#include <openssl/rand.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

#define KEY_SIZE 32
#define IV_SIZE 16

typedef enum {
    AES_MODE_ECB,
    AES_MODE_CBC,
    AES_MODE_CFB,
    AES_MODE_OFB,
    AES_MODE_CTR,
    AES_MODE_NULL
} aes_mode_t;

typedef struct {
    aes_mode_t mode;
    unsigned char key[KEY_SIZE];
    unsigned char iv[IV_SIZE];
} aes_ctx_t;

int aes_init(aes_ctx_t *ctx, aes_mode_t mode, const unsigned char *key, const unsigned char *iv) {
    if (mode == AES_MODE_NULL) {
        memset(ctx, 0, sizeof(aes_ctx_t));
        return 0;
    }

    memcpy(ctx->key, key, KEY_SIZE);
    if (iv) {
        memcpy(ctx->iv, iv, IV_SIZE);
    }
    ctx->mode = mode;

    return 1;
}

int aes_encrypt(const aes_ctx_t *ctx, const unsigned char *in, unsigned char *out, size_t len) {
    AES_KEY key;
    int ret;

    if (ctx->mode == AES_MODE_NULL) {
        memset(out, 0, len);
        return 0;
    }

    if ((ret = AES_set_encrypt_key(ctx->key, KEY_SIZE * 8, &key)) != 0) {
        return -1;
    }

    switch (ctx->mode) {
        case AES_MODE_ECB:
            for (size_t i = 0; i < len; i += AES_BLOCK_SIZE) {
                AES_ecb_encrypt(in + i, out + i, &key, AES_ENCRYPT);
            }
            break;
        case AES_MODE_CBC:
            AES_cbc_encrypt(in, out, len, &key, ctx->iv, AES_ENCRYPT);
            break;
        case AES_MODE_CFB:
            AES_cfb128_encrypt(in, out, len, &key, ctx->iv, &(ctx->iv[IV_SIZE - 1]), AES_ENCRYPT);
            break;
        case AES_MODE_OFB:
            AES_ofb128_encrypt(in, out, len, &key, ctx->iv, &(ctx->iv[IV_SIZE - 1]));
            break;
        case AES_MODE_CTR:
            AES_ctr128_encrypt(in, out, len, &key, ctx->iv, (unsigned char *)&(ctx->iv[IV_SIZE / 2]), &(ctx->iv[IV_SIZE - 1]));
            break;
        default:
            return -1;
    }

    return 0;
}

int aes_decrypt(const aes_ctx_t *ctx, const unsigned char *in, unsigned char *out, size_t len) {
    AES_KEY key;
    int ret;

    if (ctx->mode == AES_MODE_NULL) {
        memset(out, 0, len);
        return 0;
    }

    if ((ret = AES_set_decrypt_key(ctx->key, KEY_SIZE * 8, &key)) != 0) {
        return -1;
    }

    switch (ctx->mode) {
        case AES_MODE_ECB:
            for (size_t i = 0; i < len; i += AES_BLOCK_SIZE) {
                AES_ecb_encrypt(in + i, out + i, &key, AES_DECRYPT);
            }
            break;
        case AES_MODE_CBC:
            AES_cbc_encrypt(in, out, len, &key, ctx->iv, AES_DECRYPT);
            break;
        case AES_MODE_CFB:
            AES_cfb128_encrypt(in, out, len, &key, ctx->iv, &(ctx->iv[IV_SIZE - 1]), AES_DECRYPT);
            break;
        case AES_MODE_OFB:
            AES_ofb128_encrypt(in, out, len, &key, ctx->iv, &(ctx->iv[IV_SIZE - 1]));
            break;
        case AES_MODE_CTR:
            AES_ctr128_encrypt(in, out, len, &key, ctx->iv, (unsigned char *)&(ctx->iv[IV_SIZE / 2]), &(ctx->iv[IV_SIZE - 1]));
            break;
        default:
            return -1;
    }

    return 0;
}
