# Import necessary libraries
import boto3
from botocore.exceptions import NoCredentialsError
import av
import requests

class VideoProcessingService:
    def __init__(self, bucket_name):
        self.s3_client = boto3.client('s3')
        self.bucket_name = bucket_name

    def upload_video(self, file_path, object_name=None):
        if object_name is None:
            object_name = file_path.split('/')[-1]

        try:
            self.s3_client.upload_file(file_path, self.bucket_name, object_name)
            print(f"Video uploaded successfully: {object_name}")
        except FileNotFoundError:
            print("The file was not found")
        except NoCredentialsError:
            print("Credentials not available")

    def transcode_video(self, object_name):
        try:
            response = self.s3_client.get_object(Bucket=self.bucket_name, Key=object_name)
            video_container = av.open(response['Body'])

            output_container = av.open(f"{object_name}.transcoded", mode='w')
            for stream in video_container.streams.video:
                codec_context = av.CodecContext.create('libx264', 'w')
                codec_context.width = stream.width
                codec_context.height = stream.height
                codec_context.pix_fmt = 'yuv420p'
                output_stream = output_container.add_stream(codec_context)

            for frame in video_container.decode(video=0):
                packet = codec_context.encode(frame)
                if packet:
                    output_stream.mux(packet)

            for packet in codec_context.encode(None):
                output_stream.mux(packet)

            output_container.close()
            print(f"Video transcoded successfully: {object_name}.transcoded")
        except Exception as e:
            print(f"Error transcoding video: {e}")

    def extract_metadata(self, object_name):
        try:
            response = self.s3_client.get_object(Bucket=self.bucket_name, Key=object_name)
            metadata_url = "https://api.video-metadata-extraction.com/extract"

            files = {'file': response['Body']}
            metadata_response = requests.post(metadata_url, files=files)

            if metadata_response.status_code == 200:
                metadata = metadata_response.json()
                print(f"Metadata extracted successfully: {metadata}")
            else:
                print("Failed to extract metadata")
        except Exception as e:
            print(f"Error extracting metadata: {e}")

# Example usage
if __name__ == "__main__":
    service = VideoProcessingService('your-s3-bucket-name')

    # Upload video
    service.upload_video('path/to/your/video.mp4')

    # Transcode video
    service.transcode_video('video.mp4')

    # Extract metadata
    service.extract_metadata('video.transcoded')
```

