const { Readable, Writable } = require('stream');
const axios = require('axios');

class DataProcessor {
  constructor(options) {
    this.bufferSize = options.bufferSize || 1024;
    this.retryAttempts = options.retryAttempts || 3;
    this.retryDelay = options.retryDelay || 100;
    this.serviceEndpoint = options.serviceEndpoint;
    this.destinationBuffer = Buffer.alloc(this.bufferSize);
    this.transferPosition = 0;
  }

  async processStream(inputStream) {
    inputStream.on('data', chunk => this.handleData(chunk));
    inputStream.on('end', () => this.finalizeTransfer());
    inputStream.on('error', err => this.handleError(err));
  }

  async handleData(chunk) {
    if (this.transferPosition >= this.destinationBuffer.length) {
      throw new Error('Destination buffer overflow');
    }
    chunk.copy(this.destinationBuffer, this.transferPosition);
    this.transferPosition += chunk.length;
    await this.sendToService();
  }

  async sendToService() {
    try {
      for (let attempt = 0; attempt < this.retryAttempts; attempt++) {
        await axios.post(this.serviceEndpoint, this.destinationBuffer.slice(0, this.transferPosition));
        break;
      }
    } catch (error) {
      if (attempt === this.retryAttempts - 1) throw error;
      const delay = Math.pow(2, attempt + 1) * this.retryDelay;
      await new Promise(resolve => setTimeout(resolve, delay));
      return this.sendToService();
    }
  }

  finalizeTransfer() {
    console.log('Data transfer completed');
  }

  handleError(err) {
    console.error('Error during data processing:', err);
  }
}

// Usage example
const inputStream = new Readable({
  read(size) {}
});

const processor = new DataProcessor({ bufferSize: 2048, retryAttempts: 5, retryDelay: 200, serviceEndpoint: 'http://example.com/api/transform' });
processor.processStream(inputStream);
