// Node.js-based RESTful API service setup

const express = require('express');
const bodyParser = require('body-parser');
const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const app = express();
app.use(bodyParser.json());

app.post('/hash', (req, res) => {
  const filePath = req.body.filePath;
  const tempFile = '/tmp/largefile';

  // Download file from third-party storage service or handle locally
  fs.copyFile(filePath, tempFile, (err) => {
    if (err) return res.status(500).send('Error downloading file');

    const pythonScript = path.join(__dirname, 'hash_large_file.py');
    const child = spawn('python', [pythonScript, tempFile]);

    let hashResult = '';
    child.stdout.on('data', (chunk) => {
      hashResult += chunk.toString();
    });

    child.stderr.on('data', (err) => {
      res.status(500).send('Error calculating MD5 hash: ' + err);
    });

    child.on('close', (code) => {
      if (code !== 0) return;
      fs.unlinkSync(tempFile); // Clean up temporary file
      res.send({ md5Hash: hashResult });
    });
  });
});

app.listen(3000, () => {
  console.log('API server listening on port 3000');
});
