# Python module for calculating MD5 hashes of large files

import sys
import hashlib
import logging
import requests

logging.basicConfig(filename='hashing.log', level=logging.INFO)

def calculate_md5(file_path, chunk_size=65536):
    hash_md5 = hashlib.md5()
    try:
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(chunk_size), b""):
                hash_md5.update(chunk)
        return hash_md5.hexdigest()
    except Exception as e:
        logging.error(f"Error reading file or calculating MD5: {e}")
        return None

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python hash_large_file.py <file_path>")
        sys.exit(1)

    file_path = sys.argv[1]
    result = calculate_md5(file_path)
    print(result)
```

