#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <thread>
#include <future>
#include <mutex>
#include <condition_variable>
#include <openssl/sha.h>

struct LTE_ENB_TASK_CONFIG_T {
    std::string id;
    std::string configData;
};

class ConfigManager {
private:
    std::vector<LTE_ENB_TASK_CONFIG_T> configList;
    std::unordered_map<std::string, std::string> keyValueStore;
    std::mutex mutex;
    std::condition_variable cv;

public:
    void updateConfigFromAPI() {
        // Simulate fetching config from RESTful API
        LTE_ENB_TASK_CONFIG_T newConfig = {"1", "new_config_data"};
        updateConfig(newConfig);
    }

    void updateConfig(const LTE_ENB_TASK_CONFIG_T& newConfig) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = std::find_if(configList.begin(), configList.end(),
                               [&newConfig](const LTE_ENB_TASK_CONFIG_T& config) {
                                   return config.id == newConfig.id;
                               });
        if (it != configList.end()) {
            *it = newConfig; // Update existing
        } else {
            configList.push_back(newConfig); // Add new
        }
        cv.notify_all();
    }

    void processConfigs() {
        std::unique_lock<std::mutex> lock(mutex);
        while (true) {
            cv.wait(lock, [this] { return !configList.empty(); });
            for (auto& config : configList) {
                // Process each config
                validateConfig(config);
                applyConfigChanges(config);
            }
            configList.clear();
        }
    }

    void validateConfig(const LTE_ENB_TASK_CONFIG_T& config) {
        std::string hash = computeHash(config.configData);
        if (keyValueStore.find(hash) == keyValueStore.end()) {
            // Hash not found, revalidate and reload
            updateKeyValueStore(hash, "Validated");
        }
    }

    void applyConfigChanges(const LTE_ENB_TASK_CONFIG_T& config) {
        // Apply changes to system
        std::cout << "Applying config changes for task ID: " << config.id << std::endl;
    }

private:
    std::string computeHash(const std::string& data) {
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256_CTX sha256;
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, data.c_str(), data.size());
        SHA256_Final(hash, &sha256);

        std::stringstream ss;
        for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
            ss << std::hex << std::setw(2) << std::setfill('0') << (int)hash[i];
        }
        return ss.str();
    }

    void updateKeyValueStore(const std::string& hash, const std::string& status) {
        keyValueStore[hash] = status;
    }
};

int main() {
    ConfigManager manager;

    // Simulate updating config from API
    manager.updateConfigFromAPI();

