# hash_md5.py

import hashlib
import threading

class MD5Hasher:
    def __init__(self, chunk_size=65536):
        self.chunk_size = chunk_size

    def compute_hash(self, file_path):
        hasher = hashlib.md5()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(self.chunk_size), b''):
                hasher.update(chunk)
        return hasher.hexdigest()

class MD5HasherThread(threading.Thread):
    def __init__(self, file_path):
        threading.Thread.__init__(self)
        self.file_path = file_path
        self.result = None

    def run(self):
        self.result = MD5Hasher().compute_hash(self.file_path)

# Example usage:
def main():
    hasher_thread = MD5HasherThread('large_file.mp4')
    hasher_thread.start()
    hasher_thread.join()
    print(f"MD5 hash: {hasher_thread.result}")

if __name__ == "__main__":
    main()
