func NewImageProcessor() (*ImageProcessor, error) {
	sess, err := session.NewSession()
	if err != nil {
		return nil, err
	}
	s3Client := storage.New(sess)
	gcsClient := storage.New(sess)

	stripeClient := client.New(client.WithSecretKey("your_stripe_secret_key"))

	return &ImageProcessor{
		s3Client:    s3Client,
		gcsClient:   gcsClient,
		stripeClient: stripeClient,
	}, nil
}

func (ip *ImageProcessor) UploadImage(ctx context.Context, storageType string, bucketName string, imagePath string) error {
	switch storageType {
	case "s3":
		return ip.uploadToS3(ctx, bucketName, imagePath)
	case "gcs":
		return ip.uploadToGCS(ctx, bucketName, imagePath)
	default:
		return fmt.Errorf("unsupported storage type: %s", storageType)
	}
}

func (ip *ImageProcessor) uploadToS3(ctx context.Context, bucketName string, imagePath string) error {
	bucket := ip.s3Client.Bucket(bucketName)
	object := bucket.Object(imagePath)

	w := object.NewWriter(ctx)
	defer w.Close()

	f, err := os.Open(imagePath)
	if err != nil {
		return err
	}
	defer f.Close()

	if _, err = io.Copy(w, f); err != nil {
		return err
	}

	return nil
}

