// Define the structure for UE context
struct UERadioBearer {
    int bearerID;
    int QoSParameters;
    bool connectionStatus;
};

class UEContext {
public:
    int cellIdentity;
    std::unordered_map<int, UERadioBearer> RABs;

    void addRAB(int bearerID, int QoSParameters) {
        RABs[bearerID] = {bearerID, QoSParameters, false};
    }

    void removeRAB(int bearerID) {
        RABs.erase(bearerID);
    }
};

class UEMutex {
private:
    std::mutex m_mutex;

public:
    void lock() {
        m_mutex.lock();
    }

    void unlock() {
        m_mutex.unlock();
    }

    template<typename T>
    friend bool try_lock(UEMutex& mutex, T& value) {
        return mutex.m_mutex.try_lock();
    }
};

class UEContextManager {
private:
    std::unordered_map<int, UEContext> m_UEs;
    UEMutex m_mutex;

public:
    void addUE(int cellIdentity) {
        UEMutex::lock(m_mutex);
        m_UEs[cellIdentity] = {cellIdentity};
        UEMutex::unlock(m_mutex);
    }

    void removeUE(int cellIdentity) {
        UEMutex::lock(m_mutex);
        m_UEs.erase(cellIdentity);
        UEMutex::unlock(m_mutex);
    }

    void updateRAB(int cellIdentity, int bearerID, int QoSParameters, bool connectionStatus) {
        UEMutex::lock(m_mutex);
        if (m_UEs.find(cellIdentity) != m_UEs.end()) {
            m_UEs[cellIdentity].RABs[bearerID] = {bearerID, QoSParameters, connectionStatus};
        }
        UEMutex::unlock(m_mutex);
    }
};

int main() {
    UEContextManager manager;
    manager.addUE(12345);
    manager.updateRAB(12345, 1, 10, true);
    manager.removeUE(12345);
    return 0;
}
