    void start() {
        running = true;
        worker_thread = std::thread(&UeContextManager::processQueue, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            running = false;
        }
        condition.notify_all();
        if (worker_thread.joinable()) {
            worker_thread.join();
        }
    }

    void enqueue(UeContext& context) {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            task_queue.push(context);
        }
        condition.notify_one();
    }

private:
    void processQueue() {
        while (true) {
            UeContext context;
            {
                std::unique_lock<std::mutex> lock(queue_mutex);
                condition.wait(lock, [this] { return !task_queue.empty() || !running; });
                if (!running && task_queue.empty()) {
                    break;
                }
                context = task_queue.front();
                task_queue.pop();
