class file_processing_engine {
public:
    file_processing_engine(int num_threads) : stop(false), thread_count(num_threads) {
        for (int i = 0; i < num_threads; ++i) {
            workers.emplace_back(&file_processing_engine::worker_thread, this);
        }
    }

    ~file_processing_engine() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void process_file(const std::string& file_path, const std::string& tenant_id) {
        std::unique_lock<std::mutex> lock(mutex);
        tasks.push({file_path, tenant_id});
        condition.notify_one();
    }

private:
    struct Task {
        std::string file_path;
        std::string tenant_id;
    };

    void worker_thread() {
        while (true) {
            Task task;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this] { return stop || !tasks.empty(); });
                if (stop && tasks.empty()) {
                    return;
                }
                task = tasks.front();
                tasks.pop();
            }
            process_task(task.file_path, task.tenant_id);
        }
    }

    void process_task(const std::string& file_path, const std::string& tenant_id) {
        FileProcessor processor(file_path, tenant_id);
        processor.process();

        ExternalService service(tenant_id);
        service.notify_completion(processor.get_hash());
    }

    std::queue<Task> tasks;
    std::vector<std::thread> workers;
    std::mutex mutex;
    std::condition_variable condition;
    bool stop;
    int thread_count;
};

