use sysinfo::{ProcessExt, ProcessRefreshKind, System, SystemExt};

fn measure_rust_compiler_performance() -> i32 {
    // Define the path to the Rust compiler
    let rustc_path = "rustc";

    // Capture the start time and system information before compilation
    let start_time = Instant::now();
    let mut sys = System::new_all();
    sys.refresh_memory();

    // Run the Rust compiler as a subprocess
    let mut child = Command::new(rustc_path)
        .arg("--version")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("Failed to spawn Rust compiler");

    // Get the initial process information
    let pid = child.id().unwrap();
    let start_memory_usage = sys.process(pid).map_or(0, |proc| proc.memory());

    // Wait for the subprocess to finish and capture its exit status
    let status = child.wait_with_output().expect("Failed to read output of Rust compiler");

    // Get the final process information
    sys.refresh_memory();
    let end_memory_usage = sys.process(pid).map_or(0, |proc| proc.memory());

    // Calculate the time taken for compilation and memory usage change
    let elapsed_time = start_time.elapsed().as_secs_f64();
    let memory_change = end_memory_usage - start_memory_usage;

    // Log the results
    println!("Rust compiler performance:");
    println!("Elapsed time: {:.2} seconds", elapsed_time);
    println!("Memory usage change: {} bytes", memory_change);

    // Return the exit status of the subprocess
    status.status.code().unwrap_or(-1)
}
