std::string generateSecureToken(size_t length) {
    std::string token;
    token.resize(length);
    if (RAND_bytes(reinterpret_cast<unsigned char*>(token.data()), length) != 1) {
        throw std::runtime_error("Failed to generate secure token");
    }
    return token;
}

