const express = require('express');
const bodyParser = require('body-parser');
const mongoose = require('mongoose');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const redis = require('redis');
const CircuitBreaker = require('opossum');

const app = express();
app.use(bodyParser.json());

// Connect to MongoDB
mongoose.connect('mongodb://user:password@localhost:27017/userdb', {
  useNewUrlParser: true,
  useUnifiedTopology: true,
});

// Define User model
const UserSchema = new mongoose.Schema({
  name: String,
  email: { type: String, unique: true },
  password: String,
  roles: [String],
});
const User = mongoose.model('User', UserSchema);

// Connect to Redis for caching
const redisClient = redis.createClient();
redisClient.on('error', (err) => {
  console.error('Redis error:', err);
});

// Circuit breaker for third-party identity provider
const identityProviderCB = new CircuitBreaker((req, res, next) => {
  // Simulate async operation to third-party service
  setTimeout(() => {
    next();
  }, 100);
}, {
  timeout: 500,
  errorThresholdPercentage: 25,
  resetTimeout: 30000,
});

// Middleware for authentication
const authenticate = (req, res, next) => {
  const token = req.headers['authorization'];
  if (!token) return res.status(403).send('No token provided');

  jwt.verify(token, 'secretKey', (err, decoded) => {
    if (err) return res.status(500).send('Failed to authenticate token');
    req.userId = decoded.id;
    next();
  });
};

// User creation
app.post('/users', async (req, res) => {
  const { name, email, password } = req.body;
  try {
    let user = await User.findOne({ email });
    if (user) return res.status(400).send('Email already in use');

    user = new User({ name, email, password: await bcrypt.hash(password, 10) });
    await user.save();

    const token = jwt.sign({ id: user.id }, 'secretKey', { expiresIn: 86400 });
    res.send({ token });
  } catch (error) {
    res.status(500).send(error);
  }
});

// User update
app.put('/users/:id', authenticate, async (req, res) => {
  const { name, email } = req.body;
  try {
    let user = await User.findById(req.params.id);
    if (!user) return res.status(404).send('User not found');

    user.name = name || user.name;
    user.email = email || user.email;

    await user.save();
    res.send(user);
  } catch (error) {
    res.status(500).send(error);
  }
});

// User deletion
app.delete('/users/:id', authenticate, async (req, res) => {
  try {
    const user = await User.findByIdAndDelete(req.params.id);
    if (!user) return res.status(404).send('User not found');
    res.send(user);
  } catch (error) {
    res.status(500).send(error);
  }
});

// Start server
app.listen(3000, () => {
  console.log('Server started on port 3000');
});
