import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.connectors.kafka.FlinkKafkaConsumer;
import org.apache.flink.streaming.api.functions.sink.SinkFunction;
import software.amazon.awssdk.regions.Region;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.PutObjectRequest;

import java.util.Properties;

public class LogProcessingPipeline {

    public static void main(String[] args) throws Exception {
        final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // Configure Kafka consumer properties
        Properties kafkaProps = new Properties();
        kafkaProps.setProperty("bootstrap.servers", "kafka-broker:9092");
        kafkaProps.setProperty("group.id", "log-processing-group");

        FlinkKafkaConsumer<String> kafkaConsumer = new FlinkKafkaConsumer<>("iot-logs-topic", new SimpleStringSchema(), kafkaProps);
        kafkaConsumer.setStartFromLatest();

        // Add the Kafka consumer to the data stream
        env.addSource(kafkaConsumer)
            .filter(log -> log != null && !log.isEmpty())
            .map(LogEntry::fromString) // Assuming LogEntry is a custom class representing a log entry
            .keyBy(LogEntry::getDeviceId)
            .process(new LogAggregator()) // Assuming LogAggregator is a custom process function for aggregation
            .addSink(new S3Sink());

        env.execute("Real-time IoT Log Processing Pipeline");
    }

    static class S3Sink implements SinkFunction<LogSummary> {
        private final S3Client s3 = S3Client.builder()
                .region(Region.US_EAST_1)
                .build();

        @Override
        public void invoke(LogSummary value, Context context) throws Exception {
            PutObjectRequest request = PutObjectRequest.builder()
                    .bucket("iot-log-bucket")
                    .key(value.getDeviceId() + "_" + context.currentProcessingTime())
                    .build();
            s3.putObject(request, () -> new ByteArrayInputStream(value.toString().getBytes()));
        }
    }
}
```

This code snippet outlines the basic structure of a scalable, cloud-native data processing pipeline in Java. It uses Apache Flink for stream processing and Amazon S3 for storing processed log summaries. The pipeline ingests real-time log data from IoT devices via Kafka, processes it to aggregate logs by device, and stores the results in S3. This setup leverages AWS Lambda, S3, and CloudWatch as per the operational constraints.']

