#include <iostream>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <queue>
#include <atomic>
#include <chrono>
#include <functional>
#include <openssl/md5.h>

class FileMetadataCache {
private:
    std::unordered_map<std::string, std::pair<int, unsigned char*>> cache;
    std::mutex cache_mutex;
    std::condition_variable cache_cv;

    std::unordered_map<std::string, int> access_frequency;
    std::mutex frequency_mutex;

    std::queue<std::string> lru_queue;
    std::mutex lru_mutex;

    std::atomic<bool> running;
    std::thread worker_thread;

    void worker() {
        while (running) {
            std::unique_lock<std::mutex> lock(cache_mutex);
            cache_cv.wait(lock, [this] { return !cache.empty(); });
            auto key = lru_queue.front();
            lru_queue.pop();
            delete[] cache[key].second;
            cache.erase(key);
        }
    }

public:
    FileMetadataCache() : running(true) {
        worker_thread = std::thread(&FileMetadataCache::worker, this);
    }

    ~FileMetadataCache() {
        running = false;
        cache_cv.notify_all();
        worker_thread.join();
    }

    void add_metadata(const std::string& key, const unsigned char* data, size_t size) {
        std::lock_guard<std::mutex> lock(cache_mutex);
        if (cache.size() >= 5000000) {
            delete[] cache[lru_queue.front()].second;
            cache.erase(lru_queue.front());
            lru_queue.pop();
        }
        cache[key] = {1, new unsigned char[size]};
        std::copy(data, data + size, cache[key].second);
        lru_queue.push(key);

        std::lock_guard<std::mutex> freq_lock(frequency_mutex);
        access_frequency[key]++;
    }

    bool get_metadata(const std::string& key, unsigned char*& data, size_t& size) {
        std::unique_lock<std::mutex> lock(cache_mutex);
        auto it = cache.find(key);
        if (it == cache.end()) return false;

        ++access_frequency[key];
        lru_queue.erase(std::remove(lru_queue.begin(), lru_queue.end(), key), lru_queue.end());
        lru_queue.push(key);

        data = it->second.second;
        size = std::strlen(reinterpret_cast<char*>(data));
        cache_cv.notify_all();
        return true;
    }
};

int main() {
    FileMetadataCache cache;

    // Example usage
    unsigned char metadata[] = "Example Metadata";
    cache.add_metadata("example_key", metadata, sizeof(metadata));

    unsigned char* retrieved_metadata;
    size_t size;
    if (cache.get_metadata("example_key", retrieved_metadata, size)) {
        std::cout << "Retrieved metadata: " << retrieved_metadata << std::endl;
    } else {
        std::cout << "Metadata not found" << std::endl;
    }

    return 0;
}
```']

