#include <iostream>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <thread>
#include <memory>
#include <functional>

// Forward declarations
class UserEquipment;
class RadioAccessBearer;

// Singleton pattern for the UE pool manager
class UEModularPoolManager {
public:
    static UEModularPoolManager& getInstance() {
        static UEModularPoolManager instance;
        return instance;
    }

    // Add a new UE context to the pool
    void addUEContext(const std::string& ci, const UserEquipment& ue) {
        std::lock_guard<std::mutex> lock(mutex_);
        ue_pool_[ci] = ue;
        cv_.notify_all();
    }

    // Remove an UE context from the pool
    void removeUEContext(const std::string& ci) {
        std::lock_guard<std::mutex> lock(mutex_);
        ue_pool_.erase(ci);
        cv_.notify_all();
    }

    // Update an existing UE context in the pool
    void updateUEContext(const std::string& ci, const UserEquipment& ue) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (ue_pool_.find(ci) != ue_pool_.end()) {
            ue_pool_[ci] = ue;
            cv_.notify_all();
        }
    }

    // Get an UE context from the pool
    std::optional<UserEquipment> getUEContext(const std::string& ci) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (ue_pool_.find(ci) != ue_pool_.end()) {
            return ue_pool_[ci];
        }
        return std::nullopt;
    }

private:
    UEModularPoolManager() = default;
    UEModularPoolManager(const UEModularPoolManager&) = delete;
    UEModularPoolManager& operator=(const UEModularPoolManager&) = delete;

    std::mutex mutex_;
    std::condition_variable cv_;
    std::unordered_map<std::string, UserEquipment> ue_pool_;
};

// Class representing a User Equipment context
class UserEquipment {
public:
    UserEquipment(std::string ci) : cell_identity_(ci) {}

    // Add a new RAB to the UE context
    void addRAB(const RadioAccessBearer& rab) {
        rabs_.push_back(rab);
    }

    // Remove an existing RAB from the UE context
    void removeRAB(int bearer_id) {
        auto it = std::remove_if(rabs_.begin(), rabs_.end(),
                                [bearer_id](const RadioAccessBearer& rab) { return rab.bearerId() == bearer_id; });
        if (it != rabs_.end()) {
            rabs_.erase(it, rabs_.end());
        }
    }

    // Update an existing RAB in the UE context
    void updateRAB(int bearer_id, const RadioAccessBearer& updated_rab) {
        for (auto& rab : rabs_) {
            if (rab.bearerId() == bearer_id) {
                rab = updated_rab;
                break;
            }
        }
    }

    // Get all RABS associated with the UE context
    const std::vector<RadioAccessBearer>& getRABs() const {
        return rabs_;
    }

    // Get the cell identity of the UE context
    const std::string& cellIdentity() const {
        return cell_identity_;
    }

private:
    std::string cell_identity_;
    std::vector<RadioAccessBearer> rabs_;
};

// Class representing a Radio Access Bearer
class RadioAccessBearer {
public:
    RadioAccessBearer(int bearer_id, int qos, bool connected)
        : bearer_id_(bearer_id), qos_(qos), connected_(connected) {}

    // Get the bearer ID of the RAB
    int bearerId() const {
        return bearer_id_;
    }

    // Get the QoS parameters of the RAB
    int qosParameters() const {
        return qos_;
    }

    // Check if the RAB is connected
    bool isConnected() const {
        return connected_;
    }

private:
    int bearer_id_;
    int qos_;
    bool connected_;
};

// Example usage
int main() {
    UserEquipment ue("12345");
    ue.addRAB(RadioAccessBearer(1, 10, true));
    ue.addRAB(RadioAccessBearer(2, 20, false));

    UEModularPoolManager::getInstance().addUEContext("12345", ue);

    // Retrieve and update the UE context
    if (auto ue_context = UEModularPoolManager::getInstance().getUEContext("12345")) {
        ue_context->updateRAB(1, RadioAccessBearer(1, 10, false));
    }

    return 0;
}
