import hashlib
import os
import threading
from celery import Celery, Task, chord
from celery.signals import task_prerun, task_postrun
from redis import Redis
import requests
import time
import psutil

# Initialize Flask app and Celery
app = Flask(__name__)
app.config['CELERY_BROKER_URL'] = 'redis://localhost:6379/0'
app.config['CELERY_RESULT_BACKEND'] = 'redis://localhost:6379/0'
celery = Celery(app.name, broker=app.config['CELERY_BROKER_URL'], backend=app.config['CELERY_RESULT_BACKEND'])

# Initialize Redis cache
cache = Redis(host='localhost', port=6379, db=1)

# Define task for hashing files
@celery.task(bind=True)
def hash_file(self, file_path):
    if os.path.exists(file_path):
        try:
            md5_hash = hashlib.md5()
            with open(file_path, 'rb') as f:
                for chunk in iter(lambda: f.read(4096), b''):
                    md5_hash.update(chunk)
            return md5_hash.hexdigest()
        except Exception as e:
            self.update_state(state='FAILURE', meta={'error': str(e)})
    else:
        self.update_state(state='FAILURE', meta={'error': 'File not found'})
    return None

# Define route for file hash computation
@app.route('/hash', methods=['POST'])
def compute_hash():
    if 'file' in request.files or request.form.get('url'):
        file_path = None
        if 'file' in request.files:
            file = request.files['file']
            if file.filename == '':
                return jsonify({'error': 'No selected file'}), 400
            if file and allowed_file(file.filename):
                file_path = os.path.join('/tmp', secure_filename(file.filename))
                file.save(file_path)
        elif request.form.get('url'):
            url = request.form['url']
            try:
                response = requests.get(url, stream=True)
                response.raise_for_status()
                file_path = '/tmp/temp_file'
                with open(file_path, 'wb') as f:
                    for chunk in response.iter_content(chunk_size=4096):
                        f.write(chunk)
            except requests.RequestException as e:
                return jsonify({'error': str(e)}), 500

        if file_path:
            task = hash_file.delay(file_path)
            return jsonify({'task_id': task.id}), 202
    return jsonify({'error': 'Invalid input'}), 400

# Define health check route
@app.route('/health', methods=['GET'])
def health_check():
    # Add your health check logic here
    return jsonify({'status': 'OK'}), 200

# Define allowed file extensions
ALLOWED_EXTENSIONS = {'txt', 'pdf', 'png', 'jpg', 'jpeg', 'gif'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

if __name__ == '__main__':
    app.run(debug=True)
