from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

class FileProcessor:
    def __init__(self):
        self.md5_hash = hashlib.md5()
        self.sha256_hash = hashlib.sha256()

    def update_hashes(self, data):
        self.md5_hash.update(data)
        self.sha256_hash.update(data)

    def get_md5(self):
        return self.md5_hash.hexdigest()

    def get_sha256(self):
        return self.sha256_hash.hexdigest()

class URLProcessor(FileProcessor):
    def __init__(self, url):
        super().__init__()
        self.url = url

    def process(self):
        response = requests.get(self.url)
        if response.status_code == 200:
            self.update_hashes(response.content)

class S3Processor(FileProcessor):
    def __init__(self, bucket_name, object_key):
        super().__init__()
        self.s3_client = boto3.client('s3')
        self.bucket_name = bucket_name
        self.object_key = object_key

    def process(self):
        try:
            response = self.s3_client.get_object(Bucket=self.bucket_name, Key=self.object_key)
            self.update_hashes(response['Body'].read())
        except (NoCredentialsError, PartialCredentialsError) as e:
            print(f"Credentials error: {e}")

class FileEventHandler(FileSystemEventHandler):
    def __init__(self, processor):
        self.processor = processor

    def on_created(self, event):
        if not event.is_directory:
            with open(event.src_path, 'rb') as f:
                chunk_size = 8192
                while chunk := f.read(chunk_size):
                    self.processor.update_hashes(chunk)
            print(f"Processed file: {event.src_path}")

class DynamicFileProcessor:
    def __init__(self, observers, processors):
        self.observers = observers
        self.processors = processors

    def start_observers(self):
        for observer in self.observers:
            observer.start()

    def stop_observers(self):
        for observer in self.observers:
            observer.stop()
            observer.join()

    def process_files(self):
        with concurrent.futures.ThreadPoolExecutor() as executor:
            futures = [executor.submit(processor.process) for processor in self.processors]
            concurrent.futures.wait(futures)

def main():
    # Initialize processors
    url_processor = URLProcessor('http://example.com/file.txt')
    s3_processor = S3Processor('my-bucket', 'path/to/file.txt')

    # Initialize observers
    event_handler = FileEventHandler(url_processor)
    observer = Observer()
    observer.schedule(event_handler, path='/path/to/watch', recursive=False)

    # Initialize DynamicFileProcessor
    dynamic_file_processor = DynamicFileProcessor([observer], [url_processor, s3_processor])

    try:
        dynamic_file_processor.start_observers()
        dynamic_file_processor.process_files()
    except KeyboardInterrupt:
        pass
    finally:
        dynamic_file_processor.stop_observers()

if __name__ == '__main__':
    main()
