import hashlib
import os
import requests
from concurrent.futures import ThreadPoolExecutor
from botocore.client import Session
from rq import Queue, Connection
from redis import Redis
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

class FileProcessor:
    def __init__(self):
        self.executor = ThreadPoolExecutor(max_workers=5)
        self.redis_client = Redis()
        self.queue = Queue(connection=Connection(self.redis_client))

    def compute_md5(self, file_path):
        md5_hash = hashlib.md5()
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                md5_hash.update(chunk)
        return md5_hash.hexdigest()

    def compute_sha256(self, file_path):
        sha256_hash = hashlib.sha256()
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                sha256_hash.update(chunk)
        return sha256_hash.hexdigest()

    def process_file(self, file_path):
        self.executor.submit(self.compute_and_store_hashes, file_path)

    def compute_and_store_hashes(self, file_path):
        md5 = self.compute_md5(file_path)
        sha256 = self.compute_sha256(file_path)
        self.redis_client.set(f"md5:{file_path}", md5)
        self.redis_client.set(f"sha256:{file_path}", sha256)

class URLProcessor:
    def __init__(self):
        self.executor = ThreadPoolExecutor(max_workers=5)

    def compute_md5(self, url):
        response = requests.get(url, stream=True)
        md5_hash = hashlib.md5()
        for chunk in response.iter_content(chunk_size=4096):
            if chunk:
                md5_hash.update(chunk)
        return md5_hash.hexdigest()

    def compute_sha256(self, url):
        response = requests.get(url, stream=True)
