# Inventory Management
@app.route('/update_inventory', methods=['POST'])
def update_inventory():
    data = request.json
    product_id, quantity = data['product_id'], data['quantity']
    current_stock = redis_client.get(f'inventory:{product_id}')
    if current_stock:
        new_stock = int(current_stock) + quantity
        redis_client.set(f'inventory:{product_id}', new_stock)
    else:
        redis_client.set(f'inventory:{product_id}', quantity)
    return jsonify({'message': 'Inventory updated successfully'})

