import hashlib
import requests
from threading import Lock
from queue import Queue
from concurrent.futures import ThreadPoolExecutor
import logging

# Configuration settings
HASH_ALGORITHM = 'md5'  # or 'sha256'
CHUNK_SIZE = 4096  # bytes

# Distributed database connection (simplified example)
class DistributedDB:
    def store_metadata(self, file_path, metadata):
        pass

# External REST API client (simplified example)
class MetadataAPI:
    @staticmethod
    def get_metadata(file_path):
        try:
            response = requests.get(f"https://api.example.com/metadata?file={file_path}")
            return response.json()
        except requests.RequestException as e:
            logging.error(f"Metadata API request failed: {e}")
            return None

# File processing class
class FileProcessor:
    def __init__(self, db_connection, api_client):
        self.db_connection = db_connection
        self.api_client = api_client
        self.file_queue = Queue()
        self.lock = Lock()

    def enqueue_file(self, file_path):
        self.file_queue.put(file_path)

    def process_files(self, num_threads=5):
        with ThreadPoolExecutor(max_workers=num_threads) as executor:
            while not self.file_queue.empty():
                file_path = self.file_queue.get()
                executor.submit(self.process_file, file_path)
                self.file_queue.task_done()

    def process_file(self, file_path):
        try:
            metadata = MetadataAPI.get_metadata(file_path)
            if metadata is None:
                # Fallback mechanism for metadata extraction
                metadata = {"file_name": file_path}

            hash_value = self.calculate_hash(file_path, HASH_ALGORITHM)
            lock.acquire()
            try:
                self.db_connection.store_metadata(file_path, {
                    "hash": hash_value,
                    **metadata
                })
            finally:
                lock.release()

        except Exception as e:
            logging.error(f"Error processing file {file_path}: {e}")

    def calculate_hash(self, file_path, algorithm):
        hasher = hashlib.new(algorithm)
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(CHUNK_SIZE), b''):
                hasher.update(chunk)
        return hasher.hexdigest()

# Example usage
if __name__ == "__main__":
    db_connection = DistributedDB()
    api_client = MetadataAPI()
    processor = FileProcessor(db_connection, api_client)

    # Enqueue files for processing
    processor.enqueue_file('/path/to/file1')
    processor.enqueue_file('/path/to/file2')

    # Process files in parallel
    processor.process_files(num_threads=3)
