#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netdb.h>

int resolve_hostname_to_ip(const char *hostname, char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return 1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char *ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ip_address, INET6_ADDRSTRLEN);
        printf("  %s: %s\n", ipver, ip_address);
    }

    freeaddrinfo(res); // free the linked list

    return 0;
}

int main() {
    char hostname[256];
    char ip_address[INET6_ADDRSTRLEN];

    printf("Enter a hostname to resolve: ");
    fgets(hostname, sizeof(hostname), stdin);
    hostname[strcspn(hostname, "\n")] = '\0'; // remove newline character

    if (resolve_hostname_to_ip(hostname, ip_address) == 0) {
        printf("IP Address: %s\n", ip_address);
    }

    return 0;
}
```

This C function `resolve_hostname_to_ip` takes a hostname as input and attempts to resolve it to an IP address using standard library functions (`getaddrinfo`, `inet_ntop`). It handles errors gracefully by printing an error message if the resolution fails. The function supports both IPv4 and IPv6 addresses and uses dynamic memory allocation with `malloc` and `freeaddrinfo` for managing the linked list of results.']

