import java.net.HttpURLConnection;
import java.net.URL;
import java.security.MessageDigest;
import java.util.concurrent.*;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

public class FileProcessingPipeline {

    private static final String API_URL = "https://metadata-api.example.com";
    private static final String DATABASE_URL = "jdbc:mysql://db-host:3306/file_db";
    private static final String SECRET_KEY = "your-secret-key";

    public static void main(String[] args) {
        ExecutorService executorService = Executors.newFixedThreadPool(10);
        BlockingQueue<File> fileQueue = new LinkedBlockingQueue<>();

        // Start processing files
        for (int i = 0; i < 5; i++) {
            executorService.submit(new FileProcessor(fileQueue));
        }

        // Simulate receiving files
        for (int i = 0; i < 20; i++) {
            try {
                File file = new File("path/to/file" + i);
                fileQueue.put(file);
                Thread.sleep(100);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        executorService.shutdown();
    }

    static class FileProcessor implements Runnable {
        private final BlockingQueue<File> queue;

        public FileProcessor(BlockingQueue<File> queue) {
            this.queue = queue;
        }

        @Override
        public void run() {
            while (true) {
                try {
                    File file = queue.take();
                    processFile(file);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        private void processFile(File file) {
            try {
                // Extract metadata from API
                String metadata = getMetadataFromAPI(file);

                // Calculate MD5 and SHA256 hashes
                String md5Hash = calculateMD5(file);
                String sha256Hash = calculateSHA256(file);

                // Store results in database
                storeInDatabase(metadata, md5Hash, sha256Hash, file.getAbsolutePath());
            } catch (IOException | InterruptedException e) {
                handleException(e, file);
            }
        }

        private String getMetadataFromAPI(File file) throws IOException, InterruptedException {
            URL url = new URL(API_URL + "/metadata");
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("POST");
            connection.setDoOutput(true);

            try (OutputStream os = connection.getOutputStream()) {
                byte[] input = file.getAbsolutePath().getBytes("utf-8");
                os.write(input, 0, input.length);
                os.flush();
            }

            int responseCode = connection.getResponseCode();
            if (responseCode != HttpURLConnection.HTTP_OK) {
                throw new IOException("Failed to get metadata: " + responseCode);
            }

            try (BufferedReader br = new BufferedReader(new InputStreamReader(connection.getInputStream(), "utf-8"))) {
                StringBuilder response = new StringBuilder();
                String responseLine;
                while ((responseLine = br.readLine()) != null) {
                    response.append(responseLine.trim());
                }
                return response.toString();
            } finally {
                connection.disconnect();
            }
        }

        private String calculateMD5(File file) throws IOException {
            try (InputStream is = new FileInputStream(file)) {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] buffer = new byte[8192];
                int bytesRead;
                while ((bytesRead = is.read(buffer)) != -1) {
                    md.update(buffer, 0, bytesRead);
                }
                return bytesToHex(md.digest());
            }
        }

        private String calculateSHA256(File file) throws IOException {
            try (InputStream is = new FileInputStream(file)) {
                MessageDigest md = MessageDigest.getInstance("SHA-256");
                byte[] buffer = new byte[8192];
                int bytesRead;
                while ((bytesRead = is.read(buffer)) != -1) {
                    md.update(buffer, 0, bytesRead);
                }
                return bytesToHex(md.digest());
            }
        }

        private String bytesToHex(byte[] hash) {
            StringBuilder hexString = new StringBuilder();
            for (byte b : hash) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        }

        private void storeInDatabase(String metadata, String md5Hash, String sha256Hash, String filePath) throws IOException {
            // Use JDBC to connect and insert data into database
            // Example: PreparedStatement ps = connection.prepareStatement("INSERT INTO file_data (metadata, md5_hash, sha256_hash, file_path) VALUES (?, ?, ?, ?)");
        }

        private void handleException(Exception e, File file) {
            // Log the exception and retry or fail the process
            System.err.println("Error processing file " + file.getAbsolutePath() + ": " + e.getMessage());
            // Retry mechanism or fail gracefully
        }
    }
}
