// DynamicContentLoader.js

class DynamicContentLoader {
  constructor(config) {
    this.config = config;
    this.cache = {};
  }

  async fetchContent(apiUrl, headers = {}) {
    const cachedData = this.cache[apiUrl];
    if (cachedData && Date.now() - cachedData.timestamp < this.config.cacheDuration) {
      return cachedData.data;
    }

    try {
      const response = await fetch(apiUrl, { headers });
      if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
      const data = await response.json();
      this.cache[apiUrl] = { data, timestamp: Date.now() };
      return data;
    } catch (error) {
      console.error('Fetch failed:', error);
      // Implement retry logic and backoff strategy here
      throw error;
    }
  }

  async renderContent(containerId, content) {
    const container = document.getElementById(containerId);
    if (!container) throw new Error(`Container with id ${containerId} not found`);

    container.innerHTML = '';
    content.forEach(item => {
      const element = document.createElement('div');
      // Customize rendering logic based on the content structure
      element.textContent = item.title;
      container.appendChild(element);
    });
  }

  async updateContent(apiUrl, containerId) {
    try {
      const data = await this.fetchContent(apiUrl, this.config.requestHeaders);
      await this.renderContent(containerId, data);
    } catch (error) {
      console.error('Update failed:', error);
      // Provide user-friendly notifications here
    }
  }

  startScheduledUpdates(apiUrl, containerId, interval) {
    setInterval(() => this.updateContent(apiUrl, containerId), interval);
  }
}

// Usage example
const config = {
  apiUrl: 'https://api.example.com/content',
  requestHeaders: { 'Authorization': 'Bearer your_token' },
  cacheDuration: 3600000 // 1 hour in milliseconds
};

const loader = new DynamicContentLoader(config);
loader.updateContent('content-container', 'main');
loader.startScheduledUpdates('https://api.example.com/content', 'content-container', 5 * 60 * 1000); // every 5 minutes
```

