import os
import hashlib
import requests
from time import sleep
from functools import wraps
from concurrent.futures import ThreadPoolExecutor, as_completed

# Function to generate a secure sessionId using UUID
def generate_session_id():
    return str(uuid.uuid4())

# Decorator for handling OAuth2 token validation
def validate_token(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        token = kwargs.get('token')
        if not token or token['token_type'] != 'Bearer' or not isinstance(token['expires_in'], int) or token['expires_in'] <= 0:
            raise ValueError("Invalid OAuth2 token")
        return func(*args, **kwargs)
    return wrapper

# Function to calculate MD5 hash of a file
def calculate_md5(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        buf = f.read(65536)  # Read in chunks to handle large files
        while len(buf) > 0:
            hasher.update(buf)
            buf = f.read(65536)
    return hasher.hexdigest()

# Function to monitor directory for file changes and calculate MD5 hashes
@validate_token
def monitor_directory(token, directory_path):
    executor = ThreadPoolExecutor(max_workers=10)
    futures = {executor.submit(calculate_md5, file): file for file in os.listdir(directory_path)}

    while True:
        done, not_done = as_completed(futures), []
        for future in done:
            try:
                md5_hash = future.result()
                report_to_external_platform(md5_hash, token)
            except Exception as e:
                print(f"Error processing file: {e}")

        sleep(10)  # Check every 10 seconds

# Function to report MD5 hash to external monitoring platform
def report_to_external_platform(md5_hash, token):
    url = "https://example.com/api/report"
    headers = {
        'Authorization': f'Bearer {token["access_token"]}',
        'Content-Type': 'application/json'
    }
    data = {
        'md5_hash': md5_hash
    }
    response = requests.post(url, headers=headers, json=data)
    if response.status_code != 200:
        raise Exception("Failed to report MD5 hash")

# Example usage
token = {'access_token': 'example_token', 'token_type': 'Bearer', 'expires_in': 3600}
monitor_directory(token, '/path/to/directory')
