# Python component for file monitoring and MD5 hashing
import os
import hashlib
import asyncio
from aiofiles import open as aiopen

async def calculate_md5(file_path):
    hash_md5 = hashlib.md5()
    async with aiopen(file_path, 'rb') as f:
        chunk = await f.read(4096)
        while chunk:
            hash_md5.update(chunk)
            chunk = await f.read(4096)
    return hash_md5.hexdigest()

async def monitor_directory(directory):
    last_hashes = {}
    while True:
        current_hashes = {f: calculate_md5(os.path.join(directory, f)) for f in os.listdir(directory)}
        new_files = [f for f in current_hashes if f not in last_hashes]
        removed_files = [f for f in last_hashes if f not in current_hashes]

        # Handle new files
        for file in new_files:
            hash_value = await calculate_md5(os.path.join(directory, file))
            report_to_external_platform(file, hash_value)

        # Handle removed files
        for file in removed_files:
            report_to_external_platform(file, None)

        last_hashes = current_hashes
        await asyncio.sleep(1)  # Adjust the polling interval as needed

