    await redisClient.set(sessionId, 'session_active', 'EX', 3600);  // Set expiration to 1 hour
    return sessionId;
}

app.post('/login', async (req, res) => {
    const { token } = req.body;
    if (!token || !token.startsWith('Bearer ') || isNaN(parseInt(token.split('.')[2]))) {
        return res.status(400).send('Invalid token');
    }

    try {
        await generateSessionId();
        res.send({ sessionId: await redisClient.get('sessionId') });
    } catch (error) {
        res.status(500).send('Error generating session ID');
    }
});

app.listen(3000, () => console.log('Server is running on port 3000'));
