        if (uePool.find(cellIdentity) == uePool.end()) {
            uePool[cellIdentity] = std::make_shared<UserEquipment>(cellIdentity);
        }
    }

    void removeUserEquipment(int cellIdentity) {
        std::lock_guard<std::mutex> lock(mutex);
        if (uePool.find(cellIdentity) != uePool.end()) {
            uePool.erase(cellIdentity);
        }
    }

    void updateRabStatus(int cellIdentity, const std::string& bearerID, bool connected) {
