// dataLoader.js

const axios = require('axios');
const { v4: uuidv4 } = require('uuid');
const LRU = require('lru-cache');

class DataLoader {
  constructor() {
    this.cache = new LRU({ max: 500, ttl: 60 * 1000 }); // Cache up to 500 items for 1 minute
    this.retryCount = 3;
    this.backoffDelay = 100; // Initial backoff delay in milliseconds
  }

  async fetchData(userId) {
    try {
      const cachedData = this.cache.get(userId);
      if (cachedData) return cachedData;

      let response;
      for (let i = 0; i < this.retryCount; i++) {
        try {
          response = await axios.get(`https://api.example.com/users/${userId}`);
          break;
        } catch (error) {
          if (i === this.retryCount - 1) throw error;
          await new Promise(resolve => setTimeout(resolve, this.backoffDelay));
          this.backoffDelay *= 2; // Exponential backoff
        }
      }

      const data = this.processData(response.data);
      this.cache.set(userId, data);
      return data;
    } catch (error) {
      console.error(`Failed to fetch user data for userId: ${userId}`, error);
      throw error;
    }
  }

  processData(data) {
    // Validate and process data here
    if (!data || !data.id) throw new Error('Invalid user profile data');
    return {
      id: data.id,
      name: data.name,
      email: data.email,
      age: data.age,
      // Additional processing logic...
    };
  }
}

module.exports = DataLoader;
```

