        // Other relevant fields for UE context
    };

    void addUEContext(const UEContext& ue) {
        std::lock_guard<std::mutex> lock(mutex_);
        uePool_[ue.CI] = ue;
    }

    bool removeUEContext(int ci) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = uePool_.find(ci);
        if (it != uePool_.end()) {
            uePool_.erase(it);
            return true;
        }
        return false;
    }

    void updateUEContext(int ci, const UEContext& newUe) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = uePool_.find(ci);
        if (it != uePool_.end()) {
            it->second = newUe;
        }
    }

    bool getUEContext(int ci, UEContext& outUe) const {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = uePool_.find(ci);
        if (it != uePool_.end()) {
            outUe = it->second;
            return true;
        }
        return false;
    }

private:
    mutable std::mutex mutex_;
    std::unordered_map<int, UEContext> uePool_;
};

