// Define a modular interface for chat services
public interface ChatService {
    void sendMessage(String message, String recipient);
    String receiveMessages(String user);
}

// Implement a basic in-memory chat service
public class InMemoryChatService implements ChatService {
    private Map<String, List<String>> userMessages = new ConcurrentHashMap<>();

    @Override
    public void sendMessage(String message, String recipient) {
        userMessages.computeIfAbsent(recipient, k -> new ArrayList<>()).add(message);
    }

    @Override
    public String receiveMessages(String user) {
        return String.join("\n", userMessages.getOrDefault(user, Collections.emptyList()));
    }
}

// Implement a decorator for adding security to the chat service
public class SecureChatService implements ChatService {
    private final ChatService delegate;

    public SecureChatService(ChatService delegate) {
        this.delegate = delegate;
    }

    @Override
    public void sendMessage(String message, String recipient) {
        // Add security checks here
        delegate.sendMessage(message, recipient);
    }

    @Override
    public String receiveMessages(String user) {
        // Add authentication and authorization checks here
        return delegate.receiveMessages(user);
    }
}

// Implement a class to handle concurrent connections
public class ChatServer {
    private final ExecutorService executor;
    private final ChatService chatService;

    public ChatServer(int poolSize, ChatService chatService) {
        this.executor = Executors.newFixedThreadPool(poolSize);
        this.chatService = chatService;
    }

    public void processMessage(String message, String recipient) {
        executor.execute(() -> chatService.sendMessage(message, recipient));
    }

    public String getMessagesForUser(String user) {
        return chatService.receiveMessages(user);
    }

    public void shutdown() {
        executor.shutdown();
    }
}

// Main class to demonstrate usage
public class ChatApplication {
    public static void main(String[] args) {
        ChatService basicService = new InMemoryChatService();
        ChatService secureService = new SecureChatService(basicService);
        ChatServer server = new ChatServer(10, secureService);

        // Simulate concurrent message processing
        for (int i = 0; i < 20; i++) {
            final int userId = i;
            server.processMessage("Hello from user " + userId, "user1");
        }

        System.out.println(server.getMessagesForUser("user1"));
        server.shutdown();
    }
}
