import com.amazonaws.services.s3.AmazonS3ClientBuilder;
import com.amazonaws.services.s3.model.GetObjectRequest;
import java.io.IOException;
import java.security.MessageDigest;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class FileHashService implements RequestHandler<Request, Response> {

    private AmazonS3 s3 = AmazonS3ClientBuilder.defaultClient();
    private ExecutorService executorService = Executors.newFixedThreadPool(10);

    @Override
    public Response handleRequest(Request request, Context context) {
        String bucketName = request.getBucketName();
        String key = request.getKey();

        Future<String> future = executorService.submit(() -> {
            try (S3ObjectInputStream inputStream = s3.getObject(new GetObjectRequest(bucketName, key)).getObjectContent()) {
                MessageDigest digest = MessageDigest.getInstance("SHA-256");
                byte[] buffer = new byte[8192];
                int bytesRead;
                long fileSize = 0;
                long processedSize = 0;

                while ((bytesRead = inputStream.read(buffer)) != -1) {
                    digest.update(buffer, 0, bytesRead);
                    fileSize += bytesRead;
                }

                String hash = bytesToHex(digest.digest());
                return new Result(hash, fileSize);
            } catch (IOException | NoSuchAlgorithmException e) {
                throw new RuntimeException("Error processing file", e);
            }
        });

        try {
            Result result = future.get();
            sendProgressUpdate(context, key, 100.0f);
            return new Response(result.hash(), result.size());
        } catch (Exception e) {
            sendErrorNotification(context, key, "File processing failed");
            throw new RuntimeException("Failed to process file", e);
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

