class Middleware {
public:
    void start() {
        producer_thread_ = std::thread(&Middleware::produce, this);
        consumer_thread_ = std::thread(&Middleware::consume, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            running_ = false;
        }
        condition_.notify_all();
        producer_thread_.join();
        consumer_thread_.join();
    }

private:
    void produce() {
        while (true) {
            // Simulate data ingestion from Kafka
            Data data = ingestDataFromKafka();
            {
                std::unique_lock<std::mutex> lock(mutex_);
                queue_.push(data);
                condition_.notify_one();
            }
        }
    }

    void consume() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return !queue_.empty() || !running_; });
            if (!running_ && queue_.empty()) break;
            Data data = queue_.front();
            queue_.pop();
            lock.unlock();

            // Simulate data transformation and persistence to database
            transformAndPersistData(data);
        }
    }

    Data ingestDataFromKafka() {
        // Placeholder for Kafka ingestion logic
        return Data();
    }

    void transformAndPersistData(const Data& data) {
        // Placeholder for data transformation and database persistence logic
    }

private:
    std::thread producer_thread_;
    std::thread consumer_thread_;
    std::queue<Data> queue_;
    std::mutex mutex_;
    std::condition_variable condition_;
    bool running_ = true;
};

int main() {
    Middleware middleware;
    middleware.start();
    // Simulate application running for some time
