```cpp
// modular_data_pipeline_library.cpp

#include "modular_data_pipeline_library.h"

void DataProcessor::enqueueTask(Task task) {
    std::lock_guard<std::mutex> lock(mutex_);
    tasks_.push(task);
    condition_.notify_one();
}

void DataProcessor::start() {
    running_ = true;
    for (size_t i = 0; i < workers_.size(); ++i) {
        workers_.emplace_back(&DataProcessor::workerThread, this);
    }
}

void DataProcessor::stop() {
    {
        std::lock_guard<std::mutex> lock(mutex_);
        running_ = false;
    }
    condition_.notify_all();
    for (auto& worker : workers_) {
        worker.join();
    }
}

void DataProcessor::workerThread() {
    while (true) {
        Task task;
        {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return !running_ || !tasks_.empty(); });
            if (!running_ && tasks_.empty()) {
                return;
            }
            task = std::move(tasks_.front());
            tasks_.pop();
        }
        task();
    }
}

void DataPipeline::addSource(const std::string& source) {
    sources_.push_back(source);
}

void DataPipeline::removeSource(const std::string& source) {
    sources_.erase(std::remove(sources_.begin(), sources_.end(), source), sources_.end());
}

void DataPipeline::setTransformationRule(const std::string& rule) {
    transformationRules_[rule] = [](const std::string& data) { /* Apply transformation */ };
}

void DataPipeline::setProcessingPriority(int priority) {
    processingPriority_ = priority;
}

void processStream(DataPipeline& pipeline, const std::string& data) {
    // Process incoming data stream
}
