// Define the UserSession structure
typedef struct {
    char uuid[37]; // UUID in string format
    time_t start_time;
    struct Message *messages;
    int message_count;
} UserSession;

// Define the Message structure
typedef struct Message {
    time_t timestamp;
    char content[256];
    int delivered;
} Message;

// Function to create a new UserSession
UserSession* create_user_session(const char *uuid, time_t start_time) {
    UserSession *session = (UserSession*)malloc(sizeof(UserSession));
    if (!session) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    strncpy(session->uuid, uuid, 37);
    session->start_time = start_time;
    session->messages = NULL;
    session->message_count = 0;
    return session;
}

// Function to add a message to a UserSession
void add_message_to_session(UserSession *session, const char *content) {
    Message *new_message = (Message*)malloc(sizeof(Message));
    if (!new_message) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_message->timestamp = time(NULL);
