import java.io.File;
import java.security.MessageDigest;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class FileProcessingPipeline {
    private ExecutorService executorService = Executors.newFixedThreadPool(10);

    public void processFile(File file) {
        executorService.submit(() -> {
            try {
                String md5Hash = calculateMD5(file);
                String sha256Hash = calculateSHA256(file);

                // Submit metadata to REST API for processing
                submitMetadataToAPI(file.getName(), md5Hash, sha256Hash);

                // Store results in distributed database
                storeInDatabase(file.getName(), md5Hash, sha256Hash);
            } catch (Exception e) {
                handleException(e, file);
            }
        });
    }

    private String calculateMD5(File file) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] dataBytes = Files.readAllBytes(file.toPath());
        md.update(dataBytes);
        byte[] mdbytes = md.digest();

        StringBuilder sb = new StringBuilder();
        for (byte mdbyte : mdbytes) {
            sb.append(Integer.toString((mdbyte & 0xff) + 0x100, 16).substring(1));
        }
        return sb.toString();
    }

    private String calculateSHA256(File file) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] dataBytes = Files.readAllBytes(file.toPath());
        md.update(dataBytes);
        byte[] mdbytes = md.digest();

        StringBuilder sb = new StringBuilder();
        for (byte mdbyte : mdbytes) {
            sb.append(Integer.toString((mdbyte & 0xff) + 0x100, 16).substring(1));
        }
        return sb.toString();
    }

    private void submitMetadataToAPI(String fileName, String md5Hash, String sha256Hash) throws Exception {
