```javascript
import React, { useEffect, useState } from 'react';
import axios from 'axios';

const ScriptItem = ({ script }) => (
  <div key={script.id}>
    <h3>{script.title}</h3>
    <pre>{script.code}</pre>
  </div>
);

const FooterScriptsComponent = () => {
  const [scripts, setScripts] = useState([]);
  const [loading, setLoading] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [page, setPage] = useState(1);
  const [error, setError] = useState(null);

  const fetchScripts = async () => {
    if (loading || !hasMore) return;
    try {
      setLoading(true);
      const response = await axios.get(`https://api.example.com/scripts?page=${page}`);
      setScripts((prevScripts) => [...prevScripts, ...response.data.scripts]);
      setPage(page + 1);
      setHasMore(response.data.scripts.length > 0);
    } catch (err) {
      setError(err.message);
      setHasMore(false);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchScripts();
  }, []);

  const handleScroll = () => {
    if (
      window.innerHeight + document.documentElement.scrollTop !==
        document.documentElement.offsetHeight ||
      loading
    )
      return;
    fetchScripts();
  };

  useEffect(() => {
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  if (error) return <div>Error: {error}. <button onClick={() => setError(null)}>Retry</button></div>;

  return (
    <div>
      {scripts.map((script) => <ScriptItem key={script.id} script={script} />)}
      {loading && <div>Loading...</div>}
    </div>
  );
};

export default FooterScriptsComponent;
```

