import java.io.IOException;
import java.net.URI;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

import javax.websocket.*;

@ClientEndpoint
public class ScriptWebSocketClient {
    private final String uri;
    private Session userSession = null;
    private static final ConcurrentHashMap<String, CopyOnWriteArrayList<ScriptWebSocketClient>> clients = new ConcurrentHashMap<>();

    public ScriptWebSocketClient(String uri) {
        this.uri = uri;
    }

    @OnOpen
    public void onOpen(Session userSession) {
        System.out.println("Connected to " + uri);
        this.userSession = userSession;
        clients.putIfAbsent(uri, new CopyOnWriteArrayList<>());
        clients.get(uri).add(this);
    }

    @OnMessage
    public void onMessage(String message, Session session) {
        for (ScriptWebSocketClient client : clients.getOrDefault(session.getRequestURI().toString(), new CopyOnWriteArrayList<>())) {
            try {
                client.userSession.getBasicRemote().sendText(message);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    @OnClose
    public void onClose(Session userSession, CloseReason reason) {
        System.out.println("Closing a WebSocket due to " + reason.getReasonPhrase());
        clients.getOrDefault(userSession.getRequestURI().toString(), new CopyOnWriteArrayList<>()).remove(this);
    }

    @OnError
    public void onError(Session session, Throwable throwable) {
        System.err.println("Error on WebSocket: " + throwable.getMessage());
    }

    public static void broadcast(String message, URI uri) throws IOException {
        for (ScriptWebSocketClient client : clients.getOrDefault(uri.toString(), new CopyOnWriteArrayList<>())) {
            try {
                client.userSession.getBasicRemote().sendText(message);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    public static void main(String[] args) throws IOException {
        URI uri = URI.create("ws://example.com/scripts");
        ScriptWebSocketClient client = new ScriptWebSocketClient(uri);
        Session session = client.userSession;
        session.getBasicRemote().sendText("Initial message");
    }
}
```

### Notes:
- Ensure you replace `https://api.example.com/scripts` and `ws://example.com/scripts` with actual API and WebSocket endpoints.
- For React, use a library like Axios for HTTP requests and install it via npm or yarn: `npm install axios`.
