    std::condition_variable cv;

    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mapMutex);
            cv.wait(lock, [this] { return !ueMap.empty(); });
            // Process tasks from the queue
            for (auto& [ci, ue] : ueMap) {
                // Perform operations on UE context and RABs
            }
        }
    }

    std::thread workerThread;
};

void LTEManager::addUe(const UeContext& ue) {
    std::lock_guard<std::mutex> lock(mapMutex);
    ueMap[ue.cellIdentity] = ue;
    cv.notify_one();
}

void LTEManager::removeUe(int cellIdentity) {
    std::lock_guard<std::mutex> lock(mapMutex);
    ueMap.erase(cellIdentity);
    cv.notify_one();
}

void LTEManager::updateRab(int cellIdentity, int bearerID, const Rab& rab) {
    std::lock_guard<std::mutex> lock(mapMutex);
    if (ueMap.find(cellIdentity) != ueMap.end()) {
        auto& ue = ueMap[cellIdentity];
        for (auto& r : ue.rabList) {
            if (r.bearerID == bearerID) {
                r = rab;
                break;
            }
        }
    }
    cv.notify_one();
}

