typedef struct {
    NetworkEventRecord *records;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} EventManager;

EventManager* event_manager_create(size_t initial_capacity) {
    EventManager *manager = (EventManager*)malloc(sizeof(EventManager));
    manager->records = (NetworkEventRecord*)calloc(initial_capacity, sizeof(NetworkEventRecord));
    manager->size = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void event_manager_destroy(EventManager *manager) {
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int event_manager_add_event(EventManager *manager, NetworkEventRecord record) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        // Handle capacity issue (e.g., resize)
        pthread_mutex_unlock(&manager->lock);
        return -1; // Return error code
    }
    manager->records[manager->size++] = record;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

