// Function to truncate and format a string dynamically
char* truncateAndFormat(const char* text, int maxLength, bool trimMode, const char* suffix) {
    if (maxLength < 0) {
        return NULL; // Handle invalid maxLength
    }

    size_t textLength = strlen(text);
    if (!trimMode && textLength > maxLength) {
        return NULL; // Error handling for non-trim mode and exceeding maxLength
    }

    char* result = malloc(maxLength + (trimMode && textLength > maxLength ? strlen(suffix) : 1));
    if (result == NULL) {
        return NULL; // Handle memory allocation failure
    }

    if (textLength <= maxLength) {
        strcpy(result, text);
    } else {
        strncpy(result, text, maxLength - (trimMode && suffix != NULL ? strlen(suffix) : 0));
        if (trimMode && suffix != NULL) {
            strcat(result, suffix);
        }
        result[maxLength] = '\0'; // Ensure null-termination
    }

    return result;
}

