#define LOG_BUFFER_SIZE 1024

typedef struct {
    char buffer[LOG_BUFFER_SIZE];
    size_t length;
} LogBuffer;

LogBuffer logBuffer = {0};

void asyncAppendToLog(const char* text) {
    if (logBuffer.length + strlen(text) >= LOG_BUFFER_SIZE) {
        // Handle log buffer overflow
        fprintf(stderr, "Log buffer overflow\n");
        return;
    }
    strcpy(logBuffer.buffer + logBuffer.length, text);
    logBuffer.length += strlen(text);
}

char* truncateAndFormat(const char* text, int maxLength, bool trimMode, const char* customSuffix) {
    if (maxLength < 0) {
        fprintf(stderr, "Invalid input: maxLength must be non-negative\n");
        return NULL;
    }

    size_t textLength = strlen(text);

    if (textLength <= maxLength) {
        char* result = (char*)malloc((textLength + 1) * sizeof(char));
        if (!result) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
        strcpy(result, text);
        return result;
    }

    if (!trimMode) {
        fprintf(stderr, "Text exceeds maxLength but trimMode is false\n");
        return NULL;
    }

    size_t suffixLength = customSuffix ? strlen(customSuffix) : 0;
    char* result = (char*)malloc((maxLength + suffixLength + 1) * sizeof(char));
    if (!result) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    strncpy(result, text, maxLength);
    result[maxLength] = '\0';

    if (suffixLength > 0) {
        strncat(result, customSuffix, maxLength - strlen(result));
    }

    asyncAppendToLog(result);

    return result;
}

