#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <openssl/md5.h>
#include <curl/curl.h>

// DNS Resolution Function
int fetch_ip_address(const char *hostname, u_char ip[4]) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    memcpy(ip, &(ipv4->sin_addr), 4);
    freeaddrinfo(res);

    return 0;
}

// Content Retrieval and Hashing Function
int fetch_and_hash_content(const char *source, u_char md5hash[MD5_DIGEST_LENGTH]) {
    CURL *curl;
    CURLcode res;
    FILE *fp;
    long file_size;
    size_t chunk_size = 8192;
    char buffer[chunk_size];

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if(curl) {
        struct stat file_stat;
        fp = fopen(source, "rb");

        if (fp == NULL) {
            fprintf(stderr, "Failed to open file\n");
            return -1;
        }

        if (fstat(fileno(fp), &file_stat) != 0) {
            fprintf(stderr, "Failed to get file size\n");
            fclose(fp);
            return -1;
        }

        file_size = file_stat.st_size;

        curl_easy_setopt(curl, CURLOPT_URL, source);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);
        curl_easy_setopt(curl, CURLOPT_INFILESIZE_LARGE, (curl_off_t)file_size);

        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            fclose(fp);
            return -1;
        }

        fclose(fp);

        MD5_CTX md5ctx;
        MD5_Init(&md5ctx);

        fp = fopen(source, "rb");
        if (fp == NULL) {
            fprintf(stderr, "Failed to reopen file\n");
            return -1;
        }

        while ((res = fread(buffer, 1, chunk_size, fp)) > 0) {
            MD5_Update(&md5ctx, buffer, res);
        }

        fclose(fp);

        MD5_Final(md5hash, &md5ctx);

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();

    return 0;
}

int main() {
    u_char ip[4];
    u_char md5hash[MD5_DIGEST_LENGTH];

    if (fetch_ip_address("example.com", ip) == -1) {
        fprintf(stderr, "Failed to resolve IP address\n");
        return -1;
    }

    printf("Resolved IP: %d.%d.%d.%d\n", ip[0], ip[1], ip[2], ip[3]);

    if (fetch_and_hash_content("example.com", md5hash) == -1) {
        fprintf(stderr, "Failed to fetch and hash content\n");
        return -1;
    }

    printf("MD5 Hash: ");
    for(int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        printf("%02x", md5hash[i]);
    }
    printf("\n");

    return 0;
}
```

