#include <iostream>
#include <memory>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <future>
#include <atomic>

// Configuration Manager Interface
class ConfigurationManager {
public:
    virtual void loadConfig() = 0;
    virtual void updateConfig(const std::string& config) = 0;
    virtual ~ConfigurationManager() {}
};

// Asynchronous Task Executor
class AsyncTaskExecutor {
private:
    std::queue<std::function<void()>> tasks;
    std::vector<std::thread> workers;
    std::mutex queue_mutex;
    std::condition_variable condition;
    bool stop;

public:
    AsyncTaskExecutor(size_t num_threads) : stop(false) {
        for (size_t i = 0; i < num_threads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->queue_mutex);
                        this->condition.wait(lock, [this]{ return this->stop || !this->tasks.empty(); });
                        if (this->stop && this->tasks.empty()) {
                            return;
                        }
                        task = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    ~AsyncTaskExecutor() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    template<class F, class... Args>
    auto enqueue(F&& f, Args&&... args) -> std::future<typename std::result_of<F(Args...)>::type> {
        using return_type = typename std::result_of<F(Args...)>::type;

        auto task = std::make_shared<std::packaged_task<return_type()>>(
            std::bind(std::forward<F>(f), std::forward<Args>(args)...)
        );

        std::future<return_type> res = task->get_future();
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            if (stop) {
                throw std::runtime_error("enqueue on stopped ThreadPool");
            }
            tasks.emplace([task](){ (*task)(); });
        }
        condition.notify_one();
        return res;
    }
};

// Configuration Manager Implementation
class CloudConfigManager : public ConfigurationManager {
private:
    AsyncTaskExecutor executor;
    std::atomic<bool> isLoaded;
    std::mutex config_mutex;

public:
    CloudConfigManager(size_t num_threads = 4) : executor(num_threads), isLoaded(false) {}

    void loadConfig() override {
        executor.enqueue([this] {
            // Simulate loading configuration from cloud
            std::this_thread::sleep_for(std::chrono::seconds(2));
            std::lock_guard<std::mutex> lock(config_mutex);
            isLoaded = true;
            std::cout << "Configuration loaded" << std::endl;
        });
    }

    void updateConfig(const std::string& config) override {
        executor.enqueue([this, config] {
            // Simulate updating configuration in cloud
            std::this_thread::sleep_for(std::chrono::seconds(1));
            std::lock_guard<std::mutex> lock(config_mutex);
            std::cout << "Configuration updated: " << config << std::endl;
        });
    }
};

int main() {
    CloudConfigManager manager;
    manager.loadConfig();

    // Simulate updating configuration
    manager.updateConfig("new_config");

    return 0;
}
