void network_event_module_init(NetworkEventModule* module, int initial_capacity) {
    module->records = (NetworkEventRecord**)malloc(initial_capacity * sizeof(NetworkEventRecord*));
    if (module->records == NULL) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }
    module->capacity = initial_capacity;
    module->size = 0;
    pthread_mutex_init(&module->lock, NULL);
}

void network_event_module_destroy(NetworkEventModule* module) {
    for (int i = 0; i < module->size; i++) {
        free(module->records[i]);
    }
    free(module->records);
    pthread_mutex_destroy(&module->lock);
}

int network_event_module_add_record(NetworkEventModule* module, NetworkEventRecord* record) {
    pthread_mutex_lock(&module->lock);
    if (module->size == module->capacity) {
        NetworkEventRecord** new_records = (NetworkEventRecord**)realloc(module->records, 2 * module->capacity * sizeof(NetworkEventRecord*));
        if (new_records == NULL) {
            perror("Failed to reallocate memory for records");
            pthread_mutex_unlock(&module->lock);
            return -1;
        }
        module->records = new_records;
        module->capacity *= 2;
    }
    module->records[module->size++] = record;
    pthread_mutex_unlock(&module->lock);
    return 0;
}

