    private readonly RequestDelegate _next;
    private readonly HttpClient _httpClient;
    private readonly IOptions<ExternalServiceConfig> _config;
    private readonly Policy _retryPolicy;
    private readonly ILogger<WebPageUpdateMiddleware> _logger;

    public WebPageUpdateMiddleware(RequestDelegate next, HttpClient httpClient, IOptions<ExternalServiceConfig> config, ILogger<WebPageUpdateMiddleware> logger)
    {
        _next = next;
        _httpClient = httpClient;
        _config = config;
        _retryPolicy = Policy
            .HandleTransientHttpError()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (context.Request.Method == "POST")
        {
            var requestData = await new StreamReader(context.Request.Body).ReadToEndAsync();
            var webPageElement = ParseWebPageElement(requestData);

            try
            {
                await UpdateCdn(webPageElement);
                await SendAnalytics(webPageElement);
                await ShareOnSocialMedia(webPageElement);
                await context.Response.WriteAsync("Update successful");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating web page element");
                context.Response.StatusCode = 500;
                await context.Response.WriteAsync("Internal server error");
            }
        }
        else
        {
            await _next(context);
        }
    }

    private WebPageElement ParseWebPageElement(string requestData)
    {
        // Implement parsing logic here
        return new WebPageElement();
    }

    private async Task UpdateCdn(WebPageElement element)
    {
        var cdnUrl = $"{_config.Value.CdnBaseUrl}/{element.Id}";
        await _retryPolicy.ExecuteAsync(() => _httpClient.PutAsJsonAsync(cdnUrl, element));
    }

    private async Task SendAnalytics(WebPageElement element)
    {
        var analyticsUrl = $"{_config.Value.AnalyticsApiUrl}/track";
        var payload = new { ElementId = element.Id, Action = "update" };
        await _retryPolicy.ExecuteAsync(() => _httpClient.PostAsJsonAsync(analyticsUrl, payload));
    }

    private async Task ShareOnSocialMedia(WebPageElement element)
    {
        var socialMediaUrl = $"{_config.Value.SocialMediaApiUrl}/share";
        var payload = new { ElementId = element.Id, Network = "facebook" };
        await _retryPolicy.ExecuteAsync(() => _httpClient.PostAsJsonAsync(socialMediaUrl, payload));
    }
}

public class WebPageElement
{
    public int Id { get; set; }
    // Other properties
}

