#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} NetworkEventRecord;

typedef struct {
    NetworkEventRecord* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} EventManager;

EventManager* create_event_manager(size_t initial_capacity) {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    if (!manager) {
        perror("Failed to allocate memory for event manager");
        return NULL;
    }
    manager->records = (NetworkEventRecord*)calloc(initial_capacity, sizeof(NetworkEventRecord));
    if (!manager->records) {
        perror("Failed to allocate memory for records");
        free(manager);
        return NULL;
    }
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_event_manager(EventManager* manager) {
    if (manager) {
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int manage_records(EventManager* manager, size_t requested_size, int key_range_start, int key_range_end) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size + requested_size > manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NetworkEventRecord* new_records = (NetworkEventRecord*)realloc(manager->records, new_capacity * sizeof(NetworkEventRecord));
        if (!new_records) {
            perror("Failed to reallocate memory for records");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < requested_size; ++i) {
        int key = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        manager->records[manager->size].key = key;
        manager->records[manager->size].offset = rand();
        ++manager->size;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int main() {
    EventManager* manager = create_event_manager(1024);
    if (manager) {
        int result = manage_records(manager, 500, 100, 999);
        if (result == 0) {
            printf("Records managed successfully\n");
        } else {
            printf("Failed to manage records\n");
        }
        destroy_event_manager(manager);
    }
    return 0;
}
```

This code snippet demonstrates the creation and usage of an `EventManager` structure, which is designed to manage a dynamic array of `NetworkEventRecord` structures. The `manage_records` function dynamically allocates memory for the records and populates them with random values based on the provided key range and requested size. It includes error handling for memory allocation failures and utilizes a mutex for thread-safe operations. This example focuses on basic functionality and does not include all advanced features such as distributed locking, periodic cleanup, or monitoring/logging frameworks, which would need to be implemented in a full-fledged solution.']

