class EventManager {
public:
    EventManager(int nodeID, int totalNodes) : nodeID(nodeID), totalNodes(totalNodes), running(true) {}

    void startIngestingEvents() {
        for (int i = 0; i < totalNodes; ++i) {
            if (i != nodeID) {
                std::thread(&EventManager::ingestEventsFromNode, this, i).detach();
            }
        }
    }

    void stopIngestingEvents() {
        running.store(false);
        for (auto& q : queues) {
            q.push(nullptr); // Signal end of events
        }
    }

private:
    int nodeID;
    int totalNodes;
    std::atomic<bool> running;
    std::vector<std::queue<NetworkEventRecord*>> queues;

    void ingestEventsFromNode(int fromNode) {
        while (running.load()) {
            NetworkEventRecord* event = fetchEventFromAPI(fromNode);
            if (!event) break;
            queues[fromNode % totalNodes].push(event);
        }
    }

    NetworkEventRecord* fetchEventFromAPI(int nodeID) {
        // Simulate fetching event from an external API
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        return new NetworkEventRecord{rand() % 1000, "Event Data"};
    }
};

