    EventManager manager(0, 3); // Node ID and total nodes in the cluster
    manager.startIngestingEvents();

    // Simulate processing events
    std::this_thread::sleep_for(std::chrono::seconds(10));
    manager.stopIngestingEvents();

    return 0;
}
