#define INITIAL_CAPACITY 1024
#define MAX_CONCURRENCY 100000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int rnti;
    // other fields
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CrcList {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} CrcList;

int populateNfaApiCrcList(void *config) {
    // Extract configuration parameters from config
    int initialCapacity = INITIAL_CAPACITY;
    int rntiMin, rntiMax;
    unsigned int seed;
    int maxConcurrency = MAX_CONCURRENCY;

    // Allocate memory for the CrcList
    CrcList *crcList = (CrcList *)malloc(sizeof(CrcList));
    if (!crcList) {
        return -1;  // Memory allocation failure
    }

    // Initialize the CrcList
    crcList->array = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crcList->array) {
        free(crcList);
        return -2;  // Memory allocation failure
    }
    crcList->capacity = initialCapacity;
    crcList->size = 0;

    // Initialize the lock
    pthread_mutex_init(&crcList->lock, NULL);

    // Seed the random number generator
    srand(seed);

    // Simulate concurrent updates
    pthread_t threads[maxConcurrency];
    for (int i = 0; i < maxConcurrency; ++i) {
        if (pthread_create(&threads[i], NULL, updateCrcList, crcList) != 0) {
            // Handle error
        }
    }

    // Join the threads
    for (int i = 0; i < maxConcurrency; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free resources
    free(crcList->array);
    free(crcList);

    return 0;
}

void *updateCrcList(void *arg) {
    CrcList *crcList = (CrcList *)arg;

    // Simulate generating random RNTI values and updating the CrcList
    for (int i = 0; i < 1000; ++i) {
        pthread_mutex_lock(&crcList->lock);
        if (crcList->size >= crcList->capacity) {
            // Resize the array if necessary
            NFAPI_CRC_INDICATION_PDU_T *newArray = realloc(crcList->array, crcList->capacity * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!newArray) {
                pthread_mutex_unlock(&crcList->lock);
                // Handle error
            }
            crcList->array = newArray;
            crcList->capacity *= 2;
        }
        int rnti = rand() % (rntiMax - rntiMin + 1) + rntiMin;
        NFAPI_CRC_INDICATION_PDU_T pdu = {rnti};
        // Update the CrcList
        crcList->array[crcList->size++] = pdu;
        pthread_mutex_unlock(&crcList->lock);
    }

    return NULL;
}
