    public void processMedia(Media media) {
        // Load balancing logic
        String selectedClient = selectApiClient(media.getType());
        ThirdPartyAPI client = apiClients.get(selectedClient);

        // Handle dynamic sets of third-party APIs
        if (client == null) {
            client = createApiClient(selectedClient);
            apiClients.put(selectedClient, client);
