// Mock classes for third-party API and video stream processing
class MetadataAPI {
public:
    using FrameData = std::pair<int, std::string>; // Frame ID and metadata
    Future<FrameData> extractMetadata(int frameId) {
        // Simulate an asynchronous API call with some delay
        auto result = std::async(std::launch::async, [frameId]() -> FrameData {
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            return {frameId, "metadata_" + std::to_string(frameId)};
        });
        return Future<FrameData>(result);
    }
};

class VideoStreamProcessor {
public:
    using Frame = int; // Simplified representation of a video frame
    using Result = std::pair<bool, size_t>; // Success flag and number of processed frames

    VideoStreamProcessor(size_t numThreads) : numThreads_(numThreads), stop_(false) {
        for (size_t i = 0; i < numThreads_; ++i) {
            workers_.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queueMutex_);
                        condition_.wait(lock, [this] { return stop_ || !tasks_.empty(); });
                        if (stop_ && tasks_.empty())
                            return;
                        task = std::move(tasks_.front());
                        tasks_.pop();
                    }
                    task();
                }
            });
        }
    }

    ~VideoStreamProcessor() {
        {
            std::unique_lock<std::mutex> lock(queueMutex_);
            stop_ = true;
        }
        condition_.notify_all();
        for (std::thread& worker : workers_)
            worker.join();
    }

    Future<Result> processFrame(int frameId) {
        auto promise = std::make_shared<std::promise<Result>>();
        auto future = promise->get_future();

        tasks_.emplace([this, frameId, promise]() mutable {
            try {
                MetadataAPI api;
                auto metadataFuture = api.extractMetadata(frameId);
                auto [frameData] = metadataFuture.get();
                // Process the video frame and update metadata
                std::cout << "Processing frame " << frameId << " with metadata: " << frameData.second << std::endl;
                promise->set_value({true, 1});
            } catch (const std::exception& e) {
                promise->set_value({false, 0});
            }
        });

        return Future<Result>(future);
    }

private:
    size_t numThreads_;
    bool stop_;
    std::vector<std::thread> workers_;
    std::queue<std::function<void()>> tasks_;
    std::mutex queueMutex_;
    std::condition_variable condition_;
};

// Mock class for external data source
class ExternalDataSource {
public:
    using Data = std::string;
    Future<Data> fetchData(const std::string& url) {
        // Simulate an asynchronous data fetch with some delay
        auto result = std::async(std::launch::async, [url]() -> Data {
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
            return "data_" + url;
        });
        return Future<Data>(result);
    }
};

// Main function to demonstrate the usage of the library
int main() {
    VideoStreamProcessor processor(4);

    // Simulate processing multiple video frames
    std::vector<Future<Result>> results;
    for (int i = 0; i < 10; ++i) {
        results.push_back(processor.processFrame(i));
    }

    for (auto& result : results) {
        auto [success, processedFrames] = result.get();
        if (success)
            std::cout << "Processed " << processedFrames << " frames successfully." << std::endl;
        else
            std::cout << "Failed to process frames." << std::endl;
    }

    return 0;
}
