    }

    struct Config {
        update_interval: Duration,
        cache_expiration: Duration,
        log_level: LogLevel,
    }

    enum LogLevel {
        Debug,
        Info,
        Warning,
        Error,
    }

    pub struct NFAPICRCManager {
        sessions: RwLock<HashMap<u32, Session>>,
        api_client: Client,
        config: Arc<RwLock<Config>>,
        sender: mpsc::Sender<(u32, NFAPI_CRC_INDICATION_PDU_T)>,
        receiver: mpsc::Receiver<(u32, NFAPI_CRC_INDICATION_PDU_T)>,
    }

    impl NFAPICRCManager {
        pub fn new(config: Config) -> Self {
            let (sender, receiver) = mpsc::channel(100);
            NFAPICRCManager {
                sessions: RwLock::new(HashMap::new()),
                api_client: Client::new(),
                config: Arc::new(RwLock::new(config)),
                sender,
                receiver,
            }
        }

        pub fn initialize_session(&self, id: u32) -> Result<(), String> {
            let mut sessions = self.sessions.write().map_err(|_| " poisoned lock")?;
            if sessions.contains_key(&id) {
                return Err("Session already exists".to_string());
            }
            sessions.insert(id, Session {
                id,
                config: self.config.read().map_err(|_| " poisoned lock")?.clone(),
                data: Arc::new(Mutex::new(Vec::new())),
            });
            Ok(())
        }

        pub fn validate_session(&self, id: u32) -> bool {
            self.sessions.read().unwrap().contains_key(&id)
        }

        pub fn terminate_session(&self, id: u32) -> Result<(), String> {
            let mut sessions = self.sessions.write().map_err(|_| " poisoned lock")?;
            if !sessions.contains_key(&id) {
                return Err("Session does not exist".to_string());
            }
            sessions.remove(&id);
            Ok(())
        }

        pub async fn update_session_data(&self, id: u32, data: NFAPI_CRC_INDICATION_PDU_T) -> Result<(), String> {
            let mut session = self.sessions.write().map_err(|_| " poisoned lock")?;
            if let Some(session) = session.get_mut(&id) {
                session.data.lock().map_err(|_| " poisoned lock")?.push(data);
                Ok(())
            } else {
                Err("Session does not exist".to_string())
            }
        }

        pub async fn fetch_and_update_ue_info(&self, id: u32) -> Result<(), String> {
            let session = self.sessions.read().map_err(|_| " poisoned lock")?;
            if !session.contains_key(&id) {
                return Err("Session does not exist".to_string());
            }
            // Implement API query and data update logic here
            Ok(())
        }

        pub async fn run(&mut self) -> Result<(), String> {
            let mut interval = tokio::time::interval(self.config.read().map_err(|_| " poisoned lock")?.update_interval);
            loop {
                tokio::select! {
                    _ = interval.tick() => {
                        for session_id in self.sessions.read().map_err(|_| " poisoned lock")?.keys().cloned().collect::<Vec<_>>() {
                            if let Err(e) = self.fetch_and_update_ue_info(session_id).await {
                                log_error(&e);
                            }
                        }
                    },
                    Some((id, data)) = self.receiver.recv() => {
                        if let Err(e) = self.update_session_data(id, data).await {
                            log_error(&e);
                        }
                    },
                };
            }
        }

        fn log_error(error: &str) {
            // Implement error logging logic here
        }
    }

    #[tokio::test]
    async fn test_nfaapi_crc_manager() {
        let config = Config {
            update_interval: Duration::from_secs(5),
            cache_expiration: Duration::from_secs(60),
            log_level: LogLevel::Debug,
        };
        let mut manager = NFAPICRCManager::new(config);
        manager.initialize_session(1).unwrap();
        assert!(manager.validate_session(1));
        manager.terminate_session(1).unwrap();
        assert!(!manager.validate_session(1));
    }
}
