using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class UserSession
{
    public Guid Id { get; set; }
    public DateTime StartTime { get; set; }
    public List<Message> Messages { get; set; } = new List<Message>();
}

public class Message
{
    public DateTime Timestamp { get; set; }
    public string Content { get; set; }
    public bool Delivered { get; set; }
}

public class UserSessionManager
{
    private readonly string _jsonFilePath;

    public UserSessionManager(string jsonFilePath)
    {
        _jsonFilePath = jsonFilePath;
    }

    public async Task AddUserSessionAsync(UserSession session)
    {
        var sessions = await LoadSessionsAsync();
        if (sessions == null)
            sessions = new List<UserSession>();

        sessions.Add(session);
        await SaveSessionsAsync(sessions);
    }

    public async Task UpdateUserSessionAsync(Guid sessionId, Action<UserSession> updateAction)
    {
        var sessions = await LoadSessionsAsync();
        if (sessions != null && sessions.Any(s => s.Id == sessionId))
        {
            var sessionToUpdate = sessions.First(s => s.Id == sessionId);
            updateAction(sessionToUpdate);
            await SaveSessionsAsync(sessions);
        }
    }

    public async Task<List<UserSession>> GetUserSessionsAsync()
    {
        return await LoadSessionsAsync();
    }

    private async Task<List<UserSession>> LoadSessionsAsync()
    {
        if (System.IO.File.Exists(_jsonFilePath))
        {
            try
            {
                var json = await System.IO.File.ReadAllTextAsync(_jsonFilePath);
                return JsonConvert.DeserializeObject<List<UserSession>>(json);
            }
            catch (Exception ex)
            {
                // Log the error and handle it gracefully, e.g., returning an empty list
                Console.WriteLine($"Error loading sessions: {ex.Message}");
                return new List<UserSession>();
            }
        }

        return null;
    }

    private async Task SaveSessionsAsync(List<UserSession> sessions)
    {
        try
        {
            var json = JsonConvert.SerializeObject(sessions, Formatting.Indented);
            await System.IO.File.WriteAllTextAsync(_jsonFilePath, json);
        }
        catch (Exception ex)
        {
            // Log the error and handle it gracefully, e.g., by not saving changes
            Console.WriteLine($"Error saving sessions: {ex.Message}");
        }
    }
}
