    }

    impl Pipeline {
        pub fn new(oauth2: OAuth2, access_token: AccessToken) -> Self {
            let (tx, rx) = mpsc::channel(32);
            Pipeline {
                oauth2,
                access_token,
                api_client: Client::new(),
                rx_channel: rx,
                tx_channel: tx,
                cache: std::collections::HashMap::new(),
            }
        }

        pub async fn run(&mut self) {
            loop {
                tokio::select! {
                    Some(indication) = self.rx_channel.recv() => {
                        self.process_indication(indication).await;
                    },
                    _ = sleep(Duration::from_secs(API_UPDATE_FREQUENCY)) => {
                        self.update_cache().await;
                    }
