            let crc_indication = generate_crc_indication(ue_info);
            self.cache.insert(ue_info.rx_ue_information_tag.clone(), (crc_indication, Duration::from_secs(CACHE_EXPIRATION * 60)));
        }

        fn generate_crc_indication(ue_info: RX_UE_INFORMATION_TAG) -> NFAPI_CRC_INDICATION_PDU_T {
