import org.springframework.context.annotation.Bean;

@SpringBootApplication
public class ConfigGatewayApplication {

    public static void main(String[] args) {
        SpringApplication.run(ConfigGatewayApplication.class, args);
    }

    @Bean
    public RouteLocator customRouteLocator(RouteLocatorBuilder builder) {
        return builder.routes()
            .route("web_config", r -> r.path("/config/web/**")
                .filters(f -> f.rewritePath("/config/web/(?<segment>.*?)/(?<residue>.*?)/?(?<version>\\d+\\.\\d+\\.\\d+)\\.json", "/${residue}/${version}/${segment}.json"))
                .uri("lb://web-config-service"))
            .route("mobile_config", r -> r.path("/config/mobile/**")
                .filters(f -> f.rewritePath("/config/mobile/(?<segment>.*?)/(?<residue>.*?)/?(?<version>\\d+\\.\\d+\\.\\d+)\\.json", "/${residue}/${version}/${segment}.json"))
