    private readonly HttpClient _httpClient;
    private readonly Dictionary<string, Func<Task<WeatherData>>> _apiClients;

    public WeatherService()
    {
        _httpClient = new HttpClient();
        _apiClients = new Dictionary<string, Func<Task<WeatherData>>>
        {
            { "OpenWeatherMap", FetchFromOpenWeatherMap },
            { "AccuWeather", FetchFromAccuWeather }
        };
    }

    public async Task<WeatherData> GetWeatherAsync(string location, string apiKey)
    {
        var apiClient = GetApiClient(apiKey);
        return await apiClient();
    }

    private Func<Task<WeatherData>> GetApiClient(string apiKey)
    {
        if (!_apiClients.ContainsKey(apiKey))
            throw new ArgumentException("Invalid API key");

        return _apiClients[apiKey];
    }

    private async Task<WeatherData> FetchFromOpenWeatherMap()
    {
        var url = "https://api.openweathermap.org/data/2.5/weather?q=London&appid=YOUR_API_KEY";
        var response = await _httpClient.GetAsync(url);
        var content = await response.Content.ReadAsStringAsync();
        return JsonConverter.Deserialize<WeatherData>(content);
    }

    private async Task<WeatherData> FetchFromAccuWeather()
    {
        var url = "https://dataservice.accuweather.com/currentconditions/v1/247365.json?apikey=YOUR_API_KEY";
        var response = await _httpClient.GetAsync(url);
        var content = await response.Content.ReadAsStringAsync();
        return JsonConverter.Deserialize<WeatherData>(content);
    }
}

public interface IWeatherService
{
    Task<WeatherData> GetWeatherAsync(string location, string apiKey);
