#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void copyBytes(char *dest, const char **src, size_t *lengths, int count) {
    size_t total = 0;
    for (int i = 0; i < count; i++) {
        total += lengths[i];
    }

    dest = realloc(dest, total);
    if (dest == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    size_t offset = 0;
    for (int i = 0; i < count; i++) {
        memcpy(&dest[offset], src[i], lengths[i]);
        offset += lengths[i];
    }
}

int main(int argc, char *argv[]) {
    // Example usage of copyBytes
    const char *data1 = "Hello";
    size_t length1 = 5;
    const char *data2 = ", World!";
    size_t length2 = 8;

    char *buffer = NULL;
    int count = 2;
    copyBytes(buffer, (const char **)&data1, &length1, count);
    copyBytes(buffer, (const char **)&data2, &length2, count);

    printf("Copied data: %s\n", buffer);

    free(buffer);
    return 0;
}
