class VideoStreamManager {
public:
    void startSession(const std::string& sessionId) {
        std::lock_guard<std::mutex> lock(mutex_);
        sessions_.push_back(sessionId);
        notifyScaling();
    }

    void endSession(const std::string& sessionId) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = std::find(sessions_.begin(), sessions_.end(), sessionId);
        if (it != sessions_.end()) {
            sessions_.erase(it);
            notifyScaling();
        }
    }

private:
    void notifyScaling() {
        std::unique_lock<std::mutex> lock(mutex_);
        condition_.notify_one();
    }

    void scalingThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return !sessions_.empty(); });
            lock.unlock();

            // Perform scaling based on session count
            scaleResources(sessions_.size());
        }
    }

    void scaleResources(size_t currentSessions) {
        // Logic to scale resources based on session count
        std::cout << "Scaling resources for " << currentSessions << " sessions" << std::endl;
    }

    std::vector<std::string> sessions_;
    std::mutex mutex_;
    std::condition_variable condition_;
};

int main() {
    VideoStreamManager manager;
    // Simulate session start and end
    manager.startSession("session1");
    manager.startSession("session2");

    std::thread scaling_thread(&VideoStreamManager::scalingThread, &manager);
    scaling_thread.join();

    return 0;
}
