# Define the UserActivityAnalyzer class
class UserActivityAnalyzer:
    def __init__(self):
        # Initialize data structures for processing and storing user activity
        self.user_data_store = {}
        self.activity_queues = {}

    def process_activity(self, platform, event):
        # Process incoming events from different platforms
        if platform not in self.activity_queues:
            self.activity_queues[platform] = []
        self.activity_queues[platform].append(event)

    def aggregate_activity(self):
        # Aggregate data from all platforms for analysis
        aggregated_data = {}
        for platform, queue in self.activity_queues.items():
            for event in queue:
                if event['user_id'] not in aggregated_data:
                    aggregated_data[event['user_id']] = {
                        'platforms': [platform],
                        'activity_count': 1,
                        'last_activity_time': event['timestamp']
                    }
                else:
                    aggregated_data[event['user_id']]['platforms'].append(platform)
                    aggregated_data[event['user_id']]['activity_count'] += 1
                    aggregated_data[event['user_id']]['last_activity_time'] = event['timestamp']
        return aggregated_data

    def analyze_engagement(self, aggregated_data):
        # Analyze engagement metrics based on aggregated data
        engagement_metrics = {}
        for user_id, activity_info in aggregated_data.items():
            engagement_score = (activity_info['activity_count'] / len(activity_info['platforms'])) * 100
            engagement_metrics[user_id] = {
                'engagement_score': engagement_score,
                'last_activity_time': activity_info['last_activity_time']
            }
        return engagement_metrics

    def visualize_data(self, engagement_metrics):
        # Visualize user activity data using a simple print statement (in practice, use a visualization library)
        for user_id, metrics in engagement_metrics.items():
            print(f"User ID: {user_id}, Engagement Score: {metrics['engagement_score']:.2f}, Last Activity: {metrics['last_activity_time']}")

# Example usage
analyzer = UserActivityAnalyzer()
events = [
    {'platform': 'web', 'user_id': '101', 'timestamp': '1633072800'},
    {'platform': 'mobile', 'user_id': '101', 'timestamp': '1633072805'},
    {'platform': 'web', 'user_id': '102', 'timestamp': '1633072810'}
]
for event in events:
    analyzer.process_activity(event['platform'], event)
aggregated = analyzer.aggregate_activity()
engagement = analyzer.analyze_engagement(aggregated)
analyzer.visualize_data(engagement)
