struct RAB {
    int bearerID;
    std::string QoSParameters;
    bool connectionStatus;
};

class UEContextManager {
private:
    std::unordered_map<int, std::vector<RAB>> uePool;
    std::mutex poolMutex;

public:
    void addUE(int CI) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (uePool.find(CI) == uePool.end()) {
            uePool[CI] = {};
        }
    }

    void removeUE(int CI) {
        std::lock_guard<std::mutex> lock(poolMutex);
        uePool.erase(CI);
    }

    void updateRAB(int CI, int bearerID, const std::string& QoSParameters) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (uePool.find(CI) != uePool.end()) {
            for (auto& rab : uePool[CI]) {
                if (rab.bearerID == bearerID) {
                    rab.QoSParameters = QoSParameters;
                    break;
                }
            }
        }
    }

    void addRAB(int CI, int bearerID, const std::string& QoSParameters) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (uePool.find(CI) != uePool.end()) {
            RAB newRAB = {bearerID, QoSParameters, true};
            uePool[CI].push_back(newRAB);
        }
    }

    void removeRAB(int CI, int bearerID) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (uePool.find(CI) != uePool.end()) {
            auto& rabs = uePool[CI];
            rabs.erase(std::remove_if(rabs.begin(), rabs.end(),
                                       [bearerID](const RAB& rab) { return rab.bearerID == bearerID; }),
                       rabs.end());
        }
    }

    void setConnectionStatus(int CI, int bearerID, bool status) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (uePool.find(CI) != uePool.end()) {
            for (auto& rab : uePool[CI]) {
                if (rab.bearerID == bearerID) {
                    rab.connectionStatus = status;
                    break;
                }
            }
        }
    }

    std::vector<RAB> getRABS(int CI) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (uePool.find(CI) != uePool.end()) {
            return uePool[CI];
        }
        return {};
    }
};

int main() {
    UEContextManager manager;
    manager.addUE(1001);
    manager.addRAB(1001, 1, "QoS1");
    manager.updateRAB(1001, 1, "QoS2");
    std::vector<RAB> rabs = manager.getRABS(1001);
    for (const auto& rab : rabs) {
        std::cout << "Bearer ID: " << rab.bearerID << ", QoS Parameters: " << rab.QoSParameters
                  << ", Connection Status: " << (rab.connectionStatus ? "Active" : "Inactive") << std::endl;
    }
    manager.removeRAB(1001, 1);
    manager.removeUE(1001);

    return 0;
}
