def compute_hash(file_url, chunk_size=1024*1024):
    response = requests.get(file_url, stream=True)
    hasher = hashlib.sha256()
    for chunk in response.iter_content(chunk_size=chunk_size):
        hasher.update(chunk)
    return hasher.hexdigest()

