# Import necessary libraries
import hashlib
import threading
import queue
import time
import logging
from google.cloud import storage
import requests

# Setup logging
logging.basicConfig(level=logging.INFO)

# Define constants
CHUNK_SIZE = 1024 * 1024  # 1MB
MAX_CONCURRENT_DOWNLOADS = 5
RETRY_DELAY = 5  # seconds

class FileHasher:
    def __init__(self, storage_client):
        self.storage_client = storage_client
        self.queue = queue.Queue()
        self.threads = []

    def add_file_to_queue(self, bucket_name, file_name):
        self.queue.put((bucket_name, file_name))

    def start_hashing(self):
        for _ in range(MAX_CONCURRENT_DOWNLOADS):
            thread = threading.Thread(target=self.worker)
            thread.start()
            self.threads.append(thread)

        # Wait for all tasks to complete
        self.queue.join()

    def worker(self):
        while True:
            bucket_name, file_name = self.queue.get()
            try:
                if self.download_and_hash(bucket_name, file_name):
                    logging.info(f"Hashed {file_name} successfully")
                else:
                    logging.error(f"Failed to hash {file_name}")
            except Exception as e:
                logging.error(f"Error hashing {file_name}: {e}")

            self.queue.task_done()

    def download_and_hash(self, bucket_name, file_name):
        blob = self.storage_client.bucket(bucket_name).blob(file_name)
        hash_obj = hashlib.sha256()
        try:
            for chunk in blob.download_as_chunks(CHUNK_SIZE):
                hash_obj.update(chunk)
            return True
        except Exception as e:
            logging.error(f"Error downloading {file_name}: {e}")
            return False

def main():
    storage_client = storage.Client.from_service_account_json('path/to/service/account.json')
    file_hasher = FileHasher(storage_client)

    # Add files to the queue
    file_hasher.add_file_to_queue('bucket1', 'largefile1.txt')
    file_hasher.add_file_to_queue('bucket2', 'largefile2.bin')

    # Start hashing in parallel
    file_hasher.start_hashing()

if __name__ == "__main__":
    main()
