#include <stdlib.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    uint16_t rnti;
    uint32_t crc_value;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

void create_and_populate_nfapi_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, int n) {
    for (int i = 0; i < n; i++) {
        pdu[i].rx_ue_info_tag = RX_UE_INFORMATION_TAG;
        pdu[i].rnti = rand() % 65536;  // Random RNTI

        CRC_INDICATION_REL8_TAG *crc_ind = &pdu[i].crc_ind_rel8_tag;
        crc_ind->rnti = pdu[i].rnti;
        crc_ind->crc_value = rand() % UINT32_MAX;  // Random CRC value
    }
}

int main() {
    int n = 10;
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    srand(time(NULL));  // Seed random number generator

    create_and_populate_nfaip_pdu(pdu, n);

    // Free allocated memory
    free(pdu);
    return 0;
}
