import os
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed
from google.cloud import storage
from azure.storage.blob import BlobServiceClient

class FileHasher:
    def __init__(self, chunk_size=1024 * 1024):
        self.chunk_size = chunk_size

    def hash_file(self, file_path):
        hasher = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(self.chunk_size), b''):
                hasher.update(chunk)
        return hasher.hexdigest()

class CloudStorageClient:
    def __init__(self, storage_type, credentials):
        self.storage_type = storage_type
        if storage_type == 'aws':
            self.client = boto3.client('s3', aws_access_key_id=credentials['access_key'], aws_secret_access_key=credentials['secret_key'])
        elif storage_type == 'google':
            self.client = storage.Client.from_service_account_json(credentials['service_account_file'])
        elif storage_type == 'azure':
            self.client = BlobServiceClient(account_url=credentials['account_url'], credential=credentials['credential'])

    def download_file(self, bucket_name, file_name):
        if self.storage_type == 'aws':
            response = self.client.get_object(Bucket=bucket_name, Key=file_name)
            return response['Body'].read()
        elif self.storage_type == 'google':
            bucket = self.client.bucket(bucket_name)
            blob = bucket.blob(file_name)
            return blob.download_as_bytes()
        elif self.storage_type == 'azure':
            container_client = self.client.get_container_client(container=bucket_name)
            blob_client = container_client.get_blob_client(blob=file_name)
            return blob_client.download_blob().readall()

class HashService:
    def __init__(self, cloud_storage_clients):
        self.cloud_storage_clients = cloud_storage_clients

    def hash_cloud_file(self, storage_type, bucket_name, file_name):
        client = next(client for client in self.cloud_storage_clients if client.storage_type == storage_type)
        file_data = client.download_file(bucket_name, file_name)
        hasher = hashlib.sha256()
        hasher.update(file_data)
        return hasher.hexdigest()

    def hash_files_concurrently(self, tasks):
        with ThreadPoolExecutor() as executor:
            future_to_task = {executor.submit(task.hash_cloud_file, task.storage_type, task.bucket_name, task.file_name): task for task in tasks}
            results = []
            for future in as_completed(future_to_task):
                try:
                    result = future.result()
                    results.append(result)
                except Exception as e:
                    print(f"Error processing file: {e}")
        return results

# Example usage
aws_client = CloudStorageClient('aws', {'access_key': 'your_aws_access_key', 'secret_key': 'your_aws_secret_key'})
google_client = CloudStorageClient('google', {'service_account_file': 'path_to_your_google_service_account.json'})
azure_client = CloudStorageClient('azure', {'account_url': 'your_azure_account_url', 'credential': 'your_azure_credential'})

hash_service = HashService([aws_client, google_client, azure_client])

tasks = [
    # Add tasks for each file and storage type
]

results = hash_service.hash_files_concurrently(tasks)
