    LogProcessor(int numThreads) : running(true), workers(numThreads) {
        for (int i = 0; i < numThreads; ++i) {
            workers.emplace_back([this]() { processLogs(); });
        }
    }

    ~LogProcessor() {
        running.store(false);
        notEmpty.notify_all();
        for (auto& worker : workers) {
            worker.join();
        }
    }

    void enqueue(const std::string& logEntry) {
        std::lock_guard<std::mutex> lock(queueMutex);
        logQueue.push(logEntry);
        notEmpty.notify_one();
    }

private:
    void processLogs() {
        while (running.load()) {
            std::unique_lock<std::mutex> lock(queueMutex);
            notEmpty.wait(lock, [this] { return !logQueue.empty() || !running.load(); });

            if (!running.load() && logQueue.empty()) {
                break;
            }

            std::string logEntry = logQueue.front();
            logQueue.pop();

            lock.unlock();
            processLog(logEntry);
        }
    }

    void processLog(const std::string& logEntry) {
        // Parse and validate log entry
        Json::Value parsedLog;
        parsedLog = Json::parse(logEntry);

        if (SchemaRegistry::validate(parsedLog, "your_schema")) {
            // Process valid log entry
            // Integrate with external systems here
        } else {
            // Handle invalid log entry
            std::cerr << "Invalid log entry: " << logEntry << std::endl;
        }
    }
};

int main(int argc, char* argv[]) {
    if (argc < 4) {
        std::cerr << "Usage: " << argv[0] << " <input_log_file> <output_directory> <config_file>" << std::endl;
        return 1;
    }

    std::string inputLogFile = argv[1];
    std::string outputDirectory = argv[2];
    std::string configFilePath = argv[3];

    // Load configuration from JSON file
    Json::Value config;
    std::ifstream configFile(configFilePath);
    configFile >> config;

    int numThreads = config["num_threads"].asInt();
    LogProcessor processor(numThreads);

    // Process log file
    std::ifstream logFile(inputLogFile);
    std::string line;
    while (std::getline(logFile, line)) {
        processor.enqueue(line);
    }

    return 0;
}
