class DynamicLogService {
public:
    DynamicLogService(const std::string& apiUrl, const std::string& clientId, const std::string& clientSecret)
        : apiUrl(apiUrl), clientId(clientId), clientSecret(clientSecret), token(""),
          lastRequestTime(0), requestCount(0) {}

    void log(int condition, const char* format, ...) {
        va_list args;
        va_start(args, format);
        std::string message = vsnprintf_to_string(format, args);
        va_end(args);

        if (message.length() > 1024) {
            message.resize(1024);
            std::cerr << "Warning: Log message truncated due to buffer overflow." << std::endl;
        }

        if (!shouldLog()) return;

        logQueue.push({condition, message});
        logCondition.notify_one();
    }

private:
    struct LogEntry {
        int condition;
        std::string message;
    };

    const std::string apiUrl;
    const std::string clientId;
    const std::string clientSecret;
    std::atomic<std::string> token;
    std::time_t lastRequestTime;
    std::atomic<int> requestCount;
    std::queue<LogEntry> logQueue;
    std::mutex queueMutex;
    std::condition_variable logCondition;
    std::thread workerThread;
    std::atomic<bool> running;

    void worker() {
        while (running) {
            LogEntry entry;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                logCondition.wait(lock, [this]{ return !logQueue.empty(); });
                entry = logQueue.front();
                logQueue.pop();
            }

            if (!authenticate()) continue;

            sendLog(entry.condition, entry.message);
        }
    }

    bool authenticate() {
