package com.example.configloader;

import java.io.InputStream;
import java.net.URL;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class ConfigLoader {

    private static final ConcurrentHashMap<String, Object> cache = new ConcurrentHashMap<>();
    private static final Lock lock = new ReentrantLock();

    public static <T> T loadConfig(String source, Class<T> configClass, String format) {
        String key = source + "-" + format;
        return cache.computeIfAbsent(key, k -> {
            try {
                Object config = fetchAndDeserialize(source, format);
                validateConfig(config, configClass);
                return config;
            } catch (Exception e) {
                handleFailure(source, format, e);
                return getDefaultConfig(configClass);
            }
        });
    }

    private static Object fetchAndDeserialize(String source, String format) throws Exception {
        switch (format.toLowerCase()) {
            case "json":
                return new JSONDeserializer().deserialize(fetchDataFromSource(source));
            case "xml":
                return new XMLDeserializer().deserialize(fetchDataFromSource(source));
            case "yaml":
                return new YAMLDeserializer().deserialize(fetchDataFromSource(source));
            case "binary":
                return new BinaryDeserializer().deserialize(fetchDataFromSource(source));
            default:
                throw new IllegalArgumentException("Unsupported format: " + format);
        }
    }

    private static InputStream fetchDataFromSource(String source) throws Exception {
        if (source.startsWith("http")) {
            URL url = new URL(source);
            return url.openStream();
        } else if (source.endsWith(".json") || source.endsWith(".xml") || source.endsWith(".yaml") || source.endsWith(".bin")) {
            return ConfigLoader.class.getResourceAsStream("/" + source);
        }
        throw new IllegalArgumentException("Unsupported source: " + source);
    }

    private static void validateConfig(Object config, Class<?> configClass) throws Exception {
        // Implement validation logic using Apache Avro or JSON Schema
    }

    private static <T> T getDefaultConfig(Class<T> configClass) {
        try {
            return configClass.getDeclaredConstructor().newInstance();
        } catch (Exception e) {
            throw new RuntimeException("Failed to create default configuration object", e);
        }
    }

    private static void handleFailure(String source, String format, Exception e) {
        // Log detailed warnings and suggest fallback strategies
    }

    public static void clearCache() {
        lock.lock();
        try {
            cache.clear();
        } finally {
            lock.unlock();
        }
    }
}
