# Policy Engine Design

class PolicyEngine:
    def __init__(self):
        self.policies = {}

    def add_policy(self, policy_name, policy_logic):
        self.policies[policy_name] = policy_logic

    def apply_policies(self, user_id):
        for policy in self.policies.values():
            if not policy(user_id):
                return False
        return True

def mfa_policy(user_id):
