const { Module } = require('./moduleManager');

const app = express();
app.use(bodyParser.json());

// Connect to NoSQL database
mongoose.connect('mongodb://localhost:27017/microservice', { useNewUrlParser: true, useUnifiedTopology: true });

// Define a simple model for demonstration purposes
const DataSchema = new mongoose.Schema({
  name: String,
  value: Number
});
const DataModel = mongoose.model('Data', DataSchema);

// Route to retrieve data from an external REST API and store in MongoDB
app.get('/data', async (req, res) => {
  try {
    const response = await axios.get('https://api.example.com/data');
    const data = response.data;

    // Store data in MongoDB
    const newData = new DataModel(data);
    await newData.save();

    res.status(200).json({ message: 'Data retrieved and stored successfully' });
  } catch (error) {
    res.status(500).json({ error: 'Failed to retrieve data' });
  }
});

// Route to dynamically load and execute JavaScript modules
app.get('/executeModule', async (req, res) => {
  const moduleName = req.query.module;
  const module = new Module(moduleName);

  try {
    await module.load();
    const result = await module.execute();
    await module.unload();

    res.status(200).json(result);
  } catch (error) {
    res.status(500).json({ error: 'Failed to execute module' });
  }
});

app.listen(3000, () => {
  console.log('Microservice listening on port 3000');
});
```

This code sets up a basic Node.js microservice using Express. It connects to a MongoDB database and retrieves data from an external REST API, storing the data in the database. The service also includes routes to dynamically load and execute JavaScript modules. Each module is loaded only when necessary, executed, and then unloaded promptly to minimize resource consumption.

To implement rate limiting and traffic shaping, you can use libraries like `express-rate-limit` for request limits and consider using a distributed message queue like Kafka or RabbitMQ for asynchronous processing with predictive analytics to manage workload spikes.

For real-time data streaming, you might integrate with services like Apache Kafka or AWS Kinesis. Implementing horizontal scaling strategies involves deploying your microservice on multiple instances and using load balancers like NGINX or AWS Elastic Load Balancer.

Ensure robust error handling and retry logic for network failures and unexpected runtime exceptions. For security, consider implementing encryption at rest and in transit, strong authentication, and authorization protocols.

Monitoring and logging can be enhanced by integrating with tools like Prometheus, Grafana, ELK stack (Elasticsearch, Logstash, Kibana), or cloud-native monitoring services like AWS CloudWatch or Google Stackdriver."]

