    url: String,
    expected_status: u16,
}

#[derive(Debug)]
struct TestReport {
    test_cases: Vec<TestCaseResult>,
}

#[derive(Debug)]
struct TestCaseResult {
    name: String,
    execution_time: Duration,
    memory_usage: Option<u64>, // in bytes
    error: Option<String>,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let api_endpoint = env::var("API_ENDPOINT")?;
    let config_file_path = env::var("CONFIG_FILE_PATH")?;
    let output_format = env::var("OUTPUT_FORMAT")?;

    let test_cases = load_test_cases(&config_file_path)?;
    let client = Client::new();
    let report = run_tests(&client, &api_endpoint, &test_cases)?;

    if output_format == "json" {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else if output_format == "csv" {
        println!("{}", export_csv(&report));
    }

    Ok(())
}

fn load_test_cases(file_path: &str) -> Result<Vec<TestCase>, Box<dyn std::error::Error>> {
    let file = File::open(file_path)?;
    let reader = BufReader::new(file);

    let test_cases: Vec<TestCase> = reader
        .lines()
        .filter_map(|line| line.ok())
        .map(|line| serde_json::from_str(&line))
        .collect::<Result<Vec<TestCase>, _>>()?;

    Ok(test_cases)
}

async fn run_test(client: &Client, api_endpoint: &str, test_case: &TestCase) -> TestCaseResult {
    let start_time = Instant::now();
    let mut memory_usage = None;

    // Simulate memory usage measurement (replace with actual implementation)
    if let Some(monitor) = get_memory_monitor() {
        monitor.start();
    }

    let response = client
        .get(&format!("{}{}", api_endpoint, test_case.url))
        .send()
        .await;

    let execution_time = start_time.elapsed();

    if let Some(monitor) = get_memory_monitor() {
        memory_usage = Some(monitor.stop());
    }

    let error = match response {
        Ok(res) => {
            if res.status() != test_case.expected_status {
                Some(format!("Expected status {}, but got {}", test_case.expected_status, res.status()))
            } else {
                None
            }
        },
        Err(e) => Some(format!("{:?}", e)),
    };

    TestCaseResult {
        name: test_case.name.clone(),
        execution_time,
        memory_usage,
        error,
    }
}

async fn run_tests(client: &Client, api_endpoint: &str, test_cases: &[TestCase]) -> TestReport {
    let results = tokio::join!({
        test_cases
            .iter()
            .map(|test_case| run_test(client, api_endpoint, test_case))
            .collect::<Vec<_>>()
    });

    TestReport { test_cases: results }
}

fn export_csv(report: &TestReport) -> String {
    let mut output = "name,execution_time,memory_usage,error\n".to_string();

    for result in report.test_cases.iter() {
        output.push_str(&format!(
            "{},{},{}{}\n",
            result.name,
            result.execution_time.as_secs_f64(),
            result.memory_usage.map_or("None", |m| format!("{}", m)),
            result.error.as_ref().map_or("", |e| &format!(",{}", e))
        ));
    }

    output
}

