package session

import (
    "crypto/aes"
    "crypto/cipher"
    "crypto/rand"
    "encoding/base64"
    "fmt"
    "github.com/external/sessionstore"
    "golang.org/x/crypto/sha3"
    "net/http"
    "time"
)

const (
    sessionTokenKey = "session_token"
    sessionExpiry   = 24 * time.Hour
)

type Session struct {
    ID        string `json:"id"`
    UserID    string `json:"user_id"`
    Data      map[string]interface{} `json:"data"`
    Expiry    time.Time            `json:"expiry"`
}

type Manager struct {
    store sessionstore.SessionStore
}

func NewManager(store sessionstore.SessionStore) *Manager {
    return &Manager{store: store}
}

func (m *Manager) StartSession(w http.ResponseWriter, r *http.Request, userID string) (*Session, error) {
    id := generateSecureToken()
    expiry := time.Now().Add(sessionExpiry)
    data := map[string]interface{}{
        "user_id": userID,
    }

    session := &Session{ID: id, UserID: userID, Data: data, Expiry: expiry}
    if err := m.store.Set(id, session); err != nil {
        return nil, fmt.Errorf("failed to store session: %w", err)
    }

    http.SetCookie(w, &http.Cookie{
        Name:     sessionTokenKey,
        Value:    id,
        Expires:  expiry,
        HttpOnly: true,
        Secure:   true,
    })

    return session, nil
}

func (m *Manager) EndSession(r *http.Request) error {
    cookie, err := r.Cookie(sessionTokenKey)
    if err != nil {
        return fmt.Errorf("session token not found")
    }

    id := cookie.Value
    if err := m.store.Delete(id); err != nil {
        return fmt.Errorf("failed to delete session: %w", err)
    }

    return nil
}

func (m *Manager) RetrieveSession(r *http.Request) (*Session, error) {
    cookie, err := r.Cookie(sessionTokenKey)
    if err != nil {
        return nil, fmt.Errorf("session token not found")
    }

    id := cookie.Value
    session, err := m.store.Get(id)
    if err != nil {
        return nil, fmt.Errorf("failed to retrieve session: %w", err)
    }

    if time.Now().After(session.Expiry) {
        if err := m.store.Delete(id); err != nil {
            return nil, fmt.Errorf("failed to delete expired session: %w", err)
        }
        return nil, fmt.Errorf("session has expired")
    }

    return session, nil
}

func generateSecureToken() string {
    token := make([]byte, 32)
    if _, err := rand.Read(token); err != nil {
        panic(err)
    }
    return base64.RawURLEncoding.EncodeToString(token)
}

func encrypt(plaintext []byte, key []byte) ([]byte, error) {
    block, err := aes.NewCipher(key)
    if err != nil {
        return nil, err
    }

    ciphertext := make([]byte, aes.BlockSize+len(plaintext))
    iv := ciphertext[:aes.BlockSize]
    if _, err := rand.Read(iv); err != nil {
        return nil, err
    }

    stream := cipher.NewCFBEncrypter(block, iv)
    stream.XORKeyStream(ciphertext[aes.BlockSize:], plaintext)

    return ciphertext, nil
}

func decrypt(ciphertext []byte, key []byte) ([]byte, error) {
    block, err := aes.NewCipher(key)
    if err != nil {
        return nil, err
    }

    iv := ciphertext[:aes.BlockSize]
    ciphertext = ciphertext[aes.BlockSize:]

    stream := cipher.NewCFBDecrypter(block, iv)
    stream.XORKeyStream(ciphertext, ciphertext)

    return ciphertext, nil
}
