            # Retrieve transaction details from database
            transaction = self.db_client.get_transaction(refund_request['transaction_id'])
            # Refund customer using external billing service
            self.billing_service.refund_customer(transaction)
            # Log refund request in the database
            self.db_client.log_refund(refund_request)
